interface PinnedAnnouncementsProps {
  announcements: Announcement[];
  dismissedAnnouncements: number[];
  handleDismissAnnouncement: (id: number) => void;
}

export const PinnedAnnouncements = ({
  announcements,
  dismissedAnnouncements,
  handleDismissAnnouncement,
}: PinnedAnnouncementsProps) => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === "ar";

  const pinnedAnnouncements = announcements.filter((a) => a.isPinned);
  const visiblePinned = pinnedAnnouncements.filter(
    (a) => !dismissedAnnouncements.includes(a.id),
  );

  if (visiblePinned.length === 0) return null;

  return (
    <div className="space-y-4 px-2 md:px-0">
      <AnimatePresence mode="popLayout">
        {visiblePinned.map((announcement, index) => (
          <motion.div
            key={announcement.id}
            initial={{ opacity: 0, y: -20, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95, transition: { duration: 0.2 } }}
            transition={{
              delay: index * 0.1,
              type: "spring",
              stiffness: 200,
              damping: 20,
            }}
            className="group relative bg-amber-500/10 border-2 border-amber-500/20 rounded-4xl md:rounded-[2.5rem] p-6 md:p-8 flex flex-col md:flex-row items-start md:items-center justify-between gap-6 shadow-xl shadow-amber-500/5 backdrop-blur-md overflow-hidden text-start"
          >
            {/* Subtle Animated Background */}
            <div className="absolute inset-0 bg-linear-to-r from-transparent via-amber-500/5 to-transparent -translate-x-full group-hover:animate-[shine_3s_infinite] pointer-events-none" />

            <div className="flex items-start gap-4 md:gap-5 flex-1 min-w-0 z-10">
              <div className="p-3 md:p-3.5 rounded-xl md:rounded-2xl bg-amber-500/20 text-amber-600 shadow-inner shrink-0 group-hover:scale-110 group-hover:-rotate-3 transition-transform duration-500">
                <Megaphone className="h-5 w-5 md:h-6 md:w-6" />
              </div>
              <div className="space-y-1.5 md:space-y-2">
                <div className="flex flex-wrap items-center gap-2 md:gap-3">
                  <Badge
                    variant="outline"
                    className="bg-amber-500/10 text-amber-700 border-amber-500/30 text-[9px] md:text-[10px] font-black uppercase tracking-widest px-3 py-0.5 md:py-1 rounded-full shadow-sm"
                  >
                    <Pin className="h-3 w-3 me-1.5" />
                    {t("classes.show.banner.pinned" as any)}
                  </Badge>
                  <h4 className="font-black text-lg md:text-xl text-amber-900 dark:text-amber-400 tracking-tight leading-tight group-hover:text-amber-600 transition-colors">
                    {announcement.title}
                  </h4>
                </div>
                <p className="text-sm md:text-base text-amber-800/80 dark:text-amber-500/80 font-medium leading-relaxed max-w-3xl">
                  {announcement.content}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3 w-full md:w-auto z-10 shrink-0">
              {announcement.linkUrl && (
                <Button
                  variant="outline"
                  className="flex-1 md:flex-none rounded-xl md:rounded-2xl font-black uppercase tracking-widest text-[9px] md:text-[10px] h-10 md:h-12 px-6 bg-white dark:bg-muted/10 border-amber-500/20 text-amber-700 hover:bg-amber-50 hover:text-amber-800 shadow-sm transition-all"
                  asChild
                >
                  <a
                    href={announcement.linkUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {t("buttons.readMore" as any)}
                    <ChevronRight
                      className={cn("h-4 w-4 ms-1.5", isAr && "rotate-180")}
                    />
                  </a>
                </Button>
              )}
              <Button
                variant="ghost"
                size="icon"
                className="h-10 w-10 md:h-12 md:w-12 rounded-xl md:rounded-2xl text-amber-700/50 hover:text-destructive hover:bg-destructive/10 transition-colors shrink-0"
                onClick={() => handleDismissAnnouncement(announcement.id)}
                title={t("buttons.dismiss" as any)}
              >
                <X className="h-5 w-5 md:h-6 md:w-6" />
              </Button>
            </div>
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

import { useMemo, useState } from "react";
import { Enrollment, User } from "@/types";
import { HttpError, useInvalidate } from "@refinedev/core";
import { ColumnDef } from "@tanstack/react-table";
import { useTable } from "@refinedev/react-table";
import { DataTable } from "@/components/refine-ui/data-table/data-table";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import {
  Calendar,
  Sparkles,
  Trash2,
  UserPlus,
  Users,
  MessageSquare,
  CheckCircle2,
  XCircle,
  FileSpreadsheet,
  ShieldAlert,
  TrendingDown,
  BrainCircuit,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";
import { ScrollArea } from "@/components/ui/scroll-area";
import { motion, AnimatePresence } from "framer-motion";
import { useQueryClient } from "@tanstack/react-query";
import { BulkEnrollDialog } from "./bulk-enroll-dialog";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import dayjs from "dayjs";

interface StudentsTabProps {
  classId: string;
  approvedCount: number;
  pendingEnrollments: Enrollment[];
  isStaff: boolean;
  onInsight: (student: { id: string; name: string }) => void;
  onUnenroll: (id: number) => void;
  onEnrollClick: () => void;
  onMessageAllClick: () => void;
  onEnrollmentAction: (id: number, status: "approved" | "rejected") => void;
}

export const StudentsTab = ({
  classId,
  approvedCount,
  pendingEnrollments,
  isStaff,
  onInsight,
  onUnenroll,
  onEnrollClick,
  onMessageAllClick,
  onEnrollmentAction,
}: StudentsTabProps) => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === "ar";
  const queryClient = useQueryClient();
  const [bulkDialogOpen, setBulkDialogOpen] = useState(false);

  /**
   * ARCHITECTURAL PATTERN: Optimistic Update Helper
   * Manually updates the React Query cache before the server responds.
   */
  const handleOptimisticEnrollment = async (id: number, status: "approved" | "rejected") => {
    // 1. Trigger the actual mutation (which remains passed from the parent for consistency)
    onEnrollmentAction(id, status);

    // 2. Perform manual cache manipulation for instant UI feedback
    const queryKey = ["enrollments", "list"];
    
    // We update both the specific enrollment list and general dashboard stats
    await queryClient.cancelQueries({ queryKey });
    
    queryClient.setQueriesData({ queryKey }, (old: any) => {
        if (!old?.data) return old;
        return {
            ...old,
            data: old.data.map((e: Enrollment) => e.id === id ? { ...e, status } : e)
        };
    });
  };

  const columns = useMemo<ColumnDef<Enrollment>[]>(
    () => [
      {
        id: "student",
        header: () => (
          <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">
            {t("classes.show.students.table.student")}
          </p>
        ),
        accessorKey: "student",
        cell: ({ getValue, row }) => {
          const student = getValue<User>();
          const isWaitlisted = row.original.status === "waitlisted";
          const isPending = row.original.status === "pending";
          const riskAssessment = row.original.riskAssessment;

          return (
            <div className="flex items-center gap-3 py-1">
              <Avatar className="size-9 md:size-10 border-2 border-background shadow-sm rounded-lg md:rounded-xl">
                {student.image && (
                  <AvatarImage
                    src={student.image}
                    alt={student.name}
                    className="object-cover"
                  />
                )}
                <AvatarFallback className="bg-primary/5 text-primary font-black text-[10px] md:text-xs">
                  {student.name?.[0]}
                </AvatarFallback>
              </Avatar>
              <div className="flex flex-col truncate text-start min-w-0">
                <div className="flex items-center gap-1.5 md:gap-2">
                  <span className="font-black text-xs md:text-sm tracking-tight truncate text-foreground">
                    {student.name}
                  </span>
                  
                  {isStaff && row.original.riskAssessment && row.original.riskAssessment.riskLevel !== "low" && (
                    <Badge 
                        variant="destructive" 
                        className={cn(
                            "border-none text-[7px] md:text-[8px] font-black uppercase tracking-tighter px-1.5 md:px-2 py-0 h-3.5 md:h-4 shrink-0 gap-1",
                            row.original.riskAssessment.riskLevel === "critical" ? "bg-red-600 text-white animate-pulse" : 
                            row.original.riskAssessment.riskLevel === "high" ? "bg-orange-600 text-white" : "bg-yellow-500 text-white"
                        )}
                    >
                        <ShieldAlert className="h-2 w-2" />
                        {row.original.riskAssessment.riskLevel}
                    </Badge>
                  )}

                  {/* 🧠 LEARNING DNA TOOLTIP (Staff Only) */}
                  {isStaff && student.persona && (
                    <TooltipProvider>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <div className="p-1 rounded-md bg-ai-primary/10 text-ai-primary cursor-help hover:bg-ai-primary/20 transition-colors">
                                    <BrainCircuit className="h-3 w-3" />
                                </div>
                            </TooltipTrigger>
                            <TooltipContent side="right" className="max-w-xs p-4 rounded-2xl bg-card/95 backdrop-blur-xl border-ai-primary/20 shadow-2xl z-50">
                                <div className="space-y-2">
                                    <div className="flex items-center gap-2 border-b border-border/40 pb-2 mb-2">
                                        <Sparkles className="h-3 w-3 text-ai-primary" />
                                        <span className="text-[10px] font-black uppercase tracking-widest text-ai-primary">Learning DNA</span>
                                    </div>
                                    <p className="text-xs font-medium leading-relaxed italic break-words whitespace-pre-wrap">
                                        "{student.persona.learningDNA}"
                                    </p>
                                    <div className="pt-2 flex justify-between items-center text-[8px] font-bold text-muted-foreground uppercase">
                                        <span>Tone: {student.persona.preferredTone}</span>
                                        <span>Updated: {dayjs(student.persona.lastSummarizedAt).fromNow()}</span>
                                    </div>
                                </div>
                            </TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                  )}

                  {isWaitlisted && (
                    <Badge
                      variant="outline"
                      className="bg-orange-500/10 text-orange-600 border-none text-[7px] md:text-[8px] font-black uppercase tracking-tighter px-1.5 md:px-2 py-0 h-3.5 md:h-4 shrink-0"
                    >
                      {t("classes.show.students.table.waitlist", {
                        pos: row.original.waitlistPosition,
                      })}
                    </Badge>
                  )}
                  {isPending && (
                    <Badge
                      variant="outline"
                      className="bg-blue-500/10 text-blue-600 border-none text-[7px] md:text-[8px] font-black uppercase tracking-tighter px-1.5 md:px-2 py-0 h-3.5 md:h-4 shrink-0"
                    >
                      {t("classes.show.students.pending.title")}
                    </Badge>
                  )}
                  {isStaff && riskAssessment && riskAssessment.riskLevel !== "low" && (
                    <Badge
                      variant="destructive"
                      className={cn(
                        "border-none text-[7px] md:text-[8px] font-black uppercase tracking-tighter px-1.5 md:px-2 py-0 h-3.5 md:h-4 shrink-0 gap-1",
                        riskAssessment.riskLevel === "critical" ? "bg-red-600 text-white animate-pulse" : 
                        riskAssessment.riskLevel === "high" ? "bg-orange-600 text-white" : "bg-yellow-500 text-white"
                      )}
                    >
                      <ShieldAlert className="h-2 w-2" />
                      {riskAssessment.riskLevel}
                    </Badge>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[9px] md:text-[10px] text-muted-foreground font-bold truncate">
                    {student.email}
                  </span>
                  {isStaff && riskAssessment?.predictedGrade && (
                    <span className="text-[9px] font-black text-destructive flex items-center gap-0.5">
                      <TrendingDown className="h-2.5 w-2.5" />
                      AI: {riskAssessment.predictedGrade}%
                    </span>
                  )}
                </div>
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "createdAt",
        header: () => (
          <p className="hidden sm:block text-[10px] font-black uppercase tracking-widest text-muted-foreground">
            {t("classes.show.students.table.enrolledOn")}
          </p>
        ),
        cell: ({ getValue }) => (
          <div className="hidden sm:flex items-center gap-2 text-[10px] md:text-xs font-bold text-muted-foreground">
            <Calendar className="h-3 md:h-3.5 w-3 md:w-3.5 opacity-40" />
            <span className="whitespace-nowrap">
              {new Date(getValue<string>()).toLocaleDateString(
                isAr ? "ar-EG" : "en-US",
                { month: "short", day: "numeric", year: "numeric" },
              )}
            </span>
          </div>
        ),
      },
      {
        id: "actions",
        header: "",
        cell: ({ row }) => (
          <div className={cn("flex items-center gap-1.5 md:gap-2 justify-end")}>
            {isStaff && row.original.status === "approved" && (
              <Button
                variant="outline"
                size="sm"
                className="h-8 md:h-9 rounded-lg md:rounded-xl font-black text-[9px] md:text-[10px] uppercase tracking-widest gap-1.5 md:gap-2 border-ai-primary/20 hover:bg-ai-primary/5 text-ai-primary transition-all shadow-sm px-2 md:px-3"
                onClick={() =>
                  onInsight({
                    id: row.original.student.id,
                    name: row.original.student.name,
                  })
                }
              >
                <Sparkles className="h-3 w-3 md:h-3.5 md:w-3.5" />
                <span className="hidden xs:inline">
                  {t("buttons.aiInsight")}
                </span>
              </Button>
            )}
            {isStaff && (
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 md:h-9 md:w-9 rounded-lg md:rounded-xl text-muted-foreground hover:text-destructive hover:bg-destructive/5"
                onClick={() => onUnenroll(row.original.id)}
              >
                <Trash2 className="h-3.5 w-3.5 md:h-4 md:w-4" />
              </Button>
            )}
          </div>
        ),
      },
    ],
    [isStaff, t, isAr, onInsight, onUnenroll],
  );

  const enrollmentsTable = useTable<Enrollment, HttpError>({
    columns,
    refineCoreProps: {
      resource: "enrollments",
      filters: {
        initial: [
          {
            field: "classId",
            operator: "eq",
            value: classId,
          },
          {
            field: "status",
            operator: "in",
            value: ["approved", "waitlisted"],
          },
        ],
      },
      pagination: {
        pageSize: 50,
      },
      syncWithLocation: false,
    },
  });

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 md:gap-10 items-start">
      <div className="lg:col-span-3 space-y-6 md:space-y-8">
        <Card className="rounded-4xl md:rounded-[2.5rem] border-none shadow-2xl shadow-black/5 overflow-hidden bg-card/50 backdrop-blur-3xl">
          <CardHeader className="p-6 md:p-10 pb-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6 border-b border-black/3 dark:border-white/3 bg-muted/30">
            <div className="space-y-1.5 md:space-y-2 text-start">
              <div className="flex items-center gap-3">
                <div className="p-2 md:p-3 rounded-xl md:rounded-2xl bg-primary/10 text-primary border border-primary/5 shadow-sm">
                  <Users className="h-5 w-5 md:h-6 md:w-6" />
                </div>
                <CardTitle className="text-xl md:text-2xl font-black tracking-tight text-foreground">
                  {t("classes.show.students.table.title")}
                </CardTitle>
              </div>
              <CardDescription className="text-xs md:text-sm text-muted-foreground font-medium px-1">
                {t("classes.show.students.table.description", {
                  count: approvedCount,
                })}
              </CardDescription>
            </div>
            {isStaff && (
              <div className="flex flex-wrap items-center gap-2 md:gap-3 w-full sm:w-auto">
                <Button
                  variant="outline"
                  size="lg"
                  onClick={onMessageAllClick}
                  className="flex-1 sm:flex-none rounded-xl md:rounded-2xl h-12 md:h-14 px-6 md:px-8 font-black uppercase tracking-widest text-[9px] md:text-[10px] gap-2 border-primary/20 hover:bg-primary/10 transition-all text-primary shadow-sm"
                >
                  <MessageSquare className="h-4 w-4 md:h-5 md:w-5" />
                  <span className="hidden xs:inline">
                    {t("classes.show.students.actions.messageAll")}
                  </span>
                  <span className="xs:hidden">{t("classes.show.students.actions.message")}</span>
                </Button>
                <Button
                  variant="outline"
                  size="lg"
                  onClick={() => setBulkDialogOpen(true)}
                  className="flex-1 sm:flex-none rounded-xl md:rounded-2xl h-12 md:h-14 px-6 md:px-8 font-black uppercase tracking-widest text-[9px] md:text-[10px] gap-2 border-emerald-500/20 hover:bg-emerald-500/10 transition-all text-emerald-600 shadow-sm"
                >
                  <FileSpreadsheet className="h-4 w-4 md:h-5 md:w-5" />
                  <span className="hidden xs:inline">
                    {t("classes.show.students.actions.bulkEnroll", "Bulk Enroll")}
                  </span>
                  <span className="xs:hidden">{t("classes.show.students.actions.csv")}</span>
                </Button>
                <Button
                  size="lg"
                  onClick={onEnrollClick}
                  className="flex-1 sm:flex-none rounded-xl md:rounded-2xl h-12 md:h-14 px-6 md:px-8 font-black uppercase tracking-widest text-[9px] md:text-[10px] gap-2 shadow-xl shadow-primary/20 transition-all text-white bg-primary hover:bg-primary/90"
                >
                  <UserPlus className="h-4 w-4 md:h-5 md:w-5" />
                  <span className="hidden xs:inline">
                    {t("classes.show.students.actions.enrollStudent")}
                  </span>
                  <span className="xs:hidden">{t("classes.show.students.actions.enroll")}</span>
                </Button>
              </div>
            )}
          </CardHeader>
          <CardContent className="p-0 overflow-x-auto relative min-h-100">
            <DataTable table={enrollmentsTable} />
          </CardContent>
        </Card>
      </div>

      {/* Sidebar - Pending Requests */}
      {isStaff && (
        <div className="space-y-6 md:space-y-8 lg:sticky lg:top-40">
          <Card className="rounded-4xl md:rounded-[2.5rem] border-none shadow-2xl shadow-black/5 overflow-hidden bg-card/50 backdrop-blur-3xl">
            <CardHeader className="p-6 md:p-8 pb-4 bg-orange-500/5 border-b border-orange-500/10">
              <div className="flex items-center justify-between">
                <div className="space-y-1.5 text-start">
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-xl bg-orange-500/10 text-orange-600 shadow-sm border border-orange-500/20">
                      <UserPlus className="h-4 w-4" />
                    </div>
                    <CardTitle className="text-lg md:text-xl font-black tracking-tight text-foreground">
                      {t("classes.show.students.pending.title")}
                    </CardTitle>
                  </div>
                  <CardDescription className="text-[10px] md:text-xs font-bold uppercase tracking-widest text-orange-600/80 px-1">
                    {t("classes.show.students.pending.count", {
                      count: pendingEnrollments.length,
                    })}
                  </CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent className="p-0">
              <ScrollArea className="max-h-125">
                <div className="p-4 md:p-6 space-y-3 md:space-y-4">
                  {pendingEnrollments.length === 0 ? (
                    <div className="text-center py-10 md:py-16 space-y-3 opacity-40">
                      <UserPlus className="h-8 w-8 md:h-12 md:w-12 mx-auto text-muted-foreground" />
                      <p className="text-[10px] md:text-xs font-black uppercase tracking-widest text-muted-foreground">
                        {t("classes.show.students.pending.empty")}
                      </p>
                    </div>
                  ) : (
                    <AnimatePresence mode="popLayout">
                      {pendingEnrollments.map(
                        (enrollment: Enrollment, index: number) => (
                          <motion.div
                            key={enrollment.id}
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            transition={{ delay: index * 0.05 }}
                            className="flex items-center justify-between p-4 md:p-5 rounded-2xl md:rounded-3xl bg-orange-500/3 border border-orange-500/10 transition-all hover:bg-orange-500/10 hover:border-orange-500/20 group shadow-sm"
                          >
                            <div className="flex items-center gap-3 md:gap-4 min-w-0">
                              <Avatar className="h-10 w-10 md:h-12 md:w-12 border-2 border-background shadow-sm rounded-xl md:rounded-2xl group-hover:scale-105 transition-transform duration-500">
                                {enrollment.student.image && (
                                  <AvatarImage
                                    src={enrollment.student.image}
                                    alt={enrollment.student.name}
                                    className="object-cover"
                                  />
                                )}
                                <AvatarFallback className="bg-orange-500/10 text-orange-600 font-black text-xs md:text-sm">
                                  {enrollment.student.name?.[0]}
                                </AvatarFallback>
                              </Avatar>
                              <div className="flex flex-col text-start min-w-0">
                                <span className="text-sm md:text-base font-black tracking-tight truncate text-foreground group-hover:text-orange-700 transition-colors">
                                  {enrollment.student.name}
                                </span>
                                <span className="text-[9px] md:text-[10px] text-muted-foreground/80 font-bold uppercase tracking-widest truncate mt-0.5">
                                  {t("classes.show.students.pending.requested")}
                                </span>
                              </div>
                            </div>
                            <div className="flex items-center gap-1 md:gap-2 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
                              <Button
                                variant="outline"
                                size="icon"
                                className="h-9 w-9 md:h-10 md:w-10 rounded-xl text-emerald-600 border-emerald-500/20 bg-emerald-500/5 hover:bg-emerald-500 hover:text-white transition-all shadow-sm"
                                onClick={() =>
                                  handleOptimisticEnrollment(enrollment.id, "approved")
                                }
                              >
                                <CheckCircle2 className="h-4 w-4 md:h-5 md:w-5" />
                              </Button>
                              <Button
                                variant="outline"
                                size="icon"
                                className="h-9 w-9 md:h-10 md:w-10 rounded-xl text-destructive border-destructive/20 bg-destructive/5 hover:bg-destructive hover:text-white transition-all shadow-sm"
                                onClick={() =>
                                  handleOptimisticEnrollment(enrollment.id, "rejected")
                                }
                              >
                                <XCircle className="h-4 w-4 md:h-5 md:w-5" />
                              </Button>
                            </div>
                          </motion.div>
                        ),
                      )}
                    </AnimatePresence>
                  )}
                </div>
              </ScrollArea>
            </CardContent>
          </Card>
        </div>
      )}

      <BulkEnrollDialog
        open={bulkDialogOpen}
        onOpenChange={setBulkDialogOpen}
        classId={classId}
      />
    </div>
  );
};

import {
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { socket } from "@/lib/socket";
import { useCustomMutation, useGetIdentity } from "@refinedev/core";
import { User } from "@/types";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Loader2, Lock, Save, Trash2, Unlock } from "lucide-react";
import { toast } from "sonner";

// Lazy load Excalidraw to avoid SSR/Vite bundling issues
const Excalidraw = lazy(async () => {
  const module = await import("@excalidraw/excalidraw");
  return { default: module.Excalidraw };
});

// Helper for exporting (needs to be imported dynamically too)
let exportToBlob: any;

interface WhiteboardProps {
  classId?: string; // Optional: context for saving resources
  roomId?: string; // Explicit socket room ID. If not provided, defaults to classId.
}

export const Whiteboard = ({ classId, roomId }: WhiteboardProps) => {
  const { data: identity } = useGetIdentity<User>();
  const [excalidrawAPI, setExcalidrawAPI] = useState<any>(null);
  const [isLocked, setIsLocked] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const lastUpdateRef = useRef<number>(0);
  const isTeacher = identity?.role === "teacher" || identity?.role === "admin";
  const hasChangesRef = useRef<boolean>(false);

  // If roomId is not provided, fallback to classId (backward compatibility)
  const activeRoomId = roomId || classId;

  const { mutate: uploadFile } = useCustomMutation();

  useEffect(() => {
    // Load helper functions dynamically
    const loadHelpers = async () => {
      const module = await import("@excalidraw/excalidraw");
      exportToBlob = module.exportToBlob;
    };
    void loadHelpers();
  }, []);

  useEffect(() => {
    if (!activeRoomId) return;
    if (!socket.connected) socket.connect();

    console.log(`[Whiteboard] Joining room: ${activeRoomId}`);
    socket.emit("whiteboard:join", activeRoomId);

    socket.on("whiteboard:init", (data) => {
      if (excalidrawAPI && data.elements) {
        excalidrawAPI.updateScene({
          elements: data.elements,
          appState: { ...data.appState, collaborators: [] },
        });
        setIsLocked(data.isLocked);
      }
    });

    socket.on("whiteboard:update", (data) => {
      if (excalidrawAPI) {
        excalidrawAPI.updateScene({
          elements: data.elements,
          appState: { ...data.appState, collaborators: [] },
        });
      }
    });

    socket.on("whiteboard:lock-status", (data) => {
      setIsLocked(data.isLocked);
      if (!isTeacher) {
          toast.info(data.isLocked ? "Teacher has locked the board" : "Teacher has unlocked the board");
      }
    });

    socket.on("whiteboard:clear", () => {
      if (excalidrawAPI) {
        excalidrawAPI.updateScene({ elements: [] });
        if (!isTeacher) toast.warning("The teacher has cleared the whiteboard");
      }
    });

    return () => {
      socket.off("whiteboard:init");
      socket.off("whiteboard:update");
      socket.off("whiteboard:lock-status");
      socket.off("whiteboard:clear");
    };
  }, [activeRoomId, excalidrawAPI]);

  // 🚀 AUTO-SAVE HEARTBEAT: Save to Postgres every 10 seconds if changes exist
  useEffect(() => {
    if (!activeRoomId || !isTeacher) return;

    const interval = setInterval(() => {
      if (hasChangesRef.current && excalidrawAPI) {
        const elements = excalidrawAPI.getSceneElements();
        const appState = excalidrawAPI.getAppState();

        socket.emit("whiteboard:save", {
          classId: activeRoomId,
          elements,
          appState,
        });
        hasChangesRef.current = false;
        console.log("[Whiteboard] Auto-saved to Postgres");
      }
    }, 10000);

    return () => clearInterval(interval);
  }, [activeRoomId, isTeacher, excalidrawAPI]);

  const onChange = useCallback(
    (elements: readonly any[], appState: any) => {
      if (!excalidrawAPI || !activeRoomId) return;

      // Only broadcast if not locked or if user is teacher
      if (isLocked && !isTeacher) return;

      hasChangesRef.current = true; // Mark for autosave

      const now = Date.now();
      if (now - lastUpdateRef.current > 100) {
        // Throttle updates
        socket.emit("whiteboard:update", {
          classId: activeRoomId, // Backend expects "classId" property for room ID
          elements,
          appState,
        });
        lastUpdateRef.current = now;
      }
    },
    [activeRoomId, excalidrawAPI, isLocked, isTeacher],
  );

  const toggleLock = () => {
    if (!activeRoomId) return;
    const newLockedState = !isLocked;
    setIsLocked(newLockedState);
    socket.emit("whiteboard:toggle-lock", {
      classId: activeRoomId,
      isLocked: newLockedState,
    });
  };

  const clearWhiteboard = () => {
    if (!activeRoomId) return;
    if (window.confirm("Are you sure you want to clear the whiteboard?")) {
      socket.emit("whiteboard:clear", activeRoomId);
    }
  };

  const saveSnapshot = async () => {
    if (!excalidrawAPI || !exportToBlob || !classId) {
      if (!classId) toast.error("Cannot save snapshot: Class context missing.");
      return;
    }
    setIsSaving(true);

    try {
      const elements = excalidrawAPI.getSceneElements();
      if (!elements || elements.length === 0) {
        toast.error("Whiteboard is empty");
        setIsSaving(false);
        return;
      }

      const blob = await exportToBlob({
        elements,
        mimeType: "image/png",
        appState: excalidrawAPI.getAppState(),
        files: excalidrawAPI.getFiles(),
      });

      const file = new File(
        [blob],
        `whiteboard-${activeRoomId}-${Date.now()}.png`,
        { type: "image/png" },
      );

      const formData = new FormData();
      formData.append("file", file);
      formData.append("folder", "resources");

      uploadFile(
        {
          url: "/upload",
          method: "post",
          values: formData,
          meta: {
            headers: { "Content-Type": "multipart/form-data" },
          },
        },
        {
          onSuccess: (data: any) => {
            const fileUrl = data.data.url;
            // Now create a resource entry
            uploadFile(
              {
                url: "/resources",
                method: "post",
                values: {
                  title: `Whiteboard Snapshot - ${new Date().toLocaleString()}`,
                  type: "image",
                  url: fileUrl,
                  classId: Number(classId),
                  description: `Snapshot from ${roomId ? "Group" : "Class"} Whiteboard`,
                },
              },
              {
                onSuccess: () => {
                  toast.success("Whiteboard snapshot saved to resources");
                  setIsSaving(false);
                },
                onError: () => {
                  toast.error("Failed to save resource entry");
                  setIsSaving(false);
                },
              },
            );
          },
          onError: () => {
            toast.error("Failed to upload image");
            setIsSaving(false);
          },
        },
      );
    } catch (error) {
      console.error("Save snapshot error:", error);
      toast.error("Failed to save snapshot");
      setIsSaving(false);
    }
  };

  return (
    <div className="flex flex-col h-full border rounded-xl overflow-hidden bg-background">
      <div className="flex items-center justify-between p-2 border-b bg-muted/30">
        <div className="flex items-center gap-4">
          <h4 className="text-sm font-semibold px-2">
            {roomId ? "Group Whiteboard" : "Class Whiteboard"}
          </h4>
          {isTeacher && (
            <div className="flex items-center space-x-2">
              <Switch
                id="lock-mode"
                checked={isLocked}
                onCheckedChange={toggleLock}
              />
              <Label
                htmlFor="lock-mode"
                className="text-xs flex items-center gap-1"
              >
                {isLocked ? (
                  <Lock className="h-3 w-3" />
                ) : (
                  <Unlock className="h-3 w-3" />
                )}
                {isLocked ? "Students Locked" : "Students Can Draw"}
              </Label>
            </div>
          )}
          {!isTeacher && isLocked && (
            <div className="flex items-center gap-1 text-xs text-destructive font-medium">
              <Lock className="h-3 w-3" />
              Drawing is currently disabled by teacher
            </div>
          )}
        </div>
        <div className="flex items-center gap-2">
          {isTeacher && (
            <Button
              variant="outline"
              size="sm"
              onClick={clearWhiteboard}
              className="h-8"
            >
              <Trash2 className="h-4 w-4 me-1" />
              Clear
            </Button>
          )}
          {classId && (
            <Button
              variant="default"
              size="sm"
              onClick={saveSnapshot}
              disabled={isSaving}
              className="h-8 bg-live-primary hover:bg-live-primary/90"
            >
              {isSaving ? (
                <Loader2 className="h-4 w-4 animate-spin me-1" />
              ) : (
                <Save className="h-4 w-4 me-1" />
              )}
              Save Snapshot
            </Button>
          )}
        </div>
      </div>
      <div className="flex-1 relative min-h-125">
        <Suspense
          fallback={
            <div className="flex items-center justify-center h-full">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          }
        >
          <Excalidraw
            excalidrawAPI={(api) => setExcalidrawAPI(api)}
            onChange={onChange}
            viewModeEnabled={isLocked && !isTeacher}
            theme="light"
            UIOptions={{
              canvasActions: {
                loadScene: false,
                saveAsImage: true,
                export: false,
              },
            }}
          />
        </Suspense>
      </div>
    </div>
  );
};

import * as React from "react";
import { useNavigate } from "react-router-dom";
import {
  useNavigation,
  useLogout,
  useCustom,
} from "@refinedev/core";
import {
  Calculator,
  Calendar,
  User as UserIcon,
  BookOpen,
  Sparkles,
  Home,
  LogOut,
  Moon,
  Sun,
  Search,
  PlusCircle,
  History,
  GraduationCap,
  ClipboardCheck,
  FileText,
  Loader2,
} from "lucide-react";

import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
} from "@/components/ui/command";
import { useTheme } from "@/components/refine-ui/theme/theme-provider";
import { useDebounce } from "react-use";
import { useTranslation } from "react-i18next";
import { useUserRole } from "@/hooks/use-user-role";

const RECENT_SEARCHES_KEY = "classroom_recent_searches";
const MAX_RECENT_SEARCHES = 5;

interface SearchResult {
  id: number | string;
  type: "class" | "subject" | "assignment" | "resource";
  title: string;
  description?: string | null;
  link: string;
  metadata?: any;
}

export function CommandMenu() {
  const { t } = useTranslation();
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState("");
  const [debouncedSearch, setDebouncedSearch] = React.useState("");
  const [recentSearches, setRecentSearches] = React.useState<string[]>([]);

  const navigate = useNavigate();
  const { identity, isStaff, isStudent } = useUserRole();
  const { show, create, list } = useNavigation();
  const { mutate: logout } = useLogout();
  const { theme, setTheme } = useTheme();

  useDebounce(
    () => {
      setDebouncedSearch(search);
    },
    300,
    [search]
  );

  // Load recent searches
  React.useEffect(() => {
    const saved = localStorage.getItem(RECENT_SEARCHES_KEY);
    if (saved) {
      try {
        setRecentSearches(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse recent searches", e);
      }
    }
  }, []);

  const saveRecentSearch = (term: string) => {
    if (!term.trim()) return;
    const updated = [
      term,
      ...recentSearches.filter((s) => s !== term),
    ].slice(0, MAX_RECENT_SEARCHES);
    setRecentSearches(updated);
    localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify(updated));
  };

  // --- UNIFIED GLOBAL SEARCH ---
  const { result: searchResult, query: searchQuery } = useCustom<SearchResult[]>({
    url: "/search",
    method: "get",
    config: {
        query: { q: debouncedSearch }
    },
    queryOptions: { 
        enabled: open && debouncedSearch.length >= 2,
        // Keep previous data while fetching new results for smoother UX
        placeholderData: (previousData) => previousData,
    },
  });

  const results = searchResult?.data || [];
  const isSearching = searchQuery.isFetching;

  React.useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((open) => !open);
      }
    };

    document.addEventListener("keydown", down);
    return () => document.removeEventListener("keydown", down);
  }, []);

  const runCommand = React.useCallback((command: () => void, term?: string) => {
    setOpen(false);
    if (term) saveRecentSearch(term);
    command();
  }, [recentSearches]);

  const getIcon = (type: string) => {
    switch (type) {
        case "class": return <BookOpen className="me-2 h-4 w-4 text-blue-500 rtl:me-0 rtl:ms-2" />;
        case "assignment": return <Calculator className="me-2 h-4 w-4 text-orange-500 rtl:me-0 rtl:ms-2" />;
        case "resource": return <FileText className="me-2 h-4 w-4 text-emerald-500 rtl:me-0 rtl:ms-2" />;
        case "subject": return <GraduationCap className="me-2 h-4 w-4 text-purple-500 rtl:me-0 rtl:ms-2" />;
        default: return <Search className="me-2 h-4 w-4 rtl:me-0 rtl:ms-2" />;
    }
  };

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="flex items-center gap-2 px-3 py-1.5 text-sm text-muted-foreground border rounded-md bg-muted/50 hover:bg-muted transition-colors w-full max-w-50"
      >
        <Search className="h-4 w-4" />
        <span>{t("common.search")}</span>
        <kbd className="pointer-events-none inline-flex h-5 select-none items-center gap-1 rounded border bg-muted px-1.5 font-mono text-[10px] font-medium text-muted-foreground opacity-100 ms-auto ltr:flex rtl:hidden">
          <span className="text-xs">⌘</span>K
        </kbd>
        <kbd className="pointer-events-none inline-flex h-5 select-none items-center gap-1 rounded border bg-muted px-1.5 font-mono text-[10px] font-medium text-muted-foreground opacity-100 me-auto rtl:flex ltr:hidden">
          <span className="text-xs">⌘</span>K
        </kbd>
      </button>
      <CommandDialog open={open} onOpenChange={setOpen}>
        <div className="relative">
            <CommandInput 
                placeholder={t("common.typeToSearch")} 
                value={search}
                onValueChange={setSearch}
            />
            {isSearching && (
                <div className="absolute end-4 top-1/2 -translate-y-1/2 rtl:end-auto rtl:start-4">
                    <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                </div>
            )}
        </div>
        <CommandList>
          <CommandEmpty>
            {isSearching ? t("common.searching") : t("common.noResults")}
          </CommandEmpty>
          
          {!search && recentSearches.length > 0 && (
            <CommandGroup heading={t("common.recentSearches")}>
              {recentSearches.map((term) => (
                <CommandItem
                  key={term}
                  onSelect={() => setSearch(term)}
                >
                  <History className="me-2 h-4 w-4 text-muted-foreground rtl:me-0 rtl:ms-2" />
                  <span>{term}</span>
                </CommandItem>
              ))}
            </CommandGroup>
          )}

          <CommandGroup heading={t("common.quickActions")}>
            <CommandItem onSelect={() => runCommand(() => navigate("/"))}>
              <Home className="me-2 h-4 w-4 rtl:me-0 rtl:ms-2" />
              <span>{t("resources.dashboard.label")}</span>
            </CommandItem>

            {isStaff && (
              <>
                <CommandItem onSelect={() => runCommand(() => create("classes"))}>
                  <PlusCircle className="me-2 h-4 w-4 text-primary rtl:me-0 rtl:ms-2" />
                  <span>{t("buttons.createClass")}</span>
                </CommandItem>
                <CommandItem onSelect={() => runCommand(() => list("submissions"))}>
                  <ClipboardCheck className="me-2 h-4 w-4 text-primary rtl:me-0 rtl:ms-2" />
                  <span>{t("resources.submissions.label")}</span>
                </CommandItem>
                <CommandItem onSelect={() => runCommand(() => navigate("/ai-assistant"))}>
                  <Sparkles className="me-2 h-4 w-4 text-primary rtl:me-0 rtl:ms-2" />
                  <span>{t("resources.ai-assistant.label")}</span>
                </CommandItem>
              </>
            )}

            {isStudent && (
              <CommandItem onSelect={() => runCommand(() => list("classes"))}>
                <GraduationCap className="me-2 h-4 w-4 text-primary rtl:me-0 rtl:ms-2" />
                <span>{t("buttons.joinClass")}</span>
              </CommandItem>
            )}

            <CommandItem onSelect={() => runCommand(() => navigate("/calendar"))}>
              <Calendar className="me-2 h-4 w-4 rtl:me-0 rtl:ms-2" />
              <span>{t("resources.calendar.label")}</span>
            </CommandItem>
          </CommandGroup>

          {results.length > 0 && (
            <CommandGroup heading={t("common.searchResults")}>
              {results.map((res) => (
                <CommandItem
                  key={`${res.type}-${res.id}`}
                  onSelect={() => runCommand(() => navigate(res.link), res.title)}
                >
                  {getIcon(res.type)}
                  <div className="flex flex-col">
                    <span>{res.title}</span>
                    {res.description && (
                        <span className="text-[10px] text-muted-foreground line-clamp-1">{res.description}</span>
                    )}
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          )}

          <CommandSeparator />
          <CommandGroup heading={t("common.settings")}>
            <CommandItem
              onSelect={() =>
                runCommand(() => identity?.id && show("users", identity.id))
              }
            >
              <UserIcon className="me-2 h-4 w-4 rtl:me-0 rtl:ms-2" />
              <span>{t("resources.portfolio.label")}</span>
              <CommandShortcut className="ltr:block rtl:hidden">⌘P</CommandShortcut>
            </CommandItem>
            <CommandItem
              onSelect={() =>
                runCommand(() => setTheme(theme === "dark" ? "light" : "dark"))
              }
            >
              {theme === "dark" ? (
                <Sun className="me-2 h-4 w-4 rtl:me-0 rtl:ms-2" />
              ) : (
                <Moon className="me-2 h-4 w-4 rtl:me-0 rtl:ms-2" />
              )}
              <span>{t("common.toggleTheme")}</span>
              <CommandShortcut className="ltr:block rtl:hidden">⌘T</CommandShortcut>
            </CommandItem>
            <CommandItem onSelect={() => runCommand(() => logout())}>
              <LogOut className="me-2 h-4 w-4 text-destructive rtl:me-0 rtl:ms-2" />
              <span className="text-destructive">{t("buttons.signOut")}</span>
            </CommandItem>
          </CommandGroup>
        </CommandList>
      </CommandDialog>
    </>
  );
}

import React, { useState, useRef } from "react";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Label } from "./ui/label";
import { Loader2, Upload, File as FileIcon, X, CheckCircle2 } from "lucide-react";
import { toast } from "sonner";
import { BACKEND_URL } from "@/config";
import { useTranslation } from "react-i18next";

interface FileUploadProps {
  onUploadSuccess: (url: string, publicId: string) => void;
  onClear?: () => void;
  folder?: string;
  label?: string;
  accept?: string;
  maxSize?: number; // In bytes
}

const DEFAULT_MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

export const FileUpload: React.FC<FileUploadProps> = ({ 
  onUploadSuccess, 
  onClear,
  folder = "general",
  label,
  accept = ".pdf,.doc,.docx,.jpg,.jpeg,.png,.webp",
  maxSize = DEFAULT_MAX_FILE_SIZE
}) => {
  const { t } = useTranslation();
  const [file, setFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadComplete, setUploadComplete] = useState(false);
  const [uploadedPublicId, setUploadedPublicId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      
      // Fix for truncated code in original diff
      if (selectedFile.size > maxSize) {
        toast.error(t("common.upload.tooLarge"), {
          description: t("common.upload.tooLargeDesc", { size: (maxSize / (1024 * 1024)).toFixed(0) })
        });
        if (fileInputRef.current) fileInputRef.current.value = "";
        return;
      }

      setFile(selectedFile);
      setUploadComplete(false);
      setUploadedPublicId(null);
    }
  };

  const handleUpload = async () => {
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append("file", file);
    formData.append("folder", folder);

    try {
      const token = localStorage.getItem("token"); // Get token for authorization
      const response = await fetch(`${BACKEND_URL}/upload`, {
        method: "POST",
        body: formData,
        headers: {
             ...(token ? { Authorization: `Bearer ${token}` } : {})
        }
      });

      if (!response.ok) {
        const errorData = await response.json();
        toast.error(errorData.message || t("common.upload.error"));
        setIsUploading(false);
        return;
      }

      const result = await response.json();
      onUploadSuccess(result.data.url, result.data.publicId);
      setUploadedPublicId(result.data.publicId);
      setUploadComplete(true);
      toast.success(t("common.upload.success"));
    } catch (error: any) {
      console.error("Upload Error:", error);
      const message = error instanceof Error ? error.message : t("common.upload.error");
      toast.error(message);
    } finally {
      setIsUploading(false);
    }
  };

  const clearFile = () => {
    setFile(null);
    setUploadComplete(false);
    setUploadedPublicId(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
    onClear?.();
  };

  const handleContainerClick = () => {
      // Trigger file input click only if not uploading
      if (!isUploading && !file) {
        fileInputRef.current?.click();
      }
  };

  const isVideo = folder === "trailers" || (accept && accept.includes("video"));

  return (
    <div className="space-y-3 w-full">
      {label && (
        <Label className="text-sm font-medium">
          {label}
        </Label>
      )}
      
      {!file ? (
        <div 
          onClick={handleContainerClick}
          className="border-2 border-dashed rounded-lg p-6 flex flex-col items-center justify-center bg-muted/20 hover:bg-muted/30 transition-colors cursor-pointer relative min-h-[120px]"
        >
          <input
            ref={fileInputRef}
            type="file"
            className="hidden"
            onChange={handleFileChange}
            accept={accept}
          />
          <Upload className="h-8 w-8 text-muted-foreground mb-2" />
          <p className="text-sm font-medium text-muted-foreground">{t("common.upload.clickOrDrag")}</p>
          <p className="text-xs text-muted-foreground/60 mt-1">
            {t("common.upload.maxSize", { size: (maxSize / (1024 * 1024)).toFixed(0) })}
          </p>
        </div>
      ) : (
        <div className="flex flex-col gap-3 p-4 border rounded-lg bg-background shadow-sm">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center gap-3 min-w-0">
              <div className="p-2 bg-primary/10 rounded-md shrink-0">
                <FileIcon className="h-5 w-5 text-primary" />
              </div>
              <div className="flex flex-col min-w-0">
                <span className="text-sm font-medium truncate max-w-50 sm:max-w-xs block">
                  {file.name}
                </span>
                <span className="text-xs text-muted-foreground">
                  {(file.size / (1024 * 1024)).toFixed(2)} MB
                </span>
              </div>
            </div>
            
            <Button 
              variant="ghost" 
              size="icon" 
              onClick={(e) => {
                  e.stopPropagation();
                  clearFile();
              }} 
              disabled={isUploading}
              className="h-8 w-8 shrink-0 text-muted-foreground hover:text-destructive hover:bg-destructive/10"
              title={t("common.upload.remove")}
            >
              <X className="h-4 w-4" />
            </Button>
          </div>

          <div className="flex justify-end pt-2 border-t mt-1">
            {!uploadComplete ? (
              <Button 
                size="sm" 
                onClick={(e) => {
                    e.stopPropagation();
                    handleUpload();
                }}
                disabled={isUploading}
                className="w-full sm:w-auto min-w-[100px]"
              >
                {isUploading ? (
                  <>
                    <Loader2 className="me-2 h-4 w-4 animate-spin" />
                    {t("buttons.uploading")}
                  </>
                ) : (
                  <>
                    <Upload className="me-2 h-4 w-4" />
                    {t("common.upload.label")}
                  </>
                )}
              </Button>
            ) : (
              <div className="flex items-center gap-2 text-green-600 text-sm font-medium w-full justify-end bg-green-50/50 dark:bg-green-900/10 p-2 rounded">
                <CheckCircle2 className="h-4 w-4" />
                {t("common.upload.uploaded")}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from "react";
import { useNavigation } from "@refinedev/core";
import { socket } from "@/lib/socket";
import { Button } from "@/components/ui/button";
import { Video, X } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useTranslation } from "react-i18next";
import axios from "axios";
import { BACKEND_URL } from "@/config";
import { cn } from "@/lib/utils";

interface LiveClass {
  id: number;
  name: string;
  subject?: { name: string };
}

export const GlobalLiveIndicator = () => {
  const { t, i18n } = useTranslation();
  const { show } = useNavigation();
  const [liveClasses, setLiveClasses] = useState<LiveClass[]>([]);
  const isAr = i18n.language === "ar";

  useEffect(() => {
    // 1. Initial Load: Fetch already live classes
    const fetchLive = async () => {
      try {
        const response = await axios.get(`${BACKEND_URL}/classes/live`, { withCredentials: true });
        setLiveClasses(response.data?.data || []);
      } catch (err) {
        console.error("Failed to fetch initial live classes:", err);
      }
    };
    void fetchLive();

    // 2. Real-time Listeners
    const handleStarted = () => {
        // Fetch full class details to get the name
        void fetchLive(); 
    };

    const handleEnded = (data: { classId: number }) => {
        setLiveClasses(prev => prev.filter(c => c.id !== data.classId));
    };

    socket.on("live_session_started", handleStarted);
    socket.on("live_session_ended", handleEnded);

    return () => {
      socket.off("live_session_started", handleStarted);
      socket.off("live_session_ended", handleEnded);
    };
  }, []);

  if (liveClasses.length === 0) return null;

  const currentClass = liveClasses[0]; // Show the most recent one

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: -20, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: -20, scale: 0.95 }}
        className="fixed top-20 start-1/2 -translate-x-1/2 z-[100] w-full max-w-xs md:max-w-sm px-4"
      >
        <div className="bg-live-primary text-white rounded-2xl shadow-2xl shadow-live-primary/40 border border-white/20 p-1 flex items-center gap-3 overflow-hidden backdrop-blur-md">
          <div className="bg-white/20 p-2 rounded-xl animate-pulse">
            <Video className="h-4 w-4 md:h-5 md:w-5" />
          </div>
          
          <div className="flex-1 min-w-0 py-1">
            <p className="text-[10px] font-black uppercase tracking-widest opacity-80 leading-none">
              {t("classes.live.indicator.liveNow", "Live Now")}
            </p>
            <h4 className="text-xs md:text-sm font-bold truncate pe-2">
              {currentClass.name}
            </h4>
          </div>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => show("classes", currentClass.id.toString(), { tab: "live" } as any)}
            className="h-8 md:h-10 rounded-xl bg-white text-live-primary hover:bg-white/90 font-black text-[10px] uppercase tracking-tighter px-3 md:px-4"
          >
            {t("notifications.joinNow", "Join")}
          </Button>

          <Button
            variant="ghost"
            size="icon"
            onClick={() => setLiveClasses([])}
            className="h-8 w-8 rounded-full hover:bg-white/10 text-white/60"
          >
            <X className="h-3 w-3" />
          </Button>
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

import React from "react";
import { useLocation } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useNavigation } from "@refinedev/core";
import { 
  Sheet, 
  SheetContent, 
  SheetDescription, 
  SheetHeader, 
  SheetTitle, 
  SheetTrigger 
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { 
  HelpCircle, 
  BookOpen, 
  Sparkles, 
  CheckCircle2, 
  ArrowRight,
  Lightbulb
} from "lucide-react";
import { motion } from "framer-motion";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";

interface HelpStep {
  title: string;
  description: string;
  actionId?: string;
}

export const HelpHub = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const { list } = useNavigation();
  const [isOpen, setIsOpen] = React.useState(false);
  const path = location.pathname;
  const hash = location.hash;

  // Logic to determine help content based on route
  const getPathKey = () => {
    if (path === "/dashboard") return "dashboard";
    if (path.startsWith("/classes/")) {
        if (hash === "#curriculum") return "classCurriculum";
        if (hash === "#attendance") return "classAttendance";
        return "classHub";
    }
    if (path === "/assignments/create") return "createAssignment";
    if (path === "/ai-study-lab") return "studyLab";
    return "general";
  };

  const key = getPathKey();

  // FIX: Use 'as any' to bypass the complex i18next union type issues with returnObjects
  const steps = t(`help.pages.${key}.steps` as any, { returnObjects: true }) as unknown as HelpStep[];
  const tips = t(`help.pages.${key}.tips` as any, { returnObjects: true }) as unknown as string[];

  const handleAskAi = () => {
    setIsOpen(false);
    list("ai-assistant");
  };

  const handleStepClick = (actionId?: string) => {
    if (!actionId) return;
    
    setIsOpen(false);
    
    // Small delay to let the sheet close
    setTimeout(() => {
      const element = document.getElementById(actionId);
      if (element) {
        element.scrollIntoView({ behavior: "smooth", block: "center" });
        
        // Visual feedback
        element.classList.add("ring-4", "ring-primary", "ring-offset-4", "transition-all", "duration-500", "z-50");
        
        // Trigger click if it's a button
        if (element.tagName === "BUTTON") {
            (element as HTMLButtonElement).click();
        }

        setTimeout(() => {
          element.classList.remove("ring-4", "ring-primary", "ring-offset-4");
        }, 3000);
      }
    }, 400);
  };

  return (
    <Sheet open={isOpen} onOpenChange={setIsOpen}>
      <SheetTrigger asChild>
        <Button 
          variant="ghost" 
          size="icon" 
          className="relative h-9 w-9 md:h-10 md:w-10 rounded-full bg-primary/5 hover:bg-primary/10 text-primary transition-all duration-300 group"
        >
          <HelpCircle className="h-5 w-5 md:h-6 md:w-6 transition-transform group-hover:scale-110" />
          <span className="sr-only">Help</span>
          <span className="absolute -top-1 -end-1 flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-20"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-primary/40"></span>
          </span>
        </Button>
      </SheetTrigger>
      <SheetContent className="w-full sm:max-w-md border-l border-border/40 bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none p-0 shadow-2xl">
        <ScrollArea className="h-full">
          <div className="p-6 space-y-8">
            <SheetHeader className="text-start">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 rounded-xl bg-primary/10 text-primary">
                  <Lightbulb className="h-5 w-5 animate-pulse" />
                </div>
                <SheetTitle className="text-2xl font-black tracking-tight">
                  {t(`help.pages.${key}.title` as any, { defaultValue: t("help.pages.general.title" as any) })}
                </SheetTitle>
              </div>
              <SheetDescription className="text-base font-medium text-muted-foreground">
                {t(`help.pages.${key}.description` as any, { defaultValue: t("help.pages.general.description" as any) })}
              </SheetDescription>
            </SheetHeader>

            {/* How-to Steps */}
            <div className="space-y-4">
              <div className="flex items-center justify-between px-1">
