import { useEffect, useState } from "react";
import { socket } from "@/lib/socket";
import { Zap } from "lucide-react";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";

interface XPGain {
  id: number;
  amount: number;
  reason?: string;
}

export function XPGainPopup() {
  const { t, i18n } = useTranslation();
  const isArabic = i18n.language === 'ar';
  const [gains, setGains] = useState<XPGain[]>([]);

  const formatNumber = (num: number) => {
    return new Intl.NumberFormat(isArabic ? 'ar-EG' : 'en-US').format(num);
  };

  useEffect(() => {
    socket.connect();

    const handleXPGained = (data: { amount: number; reason?: string }) => {
      const id = Date.now();
      setGains((prev) => [...prev, { id, amount: data.amount, reason: data.reason }]);
      
      // Remove after animation (3 seconds)
      setTimeout(() => {
        setGains((prev) => prev.filter((g) => g.id !== id));
      }, 3000);
    };

    const handleLocalXPGained = (event: any) => {
      handleXPGained(event.detail);
    };

    socket.on("xp_gained", handleXPGained);
    window.addEventListener("xp_gained_local", handleLocalXPGained);

    return () => {
      socket.off("xp_gained", handleXPGained);
      window.removeEventListener("xp_gained_local", handleLocalXPGained);
      socket.disconnect();
    };
  }, []);

  return (
    <div className={cn(
        "fixed bottom-8 z-[100] flex flex-col gap-2 pointer-events-none",
        "end-8"
    )}>
      {gains.map((gain) => (
        <div
          key={gain.id}
          className={cn(
            "bg-gold-primary text-white px-4 py-2 rounded-full shadow-lg flex items-center gap-2 border-2 border-white/20 backdrop-blur-md",
            "animate-in slide-in-from-bottom-4 fade-in duration-500 fill-mode-both"
          )}
        >
          <Zap className={cn("h-4 w-4 fill-white", isArabic && "order-last")} />
          <span className="font-black text-sm">+{formatNumber(gain.amount)} {t("common.xp")}</span>
          {gain.reason && (
            <span className={cn(
                "text-[10px] font-bold uppercase opacity-80",
                isArabic ? "border-r border-white/20 pe-2 order-first" : "border-l border-white/20 ps-2"
            )}>
              {gain.reason}
            </span>
          )}
        </div>
      ))}
    </div>
  );
}

import React, { createContext, useContext, useEffect, useState } from "react";
import { useGetIdentity } from "@refinedev/core";
import { User } from "@/types";
import { socket, connectSocket } from "@/lib/socket"; 
import axios from "axios";
import { BACKEND_URL } from "@/config";

interface SocketContextType {
  socket: typeof socket | null;
  isConnected: boolean;
}

const SocketContext = createContext<SocketContextType>({
  socket: null,
  isConnected: false,
});

export const useSocket = () => useContext(SocketContext);

export const SocketProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { data: user, isLoading } = useGetIdentity<User>();
  const [isConnected, setIsConnected] = useState(socket.connected);

  useEffect(() => {
    if (isLoading) return;

    if (user?.id) {
      // Establish secure connection
      void connectSocket().then(async () => {
          // 🚀 GLOBAL SYNC: Join all class rooms for this user
          try {
              const response = await axios.get(`${BACKEND_URL}/classes/mine`, { withCredentials: true });
              const classes = response.data?.data || [];
              classes.forEach((c: any) => {
                  socket.emit("join_class", c.id);
                  console.log(`[Socket] Globally joined class room: ${c.id}`);
              });
          } catch (err) {
              console.error("Failed to auto-join class rooms:", err);
          }
      });

      const onConnect = () => setIsConnected(true);
      const onDisconnect = () => setIsConnected(false);

      socket.on("connect", onConnect);
      socket.on("disconnect", onDisconnect);

      setIsConnected(socket.connected);

      return () => {
        socket.off("connect", onConnect);
        socket.off("disconnect", onDisconnect);
        socket.disconnect();
      };
    } else {
      if (socket.connected) {
        socket.disconnect();
        setIsConnected(false);
      }
    }
  }, [user?.id, isLoading]);

  return (
    <SocketContext.Provider value={{ socket, isConnected }}>
      {children}
    </SocketContext.Provider>
  );
};

import React, { createContext, useContext, useEffect, useState } from "react";
import { useList } from "@refinedev/core";
import { AcademicTerm } from "@/types";

interface TermContextType {
  currentTerm: AcademicTerm | null;
  selectedTerm: AcademicTerm | null;
  setSelectedTerm: (term: AcademicTerm) => void;
  terms: AcademicTerm[];
  isLoading: boolean;
}

const TermContext = createContext<TermContextType | undefined>(undefined);

export const TermProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [selectedTerm, setSelectedTerm] = useState<AcademicTerm | null>(null);
  
  // Refine useList implementation returns { result, query }
  const { result, query } = useList<AcademicTerm>({
    resource: "academic-terms",
    sorters: [
      {
        field: "startDate",
        order: "desc",
      },
    ],
    queryOptions: {
      staleTime: 5 * 60 * 1000, 
    }
  });

  const terms = result?.data || [];
  const isLoading = query.isLoading;
  
  const currentTerm =
    terms.find((t: AcademicTerm) => t.status === "active") || terms[0] || null;

  useEffect(() => {
    if (currentTerm && !selectedTerm) {
      setSelectedTerm(currentTerm);
    }
  }, [currentTerm, selectedTerm]);

  return (
    <TermContext.Provider
      value={{
        currentTerm,
        selectedTerm,
        setSelectedTerm,
        terms,
        isLoading,
      }}
    >
      {children}
    </TermContext.Provider>
  );
};

export const useTerm = () => {
  const context = useContext(TermContext);
  if (context === undefined) {
    throw new Error("useTerm must be used within a TermProvider");
  }
  return context;
};

