import { useForm } from "@refinedev/react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useSearchParams, useLocation } from "react-router-dom";
import { useGo, useList } from "@refinedev/core";
import { toast } from "sonner";
import { useFieldArray } from "react-hook-form";
import { Module, Class } from "@/types";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { TFunction } from "i18next";

const createAssignmentSchema = (t: TFunction) => z.object({
  title: z.string().min(1, t("assignments.create.validation.titleRequired")),
  description: z.string().optional(),
  dueDate: z.string().optional(),
  fileUrl: z.string().optional(),
  fileCldPubId: z.string().optional(),
  moduleId: z.coerce.number().optional().nullable(),
  classId: z.coerce.number().min(1, t("assignments.create.validation.classRequired")),
  hasPeerReview: z.boolean().default(false),
  isGroupAssignment: z.boolean().default(false),
  peerReviewWeight: z.coerce.number().min(0).max(100).default(20),
  rubric: z.array(z.object({
    criteria: z.string().min(1, t("assignments.create.validation.criteriaRequired")),
    maxPoints: z.coerce.number().min(1, t("assignments.create.validation.pointsRequired")),
  })).default([]),
});

export type AssignmentFormValues = z.infer<ReturnType<typeof createAssignmentSchema>>;

interface LocationState {
  pendingContent?: string;
}

export const useAssignmentForm = () => {
  const { t, i18n } = useTranslation();
  const [searchParams] = useSearchParams();
  const location = useLocation();
  const urlClassId = searchParams.get("classId");
  const initialModuleId = searchParams.get("moduleId");
  const go = useGo();
  const [showAI, setShowAI] = useState(false);
  const isAr = i18n.language === 'ar';

  const { query: classesQuery } = useList<Class>({
    resource: "classes",
    pagination: { mode: "off" },
  });

  const form = useForm<AssignmentFormValues>({
    resolver: zodResolver(createAssignmentSchema(t)) as any,
    defaultValues: {
      title: "",
      description: "",
      dueDate: "",
      fileUrl: "",
      fileCldPubId: "",
      moduleId: initialModuleId ? Number(initialModuleId) : null,
      classId: urlClassId ? Number(urlClassId) : undefined as unknown as number,
      hasPeerReview: false,
      isGroupAssignment: false,
      peerReviewWeight: 20,
      rubric: [{ criteria: "Accuracy", maxPoints: 10 }, { criteria: "Clarity", maxPoints: 10 }],
    },
    warnWhenUnsavedChanges: true,
    refineCoreProps: {
      resource: "assignments",
      action: "create",
      onMutationSuccess: () => {
        const targetClassId = form.getValues("classId");
        localStorage.removeItem("draft:assignment:new"); // Clear draft on success
        go({ to: `/classes/show/${targetClassId}`, type: "replace" });
      },
    },
  });

  // 🛡️ AUTO-DRAFT PERSISTENCE: Save form state to localStorage
  const watchedValues = form.watch();
  useEffect(() => {
      const draft = {
          title: watchedValues.title,
          description: watchedValues.description,
          classId: watchedValues.classId,
          moduleId: watchedValues.moduleId
      };
      if (draft.title || draft.description) {
          localStorage.setItem("draft:assignment:new", JSON.stringify(draft));
      }
  }, [watchedValues.title, watchedValues.description, watchedValues.classId, watchedValues.moduleId]);

  // 🚀 DRAFT RECOVERY: Restore state on mount
  useEffect(() => {
      const savedDraft = localStorage.getItem("draft:assignment:new");
      if (savedDraft) {
          try {
              const parsed = JSON.parse(savedDraft);
              if (parsed.title && !form.getValues("title")) form.setValue("title", parsed.title);
              if (parsed.description && !form.getValues("description")) form.setValue("description", parsed.description);
              if (parsed.classId && !form.getValues("classId")) form.setValue("classId", parsed.classId);
          } catch (e) {
              console.error("Draft recovery failed", e);
          }
      }
  }, [form]);

  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "rubric",
  });

  const selectedClassId = form.watch("classId");

  const { query: modulesQuery } = useList<Module>({
    resource: "modules",
    filters: [{ field: "classId", operator: "eq", value: selectedClassId }],
    queryOptions: { enabled: !!selectedClassId },
  });

  useEffect(() => {
    if (initialModuleId) form.setValue("moduleId", Number(initialModuleId));
    
    const stateContent = (location.state as LocationState)?.pendingContent;
    const sessionContent = sessionStorage.getItem("pending_ai_assignment");
    const pendingContent = stateContent || sessionContent;

    if (pendingContent) {
        form.setValue("description", pendingContent);
        if (sessionContent) sessionStorage.removeItem("pending_ai_assignment");
        toast.info(t("assignments.create.toasts.aiDraftApplied"));
        setShowAI(false);
    }
  }, [initialModuleId, location.state, t, form]);

  const handleUseAIContent = (content: string) => {
    form.setValue("description", content);
    toast.success(t("assignments.create.toasts.aiContentApplied"));
    document.getElementById("description")?.scrollIntoView({ behavior: "smooth" });
  };

  const handleFileUpload = (url: string, publicId: string) => {
    form.setValue("fileUrl", url);
    form.setValue("fileCldPubId", publicId);
  };

  return {
    form,
    rubric: { fields, append, remove },
    data: {
      classes: classesQuery.data?.data || [],
      modules: modulesQuery.data?.data || [],
      isLoading: classesQuery.isLoading || modulesQuery.isLoading,
      urlClassId,
      isAr,
      showAI
    },
    state: { setShowAI },
    actions: { handleUseAIContent, handleFileUpload }
  };
};

import { useForm } from "@refinedev/react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import {
  useCustomMutation,
  useNotification,
  useUpdate,
  HttpError,
} from "@refinedev/core";
import { useQueryClient } from "@tanstack/react-query";
import {
  Submission,
  Assignment,
  AIFeedbackResponse,
  GetOneResponse,
} from "@/types";
import { useEffect, useState } from "react";
import {
  Sparkles,
  Loader2,
  FileText,
  User as UserIcon,
  Copy,
  Check,
  Download,
  ExternalLink,
  MessageSquareQuote,
  Trophy,
  PartyPopper,
  RotateCcw,
  Lock,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { LoadingButton } from "@/components/ui/loading-button";
import { SubmitHandler } from "react-hook-form";
import { motion, AnimatePresence } from "framer-motion";
import Confetti from "react-confetti";
import { useWindowSize } from "react-use";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { useTranslation } from "react-i18next";
import { TFunction } from "i18next";
import { toast } from "sonner";
import { useUserRole } from "@/hooks/use-user-role";

const gradingSchema = (t: TFunction) =>
  z.object({
    grade: z.coerce
      .number()
      .min(0, t("assignments.grading.validation.min"))
      .max(100, t("assignments.grading.validation.max")),
    feedback: z.string().optional(),
    requiresResubmission: z.boolean().default(false),
    teacherPrivateNotes: z.string().optional(),
    aiApprovalStatus: z.string().optional(),
  });

type GradingFormValues = z.infer<ReturnType<typeof gradingSchema>>;

interface GradingDialogProps {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  submission: (Submission & { assignment?: Assignment }) | null;
  readOnly?: boolean;
}

export const GradingDialog = ({
  isOpen,
  onOpenChange,
  submission,
  readOnly = false,
}: GradingDialogProps) => {
  const { t, i18n } = useTranslation();
  const { open } = useNotification();
  const { width, height } = useWindowSize();
  const { isStaff: _isStaff } = useUserRole();
  const isStaff = _isStaff && !readOnly;

  const [hasAutoAnalyzed, setHasAutoAnalyzed] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isAISuggested, setIsAISuggested] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);

  const { mutate: updateSubmission, mutation: updateMutation } = useUpdate<
    Submission,
    HttpError,
    GradingFormValues
  >();
  const isUpdating = updateMutation.isPending;
  const queryClient = useQueryClient();

  const form = useForm<GradingFormValues>({
    resolver: zodResolver(gradingSchema(t)) as any,
    defaultValues: {
      grade: submission?.grade ?? 0,
      feedback: submission?.feedback ?? "",
      requiresResubmission: submission?.requiresResubmission ?? false,
      teacherPrivateNotes: submission?.teacherPrivateNotes ?? "",
    },
  });

  const { handleSubmit, control, setValue, watch } = form;

  const currentGrade = watch("grade");
  const isDraft = submission?.isDraft;
  const isAr = i18n.language === "ar";

  const { mutate: getAIFeedback, mutation: aiMutation } =
    useCustomMutation<AIFeedbackResponse>();
  const isAILoading = aiMutation.isPending;

  useEffect(() => {
    if (isOpen) {
      setHasAutoAnalyzed(false);
      setIsAISuggested(false);
      setShowConfetti(false);
    }
  }, [isOpen, submission?.id]);

  useEffect(() => {
    if (submission) {
      setValue("grade", submission.grade ?? submission.suggestedGrade ?? 0);
      setValue(
        "feedback",
        submission.feedback ?? submission.suggestedFeedback ?? "",
      );
      setValue(
        "requiresResubmission",
        submission.requiresResubmission ?? false,
      );
      setValue("teacherPrivateNotes", submission.teacherPrivateNotes ?? "");

      if (
        isStaff &&
        isOpen &&
        !submission.grade &&
        !submission.suggestedGrade &&
        !hasAutoAnalyzed &&
        !isAILoading &&
        !isDraft
      ) {
        handleAIGrade();
        setHasAutoAnalyzed(true);
      }
    }
  }, [
    submission,
    setValue,
    isOpen,
    isStaff,
    hasAutoAnalyzed,
    isAILoading,
    isDraft,
  ]);

  const onSubmit: SubmitHandler<GradingFormValues> = async (values) => {
    if (!isStaff || !submission?.id || isDraft) return;

    // Optimistic Update Setup
    const queryKey = ["submissions", submission.id.toString()];
    await queryClient.cancelQueries({ queryKey });
    const previousData = queryClient.getQueryData(queryKey);

    // Update Cache Immediately
    queryClient.setQueryData(queryKey, (old: GetOneResponse<Submission> | undefined) => {
      if (!old || !old.data) return old;
      return {
        ...old,
        data: { ...old.data, ...values, updatedAt: new Date().toISOString() },
      };
    });

    updateSubmission(
      {
        resource: "submissions",
        id: submission.id,
        values: {
            ...values,
            aiApprovalStatus: "approved"
        },
      },
      {
        onSuccess: () => {
          setIsSuccess(true);
          if (values.grade >= 90) {
            setShowConfetti(true);
          }
          setTimeout(() => {
            setIsSuccess(false);
            onOpenChange(false);
          }, 1500);
        },
        onError: () => {
          // Rollback on error
          queryClient.setQueryData(queryKey, previousData);
          toast.error("Failed to save grade.");
        },
      },
    );
  };

  const handleAIGrade = () => {
    if (!submission || !isStaff || isDraft) return;

    getAIFeedback(
      {
        url: `/submissions/${submission.id}/ai-grade`,
        method: "post",
        values: {},
      },
      {
        onSuccess: (data) => {
          const { suggestedGrade, feedback } = data.data;
          setValue("grade", Number(suggestedGrade));
          setValue("feedback", feedback);
          setIsAISuggested(true);
          open?.({
            type: "success",
            message: t("assignments.grading.toasts.aiComplete"),
            description: t("assignments.grading.toasts.aiApplied"),
          });
        },
      },
    );
  };

  const copyToClipboard = () => {
    if (!submission?.content) return;
    navigator.clipboard.writeText(submission.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const wordCount =
    submission?.content?.trim().split(/\s+/).filter(Boolean).length ?? 0;

  if (!submission) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent
        className="sm:max-w-[800px] max-h-[90vh] overflow-y-auto border-none shadow-2xl p-0 overflow-hidden text-left bg-background/95 backdrop-blur-xl"
        style={{ direction: isAr ? "rtl" : "ltr" }}
      >
        {showConfetti && (
          <Confetti
            width={width}
            height={height}
            recycle={false}
            numberOfPieces={200}
            gravity={0.2}
            colors={["#4f46e5", "#9333ea", "#db2777", "#22c55e"]}
          />
        )}

        <div className="h-1.5 bg-gradient-to-r from-primary via-ai-primary to-primary w-full" />

        <div className="p-0 space-y-0 relative">
          {/* Success Overlay */}
          <AnimatePresence>
            {isSuccess && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 z-50 bg-background/80 backdrop-blur-sm flex flex-col items-center justify-center gap-4"
              >
                <motion.div
                  initial={{ scale: 0.5, rotate: -10 }}
                  animate={{ scale: 1, rotate: 0 }}
                  className="p-4 rounded-full bg-success/10 text-success"
                >
                  <Check className="h-12 w-12 stroke-[3]" />
                </motion.div>
                <h3 className="text-2xl font-black tracking-tight">
                  {t("assignments.grading.gradeSaved")}
                </h3>
                {currentGrade >= 90 && (
                  <motion.div
                    initial={{ y: 10, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.2 }}
                    className="flex items-center gap-2 text-primary font-bold"
                  >
                    <PartyPopper className="h-5 w-5" />
                    <span>{t("assignments.grading.excellentWork")}</span>
                  </motion.div>
                )}
              </motion.div>
            )}
          </AnimatePresence>

          <DialogHeader className="p-6 pb-2 text-start">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div className="space-y-1">
                <div className="flex items-center gap-3">
                  <DialogTitle className="text-2xl font-black tracking-tight flex items-center gap-2">
                    <div className="p-2 rounded-lg bg-primary/10 text-primary">
                      <FileText className="h-5 w-5" />
                    </div>
                    {isStaff
                      ? t("assignments.grading.gradeSubmission")
                      : t("assignments.grading.submissionDetails")}
                  </DialogTitle>
                  <Badge
                    variant="outline"
                    className="bg-primary/5 text-primary border-primary/10 font-black text-[10px] uppercase tracking-widest px-3 py-1 rounded-lg"
                  >
                    {t("assignments.grading.attempt", {
                      count: submission.attemptNumber,
                    })}
                  </Badge>
                  {isDraft && (
                    <Badge className="bg-amber-500/10 text-amber-600 border-none font-black text-[10px] uppercase tracking-widest px-3 py-1 rounded-lg">
                      {t("assignments.grading.draft")}
                    </Badge>
                  )}
                </div>
                <DialogDescription className="font-medium flex items-center gap-2 mt-1">
                  <UserIcon className="h-3.5 w-3.5 text-muted-foreground" />
                  <span className="text-muted-foreground text-xs uppercase tracking-wider font-bold">
                    {t("assignments.grading.studentLabel")}
                  </span>
                  <span className="text-foreground font-bold bg-primary/5 px-2 py-0.5 rounded-md border border-primary/10">
                    {submission.student?.name}
                  </span>
                </DialogDescription>
              </div>
              {isStaff && !isDraft && (
                <Button
                  variant="outline"
                  size="sm"
                  className={cn(
                    "gap-2 rounded-xl transition-all relative overflow-hidden group h-10 px-4",
                    isAILoading
                      ? "border-ai-primary bg-ai-primary/5"
                      : "border-ai-primary/20 text-ai-primary hover:border-ai-primary/40 hover:bg-ai-primary/5",
                  )}
                  onClick={handleAIGrade}
                  disabled={isAILoading}
                >
                  <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:animate-[shine_1.5s_ease-in-out] pointer-events-none" />
                  {isAILoading ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <Sparkles className="h-4 w-4" />
                  )}
                  <span className="font-bold tracking-tight">
                    {isAILoading
                      ? t("buttons.aiAnalyzing")
                      : t("buttons.aiReanalyze")}
                  </span>
                </Button>
              )}
            </div>
          </DialogHeader>

          <div className="p-6 pt-2 grid grid-cols-1 md:grid-cols-2 gap-8 text-start">
            {/* Left Column: Student Work */}
            <div className="space-y-4">
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                    <span className="w-1 h-1 rounded-full bg-primary" />
                    {t("assignments.grading.studentWork")}
                  </Label>
                  {submission.content && (
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-bold text-muted-foreground/60 uppercase tracking-tighter">
                        {t("assignments.form.wordsCount", { count: wordCount })}
                      </span>
                      <button
                        onClick={copyToClipboard}
                        className="text-muted-foreground hover:text-primary transition-colors p-1 rounded-md hover:bg-primary/5"
                        title="Copy to clipboard"
                      >
                        {copied ? (
                          <Check className="h-3.5 w-3.5 text-success" />
                        ) : (
                          <Copy className="h-3.5 w-3.5" />
                        )}
                      </button>
                    </div>
                  )}
                </div>
                <div className="relative group">
                  <div className="p-5 rounded-2xl bg-muted/30 text-sm whitespace-pre-wrap min-h-[250px] max-h-[450px] overflow-y-auto border border-dashed border-muted-foreground/20 leading-relaxed italic shadow-inner scrollbar-thin scrollbar-thumb-primary/10">
                    {submission.content || (
                      <div className="h-full flex flex-col items-center justify-center text-muted-foreground/40 py-20 gap-2">
                        <FileText className="h-8 w-8 opacity-20" />
                        <span className="font-medium italic">
                          {t("assignments.grading.noContent")}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {submission.fileUrl && (
                <div className="flex items-center justify-between p-4 border rounded-2xl bg-primary/5 border-primary/10 group hover:bg-primary/10 transition-all hover:shadow-md hover:-translate-y-0.5">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 rounded-xl bg-white dark:bg-muted/10 shadow-sm group-hover:scale-110 transition-transform">
                      <FileText className="h-5 w-5 text-primary" />
                    </div>
                    <div className="flex flex-col">
                      <span className="text-xs font-bold group-hover:text-primary transition-colors">
                        {t("assignments.grading.attachedDoc")}
                      </span>
                      <span className="text-[10px] text-muted-foreground uppercase font-medium flex items-center gap-1">
                        {t("assignments.grading.viewOrDownload")}{" "}
                        <ExternalLink className="h-2 w-2" />
                      </span>
                    </div>
                  </div>
                  <Button
                    variant="secondary"
                    size="sm"
                    className="h-9 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm gap-2"
                    asChild
                  >
                    <a
                      href={submission.fileUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <Download className="h-3 w-3" />
                      {t("buttons.open")}
                    </a>
                  </Button>
                </div>
              )}
            </div>

            {/* Right Column: Grading Form / Display */}
            <div className="space-y-4">
              {isStaff ? (
                <>
                  {isDraft ? (
                    <div className="h-full flex flex-col items-center justify-center p-10 rounded-3xl bg-amber-500/5 border-2 border-dashed border-amber-500/20 text-center space-y-4">
                      <div className="p-4 rounded-full bg-amber-500/10 text-amber-600">
                        <Lock className="h-10 w-10" />
                      </div>
                      <div className="space-y-2">
                        <h4 className="text-xl font-black tracking-tight text-amber-700">
                          {t("assignments.grading.gradingLocked")}
                        </h4>
                        <p className="text-sm text-amber-600/80 font-medium leading-relaxed">
                          {t("assignments.grading.draftNotice")}
                        </p>
                      </div>
                      <Button
                        variant="outline"
                        className="rounded-xl border-amber-500/20 text-amber-700 hover:bg-amber-500/10 font-bold"
                        onClick={() => onOpenChange(false)}
                      >
                        {t("buttons.closePreview")}
                      </Button>
                    </div>
                  ) : (
                    <Form {...form}>
                      <form
                        onSubmit={handleSubmit(onSubmit as any)}
                        className="space-y-6"
                      >
                        <FormField
                          control={control}
                          name="grade"
                          render={({ field }) => (
                            <FormItem className="space-y-4">
                              <div className="flex items-center justify-between">
                                <FormLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                                  <span className="w-1 h-1 rounded-full bg-primary" />
                                  {t("assignments.grading.finalScore")}
                                </FormLabel>
                                <AnimatePresence>
                                  {isAISuggested && (
                                    <motion.span
                                      initial={{ opacity: 0, x: 10 }}
                                      animate={{ opacity: 1, x: 0 }}
                                      className="text-[9px] font-black uppercase tracking-tighter text-ai-primary bg-ai-primary/10 px-2 py-0.5 rounded-full flex items-center gap-1"
                                    >
                                      <Sparkles className="h-2.5 w-2.5" />{" "}
                                      {t("assignments.grading.aiSuggested")}
                                    </motion.span>
                                  )}
                                </AnimatePresence>
                              </div>
                              <FormControl>
                                <div className="space-y-6">
                                  <div className="relative group">
                                    <Input
                                      type="number"
                                      {...field}
                                      onChange={(e) =>
                                        field.onChange(Number(e.target.value))
                                      }
                                      value={field.value ?? 0}
                                      className="h-20 text-4xl font-black text-center rounded-2xl bg-muted/20 border-2 border-transparent focus-visible:ring-primary focus-visible:border-primary/20 transition-all"
                                    />
                                    <span className="absolute right-6 top-1/2 -translate-y-1/2 text-2xl font-black opacity-20 group-focus-within:opacity-40 transition-opacity">
                                      %
                                    </span>
                                  </div>
                                  <div className="px-2">
                                    <Slider
                                      value={[field.value ?? 0]}
                                      min={0}
                                      max={100}
                                      step={1}
                                      onValueChange={(vals) =>
                                        field.onChange(vals[0])
                                      }
                                      className="cursor-pointer"
                                    />
                                  </div>
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={control}
                          name="feedback"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                                <span className="w-1 h-1 rounded-full bg-primary" />
                                {t("assignments.grading.feedbackToStudent")}
                              </FormLabel>
                              <FormControl>
                                <div className="relative">
                                  <Textarea
                                    placeholder={t(
                                      "assignments.grading.feedbackPlaceholder",
                                    )}
                                    className={cn(
                                      "min-h-[120px] rounded-2xl resize-none bg-muted/10 border-2 border-transparent focus-visible:ring-primary p-5 text-sm leading-relaxed shadow-inner transition-all",
                                      isAISuggested &&
                                        "border-ai-primary/10 bg-ai-primary/[0.02]",
                                    )}
                                    {...field}
                                  />
                                  {isAISuggested && (
                                    <motion.div
                                      initial={{ opacity: 0, scale: 0.5 }}
                                      animate={{ opacity: 0.2, scale: 1 }}
                                      className="absolute bottom-3 right-3"
                                    >
                                      <Sparkles className="h-5 w-5 text-ai-primary" />
                                    </motion.div>
                                  )}
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />

                        <div className="grid grid-cols-1 gap-4">
                          <FormField
                            control={control}
                            name="requiresResubmission"
                            render={({ field }) => (
                              <FormItem className="flex flex-row items-start space-x-3 space-y-0 p-4 rounded-2xl bg-orange-500/5 border border-orange-500/10">
                                <FormControl>
                                  <Checkbox
                                    checked={field.value}
                                    onCheckedChange={field.onChange}
                                  />
                                </FormControl>
                                <div className="space-y-1 leading-none">
                                  <FormLabel className="text-xs font-black uppercase tracking-widest text-orange-700 flex items-center gap-2">
                                    <RotateCcw className="h-3 w-3" />
                                    {t(
                                      "assignments.grading.requiresResubmission",
                                    )}
                                  </FormLabel>
                                  <p className="text-[10px] text-orange-600/60 font-medium">
                                    {t("assignments.grading.resubmissionNote")}
                                  </p>
                                </div>
                              </FormItem>
                            )}
                          />

                          <FormField
                            control={control}
                            name="teacherPrivateNotes"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                                  <Lock className="h-3 w-3" />
                                  {t("assignments.grading.privateNotes")}
                                </FormLabel>
                                <FormControl>
                                  <Textarea
                                    placeholder={t(
                                      "assignments.grading.privatePlaceholder",
                                    )}
                                    className="min-h-[80px] rounded-2xl resize-none bg-muted/5 border-none focus-visible:ring-primary p-4 text-xs leading-relaxed italic"
                                    {...field}
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        </div>

                        <div className="flex gap-3 pt-2">
                          <Button
                            type="button"
                            variant="ghost"
                            className="flex-1 rounded-xl font-bold h-12"
                            onClick={() => onOpenChange(false)}
                          >
                            {t("buttons.cancel")}
                          </Button>
                          <LoadingButton
                            type="submit"
                            isLoading={isUpdating}
                            isSuccess={isSuccess}
                            disabled={isAILoading}
                            className="flex-[2] rounded-xl font-black uppercase tracking-widest shadow-lg shadow-primary/20 h-12"
                          >
                            {t("buttons.saveGrade")}
                          </LoadingButton>
                        </div>
                      </form>
                    </Form>
                  )}
                </>
              ) : (
                <div className="space-y-6">
                  <div className="space-y-2">
                    <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                      <span className="w-1 h-1 rounded-full bg-primary" />
                      {t("assignments.grading.yourScore")}
                    </Label>
                    <motion.div
                      initial={{ scale: 0.95, opacity: 0 }}
                      animate={{ scale: 1, opacity: 1 }}
                      className="h-40 flex flex-col items-center justify-center rounded-3xl bg-primary/5 border-2 border-primary/10 shadow-inner relative overflow-hidden group"
                    >
                      <div className="absolute inset-0 bg-gradient-to-br from-primary/10 to-transparent pointer-events-none" />
                      <div className="absolute -right-4 -top-4 opacity-5 group-hover:opacity-10 transition-opacity rotate-12">
                        <Trophy className="h-32 w-32 text-primary" />
                      </div>
                      <div className="flex items-baseline relative z-10">
                        <span className="text-7xl font-black text-primary tracking-tighter">
                          {submission.grade ?? "--"}
                        </span>
                        <span className="text-2xl font-black text-primary/40 ml-1">
                          %
                        </span>
                      </div>
                      <div className="mt-2 px-3 py-1 rounded-full bg-primary/10 text-[10px] font-black uppercase tracking-widest text-primary relative z-10">
                        {submission.requiresResubmission
                          ? t("assignments.grading.status.requested")
                          : Number(submission.grade) >= 90
                            ? t("assignments.grading.status.excellent")
                            : Number(submission.grade) >= 70
                              ? t("assignments.grading.status.good")
                              : t("assignments.grading.status.improving")}
                      </div>
                    </motion.div>
                  </div>
                  <div className="space-y-2">
                    <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                      <span className="w-1 h-1 rounded-full bg-primary" />
                      {t("assignments.grading.teacherFeedback")}
                    </Label>
                    <motion.div
                      initial={{ y: 10, opacity: 0 }}
                      animate={{ y: 0, opacity: 1 }}
                      transition={{ delay: 0.1 }}
                      className="p-6 rounded-2xl bg-muted/20 border border-muted-foreground/10 min-h-[180px] text-sm leading-relaxed italic shadow-sm relative"
                    >
                      <MessageSquareQuote className="absolute top-4 right-4 h-5 w-5 text-muted-foreground/10" />
                      {submission.feedback ||
                        t("assignments.grading.noFeedback")}
                    </motion.div>
                  </div>
                  <Button
                    className="w-full rounded-xl font-bold h-12 mt-4"
                    onClick={() => onOpenChange(false)}
                  >
                    {t("buttons.close")}
                  </Button>
                </div>
              )}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

import { ListView } from "@/components/refine-ui/views/list-view";
import { 
  Search, 
  FileText, 
  Calendar, 
  Clock, 
  AlertCircle, 
  PlusCircle, 
  Trash2, 
  Edit3, 
  Eye,
  Filter,
  MoreHorizontal,
  CheckCircle2,
  Timer,
  ArrowRight,
  Layers
} from "lucide-react";
import { Input } from "@/components/ui/input";
import { useMemo, useState } from "react";
import { useList, useNavigation, useDelete, useGetIdentity } from "@refinedev/core";
import { Assignment, User, UserRole, Class } from "@/types";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { EmptyState } from "@/components/empty-state";
import { useTerm } from "@/contexts/term-context";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import "dayjs/locale/ar";
import usePageTitle from "@/hooks/use-page-title";
import { Skeleton } from "@/components/ui/skeleton";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useTranslation } from "react-i18next";

dayjs.extend(relativeTime);

type AssignmentListItem = Assignment & { class?: Class; isEnrolled?: boolean };

const AssignmentsListPage = () => {
  const { t, i18n } = useTranslation();
  usePageTitle(t("assignments.list.title"));
  const { data: identity } = useGetIdentity<User>();
  const isStaff = identity?.role === UserRole.ADMIN || identity?.role === UserRole.TEACHER;
  const { selectedTerm } = useTerm();

  const [searchQuery, setSearchQuery] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<number | null>(null);
  const [view, setView] = useState<"discovery" | "my">(identity?.role === UserRole.STUDENT ? "discovery" : "my");

  const { edit, show, create } = useNavigation();
  const { mutate: deleteMutation } = useDelete();

  dayjs.locale(i18n.language === 'ar' ? 'ar' : 'en');

  const filters = useMemo(() => {
    const f = [];
    if (searchQuery) {
      f.push({ field: "title", operator: "contains" as const, value: searchQuery });
    }
    if (selectedTerm) {
        f.push({ field: "termId", operator: "eq" as const, value: selectedTerm.id });
    }
    if (view === "my" && !isStaff && identity?.id) {
        f.push({ field: "my", operator: "eq" as const, value: "true" });
    }
    // IMPORTANT: Filter assignments by teacherId if the current user is a staff member (teacher)
    if (isStaff && identity?.id) {
      f.push({ field: "teacherId", operator: "eq" as const, value: identity.id });
    }
    return f;
  }, [searchQuery, selectedTerm, isStaff, identity?.id, view]);

  const { query: { data: assignmentsData, isLoading } } = useList<AssignmentListItem>({
    resource: "assignments",
    pagination: { pageSize: 50, mode: "server" },
    filters,
    sorters: [{ field: "dueDate", order: "asc" }],
    meta: {
      populate: ["class", "class.subject"]
    }
  });

  const assignments = assignmentsData?.data || [];
  const hasData = assignments.length > 0;

  const handleConfirmDelete = () => {
    if (deleteTarget) {
      deleteMutation({
        resource: "assignments",
        id: deleteTarget,
        mutationMode: "pessimistic",
      });
      setDeleteTarget(null);
    }
  };

  const stats = useMemo(() => {
    if (!assignments.length) return { total: 0, active: 0, overdue: 0 };
    return {
      total: assignments.length,
      active: assignments.filter((a: AssignmentListItem) => !a.dueDate || dayjs().isBefore(dayjs(a.dueDate))).length,
      overdue: assignments.filter((a: AssignmentListItem) => a.dueDate && dayjs().isAfter(dayjs(a.dueDate))).length
    };
  }, [assignments]);

  return (
    <ListView>
      <div className="space-y-8 md:space-y-12">
        {/* Header Section */}
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6"
        >
          <div className="space-y-4 flex-1">
            <div className="space-y-1 text-start">
              <h1 className="page-title mb-0 flex items-center gap-3">
                <div className="p-3 rounded-2xl bg-primary/10 text-primary border border-primary/5 shadow-sm">
                  <FileText className="h-6 w-6 md:h-8 md:w-8" />
                </div>
                {t("assignments.list.title")}
              </h1>
              <p className="text-muted-foreground font-medium max-w-2xl text-balance">
                {t("assignments.list.description")}
              </p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            {!isStaff && (
                <div className="flex bg-muted/50 p-1 rounded-2xl border border-border/40 me-2">
                    <Button 
                        variant={view === "discovery" ? "default" : "ghost"} 
                        size="sm" 
                        className="rounded-xl font-bold px-6"
                        onClick={() => setView("discovery")}
                    >
                        {t("classes.list.discover")}
                    </Button>
                    <Button 
                        variant={view === "my" ? "default" : "ghost"} 
                        size="sm" 
                        className="rounded-xl font-bold px-6"
                        onClick={() => setView("my")}
                    >
                        {t("classes.list.myClassrooms")}
                    </Button>
                </div>
            )}
            {isStaff && (
              <Button 
                onClick={() => create("assignments")}
                size="lg"
                className="w-full md:w-auto rounded-2xl h-12 md:h-14 px-10 font-bold uppercase tracking-widest text-[10px] gap-2 shadow-lg shadow-primary/25 hover:translate-y-[-2px] transition-all"
              >
                <PlusCircle className="h-5 w-5" />
                {t("buttons.createAssignment")}
              </Button>
            )}
          </div>
        </motion.div>

        {/* Stats Row - Adaptive */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 md:gap-6">
          <Card className="p-6 md:p-8 bg-card/40 backdrop-blur-3xl border-border/40 rounded-[2rem] md:rounded-[2.5rem] flex items-center gap-5 shadow-sm">
            <div className="p-3.5 rounded-2xl bg-primary/10 text-primary">
              <FileText className="h-6 w-6 md:h-7 md:w-7" />
            </div>
            <div className="text-start">
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 mb-1">
                {t("assignments.list.stats.total")}
              </p>
              <p className="text-2xl md:text-3xl font-black">
                {isLoading ? "..." : stats.total}
              </p>
            </div>
          </Card>
          <Card className="p-6 md:p-8 bg-card/40 backdrop-blur-3xl border-border/40 rounded-[2rem] md:rounded-[2.5rem] flex items-center gap-5 shadow-sm">
            <div className="p-3.5 rounded-2xl bg-green-500/10 text-green-600">
              <CheckCircle2 className="h-6 w-6 md:h-7 md:w-7" />
            </div>
            <div className="text-start">
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 mb-1">
                {t("assignments.list.stats.active")}
              </p>
              <p className="text-2xl md:text-3xl font-black text-green-600">
                {isLoading ? "..." : stats.active}
              </p>
            </div>
          </Card>
          <Card className="p-6 md:p-8 bg-card/40 backdrop-blur-3xl border-border/40 rounded-[2rem] md:rounded-[2.5rem] flex items-center gap-5 shadow-sm">
            <div className="p-3.5 rounded-2xl bg-destructive/10 text-destructive">
              <Timer className="h-6 w-6 md:h-7 md:w-7" />
            </div>
            <div className="text-start">
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 mb-1">
                {t("assignments.list.stats.overdue")}
              </p>
              <p className="text-2xl md:text-3xl font-black text-destructive">
                {isLoading ? "..." : stats.overdue}
              </p>
            </div>
          </Card>
        </div>
        
        {/* Search & Filters Card - Sticky */}
        <Card className="p-2 border-border/40 bg-muted/20 rounded-[1.75rem] md:rounded-3xl backdrop-blur-md sticky top-20 z-30 shadow-sm">
          <div className="flex flex-col lg:flex-row gap-2">
            <div className="relative flex-1 group">
              <Search className="absolute top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/60 group-focus-within:text-primary transition-colors start-4" />
              <Input
                type="text"
                placeholder={t("assignments.list.filters.searchPlaceholder")}
                className="h-12 rounded-2xl border-none bg-background/50 shadow-none font-medium ps-11 pe-4"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-2 bg-background/50 px-4 py-2 rounded-2xl border border-border/40 shrink-0">
              <Filter className="h-3.5 w-3.5 text-muted-foreground/60" />
              <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/60">{t("assignments.list.filters.active")}</span>
            </div>
          </div>
        </Card>

        {/* Archive Banner */}
        <AnimatePresence>
          {selectedTerm?.status === "archived" && (
            <motion.div 
              initial={{ opacity: 0, scale: 0.98 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.98 }}
              className="bg-amber-500/10 border border-amber-500/20 text-amber-700 dark:text-amber-400 p-6 md:p-8 rounded-[2rem] flex flex-col sm:flex-row items-center sm:items-start gap-5 backdrop-blur-sm text-center sm:text-start"
            >
                <div className="p-3 rounded-[1.25rem] bg-amber-500/20 shrink-0">
                  <AlertCircle className="h-6 w-6 md:h-8 md:w-8" />
                </div>
                <div className="space-y-1">
                  <p className="font-black uppercase tracking-[0.15em] text-[10px] opacity-80">{t("dashboard.archiveViewActive")}</p>
                  <p className="text-base md:text-lg font-bold">
                    {t("dashboard.archiveViewDescription", { termName: selectedTerm.name })}
                  </p>
                </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Assignments List - Global Scroll Behavior */}
        <div className="relative min-h-[400px]">
          {isLoading ? (
            <div className="space-y-4">
              {Array.from({ length: 5 }).map((_, i) => (
                <Card key={i} className="p-6 flex flex-col md:flex-row items-center gap-6 border-border/20 bg-background/50">
                  <Skeleton className="h-20 w-20 rounded-3xl shrink-0" />
                  <div className="flex-1 space-y-4 w-full">
                    <Skeleton className="h-8 w-[350px] max-w-full" />
                    <div className="flex gap-4">
                       <Skeleton className="h-4 w-24" />
                       <Skeleton className="h-4 w-24" />
                    </div>
                  </div>
                  <Skeleton className="h-12 w-36 rounded-2xl" />
                </Card>
              ))}
            </div>
          ) : !hasData ? (
            <div className="flex items-center justify-center p-16 bg-card/20 rounded-[2.5rem] border border-dashed border-border/40">
              <EmptyState
                icon={Layers}
                title={t("assignments.list.noAssignments")}
                description={isStaff ? t("assignments.list.noAssignmentsDescriptionTeacher") : t("assignments.list.noAssignmentsDescriptionStudent")}
                className="border-none bg-transparent min-h-0"
                action={isStaff && selectedTerm?.status === "active" ? {
                  label: t("buttons.createAssignment"),
                  onClick: () => create("assignments"),
                } : undefined}
              />
            </div>
          ) : (
            <div className="space-y-4">
              <AnimatePresence mode="popLayout">
                {assignments.map((assignment, index) => {
                  const isPast = assignment.dueDate && dayjs(assignment.dueDate).isBefore(dayjs());
                  const classColor = assignment.class?.color || "#6366f1";
                  
                  return (
                    <motion.div
                      key={assignment.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      transition={{ delay: index * 0.05 }}
                      className={cn(
                        "group relative flex flex-col md:flex-row items-center p-5 md:p-6 rounded-[2rem] bg-card/50 backdrop-blur-sm border border-border/40 hover:border-primary/30 hover:bg-card/80 transition-all duration-300 shadow-sm hover:shadow-xl hover:shadow-primary/5 cursor-pointer"
                      )}
                      onClick={() => show("assignments", assignment.id)}
                    >
                      {/* Class Color Accent using logical properties */}
                      <div 
                        className="absolute start-0 top-1/2 -translate-y-1/2 w-1.5 h-12 rounded-e-full transition-all group-hover:h-20"
                        style={{ backgroundColor: classColor }}
                      />

                      {/* Icon Container */}
                      <div className="relative shrink-0 mb-4 md:mb-0">
                        <div className={cn(
                            "h-20 w-20 rounded-[1.5rem] border-4 border-background flex items-center justify-center shadow-lg group-hover:scale-105 transition-transform duration-500",
                            isPast ? "bg-destructive/10 text-destructive" : "bg-primary/10 text-primary"
                        )}>
                            <FileText className="h-8 w-8 md:h-10 md:w-10" />
                        </div>
                      </div>

                      {/* Content Area */}
                      <div className={cn("flex-1 min-w-0 w-full text-center md:text-start", "md:ms-8")}>
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 mb-2">
                          <h3 className="text-xl md:text-2xl font-black tracking-tight truncate group-hover:text-primary transition-colors leading-tight">
                            {assignment.title}
                          </h3>
                          <div className="flex items-center justify-center md:justify-start gap-2">
                            <Badge 
                                variant="ai" 
                                className="h-6"
                            >
                                {assignment.class?.name || t("assignments.list.labels.general")}
                            </Badge>
                            {assignment.hasPeerReview && (
                                <Badge className="bg-amber-500/10 text-amber-600 border border-amber-500/20 font-black px-2.5 py-0.5 rounded-full text-[9px] tracking-widest uppercase shadow-sm">
                                    {t("assignments.list.labels.peerReview")}
                                </Badge>
                            )}
                          </div>
                        </div>
                        
                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 md:gap-6 mt-4">
                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <Calendar className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Due Date</span>
                                <span className="text-[11px] font-black text-foreground">
                                    {assignment.dueDate ? dayjs(assignment.dueDate).format("MMM D, YYYY") : t("assignments.list.labels.noDeadline")}
                                </span>
                            </div>
                          </div>

                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <Clock className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Time Remaining</span>
                                <span className={cn(
                                    "text-[11px] font-black uppercase tracking-tight",
                                    isPast ? "text-destructive" : "text-primary"
                                )}>
                                    {assignment.dueDate ? dayjs(assignment.dueDate).fromNow() : t("assignments.list.labels.open")}
                                </span>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Action Area */}
                      <div className="flex items-center gap-3 mt-6 md:mt-0 shrink-0">
                        <div className={cn("hidden lg:flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300 ltr:translate-x-4 rtl:-translate-x-4 group-hover:translate-x-0")}>
                            {isStaff && (
                                <>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-11 w-11 rounded-2xl text-muted-foreground hover:text-primary hover:bg-primary/5 bg-muted/20"
                                        onClick={(e) => { e.stopPropagation(); edit("assignments", assignment.id); }}
                                    >
                                        <Edit3 className="h-5 w-5" />
                                    </Button>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-11 w-11 rounded-2xl text-destructive hover:bg-destructive/10 bg-muted/20"
                                        onClick={(e) => { e.stopPropagation(); setDeleteTarget(assignment.id); }}
                                    >
                                        <Trash2 className="h-5 w-5" />
                                    </Button>
                                </>
                            )}
                        </div>

                        <Button
                          variant={isPast ? "outline" : "default"}
                          size="lg"
                          className={cn(
                            "w-full md:w-auto rounded-2xl px-8 h-12 font-black uppercase tracking-widest text-[10px] transition-all",
                            isPast ?
                              "border-destructive/20 text-destructive hover:bg-destructive/5" :
                              (assignment.isEnrolled || isStaff) ? 
                                "bg-primary hover:bg-primary/90 text-white shadow-lg shadow-primary/20" :
                                "bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-500/20",
                          )}
                          onClick={(e) => {
                              e.stopPropagation();
                              if (!isStaff && !assignment.isEnrolled) {
                                  // Navigate to class show to request enrollment
                                  show("classes", assignment.classId);
                              } else {
                                  show("assignments", assignment.id);
                              }
                          }}
                        >
                          {isStaff ? t("buttons.viewDetails") : (assignment.isEnrolled ? t("buttons.viewDetails") : "Request to Join Class")}
                          <ArrowRight className={cn("h-4 w-4", "ms-2 rtl:-scale-x-100")} />
                        </Button>

                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon" className="h-12 w-12 rounded-2xl md:hidden lg:flex bg-muted/30" onClick={(e) => e.stopPropagation()}>
                                    <MoreHorizontal className="h-5 w-5" />
                                </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end" className="w-64 p-2 rounded-3xl">
                                <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-[0.15em] text-muted-foreground/40 px-3 py-3">{t("assignments.list.labels.options")}</DropdownMenuLabel>
                                <DropdownMenuItem onClick={() => show("assignments", assignment.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                    <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                        <Eye className="h-4 w-4" />
                                    </div>
                                    <span className="font-bold">{t("buttons.viewDetails")}</span>
                                </DropdownMenuItem>
                                {isStaff && (
                                    <>
                                        <DropdownMenuItem onClick={() => edit("assignments", assignment.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                            <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                                <Edit3 className="h-4 w-4" />
                                            </div>
                                            <span className="font-bold">{t("buttons.editAssignment")}</span>
                                        </DropdownMenuItem>
                                        <DropdownMenuSeparator className="my-2 opacity-50" />
                                        <DropdownMenuItem onClick={() => setDeleteTarget(assignment.id)} className="rounded-xl gap-3 py-3 cursor-pointer text-destructive focus:bg-destructive/10">
                                            <div className="p-2 rounded-lg bg-destructive/10 text-destructive">
                                                <Trash2 className="h-4 w-4" />
                                            </div>
                                            <span className="font-bold">{t("buttons.deleteAssignment")}</span>
                                        </DropdownMenuItem>
                                    </>
                                )}
                            </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
          )}
        </div>
      </div>

      <AlertDialog open={deleteTarget !== null} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent className="rounded-[2.5rem] border-none shadow-2xl bg-card/95 backdrop-blur-xl">
          <AlertDialogHeader className="space-y-6">
            <div className="p-5 rounded-2xl bg-destructive/10 text-destructive w-fit mx-auto">
              <Trash2 className="h-10 w-10" />
            </div>
            <div className="space-y-2 text-center">
                <AlertDialogTitle className="text-3xl font-black tracking-tight">{t("assignments.list.deleteDialog.title")}</AlertDialogTitle>
                <AlertDialogDescription className="text-base font-medium px-8 leading-relaxed">
                {t("assignments.list.deleteDialog.description")}
                </AlertDialogDescription>
            </div>
          </AlertDialogHeader>
          <AlertDialogFooter className="sm:justify-center gap-4 pt-8">
            <AlertDialogCancel className="rounded-2xl px-10 h-14 font-black uppercase tracking-widest text-[10px]">{t("buttons.cancel")}</AlertDialogCancel>
            <AlertDialogAction 
                onClick={handleConfirmDelete} 
                className="rounded-2xl px-12 h-14 font-black uppercase tracking-widest text-[10px] bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-xl shadow-destructive/20"
            >
                {t("buttons.confirmDelete")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </ListView>
  );
};

export default AssignmentsListPage;

import { useForm } from "@refinedev/react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Textarea } from "@/components/ui/textarea";
import { Submission, Assignment, ProjectGroup } from "@/types";
import { FileUpload } from "@/components/file-upload";
import {
  Paperclip,
  FileText,
  CheckCircle2,
  Info,
  Sparkles,
  Send,
  Save,
  History,
  Users,
  X,
  Reply
} from "lucide-react";
import { useGo, useInvalidate, useList, HttpError, BaseRecord } from "@refinedev/core";
import { LoadingButton } from "@/components/ui/loading-button";
import { useState, useMemo } from "react";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslation } from "react-i18next";
import { TFunction } from "i18next";

const submissionSchema = (t: TFunction) =>
  z.object({
    content: z.string().min(1, t("assignments.form.toast.contentRequired")),
    fileUrl: z.string().optional(),
    fileCldPubId: z.string().optional(),
    isDraft: z.boolean().default(false),
    groupId: z.coerce.number().optional().nullable(),
    assignmentId: z.number().optional(),
  });

type SubmissionFormValues = z.infer<ReturnType<typeof submissionSchema>>;

interface SubmissionFormProps {
  assignmentId: number;
  existingSubmission?: Submission;
  latestAttemptNumber?: number;
  assignment?: Assignment;
  onCancel?: () => void;
}

export const SubmissionForm = ({
  assignmentId,
  existingSubmission,
  latestAttemptNumber = 0,
  assignment,
  onCancel,
}: SubmissionFormProps) => {
  const { t, i18n } = useTranslation();

  const go = useGo();
  const invalidate = useInvalidate();
  const [isSuccess, setIsSuccess] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");

  // Fetch groups for the class if it's a group assignment
  const { query: groupsQuery } = useList<ProjectGroup>({
    resource: "project-groups",
    filters: [{ field: "classId", operator: "eq", value: assignment?.classId }],
    queryOptions: {
      enabled: !!assignment?.isGroupAssignment && !!assignment?.classId,
    },
  });

  const groups = groupsQuery?.data?.data || [];

  const form = useForm<SubmissionFormValues>({
    resolver: zodResolver(submissionSchema(t)) as any,
    defaultValues: {
      content: existingSubmission?.content ?? "",
      fileUrl: existingSubmission?.fileUrl ?? "",
      fileCldPubId: existingSubmission?.fileCldPubId ?? "",
      isDraft: false,
      groupId: existingSubmission?.groupId ?? null,
    },
    refineCoreProps: {
      resource: "submissions",
      action: "create",
      redirect: false,
      onMutationSuccess: (data) => {
        const isDraft = (data.data as any)?.isDraft;
        setIsSuccess(true);
        setSuccessMessage(
          isDraft
            ? t("assignments.form.toast.draftSaved")
            : t("assignments.form.toast.submitted"),
        );

        void invalidate({
          resource: "submissions",
          invalidates: ["list"],
        });

        setTimeout(() => {
          setIsSuccess(false);
          if (onCancel) {
            onCancel();
          } else {
            go({
              to: `/assignments/show/${assignmentId}`,
              type: "replace",
            });
          }
        }, 1500);
      },
    },
  });

  const {
    handleSubmit,
    control,
    setValue,
    watch,
    refineCore: { onFinish, formLoading },
  } = form;

  const content = watch("content");
  const fileUrl = watch("fileUrl");

  const wordCount = useMemo(() => {
    return content?.trim().split(/\s+/).filter(Boolean).length ?? 0;
  }, [content]);

  const onSubmit = (values: SubmissionFormValues) => {
    void onFinish({
      ...values,
      assignmentId,
    });
  };

  const handleSaveDraft = () => {
    const values = form.getValues();
    void onFinish({
      ...values,
      assignmentId,
      isDraft: true,
    });
  };

  const handleFileUpload = (url: string, publicId: string) => {
    setValue("fileUrl", url);
    setValue("fileCldPubId", publicId);
  };

  const handleClearFile = () => {
    setValue("fileUrl", "");
    setValue("fileCldPubId", "");
  };

  const currentAttempt = existingSubmission?.isDraft
    ? latestAttemptNumber
    : latestAttemptNumber + 1;
  const isAr = i18n.language === "ar";

  const tips = t("assignments.form.tips", { returnObjects: true });
  const tipsList = Array.isArray(tips) ? tips : [];

  return (
    <Form {...form}>
      <form
        onSubmit={handleSubmit(onSubmit as any)}
        className="space-y-8 relative text-start"
      >
        <AnimatePresence>
          {isSuccess && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 z-50 bg-background/80 backdrop-blur-sm flex flex-col items-center justify-center gap-4 rounded-2xl"
            >
              <motion.div
                initial={{ scale: 0.5, rotate: -10 }}
                animate={{ scale: 1, rotate: 0 }}
                className="p-4 rounded-full bg-success/10 text-success"
              >
                <CheckCircle2 className="h-12 w-12 stroke-3" />
              </motion.div>
              <h3 className="text-2xl font-black tracking-tight">
                {successMessage}
              </h3>
              <p className="text-muted-foreground font-medium">
                {t("assignments.form.successRedirecting")}
              </p>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <div className="lg:col-span-3 space-y-6">
            <div className="flex items-center justify-between bg-primary/5 p-4 rounded-2xl border border-primary/10">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-xl bg-primary/10 text-primary">
                  <History className="h-4 w-4" />
                </div>
                <div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-primary/60">
                    {t("assignments.form.submissionStatus")}
                  </p>
                  <p className="text-sm font-black tracking-tight">
                    {existingSubmission?.isDraft
                      ? t("assignments.form.editingDraft")
                      : t("assignments.form.submittingAttempt", {
                          count: currentAttempt,
                        })}
                  </p>
                </div>
              </div>
              {existingSubmission?.isDraft && (
                <Badge className="bg-amber-500/10 text-amber-600 border-none font-black text-[10px] uppercase tracking-widest px-3 py-1 rounded-lg">
                  {t("assignments.form.draftMode")}
                </Badge>
              )}
            </div>

            {/* Group Selection for Group Assignments */}
            {assignment?.isGroupAssignment && (
              <div className="p-6 bg-card rounded-3xl border border-border shadow-sm">
                <FormField
                  control={control}
                  name="groupId"
                  render={({ field }) => (
                    <FormItem className="space-y-3">
                      <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                        <Users className="h-3 w-3" />
                        {t("assignments.form.selectGroup")}
                      </FormLabel>
                      <Select
                        onValueChange={(val) => field.onChange(Number(val))}
                        value={field.value?.toString()}
                        disabled={!!existingSubmission} // Cannot change group after first save/submit for consistency
                      >
                        <FormControl>
                          <SelectTrigger className="h-12 rounded-xl bg-muted/20 border-none focus:ring-primary text-start">
                            <SelectValue
                              placeholder={t(
                                "assignments.form.selectGroupPlaceholder",
                              )}
                            />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {groups.map((group) => (
                            <SelectItem
                              key={group.id}
                              value={group.id.toString()}
                              className="text-start"
                            >
                              {group.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <p className="text-[10px] text-muted-foreground">
                        {t("assignments.form.groupNote")}
                      </p>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
            )}

            <FormField
              control={control}
              name="content"
              render={({ field }) => (
                <FormItem className="space-y-3 text-start">
                  <div className="flex items-center justify-between">
                    <FormLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2">
                      <span className="w-1 h-1 rounded-full bg-primary" />
                      {t("assignments.form.yourSubmission")}
                    </FormLabel>
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-bold text-muted-foreground/60 uppercase tracking-tighter">
                        {t("assignments.form.wordsCount", { count: wordCount })}
                      </span>
                    </div>
                  </div>
                  <FormControl>
                    <div className="relative group">
                      <Textarea
                        placeholder={t("assignments.form.contentPlaceholder")}
                        className="min-h-75 rounded-3xl resize-none bg-muted/20 border-2 border-transparent focus-visible:ring-primary focus-visible:border-primary/20 p-6 text-sm leading-relaxed shadow-inner transition-all scrollbar-thin scrollbar-thumb-primary/10"
                        {...field}
                      />
                      <div
                        className={cn(
                          "absolute bottom-4 opacity-10 group-focus-within:opacity-30 transition-opacity",
                          isAr ? "left-4" : "right-4",
                        )}
                      >
                        <FileText className="h-8 w-8" />
                      </div>
                    </div>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="space-y-4 text-start">
              <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground flex items-center gap-2 ml-1">
                <span className="w-1 h-1 rounded-full bg-primary" />
                {t("assignments.form.supportingDocs")}
              </Label>
              <div
                className={cn(
                  "p-6 rounded-3xl border-2 border-dashed transition-all",
                  fileUrl
                    ? "bg-success/5 border-success/20"
                    : "bg-muted/10 border-muted-foreground/10 hover:border-primary/20 hover:bg-primary/2",
                )}
              >
                <FileUpload
                  label={
                    fileUrl
                      ? t("assignments.form.fileAttached")
                      : t("assignments.form.uploadFile")
                  }
                  folder="submissions"
                  onUploadSuccess={handleFileUpload}
                  onClear={handleClearFile}
                />
                <AnimatePresence>
                  {fileUrl && (
                    <motion.div
                      initial={{ opacity: 0, y: 5 }}
                      animate={{ opacity: 1, y: 0 }}
                      className="mt-4 flex items-center gap-3 p-3 rounded-xl bg-white dark:bg-muted/10 shadow-sm border border-success/10"
                    >
                      <div className="p-2 rounded-lg bg-success/10 text-success">
                        <Paperclip className="h-4 w-4" />
                      </div>
                      <div className="flex flex-col text-start">
                        <span className="text-xs font-bold text-success">
                          {t("assignments.form.fileSuccess")}
                        </span>
                        <span className="text-[10px] text-muted-foreground uppercase font-medium">
                          {t("assignments.form.readyForSubmission")}
                        </span>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </div>
          </div>

          <div className="lg:col-span-1 space-y-6 text-start">
            <div className="p-6 rounded-3xl bg-primary/5 border border-primary/10 space-y-4">
              <h4 className="text-[10px] font-black uppercase tracking-widest text-primary flex items-center gap-2">
                <div className="p-1.5 rounded-lg bg-primary/10">
                  <Info className="h-3.5 w-3.5" />
                </div>
                {t("assignments.form.submissionTips")}
              </h4>
              <ul className="space-y-3">
                {tipsList.map((tip: string, i: number) => (
                  <li
                    key={i}
                    className="flex items-start gap-2 text-xs font-medium text-muted-foreground"
                  >
                    <div className="mt-1 size-1 rounded-full bg-primary/40" />
                    {tip}
                  </li>
                ))}
              </ul>
              <div className="pt-4 border-t border-primary/10">
                <div className="flex items-center gap-2 text-primary">
                  <Sparkles className="h-3.5 w-3.5" />
                  <span className="text-[10px] font-black uppercase tracking-widest">
                    {t("assignments.form.aiReady")}
                  </span>
                </div>
                <p className="text-[10px] text-muted-foreground mt-1 leading-relaxed">
                  {t("assignments.form.aiDescription")}
                </p>
              </div>
            </div>

            <div className="space-y-3">
              <Button
                type="button"
                variant="outline"
                onClick={handleSaveDraft}
                disabled={formLoading}
                className="w-full h-14 rounded-2xl font-black uppercase tracking-widest border-primary/10 bg-card/50 backdrop-blur-sm hover:bg-primary/5 text-primary gap-2"
              >
                <Save className="h-4 w-4" />
                {t("buttons.saveAsDraft")}
              </Button>

              <LoadingButton
                type="submit"
                isLoading={formLoading}
                isSuccess={isSuccess}
                className="w-full h-14 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-primary/20 gap-2"
              >
                <Send className={cn("h-4 w-4", isAr && "rotate-180")} />
                {existingSubmission && !existingSubmission.isDraft
                  ? t("buttons.resubmitWork")
                  : t("buttons.turnInNow")}
              </LoadingButton>

              {onCancel && (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={onCancel}
                  disabled={formLoading}
                  className="w-full h-14 rounded-2xl font-black uppercase tracking-widest text-muted-foreground hover:bg-destructive/5 hover:text-destructive gap-2"
                >
                  <X className="h-4 w-4" />
                  {t("buttons.cancel")}
                </Button>
              )}
            </div>
          </div>
        </div>
      </form>
    </Form>
  );
};

import {
  useReactTable,
  getCoreRowModel,
  ColumnDef,
  flexRender,
} from "@tanstack/react-table";
import { useMemo, useState } from "react";
import { Submission, User, PeerReview } from "@/types";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Eye, Clock, CheckCircle2, AlertCircle, MessageSquare, Trophy, MoreHorizontal } from "lucide-react";
import { useCustom } from "@refinedev/core";
import { GradingDialog } from "./grading-dialog";
import { SOCKET_URL } from "@/config";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import "dayjs/locale/ar";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

dayjs.extend(relativeTime);

interface SubmissionListProps {
  submissions?: Submission[];
  assignmentId?: number;
}

export const SubmissionList = ({ submissions = [], assignmentId }: SubmissionListProps) => {
  const { t, i18n } = useTranslation();
  const [selectedSubmission, setSelectedSubmission] =
    useState<Submission | null>(null);
  const [isGradingOpen, setIsGradingOpen] = useState(false);

  dayjs.locale(i18n.language === "ar" ? "ar" : "en");

  const { query: allReviewsQuery } = useCustom<PeerReview[]>({
    url: `${SOCKET_URL.replace("/socket.io", "")}/api/peer-reviews/assignment/${assignmentId}`,
    method: "get",
    queryOptions: {
      enabled: !!assignmentId,
    },
  });

  const allReviews = allReviewsQuery?.data?.data || [];

  const handleGradeClick = (submission: Submission) => {
    setSelectedSubmission(submission);
    setIsGradingOpen(true);
  };

  const submissionColumns = useMemo<ColumnDef<Submission>[]>(
    () => [
      {
        id: "student",
        header: t("assignments.list.table.student"),
        accessorFn: (row) => row.student,
        cell: ({ getValue }) => {
          const student = getValue<User>();
          if (!student) return <span className="text-muted-foreground italic text-xs">{t("assignments.list.table.unknownStudent")}</span>;
          return (
            <div className="flex items-center gap-3 py-1">
              <div className="relative group">
                <Avatar className="size-10 border-2 border-background shadow-sm group-hover:border-primary/20 transition-all">
                  {student.image && (
                    <AvatarImage src={student.image} alt={student.name} className="object-cover" />
                  )}
                  <AvatarFallback className="bg-primary/5 text-primary font-bold text-xs">
                    {student.name?.split(" ").map(n => n[0]).join("").toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                <div className="absolute -bottom-0.5 -right-0.5 size-3.5 bg-success rounded-full border-2 border-background" />
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-sm md:text-base tracking-tight group-hover:text-primary transition-colors">{student.name}</span>
                <span className="text-[10px] text-muted-foreground/60 font-medium uppercase tracking-wider">{t("assignments.list.table.studentId", { id: student.id.toString().slice(-4) })}</span>
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "updatedAt",
        header: t("assignments.list.table.status"),
        cell: ({ row }) => {
          const date = dayjs(row.original.updatedAt);
          const isLate = row.original.isLate;
          return (
            <div className="flex flex-col gap-1.5 min-w-[100px]">
              <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground/80">
                <Clock className="h-3.5 w-3.5" />
                <span>{date.fromNow()}</span>
              </div>
              {isLate ? (
                <Badge variant="destructive" className="w-fit text-[9px] h-5 px-2 uppercase font-black tracking-tighter shadow-sm">
                  <AlertCircle className="h-3 w-3 mr-1" />
                  {t("assignments.list.table.late")}
                </Badge>
              ) : (
                <Badge variant="secondary" className="w-fit text-[9px] h-5 px-2 uppercase font-black tracking-tighter bg-emerald-500/10 text-emerald-600 border border-emerald-500/20 shadow-sm">
                  <CheckCircle2 className="h-3 w-3 mr-1" />
                  {t("assignments.list.table.onTime")}
                </Badge>
              )}
            </div>
          );
        },
      },
      {
        id: "peerReviews",
        header: t("assignments.list.table.peerProgress"),
        cell: ({ row }) => {
          const submissionId = row.original.id;
          const reviewsForThis = allReviews.filter((r: PeerReview) => r.submissionId === submissionId);
          const completed = reviewsForThis.filter((r: PeerReview) => !!r.feedback).length;
          const total = reviewsForThis.length;

          if (total === 0) return (
            <div className="flex items-center gap-2 text-muted-foreground/40 min-w-[120px]">
              <MessageSquare className="h-3.5 w-3.5" />
              <span className="text-[10px] font-bold uppercase tracking-widest">{t("assignments.list.table.notAssigned")}</span>
            </div>
          );

          const isFullyReviewed = completed === total;

          return (
            <div className="flex flex-col gap-2 min-w-[120px]">
              <div className="flex items-center justify-between text-[10px] font-black uppercase tracking-tighter">
                <span className={cn(isFullyReviewed ? "text-success" : "text-primary")}>
                  {t("assignments.list.table.reviews", { completed, total })}
                </span>
                <span className="text-muted-foreground/40">{Math.round((completed / total) * 100)}%</span>
              </div>
              <div className="h-2 w-full bg-muted rounded-full overflow-hidden border border-black/[0.03] dark:border-white/10 shadow-inner">
                <div 
                  className={cn(
                    "h-full transition-all duration-500 rounded-full",
                    isFullyReviewed ? "bg-success" : "bg-primary"
                  )}
                  style={{ width: `${(completed / total) * 100}%` }}
                />
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "grade",
        header: t("assignments.list.table.grade"),
        cell: ({ getValue }) => {
          const grade = getValue<number | null>();
          
          if (grade === null) return (
            <Badge variant="outline" className="text-[10px] font-black uppercase tracking-widest border-dashed opacity-50 shadow-sm">
              {t("assignments.list.table.pending")}
            </Badge>
          );

          const isHigh = grade >= 90;
          const isLow = grade < 50;

          return (
            <div className="flex items-center gap-2 min-w-[80px]">
              <div className={cn(
                "size-10 rounded-xl flex items-center justify-center font-black text-sm shadow-md border",
                isHigh ? "bg-primary/10 text-primary border-primary/20" : 
                isLow ? "bg-destructive/10 text-destructive border-destructive/20" : 
                "bg-muted/50 text-foreground border-border/40"
              )}>
                {grade}%
              </div>
              {isHigh && <Trophy className="h-4 w-4 text-gold-primary animate-bounce" />}
            </div>
          );
        },
      },
      {
        id: "actions",
        header: "",
        cell: ({ row }) => (
          <div className="flex justify-end min-w-[80px]">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-10 w-10 rounded-xl bg-muted/30 hover:bg-muted/50"
                  onClick={(e) => e.stopPropagation()}
                >
                  <MoreHorizontal className="h-5 w-5" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-56 p-2 rounded-2xl">
                <DropdownMenuItem
                  onClick={() => handleGradeClick(row.original)}
                  className="rounded-xl gap-3 py-3 cursor-pointer"
                >
                  <div className="p-2 rounded-lg bg-primary/10 text-primary">
                    <Eye className="h-4 w-4" />
                  </div>
                  <span className="font-bold">{t("buttons.grade")}</span>
                </DropdownMenuItem>
                {/* Add other actions like edit/delete submission if applicable */}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        ),
      },
    ],
    [allReviews, t],
  );

  const table = useReactTable({
    data: submissions,
    columns: submissionColumns,
    getCoreRowModel: getCoreRowModel(),
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 px-1">
        <div className="p-2 rounded-xl bg-primary/10 text-primary shadow-sm border border-primary/5">
          <MessageSquare className="h-5 w-5" />
        </div>
        <h3 className="text-xl md:text-2xl font-black uppercase tracking-widest">{t("assignments.list.table.submissionsHeader")}</h3>
        <Badge variant="secondary" className="rounded-full px-3 py-1 h-7 text-[10px] font-black uppercase tracking-widest bg-primary/10 text-primary border-none shadow-sm">
          {submissions.length}
        </Badge>
      </div>
      
      <div className="rounded-[1.5rem] md:rounded-[2rem] border border-border/40 overflow-x-auto bg-card/50 backdrop-blur-xl shadow-lg">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                  onClick={() => handleGradeClick(row.original)}
                  className="cursor-pointer"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={submissionColumns.length} className="h-24 text-center">
                  {t("assignments.list.table.submissionsHeader")}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <GradingDialog
        isOpen={isGradingOpen}
        onOpenChange={setIsGradingOpen}
        submission={selectedSubmission}
      />
    </div>
  );
};

import React from "react";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { 
  CheckCircle2, 
  XCircle, 
  Clock, 
  AlertCircle, 
  Timer, 
  Zap, 
  Info, 
  Calendar as CalendarIcon 
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableHeader, TableRow, TableHead, TableBody, TableCell } from "@/components/ui/table";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { AttendanceStatus, Enrollment, Attendance } from "@/types";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { ar } from "date-fns/locale";

interface AttendanceStatsProps {
  stats: {
    present: number;
    absent: number;
    late: number;
    excused: number;
  };
}

// --- Stats Component ---
export const AttendanceStats = ({ stats }: AttendanceStatsProps) => {
  const { t } = useTranslation();
  const statConfig = [
    { label: t("classes.attendance.present"), value: stats?.present || 0, icon: CheckCircle2, color: "text-success", bg: "bg-success/10" },
    { label: t("classes.attendance.absent"), value: stats?.absent || 0, icon: XCircle, color: "text-destructive", bg: "bg-destructive/10" },
    { label: t("classes.attendance.late"), value: stats?.late || 0, icon: Clock, color: "text-yellow-600", bg: "bg-yellow-500/10" },
    { label: t("classes.attendance.excused"), value: stats?.excused || 0, icon: AlertCircle, color: "text-blue-600", bg: "bg-blue-500/10" },
  ];

  return (
    <div className="grid gap-6 md:grid-cols-4">
      {statConfig.map((stat) => (
        <motion.div key={stat.label} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
          <Card className={cn("border-none shadow-xl bg-card/50 backdrop-blur-xl rounded-[1.5rem] overflow-hidden group hover:shadow-2xl transition-all", stat.bg)}>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div className="space-y-1 text-start">
                  <p className="text-[10px] font-black uppercase tracking-widest opacity-60">{stat.label}</p>
                  <p className={cn("text-4xl font-black tracking-tighter", stat.color)}>{stat.value}</p>
                </div>
                <div className={cn("p-3 rounded-2xl transition-transform group-hover:scale-110", stat.bg)}>
                  <stat.icon className={cn("h-6 w-6", stat.color)} />
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      ))}
    </div>
  );
};

interface AttendanceMarkTableProps {
  enrollments: Enrollment[];
  attendanceData: Record<string, {
    status: AttendanceStatus;
    remarks: string;
    minutesPresent: number;
    participationScore: number;
  }>;
  onStatusChange: (studentId: string, status: AttendanceStatus) => void;
  onValueChange: (studentId: string, field: string, value: string | number) => void;
  isAr: boolean;
}

// --- Mark Table Component ---
export const AttendanceMarkTable = ({ 
  enrollments, 
  attendanceData, 
  onStatusChange, 
  onValueChange, 
  isAr 
}: AttendanceMarkTableProps) => {
  const { t } = useTranslation();
  return (
    <div className="px-4 pb-4 overflow-x-auto">
      <Table>
        <TableHeader>
          <TableRow className="hover:bg-transparent border-none text-start">
            <TableHead className="text-[10px] font-black uppercase tracking-widest py-6">{t("classes.attendance.table.student")}</TableHead>
            <TableHead className="text-[10px] font-black uppercase tracking-widest py-6">{t("classes.attendance.table.status")}</TableHead>
            <TableHead className="text-[10px] font-black uppercase tracking-widest py-6">{t("classes.attendance.table.minutes")}</TableHead>
            <TableHead className="text-[10px] font-black uppercase tracking-widest py-6">{t("classes.attendance.table.participation")}</TableHead>
            <TableHead className="text-[10px] font-black uppercase tracking-widest py-6">{t("classes.attendance.table.remarks")}</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {enrollments.map((enrollment: Enrollment) => {
            const student = enrollment.student;
            const data = attendanceData[student.id] || { status: AttendanceStatus.ABSENT, remarks: "", minutesPresent: 0, participationScore: 0 };
            return (
              <motion.tr key={student.id} initial={{ opacity: 0, x: isAr ? 5 : -5 }} animate={{ opacity: 1, x: 0 }} className="group hover:bg-primary/[0.02] transition-colors border-b border-black/[0.03] dark:border-white/[0.03] text-start">
                <TableCell className="py-4">
                  <div className="flex items-center gap-4">
                    <Avatar className="h-10 w-10 border-2 border-background shadow-sm group-hover:scale-110 transition-transform text-xs">
                      <AvatarImage src={student.image || ""} className="object-cover" />
                      <AvatarFallback className="bg-primary/5 text-primary font-bold">{student.name[0]}</AvatarFallback>
                    </Avatar>
                    <div className="flex flex-col">
                      <span className="font-black text-sm tracking-tight group-hover:text-primary transition-colors">{student.name}</span>
                      <span className="text-[10px] text-muted-foreground font-medium uppercase tracking-widest">{student.email}</span>
                    </div>
                  </div>
                </TableCell>
                <TableCell className="py-4">
                  <Select value={data.status} onValueChange={(val) => onStatusChange(student.id, val as AttendanceStatus)}>
                    <SelectTrigger className="w-[130px] h-11 rounded-xl bg-muted/20 border-none font-bold text-xs">
                      <div className="flex items-center gap-2">
                        <SelectValue />
                      </div>
                    </SelectTrigger>
                    <SelectContent className="rounded-xl border-none shadow-2xl">
                      {[AttendanceStatus.PRESENT, AttendanceStatus.ABSENT, AttendanceStatus.LATE, AttendanceStatus.EXCUSED].map(s => (
                        <SelectItem key={s} value={s} className="rounded-lg font-bold text-start">{t(`classes.attendance.${s.toLowerCase()}` as any)}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </TableCell>
                <TableCell className="py-4">
                  <div className="relative w-24">
                    <Input type="number" value={data.minutesPresent} onChange={(e) => onValueChange(student.id, "minutesPresent", Number(e.target.value))} className={cn("h-11 rounded-xl bg-muted/10 border-none font-black text-center", isAr ? "pl-8" : "pr-8")} />
                    <Timer className={cn("absolute top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground/40", isAr ? "left-2.5" : "right-2.5")} />
                  </div>
                </TableCell>
                <TableCell className="py-4">
                  <div className="relative w-24">
                    <Input type="number" min={0} max={10} value={data.participationScore} onChange={(e) => onValueChange(student.id, "participationScore", Number(e.target.value))} className={cn("h-11 rounded-xl bg-muted/10 border-none font-black text-center", isAr ? "pl-8" : "pr-8")} />
                    <Zap className={cn("absolute top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-yellow-500/40", isAr ? "left-2.5" : "right-2.5")} />
                  </div>
                </TableCell>
                <TableCell className="py-4">
                  <Input value={data.remarks} onChange={(e) => onValueChange(student.id, "remarks", e.target.value)} className="h-11 rounded-xl bg-muted/10 border-none font-medium min-w-[150px]" />
                </TableCell>
              </motion.tr>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
};

interface AttendanceHistoryGroup {
  date: string;
  present?: number;
  absent?: number;
  late?: number;
  excused?: number;
  records?: Attendance[];
}

interface AttendanceHistoryTableProps {
  historyData: AttendanceHistoryGroup[];
  isTeacher: boolean;
  isAr: boolean;
}

// --- History Table Component ---
export const AttendanceHistoryTable = ({ historyData, isTeacher, isAr }: AttendanceHistoryTableProps) => {
  const { t } = useTranslation();
  return (
    <div className="px-4 pb-4 overflow-x-auto">
      <Table>
        <TableHeader>
          <TableRow className="hover:bg-transparent border-none text-start">
            <TableHead className="text-[10px] font-black uppercase tracking-widest py-6">{t("classes.attendance.table.date")}</TableHead>
            {isTeacher ? (
              ["present", "absent", "late", "excused"].map(s => (
                <TableHead key={s} className="text-[10px] font-black uppercase tracking-widest py-6">{t(`classes.attendance.${s}` as any)}</TableHead>
              ))
            ) : (
              ["status", "participation", "remarks"].map(s => (
                <TableHead key={s} className="text-[10px] font-black uppercase tracking-widest py-6">{t(`classes.attendance.table.${s}` as any)}</TableHead>
              ))
            )}
          </TableRow>
        </TableHeader>
        <TableBody>
          {historyData.map((group) => (
            <TableRow key={group.date} className="group hover:bg-primary/[0.02] transition-colors border-b border-black/[0.03] dark:border-white/[0.03] text-start">
              <TableCell className="py-6 font-black text-sm tracking-tight">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-muted/50 text-muted-foreground group-hover:bg-primary/10 group-hover:text-primary transition-all">
                    <CalendarIcon className="h-4 w-4" />
                  </div>
                  {format(new Date(group.date), "PPP", { locale: isAr ? ar : undefined })}
                </div>
              </TableCell>
              {isTeacher ? (
                <>
                  <TableCell><Badge variant="outline" className="text-success border-success/20 bg-success/5">{group.present}</Badge></TableCell>
                  <TableCell><Badge variant="outline" className="text-destructive border-destructive/20 bg-destructive/5">{group.absent}</Badge></TableCell>
                  <TableCell><Badge variant="outline" className="text-yellow-600 border-yellow-500/20 bg-yellow-500/5">{group.late}</Badge></TableCell>
                  <TableCell><Badge variant="outline" className="text-blue-600 border-blue-500/20 bg-blue-500/5">{group.excused}</Badge></TableCell>
                </>
              ) : (
                <>
                  <TableCell><Badge className="bg-primary/10 text-primary border-none">{group.records?.[0]?.status}</Badge></TableCell>
                  <TableCell><div className="flex items-center gap-2 font-black text-xs"><Zap className="h-3 w-3 text-yellow-500" />{group.records?.[0]?.participationScore}/10</div></TableCell>
                  <TableCell><div className="flex items-center gap-2 text-muted-foreground/60 italic text-xs font-medium"><Info className="h-3.5 w-3.5 opacity-40" />{group.records?.[0]?.remarks || t("classes.attendance.noRemarks")}</div></TableCell>
                </>
              )}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
};

import { useState, useEffect, useRef } from "react";
import { useCustomMutation, useNotification, HttpError } from "@refinedev/core";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Html5QrcodeScanner } from "html5-qrcode";
import { Loader2, Camera, CheckCircle2, AlertCircle, XCircle, Keyboard, ArrowRight, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useNavigate } from "react-router-dom";

interface QRScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  classId: string;
}

interface ScanResponse {
  message?: string;
}

export const QRScannerModal = ({ isOpen, onClose, classId }: QRScannerModalProps) => {
  const { open } = useNotification();
  const navigate = useNavigate();
  const [isScanning, setIsScanning] = useState(true);
  const [mode, setMode] = useState<"camera" | "manual">("camera");
  const [manualCode, setManualCode] = useState("");
  const [scanResult, setScanResult] = useState<{ success: boolean; message: string } | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  const { mutate: markAttendance, mutation } = useCustomMutation<ScanResponse, HttpError>();

  useEffect(() => {
    if (!isOpen || mode !== "camera") {
      if (scannerRef.current) {
        try {
            scannerRef.current.clear();
        } catch {
            console.warn("Scanner clear failed");
        }
        scannerRef.current = null;
      }
      if (!isOpen) {
        setScanResult(null);
        setIsScanning(true);
        setMode("camera");
      }
      return;
    }

    const timer = setTimeout(() => {
        const scanner = new Html5QrcodeScanner(
          "qr-reader",
          { 
            fps: 10, 
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1.0,
          },
          /* verbose= */ false
        );
    
        scannerRef.current = scanner;
    
        scanner.render(
          (decodedText) => {
            try {
              const data = JSON.parse(decodedText);
              if (String(data.classId) === String(classId) && data.token) {
                handleScanSuccess(data.token);
                scanner.clear().catch(err => console.warn(err));
              } else {
                setScanResult({ success: false, message: "Invalid QR code for this class." });
              }
            } catch {
              setScanResult({ success: false, message: "Invalid QR code format." });
            }
          },
          () => {}
        );
    }, 100);

    return () => {
      clearTimeout(timer);
      if (scannerRef.current) {
        try {
            scannerRef.current.clear();
        } catch {
            // Ignore clear error
        }
        scannerRef.current = null;
      }
    };
  }, [isOpen, classId, mode]);

  const handleScanSuccess = (token: string) => {
    setIsScanning(false);
    
    markAttendance(
      {
        url: "/attendance/scan",
        method: "post",
        values: {
          classId,
          token,
        },
      },
      {
        onSuccess: () => {
          setScanResult({ success: true, message: "You've been marked present!" });
          open?.({
            type: "success",
            message: "Attendance Marked",
            description: "You have been marked as present and are being redirected.",
          });
          
          setTimeout(() => {
            onClose();
            navigate(`/classes/show/${classId}`);
          }, 2000);
        },
        onError: (err) => {
          const error = err as HttpError;
          setScanResult({ 
            success: false, 
            message: (error?.response?.data as any)?.message || error?.message || "Failed to mark attendance. The code might have expired."
          });
        },
      }
    );
  };

  const handleManualSubmit = () => {
    if (!manualCode.trim()) return;
    handleScanSuccess(manualCode.trim());
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[450px] overflow-hidden">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {mode === "camera" ? <Camera className="h-5 w-5 text-primary" /> : <Keyboard className="h-5 w-5 text-primary" />}
            {mode === "camera" ? "Scan QR Attendance" : "Enter Attendance Code"}
          </DialogTitle>
          <DialogDescription>
            {mode === "camera" 
              ? "Point your camera at the QR code displayed by your teacher." 
              : "Type the 8-character code shown on the teacher's screen."}
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col items-center justify-center py-4 space-y-6">
          {isScanning ? (
            <>
              {mode === "camera" ? (
                <div className="w-full overflow-hidden rounded-2xl border-4 border-primary/10 bg-black/5 aspect-square relative shadow-inner">
                  <div id="qr-reader" className="w-full h-full" />
                  <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                    <div className="w-[250px] h-[250px] border-4 border-primary/40 rounded-2xl border-dashed animate-pulse" />
                  </div>
                </div>
              ) : (
                <div className="w-full py-8 space-y-6">
                  <div className="space-y-4">
                    <div className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest text-muted-foreground">
                        <Keyboard className="h-3 w-3" />
                        Manual Entry
                    </div>
                    <Input 
                      placeholder="ABC123XY" 
                      value={manualCode}
                      onChange={(e) => setManualCode(e.target.value.toUpperCase())}
                      className="h-16 text-center text-3xl font-black tracking-[0.3em] font-mono border-2 border-primary/20 bg-primary/5 rounded-2xl focus-visible:ring-primary/30"
                      maxLength={32}
                    />
                  </div>
                  <Button className="w-full h-12 text-lg font-black gap-2 shadow-lg shadow-primary/20 rounded-xl" onClick={handleManualSubmit} disabled={!manualCode.trim()}>
                    Check In
                    <ArrowRight className="h-5 w-5" />
                  </Button>
                </div>
              )}

              <Button 
                variant="ghost" 
                size="sm" 
                className="text-[10px] font-black uppercase tracking-widest text-muted-foreground hover:bg-primary/5"
                onClick={() => setMode(mode === "camera" ? "manual" : "camera")}
              >
                {mode === "camera" ? "Switch to Manual Entry" : "Switch to Camera Scan"}
              </Button>
            </>
          ) : (
            <div className="w-full py-12 flex flex-col items-center justify-center space-y-6 text-center">
              {mutation.isPending ? (
                <div className="space-y-4">
                  <div className="relative">
                    <Loader2 className="h-16 w-16 animate-spin text-primary opacity-20" />
                    <Sparkles className="h-8 w-8 text-primary absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
                  </div>
                  <p className="text-sm font-black uppercase tracking-widest text-primary animate-pulse">Verifying Check-in...</p>
                </div>
              ) : scanResult?.success ? (
                <div className="animate-in zoom-in-95 duration-500 space-y-6">
                  <div className="h-24 w-24 bg-green-500/10 rounded-full flex items-center justify-center mx-auto shadow-lg shadow-green-500/20 border-2 border-green-500/20">
                    <CheckCircle2 className="h-12 w-12 text-green-500 animate-bounce" />
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-3xl font-black tracking-tight text-green-600">You're marked present!</h3>
                    <p className="text-sm font-medium text-muted-foreground">{scanResult.message}</p>
                  </div>
                  <div className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest text-muted-foreground">
                    <Loader2 className="h-3 w-3 animate-spin" />
                    Redirecting to class...
                  </div>
                </div>
              ) : (
                <div className="animate-in zoom-in-95 duration-500 space-y-6">
                  <div className="h-24 w-24 bg-destructive/10 rounded-full flex items-center justify-center mx-auto shadow-lg shadow-destructive/20 border-2 border-destructive/20">
                    <XCircle className="h-12 w-12 text-destructive" />
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-2xl font-black tracking-tight text-destructive">Check-in Failed</h3>
                    <p className="text-sm font-medium text-muted-foreground max-w-[250px] mx-auto">{scanResult?.message}</p>
                  </div>
                  <Button 
                    variant="outline" 
                    onClick={() => {
                      setIsScanning(true);
                      setScanResult(null);
                      setManualCode("");
                    }}
                    className="h-11 px-8 font-black uppercase tracking-widest text-xs rounded-xl"
                  >
                    Try Again
                  </Button>
                </div>
              )}
            </div>
          )}

          <div className="w-full flex items-center gap-3 p-4 bg-muted/50 rounded-2xl text-[10px] font-medium text-muted-foreground border border-black/5">
            <AlertCircle className="h-4 w-4 shrink-0 text-primary" />
            <p>Camera access requires HTTPS. If you're on a desktop or have issues, use the manual entry code provided by your teacher.</p>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

import { useState, useEffect, useCallback, useMemo } from "react";
import { 
  useShow, 
  useOne, 
  useUpdate, 
  useList, 
  useDelete, 
  useCreate,
} from "@refinedev/core";
import { Class, Announcement, Enrollment } from "@/types";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";
import debounce from "lodash/debounce";
import { useQueryClient } from "@tanstack/react-query";
import { useUserRole } from "@/hooks/use-user-role";

export const useClassDetails = (classId: string) => {
  const { t } = useTranslation();
  const { identity, isAdmin, isTeacher, isStaff } = useUserRole();
  const queryClient = useQueryClient();

  // --- Data Fetching ---
  const { query } = useShow<Class>({
    resource: "classes",
    id: classId,
    meta: { syncWithLocation: false },
  });

  const aClass = query?.data?.data;
  
  const isModerator = useMemo(() => {
    if (isAdmin) return false; // Admins are Registrars, not Instructors
    return !!aClass?.teachers?.some((t) => t.teacher.id === identity?.id);
  }, [identity, aClass, isAdmin]);

  const isOwner = useMemo(() => {
    return isAdmin || aClass?.teachers?.find((t) => t.teacher.id === identity?.id)?.isPrimary;
  }, [identity, aClass, isAdmin]);

  // --- Announcements Logic ---
  const { query: { data: announcementsResult } } = useList<Announcement>({
    resource: "announcements",
    filters: [{ field: "classId", operator: "eq", value: classId }],
    sorters: [{ field: "isPinned", order: "desc" }],
    queryOptions: { enabled: !!classId },
  });
  const announcements = announcementsResult?.data ?? [];

  const [dismissedAnnouncements, setDismissedAnnouncements] = useState<number[]>([]);
  useEffect(() => {
    if (identity?.id) {
      const dismissed = localStorage.getItem(`dismissed_announcements_${identity.id}`);
      if (dismissed) setDismissedAnnouncements(JSON.parse(dismissed));
    }
  }, [identity?.id]);

  const handleDismissAnnouncement = (id: number) => {
    const updated = [...dismissedAnnouncements, id];
    setDismissedAnnouncements(updated);
    localStorage.setItem(`dismissed_announcements_${identity?.id}`, JSON.stringify(updated));
  };

  // --- Teacher Notes Logic ---
  const [teacherNotes, setTeacherNotes] = useState("");
  const { query: notesQuery } = useOne<{ content: string }>({
    resource: `classes/${classId}/notes`,
    id: "current",
    queryOptions: { enabled: !!classId && isStaff },
  });
  const { mutate: updateNote } = useUpdate();

  useEffect(() => {
    if (notesQuery?.data?.data?.content !== undefined) {
      setTeacherNotes(notesQuery.data.data.content);
    }
  }, [notesQuery?.data]);

  const debouncedSaveNotes = useCallback(
    debounce((content: string) => {
      updateNote({
        resource: `classes/${classId}/notes`,
        id: "current",
        values: { content },
      });
    }, 1000),
    [classId, updateNote],
  );

  const handleNoteChange = (val: string) => {
    setTeacherNotes(val);
    debouncedSaveNotes(val);
  };

  // --- Enrollment & Staff Actions Logic ---
  const { mutate: deleteMutation, mutation: deleteMutationObj } = useDelete();
  const { mutate: updateEnrollment } = useUpdate();
  const { mutate: createMutation, mutation: createMutationObj } = useCreate();
  const { mutate: updateClass } = useUpdate();

  const handleEnrollmentAction = async (id: number, status: "approved" | "rejected") => {
    // Optimistic Update
    const queryKey = ["classes", "show", classId];
    await queryClient.cancelQueries({ queryKey });
    const previousClass = queryClient.getQueryData(queryKey);

    if (previousClass) {
        queryClient.setQueryData(queryKey, (old: { data?: Class } | undefined) => {
            if (!old?.data) return old;
            return {
                ...old,
                data: {
                    ...old.data,
                    enrollments: old.data.enrollments.map((e: Enrollment) => 
                        e.id === id ? { ...e, status } : e
                    )
                }
            };
        });
    }

    updateEnrollment({
      resource: "enrollments",
      id: `${id}/status`,
      values: { status },
    }, {
      onSuccess: () => {
        toast.success(t("classes.show.toast.enrollmentStatus", {
          status: status === "approved" ? t("profileRequests.toasts.approved") : t("profileRequests.toasts.rejected"),
        }));
      },
      onError: () => {
          // Rollback if error
          if (previousClass) queryClient.setQueryData(queryKey, previousClass);
          toast.error(t("classes.show.toast.enrollmentError"));
      },
      onSettled: () => {
          void query?.refetch();
      }
    });
  };

  const handleToggleLive = async () => {
      if (!aClass) return;
      const newLiveStatus = !aClass.isLive;

      // Optimistic Update
      const queryKey = ["classes", "show", classId];
      await queryClient.cancelQueries({ queryKey });
      const previousClass = queryClient.getQueryData(queryKey);

      queryClient.setQueryData(queryKey, (old: { data?: Class } | undefined) => {
          if (!old?.data) return old;
          return { ...old, data: { ...old.data, isLive: newLiveStatus } };
      });

      updateClass({
          resource: "classes",
          id: classId,
          values: { isLive: newLiveStatus },
      }, {
          onError: () => {
              if (previousClass) queryClient.setQueryData(queryKey, previousClass);
              toast.error(t("classes.show.toast.liveToggleError", "Failed to update live status"));
          },
          onSettled: () => {
              void query?.refetch();
          }
      });
  };

  const handleConfirmUnenroll = (unenrollTarget: number | null, callback: () => void) => {
    if (unenrollTarget) {
      deleteMutation({ resource: "enrollments", id: unenrollTarget }, {
        onSuccess: () => {
          callback();
          void query?.refetch();
        }
      });
    }
  };

  return {
    identity,
    aClass,
    isLoading: query?.isPending,
    isError: query?.isError,
    isStaff,
    isAdmin,
    isTeacher,
    isModerator,
    isOwner,
    announcements,
    dismissedAnnouncements,
    handleDismissAnnouncement,
    teacherNotes,
    isLoadingNotes: notesQuery?.isPending,
    handleNoteChange,
    handleEnrollmentAction,
    handleToggleLive,
    handleConfirmUnenroll,
    isDeleting: deleteMutationObj.isPending,
    createMutation,
    isMessaging: createMutationObj.isPending,
    refetch: query?.refetch
  };
};

import { useState, useEffect, useMemo } from "react";
import {
  useList,
  HttpError,
  useGetIdentity,
  useCustomMutation,
  useInvalidate,
  useDelete,
  useNavigation,
} from "@refinedev/core";
import { useTable } from "@refinedev/react-table";
import { 
  User, 
  UserRole, 
  ClassListItem, 
  TeacherApplication, 
  Subject, 
  Department 
} from "@/types";
import { toast } from "sonner";
import { socket } from "@/lib/socket";
import { useTerm } from "@/contexts/term-context";
import { useTranslation } from "react-i18next";
import { ColumnDef } from "@tanstack/react-table";

const DEFAULT_PAGE_SIZE = 50;

export const useClassList = () => {
  const { t, i18n } = useTranslation();
  const { data: identity } = useGetIdentity<User>();
  const { create, show, edit } = useNavigation();
  const { selectedTerm } = useTerm();
  const invalidate = useInvalidate();
  const { mutate: deleteClass } = useDelete();

  const isStudent = identity?.role === UserRole.STUDENT;
  const isTeacher = identity?.role === UserRole.TEACHER;
  const isAdmin = identity?.role === UserRole.ADMIN;
  const isAr = i18n.language === 'ar';

  const [inviteCode, setInviteCode] = useState("");
  const [isJoinModalOpen, setIsJoinModalOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<number | null>(null);
  const [applyTarget, setApplyTarget] = useState<{ id: number; name: string } | null>(null);
  const [view, setView] = useState<"discovery" | "my">(isStudent ? "discovery" : "my");

  const { mutate: joinClass, mutation: joinMutation } = useCustomMutation();
  const { mutate: enrollRequest, mutation: enrollMutation } = useCustomMutation();
  const { mutate: cloneClass, mutation: cloneMutation } = useCustomMutation();

  // --- SOCKET UPDATES ---
  useEffect(() => {
    if (!socket.connected) socket.connect();
    
    const handleLiveUpdate = () => invalidate({ resource: "classes", invalidates: ["list"] });
    const handleEnrollmentApproval = () => {
      toast.success(t("classes.list.toast.enrollmentApproved"));
      invalidate({ resource: "classes", invalidates: ["list"] });
    };

    socket.on("live_session_started", handleLiveUpdate);
    socket.on("live_session_ended", handleLiveUpdate);
    socket.on("enrollment_approved", handleEnrollmentApproval);

    return () => {
      socket.off("live_session_started", handleLiveUpdate);
      socket.off("live_session_ended", handleLiveUpdate);
      socket.off("enrollment_approved", handleEnrollmentApproval);
    };
  }, [invalidate, t]);

  // --- TABLE LOGIC ---
  const columns = useMemo<ColumnDef<ClassListItem>[]>(() => [{ id: "id", accessorKey: "id" }], []);

  const {
    refineCore: { tableQuery: tableQueryResult, filters, setFilters }
  } = useTable<ClassListItem>({
    columns,
    refineCoreProps: {
      resource: "classes",
      pagination: { mode: "server", pageSize: DEFAULT_PAGE_SIZE },
      sorters: { initial: [{ field: "id", order: "desc" }] },
      meta: {
        populate: ["subject", "subject.department", "teachers", "teachers.teacher", "_count", "schedules"],
      },
      syncWithLocation: true,
      filters: {
        permanent: [
          ...(selectedTerm ? [{ field: "termId", operator: "eq" as const, value: selectedTerm.id }] : []),
          ...(isTeacher && identity?.id ? [{ field: "teacherUid", operator: "eq" as const, value: identity.id }] : []),
          ...(isStudent && view === "my" ? [{ field: "my", operator: "eq" as const, value: "true" }] : []),
        ],
      },
    }
  });

  const { query: subjectsQuery } = useList<Subject, HttpError>({ resource: "subjects", pagination: { pageSize: 1000 } });
  const { query: departmentsQuery } = useList<Department, HttpError>({ resource: "departments", pagination: { pageSize: 100 } });
  const { query: applicationsQuery } = useList<TeacherApplication>({ resource: "teacher-applications", queryOptions: { enabled: isTeacher } });

  // --- ACTIONS ---
  const handleJoinByCode = () => {
    if (!inviteCode.trim()) return;
    joinClass({ url: "/classes/join", method: "post", values: { inviteCode } }, {
      onSuccess: (data) => {
        const responseData = data.data as { message?: string };
        toast.success(responseData.message || t("classes.list.toast.joinRequestSent"));
        setIsJoinModalOpen(false);
        setInviteCode("");
        // SMART FIX: Force refresh of the class lists
        void invalidate({ resource: "classes", invalidates: ["list"] });
      },
      onError: (err) => {
        const error = err as HttpError;
        toast.error((error?.response?.data as any)?.message || t("classes.list.toast.invalidInviteCode"));
      }
    });
  };

  const handleEnrollRequest = (id: number) => {
    enrollRequest({ url: `/classes/${id}/enroll`, method: "post", values: {} }, {
      onSuccess: (data) => {
        const responseData = data.data as { message?: string };
        toast.success(responseData.message);
        invalidate({ resource: "classes", invalidates: ["list"] });
      },
      onError: (err) => {
        const error = err as HttpError;
        toast.error((error?.response?.data as any)?.message || "Failed to send enrollment request.");
      }
    });
  };

  const handleClone = (id: number) => {
    cloneClass({ url: `/classes/${id}/clone`, method: "post", values: {} }, {
      onSuccess: () => {
        toast.success(t("classes.list.toast.cloned"));
        invalidate({ resource: "classes", invalidates: ["list"] });
      }
    });
  };

  const handleConfirmDelete = () => {
    if (deleteTarget) {
      deleteClass({ resource: "classes", id: deleteTarget }, {
        onSuccess: () => {
          toast.success(t("classes.list.toast.deleted"));
          setDeleteTarget(null);
        }
      });
    }
  };

  return {
    data: {
      classes: tableQueryResult?.data?.data || [],
      total: tableQueryResult?.data?.total || 0,
      subjects: subjectsQuery.data?.data || [],
      departments: departmentsQuery.data?.data || [],
      applications: applicationsQuery.data?.data || [],
      identity,
      selectedTerm
    },
    status: {
      isLoading: tableQueryResult?.isPending,
      isJoining: joinMutation.isPending,
      isEnrolling: enrollMutation.isPending,
      isCloning: cloneMutation.isPending,
      isAr,
      isStudent,
      isTeacher,
      isAdmin
    },
    filters: {
      view,
      setView,
      search: (filters.find((f) => "field" in f && f.field === "name") as any)?.value || "",
      subject: (filters.find((f) => "field" in f && f.field === "subject") as any)?.value || "all",
      department: (filters.find((f) => "field" in f && f.field === "departmentId") as any)?.value || "all",
      setSearch: (val: string) => setFilters([{ field: "name", operator: "contains", value: val || undefined }], "merge"),
      setSubject: (val: string) => setFilters([{ field: "subject", operator: "eq", value: val === "all" ? undefined : val }], "merge"),
      setDepartment: (val: string) => setFilters([{ field: "departmentId", operator: "eq", value: val === "all" ? undefined : Number(val) }], "merge")
    },
    state: {
      inviteCode, setInviteCode,
      isJoinModalOpen, setIsJoinModalOpen,
      deleteTarget, setDeleteTarget,
      applyTarget, setApplyTarget
    },
    actions: {
      handleJoinByCode,
      handleEnrollRequest,
      handleClone,
      handleConfirmDelete,
      create, show, edit,
      invalidate
    }
  };
};

import { useState } from "react";
import { useCustomMutation, HttpError } from "@refinedev/core";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Loader2, Send, Sparkles } from "lucide-react";
import { useTranslation } from "react-i18next";
import { cn } from "@/lib/utils";

interface ApplyTeacherDialogProps {
  classId: number;
  className: string;
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export const ApplyTeacherDialog = ({
  classId,
  className,
  isOpen,
  onOpenChange,
  onSuccess,
}: ApplyTeacherDialogProps) => {
  const { t, i18n } = useTranslation();
  const [message, setMessage] = useState("");
  const { mutate, mutation } = useCustomMutation();
  const isLoading = mutation.isPending;

  const handleApply = () => {
    mutate(
      {
        url: "/teacher-applications",
        method: "post",
        values: {
          classId,
          message,
        },
      },
      {
        onSuccess: () => {
          toast.success(t("classes.dialogs.applyTeacher.toast.success"));
          onOpenChange(false);
          setMessage("");
          onSuccess?.();
        },
        onError: (err) => {
          const error = err as HttpError;
          toast.error((error?.response?.data as any)?.message || t("classes.dialogs.applyTeacher.toast.error"));
        },
      }
    );
  };

  const isAr = i18n.language === 'ar';

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="rounded-[2.5rem] border-none shadow-2xl bg-card/95 backdrop-blur-xl max-w-lg text-start">
        <DialogHeader className="space-y-4">
          <div className="p-4 rounded-2xl bg-primary/10 text-primary w-fit">
            <Send className={cn("h-8 w-8", isAr && "rotate-180")} />
          </div>
          <div className="space-y-1">
            <DialogTitle className="text-3xl font-black tracking-tight">
              {t("classes.dialogs.applyTeacher.title")}
            </DialogTitle>
            <DialogDescription className="font-medium text-base">
              {isAr ? (
                <>أنت تطلب إدارة وتدريس فصل <strong>{className}</strong>. سيقوم المسؤول بمراجعة طلبك.</>
              ) : (
                <>You are requesting to manage and teach <strong>{className}</strong>. The administrator will review your request.</>
              )}
            </DialogDescription>
          </div>
        </DialogHeader>
        <div className="space-y-6 py-6">
          <div className="space-y-3">
            <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">
              {t("classes.dialogs.applyTeacher.fieldLabel")}
            </Label>
            <div className="relative group">
              <Textarea
                placeholder={t("classes.dialogs.applyTeacher.fieldPlaceholder")}
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                className="min-h-[150px] rounded-[2rem] bg-muted/30 border-none focus-visible:ring-primary p-6 text-base leading-relaxed font-medium resize-none shadow-inner"
              />
              <div className={cn("absolute bottom-4 opacity-10 group-focus-within:opacity-30 transition-opacity", isAr ? "left-4" : "right-4")}>
                <Sparkles className="h-6 w-6" />
              </div>
            </div>
          </div>
        </div>
        <DialogFooter className="gap-3">
          <Button
            variant="ghost"
            className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-8"
            onClick={() => onOpenChange(false)}
          >
            {t("buttons.cancel")}
          </Button>
          <Button
            className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-12 shadow-xl shadow-primary/20"
            onClick={handleApply}
            disabled={isLoading}
          >
            {isLoading ? (
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
            ) : (
              <Send className={cn("h-4 w-4 mr-2", isAr && "rotate-180")} />
            )}
            {t("buttons.submitApplication")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { useState, useMemo } from "react";
import { 
  Users, 
  CheckCircle2, 
  QrCode, 
  ScanLine, 
  History
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { motion, AnimatePresence } from "framer-motion";
import { format } from "date-fns";
import { ar } from "date-fns/locale";
import { Enrollment, AttendanceStatus } from "@/types";
import { QRAttendanceModal } from "../components/qr-attendance-modal";
import { QRScannerModal } from "../components/qr-scanner-modal";
import { EmptyState } from "@/components/empty-state";
import { useTranslation } from "react-i18next";
import { cn } from "@/lib/utils";

// Logic & Components
import { useAttendanceDetails } from "../hooks/use-attendance-details";
import { 
  AttendanceStats, 
  AttendanceMarkTable, 
  AttendanceHistoryTable 
} from "../components/attendance-components";

interface AttendanceTabProps {
  classId: string;
  enrollments: Enrollment[];
}

export const AttendanceTab = ({ classId, enrollments }: AttendanceTabProps) => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === "ar";
  const [viewMode, setViewMode] = useState<"mark" | "history">("mark");
  const [selectedDate] = useState<Date>(new Date());
  
  const {
    attendanceData,
    stats,
    isStaff,
    isLoading,
    isUpdating,
    handleMarkAttendance,
    handleValueChange,
    handleBulkMark,
    historyData,
    isQRModalOpen,
    setIsQRModalOpen,
    isScannerModalOpen,
    setIsScannerModalOpen
  } = useAttendanceDetails(classId, enrollments, selectedDate);

  const activeEnrollments = useMemo(() => 
    enrollments.filter(e => e.status === "approved"),
    [enrollments]
  );

  if (isLoading) return (
    <div className="flex flex-col items-center justify-center py-20 gap-4 text-start">
      <div className="h-10 w-10 border-4 border-primary/10 border-t-primary rounded-full animate-spin" />
      <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/40">{(t as any)("common.searching")}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 text-start">
        <div className="space-y-1.5">
          <div className="flex items-center gap-2">
            <div className="p-1.5 rounded-lg bg-primary/10 text-primary">
              <Users className="h-4 w-4" />
            </div>
            <h3 className="text-xl font-black tracking-tight">{(t as any)("classes.attendance.title")}</h3>
          </div>
          <p className="text-sm text-muted-foreground font-medium">
            {format(selectedDate, "EEEE, MMMM do, yyyy", { locale: isAr ? ar : undefined })}
          </p>
        </div>

        {isStaff && (
          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            <Button 
              variant="outline"
              onClick={() => setIsQRModalOpen(true)}
              className="flex-1 md:flex-none h-11 rounded-xl px-6 font-black uppercase tracking-widest text-[10px] gap-2 border-primary/20 text-primary hover:bg-primary/5 transition-all shadow-sm"
            >
              <QrCode className="h-4 w-4" />
              {(t as any)("classes.attendance.generateQR")}
            </Button>
            <Button 
              onClick={() => setIsScannerModalOpen(true)}
              className="flex-1 md:flex-none h-11 rounded-xl px-6 font-black uppercase tracking-widest text-[10px] gap-2 shadow-lg shadow-primary/20 transition-all active:scale-95"
            >
              <ScanLine className="h-4 w-4" />
              {(t as any)("classes.attendance.scanQR")}
            </Button>
          </div>
        )}
      </div>

      {activeEnrollments.length === 0 ? (
        <EmptyState 
          icon={Users}
          title={(t as any)("classes.attendance.noStudents")}
          description={(t as any)("classes.attendance.noStudentsDesc")}
        />
      ) : (
        <div className="space-y-10">
          {/* Dashboard Stats */}
          <AttendanceStats stats={stats as any} />

          {/* Main Content Area */}
          <div className="space-y-6">
            <div className="flex items-center justify-between px-2">
                <div className="flex items-center gap-1.5">
                    <Button 
                        variant="ghost" 
                        size="sm" 
                        onClick={() => setViewMode("mark")}
                        className={cn(
                            "h-9 rounded-full px-5 text-[10px] font-black uppercase tracking-widest transition-all",
                            viewMode === "mark" ? "bg-primary text-white shadow-lg shadow-primary/20" : "text-muted-foreground hover:bg-primary/5"
                        )}
                    >
                        <CheckCircle2 className="h-3.5 w-3.5 me-1.5" />
                        {(t as any)("classes.attendance.markAttendance")}
                    </Button>
                    <Button 
                        variant="ghost" 
                        size="sm" 
                        onClick={() => setViewMode("history")}
                        className={cn(
                            "h-9 rounded-full px-5 text-[10px] font-black uppercase tracking-widest transition-all",
                            viewMode === "history" ? "bg-primary text-white shadow-lg shadow-primary/20" : "text-muted-foreground hover:bg-primary/5"
                        )}
                    >
                        <History className="h-3.5 w-3.5 me-1.5" />
                        {(t as any)("classes.attendance.viewHistory")}
                    </Button>
                </div>

                {viewMode === "mark" && isStaff && (
                    <div className="flex items-center gap-2">
                        <Button 
                            variant="ghost" 
                            size="sm"
                            onClick={() => handleBulkMark(AttendanceStatus.PRESENT)}
                            className="h-8 rounded-lg text-[9px] font-black uppercase tracking-widest text-emerald-600 hover:bg-emerald-500/10"
                        >
                            {(t as any)("classes.attendance.markAllPresent")}
                        </Button>
                    </div>
                )}
            </div>

            <AnimatePresence mode="wait">
                <motion.div
                    key={viewMode}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{ duration: 0.2 }}
                >
                    {viewMode === "mark" ? (
                        <AttendanceMarkTable 
                            enrollments={activeEnrollments}
                            attendanceData={attendanceData}
                            onStatusChange={handleMarkAttendance}
                            onValueChange={handleValueChange}
                            isAr={isAr}
                        />
                    ) : (
                        <AttendanceHistoryTable 
                            historyData={historyData || []}
                            isTeacher={isStaff}
                            isAr={isAr}
                        />
                    )}
                </motion.div>
            </AnimatePresence>
          </div>
        </div>
      )}

      {/* Modals */}
      {isStaff && (
        <>
          <QRAttendanceModal 
            isOpen={isQRModalOpen}
            onClose={() => setIsQRModalOpen(false)}
            classId={classId}
          />
          <QRScannerModal 
            isOpen={isScannerModalOpen}
            onClose={() => setIsScannerModalOpen(false)}
            classId={classId}
          />
        </>
      )}
    </div>
  );
};

import { useForm } from "@refinedev/react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { CreateView } from "@/components/refine-ui/views/create-view";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb";
import { Textarea } from "@/components/ui/textarea";
import { useBack, useList, useGetIdentity, HttpError, BaseRecord } from "@refinedev/core";
import { Loader2, Check, ChevronLeft, LayoutDashboard, BookOpen, Users, Palette, FileText, Sparkles, PlusCircle, Info, Calendar } from "lucide-react";
import { classCreateFormSchema } from "@/schemas/class";
import { Subject, User, ClassStatus, AcademicTerm } from "@/types";
import { toast } from "sonner";
import z from "zod";
import { cn } from "@/lib/utils";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { useState } from "react";

type ClassCreateFormValues = z.infer<typeof classCreateFormSchema>;

const PRESET_COLORS = [
  "#3b82f6", // Blue
  "#ef4444", // Red
  "#10b981", // Emerald
  "#f59e0b", // Amber
  "#8b5cf6", // Violet
  "#ec4899", // Pink
  "#06b6d4", // Cyan
  "#71717a", // Zinc
];

const ClassesCreate = () => {
  const { t, i18n } = useTranslation();
  const back = useBack();
  const { data: identity } = useGetIdentity<User>();
  const [isCreatingNewSubject, setIsCreatingNewSubject] = useState(false);

  const form = useForm<BaseRecord, HttpError, ClassCreateFormValues>({
    resolver: zodResolver(classCreateFormSchema) as any,
    refineCoreProps: {
      resource: "classes",
      action: "create",
      redirect: "list",
    },
    defaultValues: {
      name: "",
      description: "",
      subjectId: undefined,
      termId: undefined,
      capacity: 30,
      status: ClassStatus.ACTIVE,
      schedules: [],
      color: PRESET_COLORS[0],
      newSubjectName: "",
    },
  });

  const {
    refineCore: { onFinish },
    handleSubmit,
    formState: { isSubmitting },
    watch,
    setValue,
  } = form;

  const selectedColor = watch("color");

  const onSubmit = async (values: ClassCreateFormValues) => {
    if (!identity?.id) {
      toast.error(t("classes.create.identityError"));
      return;
    }

    // Ensure only one of subjectId or newSubjectName is sent
    const payload = { ...values, teacherId: identity.id };
    if (isCreatingNewSubject) {
      delete payload.subjectId; // Remove subjectId if creating new
    } else {
      delete payload.newSubjectName; // Remove newSubjectName if using existing
    }

    await onFinish(payload as any);
  };

  const { query: subjectsQuery } = useList<Subject>({
    resource: "subjects",
    pagination: { pageSize: 100 },
  });

  const { query: termsQuery } = useList<AcademicTerm>({
    resource: "academic-terms",
    pagination: { pageSize: 100 },
    filters: [
      {
        field: "status",
        operator: "in",
        value: ["active", "upcoming"],
      },
    ],
  });

  const subjects = subjectsQuery.data?.data ?? [];
  const subjectsLoading = subjectsQuery.isLoading;

  const terms = termsQuery.data?.data ?? [];
  const termsLoading = termsQuery.isLoading;

  const isAr = i18n.language === 'ar';

  return (
    <CreateView className="class-view pb-20">
      <div className="flex flex-col gap-8">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 text-start">
          <div className="space-y-1">
            <Breadcrumb />
            <h1 className="text-4xl font-black tracking-tighter leading-none">{t("classes.create.title")}</h1>
            <p className="text-muted-foreground font-medium">{t("classes.create.description")}</p>
          </div>
          <Button 
            variant="outline" 
            onClick={() => back()}
            className="rounded-xl h-11 px-6 font-black uppercase tracking-widest text-[10px] gap-2 border-primary/20 hover:bg-primary/5 text-primary transition-all"
          >
            <ChevronLeft className={cn("h-4 w-4", isAr && "rotate-180")} />
            {t("buttons.goBack")}
          </Button>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Card className="border-none shadow-2xl bg-card/50 backdrop-blur-xl rounded-[2rem] overflow-hidden text-start">
            <div className="h-1.5 w-full transition-colors duration-500" style={{ backgroundColor: selectedColor }} />
            <CardHeader className="p-8 pb-4">
              <CardTitle className="text-sm font-black uppercase tracking-widest flex items-center gap-2 opacity-60">
                <LayoutDashboard className="h-4 w-4" />
                {t("classes.create.configuration")}
              </CardTitle>
            </CardHeader>
            <CardContent className="p-8 pt-4">
              <Form {...form}>
                <form onSubmit={handleSubmit(onSubmit)} className="space-y-10">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-8">
                      <FormField
                        control={form.control}
                        name="name"
                        render={({ field }) => (
                          <FormItem className="space-y-3">
                            <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                              <LayoutDashboard className="h-3 w-3" />
                              {t("classes.form.className")} <span className="text-destructive">*</span>
                            </FormLabel>
                            <FormControl>
                              <Input placeholder={t("classes.form.classNamePlaceholder")} {...field} className="h-14 rounded-2xl bg-muted/20 border-none focus-visible:ring-primary font-bold" />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <FormField
                          control={form.control}
                          name="subjectId"
                          render={({ field }) => (
                            <FormItem className="space-y-3">
                              <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                                <BookOpen className="h-3 w-3" />
                                {t("classes.form.subjectArea")} <span className="text-destructive">*</span>
                              </FormLabel>
                              <Select
                                onValueChange={(value) => {
                                  if (value === "new-subject") {
                                    setIsCreatingNewSubject(true);
                                    field.onChange(undefined); // Clear subjectId
                                  } else {
                                    setIsCreatingNewSubject(false);
                                    setValue("newSubjectName", ""); // Clear new subject name
                                    field.onChange(Number(value));
                                  }
                                }}
                                value={isCreatingNewSubject ? "new-subject" : (field.value?.toString() || "")}
                                disabled={subjectsLoading}
                              >
                                <FormControl>
                                  <SelectTrigger className="h-14 rounded-2xl bg-muted/20 border-none focus:ring-primary transition-all font-bold">
                                    <SelectValue placeholder={t("classes.form.selectSubject")} />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent className="rounded-xl border-none shadow-2xl">
                                  {subjects.map((subject) => (
                                    <SelectItem key={subject.id} value={subject.id.toString()} className="rounded-lg font-bold text-start">
                                      {subject.name}
                                    </SelectItem>
                                  ))}
                                  <SelectItem value="new-subject" className="rounded-lg font-bold text-start text-primary">
                                    <PlusCircle className="inline-block h-4 w-4 me-2" /> {t("classes.form.createNewSubject")}
                                  </SelectItem>
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        {isCreatingNewSubject && (
                          <FormField
                            control={form.control}
                            name="newSubjectName"
                            render={({ field }) => (
                              <FormItem className="space-y-3">
                                <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                                  <BookOpen className="h-3 w-3" />
                                  {t("classes.form.newSubjectName")} <span className="text-destructive">*</span>
                                </FormLabel>
                                <FormControl>
                                  <Input placeholder={t("classes.form.newSubjectName")} {...field} className="h-14 rounded-2xl bg-muted/20 border-none focus-visible:ring-primary font-bold" />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        )}
                        {!isCreatingNewSubject && ( // Only show term selector if not creating a new subject
                          <FormField
                            control={form.control}
                            name="termId"
                            render={({ field }) => (
                              <FormItem className="space-y-3">
                                <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                                  <Calendar className="h-3 w-3" />
                                  {t("classes.form.academicTerm")} <span className="text-destructive">*</span>
                                </FormLabel>
                                <Select
                                  onValueChange={(value) => field.onChange(Number(value))}
                                  value={field.value?.toString()}
                                  disabled={termsLoading}
                                >
                                  <FormControl>
                                    <SelectTrigger className="h-14 rounded-2xl bg-muted/20 border-none focus:ring-primary transition-all font-bold">
                                      <SelectValue placeholder={t("classes.form.selectTerm")} />
                                    </SelectTrigger>
                                  </FormControl>
                                  <SelectContent className="rounded-xl border-none shadow-2xl">
                                    {terms.map((term) => (
                                      <SelectItem key={term.id} value={term.id.toString()} className="rounded-lg font-bold text-start">
                                        {term.name}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        )}
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <FormField
                          control={form.control}
                          name="capacity"
                          render={({ field }) => (
                            <FormItem className="space-y-3">
                              <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                                <Users className="h-3 w-3" />
                                {t("classes.form.capacity")} <span className="text-destructive">*</span>
                              </FormLabel>
                              <FormControl>
                                <div className="relative group">
                                  <Input
                                    type="number"
                                    min={1}
                                    placeholder="30"
                                    {...field}
                                    onChange={(e) => field.onChange(e.target.value === '' ? undefined : Number(e.target.value))}
                                    className="h-14 rounded-2xl bg-muted/20 border-none focus-visible:ring-primary font-black text-center text-xl"
                                  />
                                  <span className={cn("absolute top-1/2 -translate-y-1/2 text-[10px] font-black opacity-20 group-focus-within:opacity-40 transition-opacity", isAr ? "left-4" : "right-4")}>
                                    {t("classes.form.studentsUnit")}
                                  </span>
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                         <FormField
                        control={form.control}
                        name="color"
                        render={({ field }) => (
                          <FormItem className="space-y-4">
                            <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                              <Palette className="h-3 w-3" />
                              {t("classes.form.themeColor")}
                            </FormLabel>
                            <FormControl>
                              <div className="flex flex-wrap gap-3 p-4 rounded-2xl bg-muted/10 border border-black/[0.03] dark:border-white/[0.03]">
                                {PRESET_COLORS.map((color) => (
                                  <button
                                    key={color}
                                    type="button"
                                    className={cn(
                                      "h-10 w-10 rounded-full border-4 transition-all hover:scale-110 flex items-center justify-center shadow-sm",
                                      field.value === color ? "border-white dark:border-white/5 scale-110 ring-2 ring-primary" : "border-transparent"
                                    )}
                                    style={{ backgroundColor: color }}
                                    onClick={() => field.onChange(color)}
                                  >
                                    {field.value === color && <Check className="h-5 w-5 text-white" />}
                                  </button>
                                ))}
                              </div>
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      </div>


                    </div>

                    <div className="space-y-8">
                      <FormField
                        control={form.control}
                        name="description"
                        render={({ field }) => (
                          <FormItem className="space-y-3">
                            <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                              <FileText className="h-3 w-3" />
                              {t("classes.form.description")}
                            </FormLabel>
                            <FormControl>
                              <div className="relative group">
                                <Textarea 
                                  placeholder={t("classes.form.descriptionPlaceholder")} 
                                  className="min-h-[280px] rounded-[1.5rem] bg-muted/20 border-none focus-visible:ring-primary p-6 text-sm leading-relaxed shadow-inner transition-all"
                                  {...field} 
                                />
                                <div className={cn("absolute bottom-4 opacity-10 group-focus-within:opacity-30 transition-opacity", isAr ? "left-4" : "right-4")}>
                                  <Sparkles className="h-8 w-8" />
                                </div>
                              </div>
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </div>

                  <div className="pt-6 border-t border-black/[0.03] dark:border-white/[0.03]">
                    <Button 
                      type="submit" 
                      size="lg" 
                      className="w-full h-16 rounded-[1.5rem] font-black uppercase tracking-[0.3em] shadow-2xl shadow-primary/30 transition-all hover:scale-[1.01] active:scale-[0.99] relative overflow-hidden group"
                      disabled={isSubmitting}
                    >
                      <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:animate-[shine_2s_infinite] pointer-events-none" />
                      {isSubmitting ? (
                        <div className="flex gap-3 items-center">
                          <Loader2 className="h-6 w-6 animate-spin" />
                          <span>{t("buttons.creatingClassroom")}</span>
                        </div>
                      ) : (
                        <div className="flex gap-3 items-center">
                          <PlusCircle className="h-6 w-6" />
                          <span>{t("buttons.createClass")}</span>
                        </div>
                      )}
                    </Button>
                    <div className="mt-4 flex items-center justify-center gap-2 text-muted-foreground/40">
                      <Info className="h-3.5 w-3.5" />
                      <span className="text-[9px] font-black uppercase tracking-widest">{t("classes.create.inviteNote")}</span>
                    </div>
                  </div>
                </form>
              </Form>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </CreateView>
  );
};

export default ClassesCreate;

import {
  useCreate,
  useCustomMutation,
  useDelete,
  useGetIdentity,
  useGo,
  useList,
  CrudFilter,
} from "@refinedev/core";
import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { Module, Progress, Resource, User, UserRole, ListResponse } from "@/types";
import { CurriculumEmptyState } from "../components/class-empty-states";
import { Accordion } from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import {
  BookOpen,
  LayoutDashboard,
  Loader2,
  PlusCircle,
  Sparkles,
  Wand2,
  Zap,
} from "lucide-react";
import { toast } from "sonner";
import { ModuleItem } from "@/components/classes/curriculum/module-item";
import {
  MagicBuilderConfig,
  MagicBuilderDialog,
} from "@/components/classes/curriculum/magic-builder-dialog";
import { CreateModuleDialog } from "@/components/classes/curriculum/create-module-dialog";
import { AddResourceDialog } from "@/components/classes/curriculum/add-resource-dialog";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { CanAccess } from "@/components/auth/can-access";
import { useDashboard } from "@/features/dashboard/hooks/use-dashboard";

interface CurriculumTabProps {
  classId: string;
}

export const CurriculumTab = ({ classId }: CurriculumTabProps) => {
  const { t, i18n } = useTranslation();
  const { coreData } = useDashboard();
  const isAr = i18n.language === "ar";
  const { data: identity } = useGetIdentity<User>();
  const isTeacher =
    identity?.role === UserRole.TEACHER || identity?.role === UserRole.ADMIN;
  const isStudent = identity?.role === UserRole.STUDENT;
  const go = useGo();

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newModuleName, setNewModuleName] = useState("");
  const [newModuleDesc, setNewModuleDesc] = useState("");

  const [isMagicModalOpen, setIsMagicModalOpen] = useState(false);
  const [isMagicCreating, setIsMagicCreating] = useState(false);
  const [magicConfig, setMagicConfig] = useState<MagicBuilderConfig>({
    topic: "",
    type: "package",
    level: "high_school",
    tone: "academic",
    objectives: "",
    moduleId: null,
  });

  const [isAddResourceOpen, setIsAddResourceOpen] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<number | null>(null);
  const [newResource, setNewResource] = useState({
    title: "",
    description: "",
    type: "file" as "file" | "link" | "video" | "note" | "other",
    url: "",
    content: "",
    cldPubId: "",
  });

  const { query: modulesQuery } = useList<Module>({
    resource: "modules",
    filters: [{ field: "classId", operator: "eq" as const, value: Number(classId) }],
    queryOptions: { enabled: !!classId },
  });

  const { query: progressQuery } = useList<Progress>({
    resource: "progress",
    filters: [{ field: "classId", operator: "eq" as const, value: Number(classId) }],
    queryOptions: { enabled: !!classId && isStudent },
  });

  const modules = modulesQuery.data?.data || [];
  const userProgress = progressQuery.data?.data || [];
  const isLoading = modulesQuery.isLoading;

  const { mutate: createModule } = useCreate();
  const { mutate: createResource } = useCreate<Resource>();
  const { mutate: deleteModule } = useDelete();
  const { mutate: customMutation } = useCustomMutation();
  const queryClient = useQueryClient();

  const isItemCompleted = (
    type: "resource" | "assignment" | "quiz",
    id: number,
  ) => {
    return userProgress.some(
      (p: Progress) =>
        p.isCompleted &&
        ((type === "resource" && p.resourceId === id) ||
          (type === "assignment" && p.assignmentId === id) ||
          (type === "quiz" && p.quizId === id)),
    );
  };

  const handleToggleProgress = async (
    type: "resource" | "assignment" | "quiz",
    id: number,
    moduleId: number,
  ) => {
    const currentStatus = isItemCompleted(type, id);
    const queryKey: [string, { filters: CrudFilter[] }] = [
      "progress",
      { filters: [{ field: "classId", operator: "eq" as const, value: Number(classId) }] },
    ];

    // 1. Cancel any outgoing refetches (so they don't overwrite our optimistic update)
    await queryClient.cancelQueries({ queryKey });

    // 2. Snapshot the previous value
    const previousProgress = queryClient.getQueryData<ListResponse<Progress>>(queryKey);

    // 3. Optimistically update to the new value
    queryClient.setQueryData(queryKey, (old: ListResponse<Progress> | undefined) => {
      if (!old || !old.data) return old;

      let newData = [...old.data];
      if (!currentStatus) {
        // Add a temporary progress record
        newData.push({
          id: Math.random(), // Temp ID
          classId: Number(classId),
          moduleId,
          resourceId: type === "resource" ? id : null,
          assignmentId: type === "assignment" ? id : null,
          quizId: type === "quiz" ? id : null,
          isCompleted: true,
          completedAt: new Date().toISOString(),
          userId: identity?.id || "",
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        } as Progress);
      } else {
        // Remove the record
        newData = newData.filter(
          (p: Progress) =>
            !(
              (type === "resource" && p.resourceId === id) ||
              (type === "assignment" && p.assignmentId === id) ||
              (type === "quiz" && p.quizId === id)
            ),
        );
      }
      return { ...old, data: newData };
    });

    // 4. Perform the actual mutation
    customMutation(
      {
        url: "progress/toggle",
        method: "post",
        values: {
          classId: Number(classId),
          moduleId,
          resourceId: type === "resource" ? id : undefined,
          assignmentId: type === "assignment" ? id : undefined,
          quizId: type === "quiz" ? id : undefined,
          isCompleted: !currentStatus,
        },
      },
      {
        onSuccess: () => {
          // Optional: Refetch to ensure we have the correct server-generated ID
          void progressQuery.refetch();
          toast.success(
            !currentStatus
              ? t("classes.curriculum.toast.completed")
              : t("classes.curriculum.toast.incomplete"),
          );
        },
        onError: () => {
          // Rollback on error
          queryClient.setQueryData(queryKey, previousProgress);
          toast.error("Failed to update progress.");
        },
      },
    );
  };

  const handleCreateModule = () => {
    if (!newModuleName.trim()) return;
    createModule(
      {
        resource: "modules",
        values: {
          name: newModuleName,
          description: newModuleDesc,
          classId: Number(classId),
          order: modules.length,
        },
      },
      {
        onSuccess: () => {
          setIsCreateModalOpen(false);
          setNewModuleName("");
          setNewModuleDesc("");
          void modulesQuery.refetch();
        },
      },
    );
  };

  const handleMagicCreate = () => {
    if (!magicConfig.topic.trim()) return;
    setIsMagicCreating(true);
    customMutation(
      {
        url: "modules/magic-create",
        method: "post",
        values: { classId: Number(classId), ...magicConfig },
        meta: {
            invalidates: ["modules"],
        }
      },
      {
        onSuccess: () => {
          setIsMagicCreating(false);
          setIsMagicModalOpen(false);
          void modulesQuery.refetch();
        },
        onError: () => setIsMagicCreating(false),
      },
    );
  };

  const handleAddResource = () => {
    if (!newResource.title || !activeModuleId) return;
    createResource(
      {
        resource: "resources",
        values: {
          ...newResource,
          classId: Number(classId),
          moduleId: activeModuleId,
        },
      },
      {
        onSuccess: () => {
          setIsAddResourceOpen(false);
          setNewResource({
            title: "",
            description: "",
            type: "file",
            url: "",
            content: "",
            cldPubId: "",
          });
          void modulesQuery.refetch();
        },
      },
    );
  };

  if (isLoading)
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4 text-start">
        <Loader2 className="h-10 w-10 animate-spin text-primary/20" />
        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/40">
          {t("classes.curriculum.loading")}
        </p>
      </div>
    );

  return (
    <div className="space-y-6 md:space-y-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 text-start">
        <div className="space-y-1 md:space-y-2">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-lg bg-primary/10 text-primary">
              <BookOpen className="h-4 w-4 md:h-5 md:w-5" />
            </div>
            <h3 className="text-xl md:text-2xl font-black tracking-tight">
              {t("classes.curriculum.courseCurriculum")}
            </h3>
          </div>
          <p className="text-sm md:text-base text-muted-foreground font-medium max-w-2xl">
            {t("classes.curriculum.curriculumDescription")}
          </p>
        </div>

        {isTeacher && (
          <div className="flex items-center gap-2 md:gap-3 w-full md:w-auto">
            {coreData?.globalConfig?.enableAiFeatures !== false && (
              <CanAccess resource="modules" action="create" params={{ classId }}>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        id="guide-magic-builder"
                        variant="outline"
                        className="flex-1 md:flex-none rounded-xl h-10 md:h-12 px-4 md:px-8 border-ai-primary/20 text-ai-primary hover:bg-ai-primary/5 font-black uppercase tracking-widest text-[9px] md:text-[10px] gap-2 relative overflow-hidden group shadow-sm"
                        onClick={() => {
                          setMagicConfig({
                            ...magicConfig,
                            moduleId: null,
                            type: "package",
                          });
                          setIsMagicModalOpen(true);
                        }}
                      >
                        <div className="absolute inset-0 bg-linear-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:animate-[shine_1.5s_ease-in-out] pointer-events-none" />
                        <Wand2 className="h-3.5 w-3.5 md:h-4 md:w-4" />
                        <span className="truncate">
                          {t("buttons.magicBuilder")}
                        </span>
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent className="max-w-xs text-center border-ai-primary/20 bg-background/95 backdrop-blur-xl p-3 shadow-2xl rounded-xl">
                      <div className="flex items-center justify-center mb-1">
                        <Sparkles className="h-4 w-4 text-ai-primary animate-pulse mr-2" />
                        <span className="font-bold">
                          {t("tooltips.magicBuilder.title")}
                        </span>
                      </div>
                      <p className="text-sm text-muted-foreground">
                        {t("tooltips.magicBuilder.description")}
                      </p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </CanAccess>
            )}

            <CanAccess resource="modules" action="create" params={{ classId }}>
              <Button
                id="guide-add-module"
                onClick={() => {
                  setNewModuleName("");
                  setNewModuleDesc("");
                  setIsCreateModalOpen(true);
                }}
                className="flex-1 md:flex-none rounded-xl h-10 md:h-12 px-4 md:px-8 font-black uppercase tracking-widest text-[9px] md:text-[10px] gap-2 shadow-lg shadow-primary/20 transition-all active:scale-95"
              >
                <PlusCircle className="h-3.5 w-3.5 md:h-4 md:w-4" />
                <span className="truncate">{t("buttons.addModule")}</span>
              </Button>
            </CanAccess>
          </div>
        )}
      </div>

      {modules.length === 0 ? (
        <CurriculumEmptyState
          isTeacher={isTeacher}
          onAddClick={() => setIsCreateModalOpen(true)}
          onMagicClick={() => setIsMagicModalOpen(true)}
        />
      ) : (
        <div className="space-y-6">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-2 text-[9px] md:text-[10px] font-black uppercase tracking-widest text-muted-foreground/60">
              <LayoutDashboard className="h-3 w-3" />
              {t("classes.curriculum.modulesPublished", {
                count: modules.length,
              })}
            </div>
            {isStudent && (
              <div className="flex items-center gap-1.5 md:gap-2 text-[9px] md:text-[10px] font-black uppercase tracking-widest text-primary">
                <Zap className="h-3 w-3 md:h-3.5 md:w-3.5" />
                <span>
                  {t("classes.curriculum.itemsCompleted", {
                    count: userProgress.filter((p) => p.isCompleted).length,
                  })}
                </span>
              </div>
            )}
          </div>

          <Accordion type="multiple" className="w-full space-y-4 md:space-y-6">
            <AnimatePresence mode="popLayout">
              {modules.map((module, idx) => (
                <motion.div
                  key={module.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                >
                  <ModuleItem
                    module={module}
                    isTeacher={isTeacher}
                    isStudent={isStudent}
                    classId={classId}
                    isItemCompleted={isItemCompleted}
                    onToggleProgress={handleToggleProgress}
                    onDeleteModule={(id) =>
                      deleteModule(
                        { resource: "modules", id },
                        {
                          onSuccess: () => {
                            void modulesQuery.refetch();
                          },
                        },
                      )
                    }
                    onMagicAction={(moduleId, type) => {
                      setMagicConfig({
                        ...magicConfig,
                        moduleId,
                        type: type as "package" | "note" | "quiz" | "assignment",
                      });
                      setIsMagicModalOpen(true);
                    }}
                    onAddMaterial={(moduleId) => {
                      setActiveModuleId(moduleId);
                      setNewResource({
                        title: "",
                        description: "",
                        type: "file",
                        url: "",
                        content: "",
                        cldPubId: "",
                      });
                      setIsAddResourceOpen(true);
                    }}
                    onAddTask={(moduleId) =>
                      go({
                        to: `/assignments/create?classId=${classId}&moduleId=${moduleId}`,
                      })
                    }
                  />
                </motion.div>
              ))}
            </AnimatePresence>
          </Accordion>
        </div>
      )}

      {isTeacher && (
        <MagicBuilderDialog
          isOpen={isMagicModalOpen}
          onOpenChange={setIsMagicModalOpen}
          config={magicConfig}
          setConfig={setMagicConfig}
          onGenerate={handleMagicCreate}
          isGenerating={isMagicCreating}
          classId={Number(classId)}
        />
      )}

      <AddResourceDialog
        isOpen={isAddResourceOpen}
        onOpenChange={setIsAddResourceOpen}
        resource={newResource}
        setResource={setNewResource}
        onSave={handleAddResource}
      />

      <CreateModuleDialog
        isOpen={isCreateModalOpen}
        onOpenChange={setIsCreateModalOpen}
        name={newModuleName}
        setName={setNewModuleName}
        description={newModuleDesc}
        setDescription={setNewModuleDesc}
        onCreate={handleCreateModule}
      />
    </div>
  );
};

import {
  useList,
  useCreate,
  useDelete,
  useGetIdentity,
  useCustomMutation,
  HttpError,
} from "@refinedev/core";
import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Discussion, User, UserRole } from "@/types";
import {
  Loader2,
  Send,
  Sparkles,
  X,
  MessageCircle,
  LayoutDashboard,
  ArrowRight,
  Trophy,
  Info,
  Reply,
} from "lucide-react";
import { toast } from "sonner";
import { ChatBubble } from "@/components/classes/chat-bubble";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MarkdownRenderer } from "@/components/ui/markdown-renderer";
import { RichTextEditor } from "@/components/ui/rich-text-editor";
import { getSocket } from "@/lib/socket";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";
import { Badge } from "@/components/ui/badge";
import { useTranslation } from "react-i18next";
import { useUserRole } from "@/hooks/use-user-role";

interface DiscussionTabProps {
  classId: string;
}

export const DiscussionTab = ({ classId }: DiscussionTabProps) => {
  const { t } = useTranslation();
  const { data: identity } = useGetIdentity<User>();
  const { isStaff } = useUserRole();
  const [newPost, setNewPost] = useState("");
  const [replyTo, setReplyTo] = useState<number | null>(null);
  
  // 🛡️ AUTO-DRAFT: Discussion Persistence
  useEffect(() => {
      const draftKey = `draft:discussion:${classId}${replyTo ? `:${replyTo}` : ''}`;
      if (newPost && newPost !== "<p></p>") {
          localStorage.setItem(draftKey, newPost);
      } else {
          localStorage.removeItem(draftKey);
      }
  }, [newPost, classId, replyTo]);

  // 🚀 DRAFT RECOVERY
  useEffect(() => {
      const draftKey = `draft:discussion:${classId}${replyTo ? `:${replyTo}` : ''}`;
      const saved = localStorage.getItem(draftKey);
      if (saved && !newPost) {
          setNewPost(saved);
      }
  }, [classId, replyTo]);

  const scrollRef = useRef<HTMLDivElement>(null);

  const [summary, setSummary] = useState<string | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);

  const { query } = useList<Discussion>({
    resource: "discussions",
    filters: [
      { field: "classId", operator: "eq", value: classId },
      { field: "parentId", operator: "null", value: true },
    ],
    pagination: { mode: "off" },
    queryOptions: { enabled: !!classId },
  });

  const discussions = query.data?.data || [];
  const isLoading = query.isLoading;
  const refetch = query.refetch;

  const { mutate: createPost, mutation } = useCreate<Discussion, HttpError, { content: string; classId: number; parentId: number | null }>();
  const { mutate: deletePost } = useDelete();
  const { mutate: solvePost } = useCustomMutation();
  const { mutate: generateSummary } = useCustomMutation();

  useEffect(() => {
    if (scrollRef.current) {
      const viewport = scrollRef.current.querySelector(
        "[data-radix-scroll-area-viewport]",
      );
      if (viewport) viewport.scrollTop = viewport.scrollHeight;
    }
  }, [discussions]);

  useEffect(() => {
    if (!identity?.id || !classId) return;

    const socket = getSocket();

    const handleNewDiscussion = () => {
      void refetch();
    };

    const handleDeleteDiscussion = () => {
      void refetch();
    };

    const handleDiscussionSolved = (payload: { message?: string }) => {
        toast.success(payload.message || "A question has been solved!", {
            icon: <Trophy className="w-4 h-4 text-yellow-500" />,
            duration: 5000,
        });
        void refetch();
    };

    socket.on("new_discussion", handleNewDiscussion);
    socket.on("delete_discussion", handleDeleteDiscussion);
    socket.on("discussion_solved", handleDiscussionSolved);

    return () => {
      socket.off("new_discussion", handleNewDiscussion);
      socket.off("delete_discussion", handleDeleteDiscussion);
      socket.off("discussion_solved", handleDiscussionSolved);
    };
  }, [identity?.id, classId, refetch]);

  const handlePost = () => {
    if (!newPost.trim() || newPost === "<p></p>") return;
    createPost(
      {
        resource: "discussions",
        values: {
          content: newPost,
          classId: Number(classId),
          parentId: replyTo,
        },
      },
      {
        onSuccess: () => {
          setNewPost("");
          setReplyTo(null);
          toast.success(
            replyTo
              ? t("classes.discussion.toast.replySent")
              : t("classes.discussion.toast.messagePosted"),
          );
        },
      },
    );
  };

  const handleSolve = (postId: number, solverId: string) => {
      solvePost({
          url: `/discussions/${postId}/solve`,
          method: "patch",
          values: { solvedById: solverId }
      }, {
          onSuccess: () => {
              void refetch();
          }
      });
  };

  const handleGenerateSummary = () => {
    if (!discussions.length) return;
    setIsSummarizing(true);
    generateSummary(
      {
        url: `ai/discussions/summarize`,
        method: "post",
        values: { classId: Number(classId) },
      },
      {
        onSuccess: (data) => {
          const responseData = data.data as { summary: string };
          setSummary(responseData.summary);
          setIsSummarizing(false);
        },
        onError: () => {
          toast.error(t("classes.discussion.toast.summaryError"));
          setIsSummarizing(false);
        },
      },
    );
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-16rem)] max-w-5xl mx-auto space-y-4">
      {/* Discussion Header */}
      <div className="flex items-center justify-between px-2">
        <div className="flex items-center gap-2">
          <MessageCircle className="w-5 h-5 text-primary" />
          <h2 className="text-xl font-bold tracking-tight">
            {t("classes.discussion.classStream")}
          </h2>
          <Badge variant="outline" className="ml-2 font-mono">
            {discussions.length}
          </Badge>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleGenerateSummary}
            disabled={isSummarizing || !discussions.length}
            className="hidden sm:flex items-center gap-2 hover:bg-primary/10 hover:text-primary transition-colors"
          >
            {isSummarizing ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Sparkles className="h-4 w-4" />
            )}
            {t("classes.discussion.aiCatchUp")}
          </Button>
        </div>
      </div>

      {/* Summary Box */}
      <AnimatePresence>
        {summary && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="mx-2 p-4 bg-primary/5 border border-primary/20 rounded-xl relative group shadow-sm"
          >
            <div className="flex items-start gap-3">
              <div className="mt-1 p-2 bg-primary/10 rounded-lg">
                <LayoutDashboard className="w-4 h-4 text-primary" />
              </div>
              <div className="flex-1 space-y-2">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-semibold text-primary flex items-center gap-2">
                    {t("classes.discussion.aiSummary")}
                    <span className="text-[10px] uppercase tracking-wider bg-primary/10 px-1.5 py-0.5 rounded text-primary/70">
                      AI GENERATED
                    </span>
                  </h3>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-6 w-6 rounded-full hover:bg-primary/10"
                    onClick={() => setSummary(null)}
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
                <div className="text-sm leading-relaxed text-foreground/80">
                  <MarkdownRenderer content={summary} />
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Messages Area */}
      <ScrollArea
        ref={scrollRef}
        className="flex-1 px-4 rounded-2xl bg-muted/30 border shadow-inner"
      >
        <div className="py-6 space-y-8">
          {discussions.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-48 text-muted-foreground space-y-4">
              <div className="p-4 bg-muted rounded-full">
                <MessageCircle className="w-8 h-8 opacity-20" />
              </div>
              <p className="text-sm font-medium">
                {t("classes.discussion.noMessages")}
              </p>
            </div>
          ) : (
            discussions.map((discussion) => (
              <ChatBubble
                key={discussion.id}
                post={discussion}
                isOwn={discussion.user.id === identity?.id}
                isAdmin={identity?.role === UserRole.ADMIN}
                isStaff={isStaff}
                onReply={(id) => {
                  setReplyTo(id);
                  // Scroll to editor
                }}
                onSolve={handleSolve}
                onDelete={(id) => {
                  deletePost({ resource: "discussions", id });
                }}
              />
            ))
          )}
        </div>
      </ScrollArea>

      {/* Posting Area */}
      <div className="px-2 pb-2 space-y-3">
        <AnimatePresence>
          {replyTo && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              className="bg-primary/10 px-4 py-2 rounded-t-xl border-x border-t flex items-center justify-between"
            >
              <div className="flex items-center gap-2 text-xs font-medium text-primary">
                <Reply className="w-3 h-3" />
                <span>Replying to message #{replyTo}</span>
              </div>
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 text-primary hover:bg-primary/20"
                onClick={() => setReplyTo(null)}
              >
                <X className="h-3 w-3" />
              </Button>
            </motion.div>
          )}
        </AnimatePresence>

        <div
          className={cn(
            "bg-background rounded-2xl border-2 transition-all duration-200 shadow-lg",
            mutation.isPending
              ? "opacity-70 pointer-events-none"
              : "hover:border-primary/30",
            replyTo ? "rounded-t-none border-t-0" : "",
          )}
        >
          <RichTextEditor
            value={newPost}
            onChange={setNewPost}
            placeholder={t("classes.discussion.messageClass")}
            className="border-0 shadow-none ring-0 min-h-[100px]"
          />
          <div className="flex items-center justify-between p-3 bg-muted/20 border-t rounded-b-2xl">
            <div className="flex items-center gap-4 text-[10px] text-muted-foreground px-1">
              <div className="flex items-center gap-1.5">
                <div className="w-1 h-1 rounded-full bg-primary" />
                Markdown supported
              </div>
              <div className="flex items-center gap-1.5">
                <div className="w-1 h-1 rounded-full bg-green-500" />
                Real-time sync
              </div>
            </div>
            <Button
              onClick={handlePost}
              disabled={
                mutation.isPending || !newPost.trim() || newPost === "<p></p>"
              }
              size="sm"
              className="px-6 rounded-xl shadow-md transition-all hover:translate-y-[-1px] active:translate-y-[0px]"
            >
              {mutation.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <Send className="h-4 w-4 mr-2" />
              )}
              {replyTo ? t("buttons.reply") : t("buttons.post")}
            </Button>
          </div>
        </div>

        {/* Tips / Info */}
        <div className="flex items-center justify-center gap-6 text-[11px] text-muted-foreground/60 font-medium pt-1">
          <div className="flex items-center gap-1">
            <Info className="w-3 h-3" />
            Guidelines
          </div>
          <div className="flex items-center gap-1">
            <ArrowRight className="w-3 h-3" />
            Class Community
          </div>
        </div>
      </div>
    </div>
  );
};

import { EditViewHeader } from "@/components/refine-ui/views/edit-view";
import { useForm } from "@refinedev/react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useSelect, useOne, useCustomMutation } from "@refinedev/core";
import { useParams } from "react-router-dom";
import { useFieldArray } from "react-hook-form";
import { Form } from "@/components/ui/form";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Info,
  Import,
  LayoutDashboard,
  Sparkles,
  Key,
  Loader2,
  History,
  BookOpen,
} from "lucide-react";
import { classFormSchema } from "@/schemas/class";
import { Subject, ClassStatus, Class } from "@/types";
import { ClassForm } from "./form";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useState } from "react";
import { useTerm } from "@/contexts/term-context";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";
import { useTranslation } from "react-i18next";

const ClassesEdit = () => {
  const { t, i18n } = useTranslation();
  const { id } = useParams();
  const { terms } = useTerm();
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [selectedSourceTerm, setSelectedSourceTerm] = useState<string>("");
  const [selectedSourceClass, setSelectedSourceClass] = useState<string>("");

  const isAr = i18n.language === "ar";

  const { query: classQuery } = useOne<Class>({
    resource: "classes",
    id,
  });

  const { mutate: importContent, mutation } = useCustomMutation();
  const isImporting = mutation.isPending;

  const {
    refineCore: { onFinish, formLoading },
    ...form
  } = useForm({
    resolver: zodResolver(classFormSchema),
    defaultValues: {
      name: "",
      subjectId: undefined,
      capacity: 0,
      status: ClassStatus.ACTIVE,
      schedules: [],
    },
    refineCoreProps: {
      resource: "classes",
      action: "edit",
      id,
      redirect: "list",
    },
  });

  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "schedules",
  });

  const { options: subjectOptions } = useSelect<Subject>({
    resource: "subjects",
    optionLabel: "name",
    optionValue: "id",
  });

  const { options: sourceClassOptions } = useSelect<Class>({
    resource: "classes",
    optionLabel: "name",
    optionValue: "id",
    filters: [
      {
        field: "termId",
        operator: "eq",
        value: selectedSourceTerm,
      },
    ],
    queryOptions: {
      enabled: !!selectedSourceTerm,
    },
  });

  const handleImport = () => {
    if (!selectedSourceClass) return;

    importContent(
      {
        url: `/classes/import-content`,
        method: "post",
        values: {
          sourceClassId: Number(selectedSourceClass),
          targetClassId: Number(id),
        },
        successNotification: () => {
          return {
            message: t("classes.list.toast.cloned"),
            type: "success",
          };
        },
        errorNotification: () => {
          return {
            message: t("common.error"),
            type: "error",
          };
        },
      },
      {
        onSuccess: () => {
          setIsImportOpen(false);
          setSelectedSourceClass("");
          setSelectedSourceTerm("");
        },
      },
    );
  };

  return (
    <div className="container mx-auto py-10 px-4 md:px-6 max-w-7xl pb-20" dir={isAr ? "rtl" : "ltr"}>
      <div className="flex flex-col gap-8">
        <div className="space-y-1">
          <EditViewHeader />
          <p className="text-muted-foreground font-medium">
            {t("classes.edit.subtitle")}
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 items-start">
          {/* Main Form Column */}
          <motion.div
            initial={{ opacity: 0, x: isAr ? 20 : -20 }}
            animate={{ opacity: 1, x: 0 }}
            className="lg:col-span-8"
          >
            <Card className="border-none shadow-2xl bg-card/50 backdrop-blur-xl rounded-[2rem] overflow-hidden">
              <div className="h-1.5 bg-gradient-to-r from-primary via-ai-primary to-primary w-full" />
              <CardHeader className="p-8 pb-4">
                <CardTitle className="text-sm font-black uppercase tracking-widest flex items-center gap-2 opacity-60">
                  <LayoutDashboard className="h-4 w-4" />
                  {t("classes.edit.configuration")}
                </CardTitle>
              </CardHeader>
              <CardContent className="p-8 pt-4">
                <Form {...form}>
                  <form onSubmit={form.handleSubmit(onFinish)}>
                    <ClassForm
                      form={form}
                      subjectOptions={subjectOptions}
                      fields={fields}
                      append={append}
                      remove={remove}
                      formLoading={formLoading}
                      isEdit={true}
                    />
                  </form>
                </Form>
              </CardContent>
            </Card>
          </motion.div>

          {/* Sidebar Column */}
          <motion.div
            initial={{ opacity: 0, x: isAr ? -20 : 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.1 }}
            className="lg:col-span-4 space-y-10"
          >
            {/* Editing Mode Info */}
            <Card className="border-none shadow-xl bg-primary/5 rounded-[2rem] overflow-hidden">
              <CardHeader className="p-6 pb-2">
                <CardTitle className="text-xs font-black uppercase tracking-widest flex items-center gap-2 text-primary">
                  <Info className="h-4 w-4" />
                  {t("classes.edit.editingMode")}
                </CardTitle>
              </CardHeader>
              <CardContent className="p-6 pt-2">
                <p className="text-sm font-medium text-muted-foreground leading-relaxed">
                  {t("classes.edit.editingModeDesc")}
                </p>
              </CardContent>
            </Card>

            {/* Invite Code Card */}
            <Card className="border-none shadow-xl bg-card/50 backdrop-blur-xl rounded-[2rem] overflow-hidden">
              <CardHeader className="p-6 pb-2">
                <CardTitle className="text-xs font-black uppercase tracking-widest flex items-center gap-2 opacity-60">
                  <Key className="h-4 w-4" />
                  {t("classes.edit.accessControl")}
                </CardTitle>
              </CardHeader>
              <CardContent className="p-6 pt-2 space-y-4">
                <div className="p-4 rounded-2xl bg-muted/20 border border-black/[0.03] dark:border-white/[0.03] flex flex-col items-center justify-center gap-2">
                  <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/40">
                    {t("classes.edit.inviteCode")}
                  </span>
                  <span className="text-3xl font-black font-mono tracking-[0.2em] text-primary">
                    {classQuery?.data?.data?.inviteCode ?? "..."}
                  </span>
                </div>
                <p className="text-[10px] text-center font-medium text-muted-foreground/60 px-4">
                  {t("classes.edit.inviteCodeDesc")}
                </p>
              </CardContent>
            </Card>

            {/* Content Actions Card */}
            <Card className="border-none shadow-2xl bg-ai-primary/[0.02] backdrop-blur-xl rounded-[2rem] overflow-hidden border border-ai-primary/10">
              <CardHeader className="p-6 pb-2">
                <CardTitle className="text-xs font-black uppercase tracking-widest flex items-center gap-2 text-ai-primary">
                  <Sparkles className="h-4 w-4" />
                  {t("classes.edit.contentActions")}
                </CardTitle>
              </CardHeader>
              <CardContent className="p-6 pt-2 space-y-6">
                <Dialog open={isImportOpen} onOpenChange={setIsImportOpen}>
                  <DialogTrigger asChild>
                    <Button
                      variant="outline"
                      className="w-full h-12 rounded-xl font-black uppercase tracking-widest text-[10px] gap-2 border-ai-primary/20 text-ai-primary hover:bg-ai-primary/5 relative overflow-hidden group shadow-sm"
                    >
                      <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:animate-[shine_1.5s_ease-in-out] pointer-events-none" />
                      <Import className="h-4 w-4" />
                      {t("classes.edit.importContent")}
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="sm:max-w-[550px] rounded-[2rem] border-none shadow-2xl bg-card/95 backdrop-blur-xl">
                    <DialogHeader className="space-y-3">
                      <div className="p-3 rounded-2xl bg-ai-primary/10 text-ai-primary w-fit">
                        <Import className="h-6 w-6" />
                      </div>
                      <DialogTitle className="text-2xl font-black tracking-tight">
                        {t("classes.edit.importArchive")}
                      </DialogTitle>
                      <DialogDescription className="font-medium">
                        {t("classes.edit.importArchiveDesc")}
                      </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-6 py-6">
                      <div className="space-y-2.5">
                        <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">
                          {t("classes.edit.selectSourceTerm")}
                        </Label>
                        <Select
                          onValueChange={setSelectedSourceTerm}
                          value={selectedSourceTerm}
                        >
                          <SelectTrigger className="h-12 rounded-xl bg-muted/20 border-none focus:ring-ai-primary transition-all font-bold">
                            <div className="flex items-center gap-2">
                              <History className="h-4 w-4 text-ai-primary/60" />
                              <SelectValue placeholder={t("classes.edit.selectTermPlaceholder")} />
                            </div>
                          </SelectTrigger>
                          <SelectContent className="rounded-xl border-none shadow-2xl">
                            {terms
                              .filter((t) => t.status === "archived")
                              .map((term) => (
                                <SelectItem
                                  key={term.id}
                                  value={term.id.toString()}
                                  className="rounded-lg font-bold"
                                >
                                  {term.name}
                                </SelectItem>
                              ))}
                          </SelectContent>
                        </Select>
                      </div>

                      <div className="space-y-2.5">
                        <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">
                          {t("classes.edit.selectSourceClass")}
                        </Label>
                        <Select
                          onValueChange={setSelectedSourceClass}
                          value={selectedSourceClass}
                          disabled={!selectedSourceTerm}
                        >
                          <SelectTrigger className="h-12 rounded-xl bg-muted/20 border-none focus:ring-ai-primary transition-all font-bold">
                            <div className="flex items-center gap-2">
                              <BookOpen className="h-4 w-4 text-ai-primary/60" />
                              <SelectValue placeholder={t("classes.edit.selectClassPlaceholder")} />
                            </div>
                          </SelectTrigger>
                          <SelectContent className="rounded-xl border-none shadow-2xl">
                            {sourceClassOptions.map((cls) => (
                              <SelectItem
                                key={cls.value}
                                value={cls.value.toString()}
                                className="rounded-lg font-bold"
                              >
                                {cls.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    <DialogFooter className="gap-3">
                      <Button
                        variant="ghost"
                        className="rounded-xl font-bold h-12"
                        onClick={() => setIsImportOpen(false)}
                      >
                        {t("buttons.cancel")}
                      </Button>
                      <Button
                        onClick={handleImport}
                        disabled={!selectedSourceClass || isImporting}
                        className="rounded-xl font-black uppercase tracking-widest h-12 px-8 shadow-lg shadow-ai-primary/20 bg-ai-primary text-white hover:bg-ai-primary/90"
                      >
                        {isImporting ? (
                          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        ) : (
                          <Sparkles className="h-4 w-4 mr-2" />
                        )}
                        {t("classes.edit.importContent")}
                      </Button>
                    </DialogFooter>
                  </DialogContent>
                </Dialog>
                <p className="text-[10px] text-center font-medium text-muted-foreground/40 px-4">
                  {t("classes.edit.importFooterDesc")}
                </p>
              </CardContent>
            </Card>
          </motion.div>
        </div>
      </div>
    </div>
  );
};

export default ClassesEdit;

import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { BookOpen, Calendar, Clock, Check, LayoutDashboard, Users, Palette, FileText, Sparkles, PlusCircle, Save, ShieldCheck, Loader2, Trash2 } from "lucide-react";
import { UseFormReturn, FieldArrayWithId, UseFieldArrayAppend, UseFieldArrayRemove } from "react-hook-form";
import { ClassStatus } from "@/types";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";
import { useList } from "@refinedev/core";
import { AcademicTerm } from "@/types";
import { useTranslation } from "react-i18next";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Info } from "lucide-react";

interface ClassFormProps {
  form: UseFormReturn<any>;
  subjectOptions: { value: string | number; label: string }[];
  fields: FieldArrayWithId<any, "schedules", "id">[];
  append: UseFieldArrayAppend<any, "schedules">;
  remove: UseFieldArrayRemove;
  formLoading: boolean;
  isEdit?: boolean;
}

const PRESET_COLORS = [
  "#3b82f6", // Blue
  "#ef4444", // Red
  "#10b981", // Emerald
  "#f59e0b", // Amber
  "#8b5cf6", // Violet
  "#ec4899", // Pink
  "#06b6d4", // Cyan
  "#71717a", // Zinc
];

export const ClassForm = ({ 
  form, 
  subjectOptions, 
  fields, 
  append, 
  remove,
  formLoading,
  isEdit = false
}: ClassFormProps) => {
  const { t, i18n } = useTranslation();
  const selectedColor = form.watch("color");

  const { query: termsQuery } = useList<AcademicTerm>({
    resource: "academic-terms",
    pagination: { pageSize: 100 },
    filters: [
      {
        field: "status",
        operator: "in",
        value: ["active", "upcoming"],
      },
    ],
  });

  const termsLoading = termsQuery.isLoading;
  const terms = termsQuery.data?.data || [];

  const isAr = i18n.language === 'ar';

  return (
    <div className="space-y-10">
      {/* Basic Details Card */}
      <Card className="border-none shadow-2xl bg-card/50 backdrop-blur-xl rounded-[2rem] overflow-hidden">
        <div className="h-1.5 w-full transition-colors duration-500" style={{ backgroundColor: selectedColor }} />
        <CardHeader className="p-8 pb-4">
          <CardTitle className="text-sm font-black uppercase tracking-widest flex items-center gap-2 opacity-60 text-start">
            <BookOpen className="h-4 w-4" />
            {isEdit ? t("classes.form.updateDetails") : t("classes.form.coreInfo")}
          </CardTitle>
        </CardHeader>
        <CardContent className="p-8 pt-4 space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-start">
            <FormField
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem className="space-y-3">
                  <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                    <LayoutDashboard className="h-3 w-3" />
                    {t("classes.form.className")}
                  </FormLabel>
                  <FormControl>
                    <Input placeholder={t("classes.form.classNamePlaceholder")} {...field} className="h-14 rounded-2xl bg-muted/20 border-none focus-visible:ring-primary font-bold" />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="capacity"
              render={({ field }) => (
                <FormItem className="space-y-3">
                  <div className="flex items-center gap-2">
                    <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                      <Users className="h-3 w-3" />
                      {t("classes.form.capacity")}
                    </FormLabel>
                    <TooltipProvider>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Info className="h-3 w-3 text-muted-foreground/40 cursor-help hover:text-primary transition-colors" />
                        </TooltipTrigger>
                        <TooltipContent className="max-w-[200px] text-[10px] font-medium leading-relaxed">
                          {t("classes.form.capacityHelp")}
                        </TooltipContent>
                      </Tooltip>
                    </TooltipProvider>
                  </div>
                  <FormControl>
                    <div className="relative group">
                      <Input 
                        type="number" 
                        {...field} 
                        onChange={(e) => field.onChange(e.target.value === '' ? undefined : Number(e.target.value))}
                        className="h-14 rounded-2xl bg-muted/20 border-none focus-visible:ring-primary font-black text-center text-xl" 
                      />
                      <span className={cn("absolute top-1/2 -translate-y-1/2 text-[10px] font-black opacity-20 group-focus-within:opacity-40 transition-opacity", isAr ? "left-4" : "right-4")}>
                        {t("classes.form.studentsUnit")}
                      </span>
                    </div>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-start">
            <FormField
              control={form.control}
              name="subjectId"
              render={({ field }) => (
                <FormItem className="space-y-3">
                  <FormLabel className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground flex items-center gap-2">
                    <BookOpen className="h-3 w-3" />
                    {t("classes.form.subjectArea")}
                  </FormLabel>
                  <Select 
                    onValueChange={field.onChange} 
                    value={field.value ? String(field.value) : ""}
                  >
                    <FormControl>
                      <SelectTrigger className="h-14 rounded-2xl bg-muted/20 border-none focus:ring-primary transition-all font-bold">
                        <SelectValue placeholder={t("classes.form.selectSubject")} />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent className="rounded-xl border-none shadow-2xl">
                      {subjectOptions.map((option) => (
                        <SelectItem key={option.value} value={String(option.value)} className="rounded-lg font-bold text-start">
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />
            
            <FormField
              control={form.control}
              name="termId"
              render={({ field }) => (
                <FormItem className="space-y-3">
