                    <FormField
                      control={form.control}
                      name={`schedules.${index}.endTime`}
                      render={({ field }) => (
                        <FormItem className="space-y-2">
                          <FormLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">{t("classes.form.endTime")}</FormLabel>
                          <FormControl>
                            <div className="relative group/input">
                              <Clock className={cn("absolute top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground group-focus-within/input:text-primary transition-colors", isAr ? "right-3" : "left-3")} />
                              <Input type="time" className={cn("h-12 rounded-xl bg-background border-none focus-visible:ring-primary font-bold", isAr ? "pr-10" : "pl-10")} {...field} />
                            </div>
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-12 w-12 rounded-xl text-destructive hover:bg-destructive/10 transition-colors"
                    onClick={() => remove(index)}
                  >
                    <Trash2 className="h-5 w-5" />
                  </Button>
                </motion.div>
              ))}
            </AnimatePresence>
            
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="w-full h-14 rounded-2xl border-2 border-dashed border-primary/20 text-primary hover:bg-primary/5 font-black uppercase tracking-widest text-[10px] gap-2 transition-all"
              onClick={() => append({ day: "Mon", startTime: "09:00", endTime: "10:30" })}
            >
              <PlusCircle className="h-4 w-4" />
              {t("buttons.addTimeSlot")}
            </Button>
          </div>
        </CardContent>
      </Card>

      <div className="pt-6 flex justify-end">
        <Button 
          type="submit" 
          size="lg" 
          disabled={formLoading} 
          className="h-16 rounded-[1.5rem] px-12 font-black uppercase tracking-[0.3em] shadow-2xl shadow-primary/30 transition-all hover:scale-[1.05] active:scale-[0.95] relative overflow-hidden group"
        >
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:animate-[shine_2s_infinite] pointer-events-none" />
          {formLoading ? (
            <div className="flex gap-3 items-center">
              <Loader2 className="h-6 w-6 animate-spin" />
              <span>{t("buttons.saving")}</span>
            </div>
          ) : (
            <div className="flex gap-3 items-center">
              <Save className="h-6 w-6" />
              <span>{isEdit ? t("buttons.saveChanges") : t("buttons.createClass")}</span>
            </div>
          )}
        </Button>
      </div>
    </div>
  );
};

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useSelect, useCreate, useGetIdentity, HttpError } from "@refinedev/core";
import { User, UserRole } from "@/types";
import { useState } from "react";
import { toast } from "sonner";
import { LoadingButton } from "@/components/ui/loading-button";
import { useTranslation } from "react-i18next";

interface InviteTeacherDialogProps {
  classId: string;
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  existingTeacherIds: string[];
}

export const InviteTeacherDialog = ({
  classId,
  isOpen,
  onOpenChange,
  existingTeacherIds,
}: InviteTeacherDialogProps) => {
  const { t } = useTranslation();
  const { data: identity } = useGetIdentity<User>();
  const [selectedTeacherId, setSelectedTeacherId] = useState<string | null>(
    null,
  );
  const [isSuccess, setIsSuccess] = useState(false);

  const { mutate: addTeacher, mutation } = useCreate();
  const isLoading = mutation.isPending;

  const { options: teacherOptions } = useSelect<User>({
    resource: "users",
    filters: [{ field: "role", operator: "eq", value: UserRole.TEACHER }],
    optionLabel: "name",
    optionValue: "id",
  });

  const handleInvite = () => {
    if (!selectedTeacherId) {
      toast.error(t("classes.dialogs.inviteTeacher.toast.selectTeacher"));
      return;
    }

    addTeacher(
      {
        resource: `classes/${classId}/teachers`,
        values: {
          teacherId: selectedTeacherId,
          isPrimary: false,
        },
      },
      {
        onSuccess: () => {
          setIsSuccess(true);
          toast.success(t("classes.dialogs.inviteTeacher.toast.success"));
          setTimeout(() => {
            setSelectedTeacherId(null);
            setIsSuccess(false);
            onOpenChange(false);
          }, 1000);
        },
        onError: (err) => {
          const error = err as HttpError;
          toast.error((error?.response?.data as any)?.message || t("classes.dialogs.inviteTeacher.toast.error"));
        },
      },
    );
  };

  const availableTeachers = teacherOptions.filter(
    (option) => 
      !existingTeacherIds.includes(String(option.value)) && 
      String(option.value) !== identity?.id
  );

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="text-start">
        <DialogHeader>
          <DialogTitle>{t("classes.dialogs.inviteTeacher.title")}</DialogTitle>
          <DialogDescription>
            {t("classes.dialogs.inviteTeacher.description")}
          </DialogDescription>
        </DialogHeader>
        <div className="py-4">
          <Select
            onValueChange={setSelectedTeacherId}
            value={selectedTeacherId ?? undefined}
          >
            <SelectTrigger>
              <SelectValue placeholder={t("classes.dialogs.inviteTeacher.fieldPlaceholder")} />
            </SelectTrigger>
            <SelectContent>
              {availableTeachers.length > 0 ? (
                availableTeachers.map((option) => (
                  <SelectItem key={option.value} value={String(option.value)} className="text-start">
                    {option.label}
                  </SelectItem>
                ))
              ) : (
                <div className="p-4 text-sm text-muted-foreground text-start">
                  {t("classes.dialogs.inviteTeacher.noTeachers")}
                </div>
              )}
            </SelectContent>
          </Select>
        </div>
        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t("buttons.cancel")}
          </Button>
          <LoadingButton
            onClick={handleInvite}
            isLoading={isLoading}
            isSuccess={isSuccess}
            disabled={availableTeachers.length === 0}
          >
            {t("buttons.inviteTeacher")}
          </LoadingButton>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { useList, useCreate, useDelete, useGetIdentity, useCustomMutation } from "@refinedev/core";
import { useState } from "react";
import { Module, User, UserRole, Resource } from "@/types";
import { 
  Accordion, 
  AccordionContent, 
  AccordionItem, 
  AccordionTrigger 
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import { 
  PlusCircle, 
  BookOpen, 
  Link as LinkIcon, 
  Video, 
  File,
  Loader2,
  Trash2,
  MoreVertical,
  ExternalLink,
  PenLine,
  Image as ImageIcon,
  Library,
  ArrowRight,
  Sparkles,
  Save,
  Play
} from "lucide-react";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogFooter,
  DialogDescription
} from "@/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
