import { ResourcesEmptyState } from "../components/class-empty-states";

import { usePersistentLive } from "@/hooks/use-persistent-live";

interface ResourceTabProps {
  classId: string;
}

export const ResourceTab = ({ classId }: ResourceTabProps) => {
  const { t, i18n } = useTranslation();
  const { data: identity } = useGetIdentity<User>();
  const isTeacher = identity?.role === UserRole.TEACHER || identity?.role === UserRole.ADMIN;

  const [isAddResourceOpen, setIsAddResourceOpen] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<number | null>(null);
  const [newResource, setNewResource] = useState({
    title: "",
    description: "",
    type: "file" as "file" | "link" | "video" | "note" | "image" | "other",
    url: "",
    content: "",
    cldPubId: "",
  });

  const { query } = useList<Module>({
    resource: "modules",
    filters: [{ field: "classId", operator: "eq", value: classId }],
    queryOptions: { enabled: !!classId },
  });

  const modules = query.data?.data || [];
  const isLoading = query.isPending;

  const { mutate: createResource, mutation: createMutation } = useCreate<Resource>();
  const isCreatingResource = createMutation.isPending;

  const { mutate: deleteResource } = useDelete();
  const { mutate: featureResource } = useCustomMutation();

  const { setActiveVideo } = usePersistentLive();

  const handleAddResource = () => {
    if (!newResource.title || !activeModuleId) {
      toast.error(t("classes.resource.toast.fillRequired"));
      return;
    }

    createResource(
      {
        resource: "resources",
        values: { 
          ...newResource, 
          classId: Number(classId), 
          moduleId: activeModuleId 
        },
      },
      {
        onSuccess: () => {
          setIsAddResourceOpen(false);
          setNewResource({ title: "", description: "", type: "file", url: "", content: "", cldPubId: "" });
          setActiveModuleId(null);
          query.refetch();
          toast.success(t("classes.resource.toast.added"));
        },
      }
    );
  };

  const handleDeleteResource = (id: number) => {
    deleteResource(
      { resource: "resources", id },
      {
        onSuccess: () => {
          toast.success(t("classes.resource.toast.deleted"));
          query.refetch();
        },
      }
    );
  };

  const isAr = i18n.language === 'ar';

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4 text-start">
        <Loader2 className="h-10 w-10 animate-spin text-primary/20" />
        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/40">{t("classes.resource.loading")}</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 text-start">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <div className="p-1.5 rounded-lg bg-primary/10 text-primary">
              <Library className="h-4 w-4" />
            </div>
            <h3 className="text-xl font-black tracking-tight">{t("classes.resource.learningMaterials")}</h3>
          </div>
          <p className="text-sm text-muted-foreground font-medium">
            {t("classes.resource.description")}
          </p>
        </div>
      </div>

      {modules.length === 0 ? (
        <ResourcesEmptyState 
          isTeacher={isTeacher}
        />
      ) : (
        <Accordion type="multiple" className="w-full space-y-6">
          <AnimatePresence mode="popLayout">
            {modules.map((module: Module) => (
              <motion.div
                key={module.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.2 }}
              >
                <AccordionItem 
                  value={`module-${module.id}`} 
                  className="border-none shadow-xl bg-card/50 backdrop-blur-xl rounded-[2rem] overflow-hidden group transition-all hover:shadow-2xl hover:bg-card/80 text-start"
                >
                  <div className="flex items-center justify-between w-full px-6">
                    <AccordionTrigger className="hover:no-underline py-6 flex-1 group/trigger">
                      <div className="flex items-center gap-4 text-left">
                        <div className="p-3 rounded-2xl bg-primary/10 text-primary group-hover/trigger:scale-110 transition-transform">
                          <BookOpen className="h-6 w-6" />
                        </div>
                        <div className="space-y-1">
                          <div className="font-black text-lg tracking-tight group-hover/trigger:text-primary transition-colors text-start">{module.name}</div>
                          <div className="flex items-center gap-3">
                            <span className="text-[10px] font-black text-primary uppercase tracking-widest">
                              {t("classes.resource.itemsCount", { count: module.resources?.length || 0 })}
                            </span>
                          </div>
                        </div>
                      </div>
                    </AccordionTrigger>
                    {isTeacher && (
                      <Button 
                        variant="outline" 
                        size="sm" 
                        className={cn("h-10 rounded-xl font-black uppercase tracking-widest text-[9px] gap-2 border-primary/20 text-primary hover:bg-primary/5", isAr ? "mr-4" : "ml-4")}
                        onClick={() => {
                          setActiveModuleId(module.id);
                          setIsAddResourceOpen(true);
                        }}
                      >
                        <PlusCircle className="h-3.5 w-3.5" />
                        {t("buttons.addMaterial")}
                      </Button>
                    )}
                  </div>
                  <AccordionContent className="pb-8 pt-2 px-8">
                    <div className="grid grid-cols-1 gap-3 text-start">
                      {module.resources && module.resources.length > 0 ? (
                        module.resources.map((res) => (
                          <div key={res.id} className="flex items-center justify-between p-4 rounded-2xl border border-black/[0.03] dark:border-white/[0.03] bg-muted/20 hover:bg-primary/5 transition-all cursor-pointer group/item">
                            <div className="flex items-center gap-4 overflow-hidden">
                              <div className={cn(
                                "p-2.5 rounded-xl shrink-0 transition-transform group-hover/item:scale-110",
                                res.type === 'video' ? 'bg-blue-500/10 text-blue-500' : 
                                res.type === 'link' ? 'bg-success/10 text-success' : 
                                res.type === 'note' ? 'bg-purple-500/10 text-purple-500' :
                                res.type === 'image' ? 'bg-pink-500/10 text-pink-500' :
                                'bg-orange-500/10 text-orange-500'
                              )}>
                                {res.type === 'video' ? <Video className="h-4 w-4" /> : 
                                 res.type === 'link' ? <LinkIcon className="h-4 w-4" /> : 
                                 res.type === 'note' ? <PenLine className="h-4 w-4" /> :
                                 res.type === 'image' ? <ImageIcon className="h-4 w-4" /> :
                                 <File className="h-4 w-4" />}
                              </div>
                              <div className="flex flex-col overflow-hidden">
                                <span className="text-sm font-black tracking-tight group-hover/item:text-primary transition-colors truncate">{res.title}</span>
                                {res.description && <span className="text-[10px] text-muted-foreground/60 font-medium uppercase tracking-widest truncate">{res.description}</span>}
                              </div>
                            </div>
                            <div className="flex items-center gap-2">
                              {isTeacher && res.type === 'video' && (
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-9 w-9 rounded-xl text-muted-foreground hover:bg-primary/5 hover:text-primary transition-all">
                                            <MoreVertical className="h-4 w-4" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="rounded-xl border-none shadow-2xl p-2 min-w-[180px] bg-card/95 backdrop-blur-xl">
                                        <DropdownMenuItem 
                                            className="rounded-lg font-black uppercase tracking-widest text-[9px] gap-2 py-3 cursor-pointer text-ai-primary hover:bg-ai-primary/10 transition-all"
                                            onClick={() => {
                                                featureResource({
                                                    url: "/channels/feature-resource",
                                                    method: "post",
                                                    values: { resourceId: res.id },
                                                    successNotification: () => ({
                                                        type: "success",
                                                        message: "Highlighted!",
                                                        description: "This lesson is now featured on your public Teacher TV channel."
                                                    })
                                                });
                                            }}
                                        >
                                            <Sparkles className="h-3.5 w-3.5" />
                                            {t("buttons.featureOnTv")}
                                        </DropdownMenuItem>
                                        <DropdownMenuItem 
                                            className="rounded-lg font-black uppercase tracking-widest text-[9px] gap-2 py-3 cursor-pointer text-destructive hover:bg-destructive/10 transition-all"
