import { useState, useMemo } from "react";
import {
  useNavigation,
  useDelete,
  useGetIdentity,
  useUpdate,
  useList,
} from "@refinedev/core";
import { User, UserRole, UserStatus, VerificationStatus } from "@/types";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";

export const useUserList = () => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === 'ar';
  const { data: identity } = useGetIdentity<User>();
  const isAdmin = identity?.role === UserRole.ADMIN;

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedRole, setSelectedRole] = useState("all");
  const [selectedStatus, setSelectedStatus] = useState("all");
  const [verificationFilter, setVerificationFilter] = useState("all");
  const [deleteTarget, setDeleteTarget] = useState<string | null>(null);
  const [verificationTarget, setVerificationTarget] = useState<User | null>(null);

  const { show, create } = useNavigation();
  const { mutate: deleteMutation } = useDelete();
  const { mutate: updateMutation, mutation } = useUpdate();

  const filters = useMemo(() => {
    const f = [];
    if (searchQuery) f.push({ field: "search", operator: "contains" as const, value: searchQuery });
    if (selectedRole && selectedRole !== "all") f.push({ field: "role", operator: "eq" as const, value: selectedRole });
    if (selectedStatus && selectedStatus !== "all") f.push({ field: "status", operator: "eq" as const, value: selectedStatus });
    if (verificationFilter === "pending") {
      f.push({ field: "role", operator: "eq" as const, value: UserRole.TEACHER });
      f.push({ field: "verificationStatus", operator: "eq" as const, value: VerificationStatus.PENDING });
    }
    return f;
  }, [searchQuery, selectedRole, selectedStatus, verificationFilter]);

  const { query: usersQuery } = useList<User>({
    resource: "users",
    pagination: { pageSize: 50, mode: "server" },
    filters,
    sorters: [{ field: "createdAt", order: "desc" }],
    meta: { populate: ["department"] },
  });

  const users = usersQuery.data?.data ?? [];

  const stats = useMemo(() => ({
    total: users.length,
    pending: users.filter((u: any) => u.role === UserRole.TEACHER && (u.verificationStatus === VerificationStatus.PENDING || u.verificationStatus === VerificationStatus.UNVERIFIED)).length,
    active: users.filter((u: any) => u.status === UserStatus.ACTIVE).length,
  }), [users]);

  const handleVerify = (id: string, isVerified: boolean) => {
    updateMutation({
      resource: "users", id,
      values: { verificationStatus: isVerified ? VerificationStatus.VERIFIED : VerificationStatus.REJECTED },
    }, {
      onSuccess: () => {
        toast.success(isVerified ? t("users.governance.toasts.verified") : t("users.governance.toasts.rejected"));
        setVerificationTarget(null);
      },
    });
  };

  const handleStatusChange = (id: string, newStatus: UserStatus) => {
    updateMutation({
      resource: "users", id,
      values: { status: newStatus },
    }, {
      onSuccess: () => toast.success(t("users.governance.toasts.statusUpdated", { status: t(`status.${newStatus.toLowerCase()}` as any) })),
    });
  };

  const handleConfirmDelete = () => {
    if (deleteTarget) {
      deleteMutation({ resource: "users", id: deleteTarget, mutationMode: "pessimistic" });
      setDeleteTarget(null);
    }
  };

  return {
    data: { users, stats, identity, isAdmin, isAr },
    status: { isLoading: usersQuery.isPending, isUpdating: mutation.isPending },
    filters: { searchQuery, setSearchQuery, selectedRole, setSelectedRole, selectedStatus, setSelectedStatus, verificationFilter, setVerificationFilter },
    state: { deleteTarget, setDeleteTarget, verificationTarget, setVerificationTarget },
    actions: { show, create, handleVerify, handleStatusChange, handleConfirmDelete }
  };
};

import { useShow, useGetIdentity, useList } from "@refinedev/core";
import { useParams } from "react-router-dom";
import { useMemo } from "react";
import { User, UserRole, Class } from "@/types";
import { Trophy, Target } from "lucide-react";
import { useTranslation } from "react-i18next";

export const useUserProfile = () => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === 'ar';
  const { id: paramsId } = useParams();
  const { data: identity } = useGetIdentity<User>();
  const id = paramsId || identity?.id;

  const { query: userQuery } = useShow<User & { userBadges?: any[] }>({
    resource: "users",
    id,
    queryOptions: { enabled: !!id },
    meta: {
        populate: ["department", "userBadges", "userBadges.badge", "teacherChannel"]
    }
  });

  const { query: badgesQuery } = useList<any>({
    resource: "badges",
    pagination: { mode: "off" },
    queryOptions: { enabled: !!userQuery.data?.data }
  });

  const { query: teacherClassesQuery } = useList<Class>({
    resource: "classes",
    filters: [{ field: "teacherUid", operator: "eq", value: id }],
    queryOptions: {
        enabled: !!userQuery.data?.data && userQuery.data.data.role === UserRole.TEACHER
    }
  });

  const user = userQuery.data?.data;

  const displayBadges = useMemo(() => {
    if (!user || !badgesQuery.data?.data) return [];
    const earnedBadgeIds = new Set(user.userBadges?.map((ub: any) => ub.badgeId));
    
    const earned = (user.userBadges || []).map((ub: any) => ({
        id: ub.badge.id.toString(),
        name: ub.badge.name,
        description: ub.badge.description || "",
        icon: Trophy,
        color: "bg-gold-primary text-white",
        unlocked: true,
    }));

    const unearned = (badgesQuery.data?.data || [])
        .filter((b: any) => !earnedBadgeIds.has(b.id))
        .map((b: any) => ({
            id: b.id.toString(),
            name: b.name,
            description: b.description || "", 
            icon: Target,
            color: "bg-muted text-muted-foreground",
            unlocked: false,
        }));

    return [...earned, ...unearned];
  }, [user, badgesQuery.data?.data]);

  return {
    user,
    teacherClasses: teacherClassesQuery.data?.data || [],
    displayBadges,
    identity,
    isAr,
    isLoading: userQuery.isLoading || badgesQuery.isLoading || teacherClassesQuery.isLoading,
    isError: userQuery.isError,
    isSelf: identity?.id === user?.id,
    isAdmin: identity?.role === UserRole.ADMIN,
    isStudent: user?.role === UserRole.STUDENT,
    isTeacher: user?.role === UserRole.TEACHER
  };
};

