}

interface ChatHistoryResponse {
  data: ChatHistoryItem[];
}

interface StreamData {
  text?: string;
  sources?: ChatSource[];
  done?: boolean;
  metadata?: {
    isDryRun?: boolean;
  };
}

const MAX_INPUT_LENGTH = 4000;

/**
 * useAIChat Hook (Final Production Grade)
 * 
 * Optimized for Tablawy OS AI Streaming.
 * Handles SSE Buffering, History Syncing, and Multi-Class Navigation.
 */
export const useAIChat = ({ url, context, classId }: UseAIChatProps) => {
  const { t } = useTranslation();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  
  // 🛡️ AUTO-DRAFT: AI Assistant Persistence
  useEffect(() => {
      const draftKey = `draft:ai-assistant:${classId || 'global'}`;
      if (input) {
          localStorage.setItem(draftKey, input);
      } else {
          localStorage.removeItem(draftKey);
      }
  }, [input, classId]);

  // 🚀 DRAFT RECOVERY
  useEffect(() => {
      const draftKey = `draft:ai-assistant:${classId || 'global'}`;
      const saved = localStorage.getItem(draftKey);
      if (saved) {
          setInput(prev => prev || saved);
      }
  }, [classId]);

  const [isLoading, setIsLoading] = useState(false);
  const [streamingMessage, setStreamingMessage] = useState("");
  const [streamingSources, setStreamingSources] = useState<ChatSource[] | null>(null);
  const [isDryRun, setIsDryRun] = useState(false);

  const scrollAreaRef = useRef<HTMLDivElement>(null);
  const accumulatorRef = useRef("");
  const lineBufferRef = useRef(""); 
  const animationFrameRef = useRef<number | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const hasLoadedHistoryFor = useRef<string | number | null>(null); 
  
  const { open } = useNotification();
  const { data: permissions, isLoading: isPermissionsLoading, isError: isPermissionsError } = usePermissions<BasePermissions>({});

  // 1. 📜 HISTORY: Standard Refine v5 GET
  // Task: Context Safety - Fallback to "global" history if no classId provided
  const effectiveClassId = classId || 'global';
  const { result: historyResult, query: historyQuery } = useCustom<ChatHistoryResponse>({
    url: `${BACKEND_URL}/ai/chat-history/${effectiveClassId}`,
    method: "get",
    queryOptions: {
      enabled: hasLoadedHistoryFor.current !== effectiveClassId,
    },
  });

  // 1b. 🦾 NON-STREAMING FALLBACK (Refine v5 Pattern Adherence)
  const { mutate: sendSimpleChat } = useCustomMutation();

  // Handle Navigation & State Resets
  useEffect(() => {
    if (effectiveClassId !== hasLoadedHistoryFor.current) {
        setMessages([]);
        accumulatorRef.current = "";
        lineBufferRef.current = "";
    }
  }, [effectiveClassId]);

  // Sync history safely
  useEffect(() => {
    const historyData = historyResult?.data?.data;
    if (historyData && hasLoadedHistoryFor.current !== effectiveClassId) {
      const history = historyData.map((m: ChatHistoryItem) => ({
        id: String(m.id),
        role: m.role,
        parts: [{ text: m.content }],
      }));
      setMessages(history);
      hasLoadedHistoryFor.current = effectiveClassId;
    }
  }, [historyResult, effectiveClassId]);

  // 2. 🧹 CLEANUP
  useEffect(() => {
    return () => {
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
      if (abortControllerRef.current) abortControllerRef.current.abort();
    };
  }, []);

  const scrollToBottom = useCallback(() => {
    if (scrollAreaRef.current) {
      const scrollContainer = scrollAreaRef.current.querySelector('[data-radix-scroll-area-viewport]');
      if (scrollContainer) {
        scrollContainer.scrollTop = scrollContainer.scrollHeight;
      }
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages, streamingMessage, scrollToBottom]);

  const updateStreamingUI = useCallback(() => {
    if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    
    animationFrameRef.current = requestAnimationFrame(() => {
      setStreamingMessage(accumulatorRef.current);
      animationFrameRef.current = null;
    });
  }, []);

  // 3. 🚀 SEND: SSE Streaming Engine
  const handleSend = async () => {
    const cleanInput = input.trim();
    if (!cleanInput || isLoading || isPermissionsLoading) return;

    // RBAC & Safety Checks
    if (isPermissionsError) {
        open?.({ type: "error", message: (t as any)("common.error"), description: (t as any)("auth.errors.permissions") as string });
        return;
    }

    if (cleanInput.length > MAX_INPUT_LENGTH) {
        open?.({ type: "error", message: (t as any)("common.error"), description: (t as any)("aiHub.errors.inputTooLong") as string });
        return;
    }

    const role = permissions?.role;
    if (effectiveClassId && role === UserRole.PARENT) {
        open?.({ type: "error", message: (t as any)("common.accessDenied") as string, description: (t as any)("aiHub.errors.parentRestricted") as string });
        return;
    }

    // Initialize Request Lifecycle
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;

    const userMessage: Message = { role: "user", parts: [{ text: cleanInput }] };
    setMessages((prev) => [...prev, userMessage]);
    
    setInput("");
    setIsLoading(true);
    setStreamingMessage("");
    setStreamingSources(null);
    accumulatorRef.current = "";
    lineBufferRef.current = ""; 

    const finalUrl = effectiveClassId ? "/ai/study-buddy" : url;
    const apiUrl = `${BACKEND_URL}${finalUrl}`;

    try {
      const token = localStorage.getItem("token");
      const correlationId = crypto.randomUUID();

      // General Chat (Non-Streaming) - Use Refine's useCustomMutation
      if (!effectiveClassId || effectiveClassId === 'global') {
        sendSimpleChat({
            url: apiUrl,
            method: "post",
            values: {
                message: cleanInput,
                history: messages.map(m => ({ role: m.role, parts: m.parts })),
                context,
                correlationId
            }
        }, {
            onSuccess: (result) => {
                const responseData = result.data as { data?: { response?: string }, metadata?: { isDryRun?: boolean } };
                if (responseData.data?.response) {
                    setMessages((prev) => [...prev, { role: "model", parts: [{ text: responseData.data?.response || "" }] }]);
                }
                if (responseData.metadata?.isDryRun) setIsDryRun(true);
                setIsLoading(false);
            },
            onError: (err) => {
                console.error("Simple Chat Error:", err);
                setIsLoading(false);
                open?.({ type: "error", message: (t as any)("common.error"), description: (t as any)("aiHub.errors.serviceUnavailable") as string });
            }
        });
        return;
      }

      const headers: Record<string, string> = { 
          "Content-Type": "application/json",
          "X-Correlation-ID": correlationId
      };
      if (token) headers["Authorization"] = `Bearer ${token}`;

      const response = await fetch(apiUrl, {
        method: "POST",
        signal: controller.signal,
        credentials: "include",
        headers,
        body: JSON.stringify({
          message: cleanInput,
          history: messages.map(m => ({ role: m.role, parts: m.parts })),
          context,
          classId: effectiveClassId,
          correlationId, // Also pass in body for non-header compliant middle-layers
        }),
      });

      if (response.status === 429) throw new Error("RATE_LIMIT_EXCEEDED");
      if (response.status === 503) throw new Error("AI_SERVICE_OFFLINE");
      if (!response.ok) throw new Error("AI_SERVICE_UNAVAILABLE");

      // Study Buddy (Streaming)
      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      if (!reader) throw new Error("STREAM_READER_UNAVAILABLE");

      let buffer = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        buffer += chunk;
        
        // 🛡️ JSON LINE BUFFERING: Split by double newlines (SSE standard)
        const lines = buffer.split("\n\n");

        // Keep the last partial line in the buffer
        buffer = lines.pop() || "";

        for (const line of lines) {
          if (line.startsWith("data: ")) {
            try {
              const rawData = line.replace("data: ", "").trim();
              if (!rawData) continue;
              
              const data = JSON.parse(rawData) as StreamData;
              if (data.text) {
                accumulatorRef.current += data.text;
                updateStreamingUI();
              }
              if (data.sources) setStreamingSources(data.sources);
              if (data.done) break;
            } catch (e) {
              console.error("Partial SSE JSON buffered or malformed:", e);
            }
          }
        }
      }

      // Final State Push (Guard against empty bubbles)
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
      const finalResponseText = accumulatorRef.current.trim();
      
      if (finalResponseText.length > 0) {
        setMessages((prev) => [
          ...prev,
          {
            role: "model",
            parts: [{ text: finalResponseText }],
            sources: streamingSources || undefined
          }
        ]);
      } else {
        throw new Error("EMPTY_RESPONSE");
      }

      setStreamingMessage("");
      setStreamingSources(null);

    } catch (err: unknown) {
      const error = err as Error;
      if (error.name === 'AbortError') return;
      
      console.error("Tablawy AI Error:", error);
      
      let description: string = (t as any)("aiHub.errors.serviceUnavailable") as string;
      if (error.message === "RATE_LIMIT_EXCEEDED") description = (t as any)("aiHub.errors.rateLimit") as string;
      if (error.message === "AI_SERVICE_OFFLINE") description = (t as any)("aiHub.errors.maintenance") as string;

      open?.({ 
        type: "error", 
        message: (t as any)("common.error"), 
        description 
      });
      
      setMessages((prev) => [...prev, { 
        role: "model", 
        parts: [{ text: (t as any)("aiHub.errors.friendlyFallback") as string }] 
      }]);
    } finally {
      if (abortControllerRef.current === controller) {
        setIsLoading(false);
        abortControllerRef.current = null;
      }
    }
  };

  return {
    messages,
    streamingMessage,
    streamingSources,
    input,
    setInput,
    handleSend,
    isLoading: isLoading || historyQuery?.isLoading || isPermissionsLoading,
    scrollAreaRef,
    isDryRun,
  };
};

import { useState, useRef, useEffect, useCallback } from "react";
import { useNotification, usePermissions } from "@refinedev/core";
import { useTranslation } from "react-i18next";
import { BACKEND_URL } from "@/config";
import { BasePermissions, UserRole } from "@/types";
import { usePersistentLive } from "./use-persistent-live";
import { AI_API } from "@/constants/api";
import { AIVisualState } from "@/features/ai/types/ai";

interface UseAILiveInteractionProps {
  classId: string;
  language?: string;
  initialVisualCue?: AIVisualState;
  onFinished?: () => void;
  onPermissionDenied?: () => void;
}

interface AuthPermissions extends BasePermissions {}

interface LiveStreamData {
  text?: string;
  latencyMs?: number;
  usage?: unknown;
  done?: boolean;
}

/**
 * 🦾 useAILiveInteraction Hook
 * 
 * Specialized for the AI Co-Teacher (AILiveCompanion).
 * Features:
 * - Hardened SSE Streaming (Line-buffered)
 * - AbortController for network lifecycle safety
 * - Decoupled SpeechSynthesis management (via refs)
 * - Refine v5 Permissions integration
 * - Zustand Session Hydration
 */
export const useAILiveInteraction = ({ 
    classId, 
    language = "English", 
    initialVisualCue = "talking",
    onFinished,
    onPermissionDenied
}: UseAILiveInteractionProps) => {
  const { t } = useTranslation();
  const { open } = useNotification();
  const { data: permissions } = usePermissions<BasePermissions>({});
  
  // Zustand Global State
  const { isJoined: globalJoined, setIsJoined, activeClassId, setActiveClassId, stopSpeaking, setIsSpeaking: setGlobalSpeaking } = usePersistentLive();

  // 🛡️ MULTI-INSTANCE SAFETY: Scoped isJoined check
  const isJoined = globalJoined && activeClassId === classId;

  // Local UI State
  const [visualState, setVisualState] = useState<AIVisualState>(initialVisualCue);
  const [isLoading, setIsLoading] = useState(false);
  const [currentScript, setCurrentScript] = useState<string | null>(null);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);

  // Sync local speaking state to global store
  useEffect(() => {
      setGlobalSpeaking(isSpeaking);
  }, [isSpeaking, setGlobalSpeaking]);

  // Refs for non-reactive state & lifecycle
  const isMounted = useRef(true);
  const abortControllerRef = useRef<AbortController | null>(null);
  const speechRef = useRef<SpeechSynthesisUtterance | null>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const accumulatorRef = useRef("");
  const lineBufferRef = useRef("");
  const animationFrameRef = useRef<number | null>(null);

  // --- 🦾 BATCHED UPDATES (Pattern Adherence: Typing Efficiency) ---
  const updateUI = useCallback((script: string, state?: AIVisualState) => {
    if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    animationFrameRef.current = requestAnimationFrame(() => {
        setCurrentScript(script);
        if (state) setVisualState(state);
        animationFrameRef.current = null;
    });
  }, []);

  // 1. 🎙️ SPEECH SYNTHESIS ENGINE (Hardened)
  const speakText = useCallback((text: string) => {
      if (!isMounted.current || !window.speechSynthesis) return;

      try {
          // 🛡️ ARCHITECTURAL: Coordinate via central manager
          stopSpeaking();

          const utterance = new SpeechSynthesisUtterance(text);
          const langCode = language === "Arabic" ? "ar-SA" : "en-US";
          utterance.lang = langCode;

          // 🌐 VOICE LOCALIZATION: Attempt to find a matching voice for the language
          if (window.speechSynthesis.getVoices) {
              const voices = window.speechSynthesis.getVoices();
              const preferredVoice = voices.find(v => v.lang.startsWith(langCode.split('-')[0]));
              if (preferredVoice) utterance.voice = preferredVoice;
          }

          utterance.onstart = () => {
              setIsSpeaking(true);
              setVisualState("talking");
          };

          utterance.onend = () => {
              setIsSpeaking(false);
              setVisualState("listening");
              speechRef.current = null;
              onFinished?.();
          };

          utterance.onerror = (event) => {
              console.error("Speech Synthesis Error:", event);
              setIsSpeaking(false);
              setVisualState("talking"); // Revert to talking (default) on error
              speechRef.current = null;
          };

          speechRef.current = utterance;
          window.speechSynthesis.speak(utterance);
      } catch (error) {
          console.error("Failed to initialize speech synthesis:", error);
          setIsSpeaking(false);
          setVisualState("talking");
      }
  }, [language, onFinished, stopSpeaking]);

  // 👂 STOP LISTENING ENGINE
  const stopListening = useCallback(() => {
      if (recognitionRef.current) {
          recognitionRef.current.abort();
          recognitionRef.current = null;
      }
      setIsListening(false);
      setVisualState("talking");
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
  }, []);

  // 2. 🚀 SEND: SSE STREAMING ENGINE
  const interact = useCallback(async (question: string) => {
    if (!question.trim() || isLoading) return;

    // RBAC: Single Source of Truth
    if (permissions?.role === UserRole.PARENT) {
        open?.({ type: "error", message: t("common.accessDenied") as string, description: t("aiHub.errors.parentRestricted") as string });
        return;
    }

    // Lifecycle: Abort previous request to prevent "Ghost Updates"
    if (abortControllerRef.current) abortControllerRef.current.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;

    setIsLoading(true);
    setVisualState("thinking");
    accumulatorRef.current = "";
    lineBufferRef.current = "";

    const apiUrl = `${BACKEND_URL}${AI_API.INTERACT(classId)}`;

    try {
      const token = localStorage.getItem("token");
      const correlationId = crypto.randomUUID();
      const headers: Record<string, string> = { 
          "Content-Type": "application/json",
          "X-Correlation-ID": correlationId
      };
      if (token) headers["Authorization"] = `Bearer ${token}`;

      const response = await fetch(apiUrl, {
        method: "PATCH",
        signal: controller.signal,
        credentials: "include",
        headers,
        body: JSON.stringify({ question, language, correlationId }),
      });

      if (response.status === 429) throw new Error("RATE_LIMIT_EXCEEDED");
      if (response.status === 503) throw new Error("AI_SERVICE_OFFLINE");
      if (!response.ok) throw new Error("AI_SERVICE_UNAVAILABLE");

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      if (!reader) throw new Error("STREAM_READER_UNAVAILABLE");

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const combinedChunk = lineBufferRef.current + chunk;
        const lines = combinedChunk.split("\n\n");

        lineBufferRef.current = lines.pop() || "";

        for (const line of lines) {
          if (line.startsWith("data: ")) {
            try {
              const rawData = line.replace("data: ", "").trim();
              if (!rawData) continue;
              
              const data = JSON.parse(rawData) as LiveStreamData;
              if (data.text) {
                accumulatorRef.current += data.text;
                // Update local UI script immediately for visual feedback
                updateUI(accumulatorRef.current);
              }
              
              // 📊 LOGGING: Performance Metadata
              if (data.latencyMs) {
                  console.debug(`[AI Co-Teacher] Latency: ${data.latencyMs}ms | Tokens:`, data.usage);
              }

              if (data.done) break;
            } catch {
              // Wait for buffer
            }
          }
        }
      }

      // Finalize Interaction: Trigger Voice
      if (isMounted.current && accumulatorRef.current) {
          speakText(accumulatorRef.current);
      }

    } catch (err: unknown) {
      const error = err as Error;
      if (error.name === 'AbortError') return;
      
      console.error("Co-Teacher Error:", error);
      let description: string = t("aiHub.errors.serviceUnavailable") as string;
      if (error.message === "RATE_LIMIT_EXCEEDED") description = t("aiHub.errors.rateLimit") as string;
      
      open?.({ type: "error", message: t("common.error"), description });
      setVisualState("talking");
    } finally {
      if (abortControllerRef.current === controller) {
        setIsLoading(false);
      }
    }
  }, [classId, isLoading, language, open, permissions?.role, speakText, t, updateUI]);

  // 2. 👂 SPEECH RECOGNITION ENGINE
  const startListening = useCallback(() => {
      const SpeechRecognitionClass = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SpeechRecognitionClass) {
          open?.({
              type: "error",
              message: t("aiHub.errors.speechNotSupported") as string,
              description: t("aiHub.errors.chromeRequired") as string,
          });
          return;
      }

      if (window.speechSynthesis) window.speechSynthesis.cancel();
      if (recognitionRef.current) recognitionRef.current.abort();

      setIsListening(true);
      setVisualState("listening");

      const recognition = new (SpeechRecognitionClass as { new(): SpeechRecognition })();
      recognition.lang = language === "Arabic" ? "ar-SA" : "en-US";
      recognition.continuous = false;
      recognition.interimResults = false;

      // ⏱️ TIMEOUT LOGIC: Auto-stop if no voice detected
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
          recognition.stop();
          setIsListening(false);
          setVisualState("talking");
          open?.({
              type: "error",
              message: t("aiHub.errors.listeningTimeout") as string,
              description: t("aiHub.errors.tryAgain") as string,
          });
      }, 8000);

      recognition.onresult = (event: SpeechRecognitionEvent) => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          const transcript = event.results[0][0].transcript;
          void interact(transcript);
      };

      recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          setIsListening(false);
          setVisualState("talking");
          if (event.error === 'not-allowed') {
              onPermissionDenied?.();
              open?.({
                  type: "error",
                  message: t("auth.errors.micAccessDenied") as string,
                  description: t("auth.errors.micSettings") as string,
              });
          }
      };

      recognition.onend = () => {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
          setIsListening(false);
      };

      recognitionRef.current = recognition;
      recognition.start();
  }, [interact, language, open, t, onPermissionDenied]);

  // 🚀 SESSION TOGGLE (Pattern Adherence: Lifecycle Safety)
  const toggleJoin = useCallback((val: boolean) => {
    if (val) setActiveClassId(classId);
    setIsJoined(val);
    if (!val) {
        // Reset local state on leave
        setCurrentScript(null);
        setVisualState("talking");
        if (window.speechSynthesis) window.speechSynthesis.cancel();
        if (recognitionRef.current) recognitionRef.current.abort();
    }
  }, [setIsJoined, setActiveClassId, classId]);

  // 3. 🧹 CLEANUP
  useEffect(() => {
    return () => {
      isMounted.current = false;
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
      if (abortControllerRef.current) abortControllerRef.current.abort();
      stopSpeaking();
      if (recognitionRef.current) recognitionRef.current.abort();
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [stopSpeaking, stopListening]);

  return {
    isJoined,
    setIsJoined: toggleJoin,
    visualState,
    setVisualState,
    isLoading,
    currentScript,
    setCurrentScript,
    isSpeaking,
    isListening,
    interact,
    speakText,
    startListening,
    stopListening,
  };
};

import { useEffect, useState } from "react";
import { toast } from "sonner"; 
import { useSocket } from "@/contexts/socket-context";
import { useNavigate } from "react-router-dom";

export interface Notification {
  id: number;
  title: string;
  message: string;
  type: string;
  link?: string;
  isRead: boolean;
  createdAt: string;
}

/**
 * Enterprise hook for real-time notifications and badge syncing.
 * Listens to events emitted by the unified NotificationService.
 */
export const useLiveNotifications = (userId: string | undefined) => {
  const { socket, isConnected } = useSocket();
  const navigate = useNavigate();
  const [unreadCount, setUnreadCount] = useState<number>(0);
  const [latestNotification, setLatestNotification] = useState<Notification | null>(null);

  useEffect(() => {
    if (!userId || !socket || !isConnected) return;

    // 1. Listen for Real-time Toast Alerts
    const handleNotification = (notification: Notification) => {
      setLatestNotification(notification);
      
      // Trigger Global Toast
      toast(notification.title, {
        description: notification.message,
        action: notification.link ? {
          label: "View",
          onClick: () => navigate(notification.link!)
        } : undefined,
      });
    };

    // 2. Listen for Atomic Unread Count Updates
    // This event is fired by our backend transaction every time count changes
    const handleUnreadCount = (data: { count: number }) => {
      setUnreadCount(data.count);
    };

    socket.on("notification", handleNotification);
    socket.on("unread_count", handleUnreadCount);

    return () => {
      socket.off("notification", handleNotification);
      socket.off("unread_count", handleUnreadCount);
    };
  }, [userId, socket, isConnected]);

  return {
    unreadCount,
    latestNotification,
    setUnreadCount,
  };
};

import { useState, useMemo, useEffect } from "react";
import { useCreate, useNotification } from "@refinedev/core";
import { parseQuizDescription, ParsedQuestion } from "@/lib/quiz-parser";
import { useSocket } from "@/contexts/socket-context";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";

interface UseQuizProps {
  assignmentId: number;
  classId?: number;
  description: string;
  onComplete?: (score: number) => void;
}

export const useQuiz = ({ assignmentId, classId, description, onComplete }: UseQuizProps) => {
  const { t } = useTranslation();
  const { mutate: submitScore } = useCreate();
  const { open } = useNotification();
  const { socket } = useSocket();

  const [activeStudents, setActiveStudents] = useState<number>(0);

  const questions = useMemo<ParsedQuestion[]>(() => {
    return parseQuizDescription(description);
  }, [description]);

  const [currentStep, setCurrentStep] = useState(0);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [isFinished, setIsFinished] = useState(false);

  const currentQuestion = questions[currentStep];
  const progress = questions.length > 0 ? (currentStep / questions.length) * 100 : 0;

  // --- LIVE ACTIVITY LOGIC ---
  useEffect(() => {
    if (!socket || !assignmentId) return;

    // Join quiz room
    socket.emit("quiz:start", { quizId: assignmentId, classId });

    const handleRoomCount = (data: { count: number }) => {
      setActiveStudents(data.count);
    };

    const handleActiveStudent = (data: { studentName: string; quizId: number }) => {
      if (data.quizId === assignmentId) {
        toast((t as any)("classes.quiz.startedToast", { name: data.studentName }), {
          icon: "✍️",
          duration: 3000,
        });
      }
    };

    const handleNudge = (data: { teacherName: string; message: string; quizId: number }) => {
        if (data.quizId === assignmentId) {
            toast(data.message, {
                description: (t as any)("classes.quiz.nudgeFrom", { name: data.teacherName }),
                icon: "👋",
                duration: 5000,
            });
        }
    };

    socket.on("quiz:room_count", handleRoomCount);
    socket.on("quiz:active_student", handleActiveStudent);
    socket.on("quiz:nudge_received", handleNudge);

    return () => {
      socket.emit("quiz:leave", assignmentId);
      socket.off("quiz:room_count", handleRoomCount);
      socket.off("quiz:active_student", handleActiveStudent);
      socket.off("quiz:nudge_received", handleNudge);
    };
  }, [socket, assignmentId, classId, t]);

  const handleOptionSelect = (option: string) => {
    if (isAnswered) return;
    setSelectedOption(option);
  };

  const handleCheckAnswer = () => {
    if (!selectedOption || !currentQuestion) return;
    setIsAnswered(true);
    if (selectedOption === currentQuestion.correctAnswer) {
      setScore(prev => prev + 1);
    }
  };

  const handleNext = () => {
    if (currentStep < questions.length - 1) {
      setCurrentStep(prev => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setIsFinished(true);
      const finalScore = Math.round((score / questions.length) * 100);
      
      submitScore({
        resource: "submissions",
        values: {
          assignmentId,
          content: `Completed AI Quiz. Final Score: ${finalScore}%`,
          grade: finalScore,
          feedback: `Automated grade from interactive quiz. Correct answers: ${score}/${questions.length}`,
        }
      }, {
        onSuccess: () => {
          open?.({
            type: "success",
            message: t("classes.quiz.submittedTitle", "Quiz Submitted!"),
            description: (t as any)("classes.quiz.submittedDesc", { score: finalScore }),
          });
          onComplete?.(finalScore);
        }
      });
    }
  };

  return {
    questions,
    currentStep,
    currentQuestion,
    selectedOption,
    isAnswered,
    score,
    isFinished,
    progress,
    activeStudents, // Export live count
    handleOptionSelect,
    handleCheckAnswer,
    handleNext,
  };
};

import { io, Socket } from "socket.io-client";
import { SOCKET_URL } from "@/config";
import { authClient } from "./auth-client";

/**
 * Singleton Socket instance to prevent multiple connections
 * and churn during navigation.
 */
export const socket: Socket = io(SOCKET_URL, {
  withCredentials: true,
  autoConnect: false,
  reconnection: true,
  reconnectionAttempts: 10,
  reconnectionDelay: 2000,
  transports: ["polling"], // Force polling to rule out websocket issues
  upgrade: false,           // Disable upgrade to websocket
});

let connectionPromise: Promise<void> | null = null;

/**
 * Connects the socket using the verified Better Auth session token.
 * This ensures the backend can cryptographically verify the user's identity.
 */
export const connectSocket = async () => {
  if (connectionPromise) return connectionPromise;

  connectionPromise = (async () => {
    try {
      const { data: sessionData } = await authClient.getSession();
      const token = sessionData?.session?.token;

      if (!token) {
        console.warn("Cannot connect socket: No active session token found.");
        return;
      }

      if (socket.connected) {
        // If already connected, check if token changed. If not, skip.
        if (socket.auth && (socket.auth as any).token === token) return;
        socket.disconnect();
      }

      // Attach token to the auth payload for the secure handshake
      socket.auth = { token };
      console.log("🔗 Attempting socket connection to:", SOCKET_URL, "with token:", token.substring(0, 10) + "...");
      socket.connect();
      
      // Wait for connection to be established or timeout
      await new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(() => {
          console.error("⏳ Socket connection timeout after 15s. Socket status:", socket.connected ? "connected" : "disconnected");
          reject(new Error("Socket connection timeout (15s)"));
        }, 15000);

        socket.once("connect", () => {
          clearTimeout(timeout);
          console.log("🚀 Socket connected successfully:", socket.id);
          resolve();
        });

        socket.once("connect_error", (err) => {
          clearTimeout(timeout);
          console.error("❌ Socket handshake failed:", err.message, err);
          reject(err);
        });
      });
    } catch (err) {
      console.error("Failed to establish secure socket connection:", err);
    } finally {
      connectionPromise = null;
    }
  })();

  return connectionPromise;
};

/**
 * Safely retrieves the socket instance.
 * Note: Does NOT auto-connect to prevent unauthenticated connections.
 */
export const getSocket = () => {
  if (!socket.connected) {
    console.warn("getSocket called before socket was authenticated or connected.");
  }
  return socket;
};

