                              <DropdownMenuTrigger asChild>
                                  <Button variant="ghost" size="icon" className="h-10 w-10 rounded-xl md:hidden lg:flex" onClick={(e) => e.stopPropagation()}>
                                      <MoreHorizontal className="h-5 w-5" />
                                  </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-56 rounded-[1.5rem] p-2 bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                                  <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground px-3 py-2">{t("classes.attendance.governance.sessionOptions")}</DropdownMenuLabel>
                                  <DropdownMenuItem onClick={() => handleRowClick(session)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                      <Eye className="h-4 w-4 text-primary" />
                                      <span className="font-bold">{t("classes.attendance.governance.viewFullReport")}</span>
                                  </DropdownMenuItem>
                                  {isStaff && (
                                      <>
                                          <DropdownMenuSeparator className="my-2" />
                                          <DropdownMenuItem 
                                              onClick={() => setQrTargetClassId(session.classId.toString())} 
                                              className="rounded-xl gap-3 py-3 cursor-pointer"
                                          >
                                              <QrCode className="h-4 w-4 text-primary" />
                                              <span className="font-bold">{t("classes.attendance.governance.startQrCheckin")}</span>
                                          </DropdownMenuItem>
                                      </>
                                  )}
                              </DropdownMenuContent>
                          </DropdownMenu>
                        </div>
                      </motion.div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </ListView>

      {qrTargetClassId && (
