        toast.info(t("classes.show.toast.inviteLinkDetected"), {
            description: t("classes.show.toast.loginToJoin")
        });
    }
  }, [inviteCode, t]);

  const onSubmit = (values: z.infer<typeof loginSchema>) => {
    login({ ...values, inviteCode }, {
      onSuccess: () => {},
      onError: (err) => {
        const error = err as HttpError;
        const errorMessage =
          (error as any)?.data?.message || error.message || t("auth.login.unknownError");
        toast.error(errorMessage);
      },
    });
  };

  return (
    <div className="min-h-dvh bg-background flex flex-col items-center justify-center p-4 md:p-8 relative overflow-hidden">
      {/* Immersive Background - Mobile Optimized */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-[-1]">
        <div className="absolute top-[-10%] start-[-10%] w-[60%] h-[40%] bg-primary/10 blur-[80px] md:blur-[120px] rounded-full opacity-50" />
        <div className="absolute bottom-[-10%] end-[-10%] w-[60%] h-[40%] bg-purple-500/10 blur-[80px] md:blur-[120px] rounded-full opacity-50" />
      </div>

      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: [0.23, 1, 0.32, 1] }}
        className="w-full max-w-md z-10"
      >
        <Link to="/" className="flex items-center justify-center gap-3 mb-10 md:mb-14 group">
          <div className="bg-primary p-2.5 rounded-2xl group-hover:rotate-6 group-hover:scale-110 transition-all duration-500 shadow-lg shadow-primary/20">
            <BookOpen className="h-7 w-7 text-primary-foreground" />
          </div>
          <span className="text-3xl font-black tracking-tighter uppercase leading-none">
            Class<span className="text-primary italic">Room</span>
          </span>
        </Link>

        <Card className="border-border/40 shadow-[0_32px_64px_-12px_rgba(0,0,0,0.15)] dark:shadow-[0_32px_64px_-12px_rgba(0,0,0,0.4)] rounded-[2.5rem] md:rounded-[3rem] bg-card/50 backdrop-blur-3xl overflow-hidden">
          <CardHeader className="text-center pt-10 md:pt-14 pb-6 md:pb-10 space-y-4 md:space-y-6">
            <div className="inline-flex items-center gap-2 px-5 py-2 rounded-full bg-primary/5 text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 mx-auto border border-primary/10">
                <ShieldCheck className="h-3.5 w-3.5" />
                {t("auth.login.secureAccess")}
            </div>
            <div className="space-y-2">
                <CardTitle className="text-3xl md:text-4xl font-black tracking-tighter uppercase leading-tight">{t("auth.login.title")}</CardTitle>
                <CardDescription className="font-medium text-base md:text-lg px-4 md:px-8">
                {t("auth.login.description")}
                </CardDescription>
            </div>
          </CardHeader>
          <CardContent className="px-6 md:px-12">
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 md:space-y-8">
                <FormField
                  control={form.control}
                  name="email"
                  render={({ field }) => (
                    <FormItem className="space-y-3">
                      <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.login.emailLabel")}</FormLabel>
                      <FormControl>
                        <Input
                          type="email"
                          placeholder={t("auth.login.emailPlaceholder")}
                          className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20"
                          {...field}
                        />
                      </FormControl>
                      <FormMessage className="ms-2 font-bold" />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="password"
                  render={({ field }) => (
                    <FormItem className="space-y-3">
                      <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.login.passwordLabel")}</FormLabel>
                      <FormControl>
                        <Input
                          type="password"
                          placeholder={t("auth.login.passwordPlaceholder")}
                          className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20"
                          {...field}
                        />
                      </FormControl>
                      <FormMessage className="ms-2 font-bold" />
                    </FormItem>
                  )}
                />
                <Button 
                    type="submit" 
                    size="lg"
                    className="w-full h-16 md:h-20 rounded-[1.5rem] md:rounded-4xl font-black uppercase tracking-widest text-xs md:text-sm shadow-2xl shadow-primary/30 group transition-all duration-300" 
                    disabled={isPending}
                >
                  {isPending ? (
                      <div className="flex items-center gap-3">
                          <Loader2 className="h-5 w-5 animate-spin" />
                          {t("buttons.authenticating")}
                      </div>
                  ) : (
                      <div className="flex items-center gap-3">
                          {t("buttons.signIn")}
                          <Zap className={cn("h-5 w-5 fill-current group-hover:scale-125 transition-transform", isAr && "rotate-180")} />
                      </div>
                  )}
                </Button>
              </form>
            </Form>
          </CardContent>
          <CardFooter className="flex justify-center py-10 md:py-14 bg-primary/2 border-t border-border/40 mt-8">
            <p className="text-sm md:text-base font-medium text-muted-foreground/80">
              {t("auth.login.newToClassroom")}&nbsp;
              <Link
                to={`/register${inviteCode ? `?inviteCode=${inviteCode}` : ''}`}
                className="font-black text-primary hover:underline uppercase tracking-[0.1em] text-xs md:text-sm"
              >
                {t("buttons.createAccount")} <ArrowRight className={cn("inline h-4 w-4 ms-1 mb-0.5", isAr && "me-1 ms-0 rotate-180")} />
              </Link>
            </p>
          </CardFooter>
        </Card>
      </motion.div>
    </div>
  );
};

export default LoginPage;

import { useRegister, HttpError } from "@refinedev/core";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import * as z from "zod";
import { useState, useEffect } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { toast } from "sonner";
import { 
  ArrowRight, 
  ArrowLeft, 
  Sparkles,
  Loader2,
  BookOpen,
  Zap,
} from "lucide-react";
import { cn } from "@/lib/utils";
import axios from "axios";
import { RoleSelector } from "@/components/auth/role-selector";
import { VerificationUpload } from "@/components/auth/verification-upload";
import { motion, AnimatePresence } from "framer-motion";
import { useTranslation } from "react-i18next";

const RegisterPage = () => {
  const { t, i18n } = useTranslation();
  const { mutate: register, isPending } = useRegister();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const inviteCode = searchParams.get("inviteCode");
  
  const [step, setStep] = useState(1);
  const [isGeneratingBio, setIsGeneratingBio] = useState(false);

  const registerSchema = z.object({
    name: z.string().min(1, t("auth.register.nameRequired")),
    email: z.string().email(t("auth.register.invalidEmail")),
    password: z.string().min(8, t("auth.register.passwordMinLength")),
    role: z.enum(["student", "teacher", "parent"]),
    phoneNumber: z.string().optional(),
    bio: z.string().optional(),
    dateOfBirth: z.string().optional(),
    parentName: z.string().optional(),
    parentPhone: z.string().optional(),
    verificationDocumentUrl: z.string().optional(),
    verificationDocumentCldPubId: z.string().optional(),
  });

  const form = useForm<z.infer<typeof registerSchema>>({
    resolver: zodResolver(registerSchema),
    defaultValues: {
      name: "",
      email: "",
      password: "",
      role: "student",
      phoneNumber: "",
      bio: "",
      dateOfBirth: "",
      parentName: "",
      parentPhone: "",
      verificationDocumentUrl: "",
      verificationDocumentCldPubId: "",
    },
    shouldUnregister: false,
  });

  const role = form.watch("role");

  useEffect(() => {
    if (inviteCode) {
        toast.info(t("classes.show.toast.inviteLinkDetected"), {
            description: t("classes.show.toast.registerToJoin")
        });
    }
  }, [inviteCode, t]);

  const generateAIBio = async () => {
    const name = form.getValues("name");
    if (!name) {
      toast.error(t("auth.register.enterNameFirst"));
      return;
    }

    setIsGeneratingBio(true);
    try {
      const response = await axios.post<{ content: string }>("/api/ai/generate-content", {
        prompt: `Generate a professional bio for a ${role} named ${name}. Keywords: passionate, experienced, dedicated. Keep it under 50 words.`,
        context: "User Registration Bio"
      });
      
      form.setValue("bio", response.data.content);
      toast.success(t("auth.register.aiBioGenerated"));
    } catch {
      const fallbacks: Record<string, string> = {
        teacher: `Hello, I'm ${name}. I am a dedicated educator committed to fostering a positive and engaging learning environment for all my students.`,
        student: `Hi, I'm ${name}. I'm an enthusiastic student eager to learn and grow in my academic journey.`,
        parent: `Hello, I'm ${name}. I am a supportive parent dedicated to my child's educational success and well-being.`,
      };
      form.setValue("bio", fallbacks[role as keyof typeof fallbacks] || `Hi, I'm ${name}.`);
      toast.info(t("auth.register.aiBioFallback"));
    } finally {
      setIsGeneratingBio(false);
    }
  };

  const nextStep = async () => {
    const fieldsToValidate = ["name", "email", "password", "role"] as const;
    const isValid = await form.trigger(fieldsToValidate as any);
    if (isValid) setStep(2);
  };

  const handleFinalSubmit = () => {
    form.handleSubmit((values) => {
      register({ ...values, inviteCode }, {
        onSuccess: () => {
          const successMsg = values.role === "teacher" 
            ? t("auth.register.registrationSuccessTeacher")
            : t("auth.register.registrationSuccess");
          toast.success(successMsg);
          navigate("/login");
        },
        onError: (err) => {
          const error = err as HttpError;
          const errorMessage =
            (error as any)?.data?.message || error.message || t("auth.login.unknownError");
          toast.error(errorMessage);
        },
      });
    })();
  };

  const isAr = i18n.language === 'ar';

  return (
    <div className="min-h-dvh bg-background flex flex-col items-center justify-center p-4 md:p-8 relative overflow-hidden">
      {/* Immersive Background - Mobile Optimized */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-[-1]">
        <div className="absolute top-[-10%] start-[-10%] w-[60%] h-[40%] bg-primary/10 blur-[80px] md:blur-[120px] rounded-full opacity-50" />
        <div className="absolute bottom-[-10%] end-[-10%] w-[60%] h-[40%] bg-purple-500/10 blur-[80px] md:blur-[120px] rounded-full opacity-50" />
      </div>

      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: [0.23, 1, 0.32, 1] }}
        className="w-full max-w-xl z-10"
      >
        <Link to="/" className="flex items-center justify-center gap-3 mb-10 md:mb-14 group">
          <div className="bg-primary p-2.5 rounded-2xl group-hover:rotate-6 group-hover:scale-110 transition-all duration-500 shadow-lg shadow-primary/20">
            <BookOpen className="h-7 w-7 text-primary-foreground" />
          </div>
          <span className="text-3xl font-black tracking-tighter uppercase leading-none">
            Class<span className="text-primary italic">Room</span>
          </span>
        </Link>

        <Card className="border-border/40 shadow-[0_32px_64px_-12px_rgba(0,0,0,0.15)] dark:shadow-[0_32px_64px_-12px_rgba(0,0,0,0.4)] rounded-[2.5rem] md:rounded-[3rem] bg-card/50 backdrop-blur-3xl overflow-hidden">
          <CardHeader className="text-center pt-10 md:pt-14 pb-6 md:pb-10 space-y-4 md:space-y-6">
            <div className="inline-flex items-center gap-2 px-5 py-2 rounded-full bg-primary/5 text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 mx-auto border border-primary/10">
                <Sparkles className="h-3.5 w-3.5" />
                {t("auth.register.stepOf", { step, label: step === 1 ? t("auth.register.accountSetup") : t("auth.register.profileDetails") })}
            </div>
            <div className="space-y-2">
                <CardTitle className="text-3xl md:text-4xl font-black tracking-tighter uppercase leading-tight">{t("auth.register.title")}</CardTitle>
                <CardDescription className="font-medium text-base md:text-lg px-4 md:px-8">
                {t("auth.register.description")}
                </CardDescription>
            </div>
          </CardHeader>
          <CardContent className="px-6 md:px-12">
            <Form {...form}>
              <div className="space-y-6 md:space-y-8">
                <AnimatePresence mode="wait">
                  {step === 1 ? (
                    <motion.div
                      key="step1"
                      initial={{ opacity: 0, x: isAr ? 20 : -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: isAr ? -20 : 20 }}
                      transition={{ duration: 0.3, ease: [0.23, 1, 0.32, 1] }}
                      className="space-y-6 md:space-y-8"
                    >
                      <FormField
                        control={form.control}
                        name="role"
                        render={({ field }) => (
                          <FormItem className="space-y-3">
                            <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("profile.labels.role")}</FormLabel>
                            <FormControl>
                              <RoleSelector 
                                value={field.value as "student" | "teacher" | "parent"}
                                onChange={(val) => field.onChange(val)} 
                              />
                            </FormControl>
                            <FormMessage className="ms-2 font-bold" />
                          </FormItem>
                        )}
                      />

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                        <FormField
                          control={form.control}
                          name="name"
                          render={({ field }) => (
                            <FormItem className="space-y-3">
                              <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.fullNameLabel")}</FormLabel>
                              <FormControl>
                                <Input placeholder={t("auth.register.fullNamePlaceholder")} className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                              </FormControl>
                              <FormMessage className="ms-2 font-bold" />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="email"
                          render={({ field }) => (
                            <FormItem className="space-y-3">
                              <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.emailLabel")}</FormLabel>
                              <FormControl>
                                <Input type="email" placeholder={t("auth.register.emailPlaceholder")} className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                              </FormControl>
                              <FormMessage className="ms-2 font-bold" />
                            </FormItem>
                          )}
                        />
                      </div>
                      <FormField
                        control={form.control}
                        name="password"
                        render={({ field }) => (
                          <FormItem className="space-y-3">
                            <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.passwordLabel")}</FormLabel>
                            <FormControl>
                              <Input type="password" placeholder={t("auth.register.passwordPlaceholder")} className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                            </FormControl>
                            <FormMessage className="ms-2 font-bold" />
                          </FormItem>
                        )}
                      />
                    </motion.div>
                  ) : (
                    <motion.div
                      key="step2"
                      initial={{ opacity: 0, x: isAr ? -20 : 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: isAr ? 20 : -20 }}
                      transition={{ duration: 0.3, ease: [0.23, 1, 0.32, 1] }}
                      className="space-y-6 md:space-y-8"
                    >
                      <div className="p-5 rounded-[1.5rem] bg-primary/5 border border-primary/10 shadow-sm">
                        <p className="text-xs md:text-sm text-muted-foreground font-black uppercase tracking-widest leading-relaxed flex items-center gap-2">
                          <Sparkles className="h-4 w-4 text-primary" />
                          {t("auth.register.completeProfileTip")}
                        </p>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                        <FormField
                          control={form.control}
                          name="phoneNumber"
                          render={({ field }) => (
                            <FormItem className="space-y-3">
                              <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.phoneNumberLabel")}</FormLabel>
                              <FormControl>
                                <Input placeholder={t("auth.register.phoneNumberPlaceholder")} className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                              </FormControl>
                              <FormMessage className="ms-2 font-bold" />
                            </FormItem>
                          )}
                        />
                        {role === "student" && (
                          <FormField
                            control={form.control}
                            name="dateOfBirth"
                            render={({ field }) => (
                              <FormItem className="space-y-3">
                                <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.dobLabel")}</FormLabel>
                                <FormControl>
                                  <Input type="date" className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                                </FormControl>
                                <FormMessage className="ms-2 font-bold" />
                              </FormItem>
                            )}
                          />
                        )}
                        {role === "parent" && (
                          <>
                            <FormField
                              control={form.control}
                              name="parentName"
                              render={({ field }) => (
                                <FormItem className="space-y-3">
                                  <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.fullNameLabel")}</FormLabel>
                                  <FormControl>
                                    <Input placeholder={t("auth.register.fullNamePlaceholder")} className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                                  </FormControl>
                                  <FormMessage className="ms-2 font-bold" />
                                </FormItem>
                              )}
                            />
                            <FormField
                              control={form.control}
                              name="parentPhone"
                              render={({ field }) => (
                                <FormItem className="space-y-3">
                                  <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.phoneNumberLabel")}</FormLabel>
                                  <FormControl>
                                    <Input placeholder={t("auth.register.phoneNumberPlaceholder")} className="h-14 md:h-16 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-black placeholder:text-muted-foreground/30 focus-visible:ring-primary/20" {...field} />
                                  </FormControl>
                                  <FormMessage className="ms-2 font-bold" />
                                </FormItem>
                              )}
                            />
                          </>
                        )}
                      </div>

                      {role === "teacher" && (
                        <div className="space-y-6 md:space-y-8">
                          <FormField
                            control={form.control}
                            name="bio"
                            render={({ field }) => (
                              <FormItem className="space-y-3">
                                <div className="flex justify-between items-center">
                                  <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.bioLabel")}</FormLabel>
                                  <Button 
                                    type="button" 
                                    variant="ghost" 
                                    size="sm" 
                                    className="h-9 text-[10px] font-black uppercase tracking-widest text-primary hover:text-primary hover:bg-primary/10 rounded-xl gap-2"
                                    onClick={generateAIBio}
                                    disabled={isGeneratingBio}
                                  >
                                    {isGeneratingBio ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />}
                                    {t("buttons.aiAssist")}
                                  </Button>
                                </div>
                                <FormControl>
                                  <Textarea placeholder={t("auth.register.bioPlaceholder")} className="min-h-32 md:min-h-40 rounded-2xl md:rounded-3xl bg-muted/30 border-none shadow-inner px-6 md:px-8 text-base md:text-lg font-medium p-6 resize-none focus-visible:ring-primary/20 leading-relaxed italic" {...field} />
                                </FormControl>
                                <FormMessage className="ms-2 font-bold" />
                              </FormItem>
                            )}
                          />
                          
                          <FormField
                            control={form.control}
                            name="verificationDocumentUrl"
                            render={({ field }) => (
                              <FormItem className="space-y-3">
                                <FormLabel className="font-black uppercase text-[10px] tracking-[0.2em] text-muted-foreground/60 ms-2">{t("auth.register.verification.uploadLabel")}</FormLabel>
                                <FormControl>
                                  <VerificationUpload 
                                    url={field.value || ""}
                                    onUpload={(url, publicId) => {
                                      field.onChange(url);
                                      form.setValue("verificationDocumentCldPubId", publicId);
                                    }}
                                    onClear={() => {
                                      field.onChange("");
                                      form.setValue("verificationDocumentCldPubId", "");
                                    }}
                                  />
                                </FormControl>
                                <CardDescription className="ms-2 text-xs md:text-sm text-muted-foreground/70">
                                    {t("auth.register.verification.success")}
                                </CardDescription>
                                <FormMessage className="ms-2 font-bold" />
                              </FormItem>
                            )}
                          />
                        </div>
                      )}
                    </motion.div>
                  )}
                </AnimatePresence>

                <div className="flex flex-col sm:flex-row gap-4 pt-4 md:pt-6">
                  {step > 1 ? (
                    <Button type="button" variant="outline" size="lg" className="flex-1 h-14 md:h-16 rounded-2xl md:rounded-3xl font-black uppercase tracking-widest text-xs md:text-sm border-2 border-border/40 bg-background/50 shadow-sm" onClick={() => setStep(1)}>
                      <ArrowLeft className={cn("h-4 w-4 me-2", isAr && "ms-2 me-0 rotate-180")} />
                      {t("buttons.back")}
                    </Button>
                  ) : (
                    <Link to={`/login${inviteCode ? `?inviteCode=${inviteCode}` : ''}`} className="flex-1">
                      <Button variant="outline" size="lg" className="w-full h-14 md:h-16 rounded-2xl md:rounded-3xl font-black uppercase tracking-widest text-xs md:text-sm border-2 border-border/40 bg-background/50 shadow-sm">
                        <ArrowLeft className={cn("h-4 w-4 me-2", isAr && "ms-2 me-0 rotate-180")} />
                        {t("buttons.signIn")}
                      </Button>
                    </Link>
                  )}
                  {step < 2 ? (
                    <Button type="button" size="lg" className="flex-1 h-14 md:h-16 rounded-2xl md:rounded-3xl font-black uppercase tracking-widest text-xs md:text-sm shadow-2xl shadow-primary/30 group" onClick={nextStep}>
                      {t("buttons.continue")}
                      <ArrowRight className={cn("h-4 w-4 ms-2 group-hover:translate-x-1 transition-transform", isAr && "me-2 ms-0 rotate-180 group-hover:-translate-x-1")} />
                    </Button>
                  ) : (
                    <Button type="button" size="lg" className="flex-1 h-14 md:h-16 rounded-2xl md:rounded-3xl font-black uppercase tracking-widest text-xs md:text-sm shadow-2xl shadow-primary/30 group" disabled={isPending} onClick={handleFinalSubmit}>
                      {isPending ? (
                        <div className="flex items-center gap-3">
                            <Loader2 className="h-5 w-5 animate-spin" />
                            {t("buttons.authenticating")}
                        </div>
                      ) : (
                        <div className="flex items-center gap-3">
                            {t("buttons.completeJoin")}
                            <Zap className={cn("h-5 w-5 fill-current group-hover:scale-125 transition-transform", isAr && "rotate-180")} />
                        </div>
                      )}
                    </Button>
                  )}
                </div>
              </div>
            </Form>
          </CardContent>
          <CardFooter className="flex justify-center py-8 md:py-12 bg-primary/2 border-t border-border/40 mt-8">
            <p className="text-sm md:text-base font-medium text-muted-foreground/80">
              {t("auth.register.alreadyHaveAccount")}&nbsp;
              <Link to={`/login${inviteCode ? `?inviteCode=${inviteCode}` : ''}`} className="font-black text-primary hover:underline uppercase tracking-[0.1em] text-xs md:text-sm">{t("buttons.signIn")}</Link>
            </p>
          </CardFooter>
        </Card>
      </motion.div>
    </div>
  );
};

export default RegisterPage;

import { useState, useMemo, useEffect } from "react";
import {
  useGetIdentity,
  useGo,
  useCustom,
  BaseRecord,
  HttpError,
  useList,
  useCustomMutation,
} from "@refinedev/core";
import { User, UserRole, Class } from "@/types";
import { Calendar } from "@/components/ui/calendar";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Button } from "@/components/ui/button";
import {
  Calendar as CalendarIcon,
  Clock,
  ChevronLeft,
  ChevronRight,
  Loader2,
  Info,
  Users,
  FileText,
  FileQuestion,
  Wand2,
  Sparkles,
} from "lucide-react";
import dayjs from "dayjs";
import utc from "dayjs/plugin/utc";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslation } from "react-i18next";
import { motion } from "framer-motion";

import usePageTitle from "@/hooks/use-page-title";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb";

dayjs.extend(utc);

interface CalendarEvent extends BaseRecord {
  id: string;
  title: string;
  type: "class" | "assignment" | "quiz" | "exam";
  date: string;
  startTime?: string;
  endTime?: string;
  classId?: number;
  className?: string;
  color?: string;
}

export const CalendarPage = () => {
  const { t, i18n } = useTranslation();
  usePageTitle(t("calendar.title"));
  const { data: identity } = useGetIdentity<User>();
  const go = useGo();
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(
    new Date(),
  );

  const [isGenerateDialogOpen, setIsGenerateDialogOpen] = useState(false);
  const [selectedClassId, setSelectedClassId] = useState<string>("");

  const isTeacher = identity?.role === UserRole.TEACHER;

  // Custom query to fetch all schedules and deadlines
  const { query: calendarQueryResult } = useCustom<CalendarEvent[], HttpError>({
    url: "/calendar/events",
    method: "get",
    queryOptions: {
      enabled: !!identity?.id,
      staleTime: 5 * 60 * 1000,
    },
  });

  const {
    data: calendarResult,
    isLoading,
    refetch,
  } = calendarQueryResult;

  const calendarData = calendarResult?.data || [];

  useEffect(() => {
    if (identity && refetch) {
      void refetch();
    }
  }, [identity, refetch]);

  const { query: { data: classesData } } = useList<Class>({
    resource: "classes",
    queryOptions: {
      enabled: isTeacher,
    },
    filters: [
      {
        field: "teacherUid",
        operator: "eq",
        value: identity?.id,
      },
    ],
  });

  const { mutate: generateSchedule, mutation } =
    useCustomMutation<BaseRecord, HttpError, { classId: number }>();
  const isGenerating = mutation.isPending;

  const handleGenerateSchedule = () => {
    if (!selectedClassId) {
      toast.error(t("calendar.toasts.selectClass"));
      return;
    }

    generateSchedule(
      {
        url: "/calendar/generate",
        method: "post",
        values: { classId: Number(selectedClassId) },
      },
      {
        onSuccess: () => {
          toast.success(t("calendar.toasts.generated"));
          setIsGenerateDialogOpen(false);
          setSelectedClassId("");
          void refetch();
        },
        onError: (error: HttpError) => {
          toast.error(
            error.message || t("common.error")
          );
        },
      },
    );
  };

  const getEventIcon = (type: string) => {
    switch (type) {
      case "class":
        return <Users className="h-4 w-4" />;
      case "assignment":
        return <FileText className="h-4 w-4" />;
      case "quiz":
        return <FileQuestion className="h-4 w-4" />;
      default:
        return <CalendarIcon className="h-4 w-4" />;
    }
  };

  const getEventColor = (type: string, customColor?: string) => {
    if (customColor) return customColor;
    switch (type) {
      case "class":
        return "var(--primary)";
      case "assignment":
        return "#f59e0b";
      case "quiz":
        return "#ef4444";
      default:
        return "#6b7280";
    }
  };

  const eventsByDate = useMemo(() => {
    const grouped: Record<string, CalendarEvent[]> = {};
    const events = calendarData || [];

    events.forEach((event: CalendarEvent) => {
      const dateKey = dayjs(event.date).format("YYYY-MM-DD");
      if (!grouped[dateKey]) {
        grouped[dateKey] = [];
      }
      grouped[dateKey].push(event);
    });

    Object.keys(grouped).forEach((key) => {
      grouped[key].sort((a, b) => {
        if (!a.startTime || !b.startTime) return 0;
        return a.startTime.localeCompare(b.startTime);
      });
    });

    return grouped;
  }, [calendarData]);

  const selectedDateKey = selectedDate
    ? dayjs(selectedDate).format("YYYY-MM-DD")
    : null;
  const selectedDayEvents = selectedDateKey
    ? eventsByDate[selectedDateKey] || []
    : [];

  const handleEventClick = (event: CalendarEvent) => {
    if (event.classId) {
      go({ to: `/classes/show/${event.classId}` });
    }
  };

  return (
    <div className="space-y-8 md:space-y-12 pb-20 relative">
      {/* Background Polish */}
      <div className="hidden sm:block absolute top-0 start-1/4 w-100 h-100 bg-primary/5 rounded-full blur-[100px] -z-10 animate-pulse" />

      {/* Header Section */}
      <motion.div 
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col md:flex-row items-start md:items-end justify-between gap-6"
      >
        <div className="space-y-4 flex-1">
          <Breadcrumb />
          <div className="space-y-1">
            <h1 className="page-title mb-0 flex items-center gap-3">
              <div className="p-3 rounded-2xl bg-primary/10 text-primary shadow-sm border border-primary/5">
                <CalendarIcon className="h-6 w-6 md:h-8 md:w-8" />
              </div>
              {t("calendar.title")}
            </h1>
            <p className="text-muted-foreground font-medium max-w-2xl text-balance">
              {t("calendar.description")}
            </p>
          </div>
        </div>

        {isTeacher && (
          <Dialog
            open={isGenerateDialogOpen}
            onOpenChange={setIsGenerateDialogOpen}
          >
            <DialogTrigger asChild>
              <Button size="lg" className="rounded-2xl font-black uppercase tracking-widest text-[10px] gap-2 shadow-xl shadow-ai-primary/20 bg-ai-primary hover:bg-ai-primary/90 text-white border-none h-12 md:h-14 px-8 w-full md:w-auto">
                <Wand2 className="h-4 w-4 md:h-5 md:w-5" />
                {t("calendar.generatePlan")}
              </Button>
            </DialogTrigger>
            <DialogContent className="rounded-[2.5rem] border-none shadow-2xl bg-card/95 backdrop-blur-3xl max-w-lg p-0 overflow-hidden">
              <div className="p-8 md:p-12 space-y-8">
                <DialogHeader className="space-y-4">
                    <div className="p-5 rounded-2xl bg-ai-primary/10 text-ai-primary w-fit mx-auto">
                    <Wand2 className="h-10 w-10" />
                    </div>
                    <div className="space-y-2 text-center">
                    <DialogTitle className="text-3xl font-black tracking-tight">
                        {t("calendar.generateTitle")}
                    </DialogTitle>
                    <DialogDescription className="font-medium text-base text-muted-foreground">
                        {t("calendar.generateDesc")}
                    </DialogDescription>
                    </div>
                </DialogHeader>
                <div className="space-y-6">
                    <div className="space-y-3">
                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ms-1">
                        {t("calendar.selectClass")}
                    </label>
                    <Select
                        value={selectedClassId}
                        onValueChange={setSelectedClassId}
                    >
                        <SelectTrigger className="h-14 rounded-2xl bg-muted/30 border-none shadow-inner px-6 text-lg">
                        <SelectValue
                            placeholder={t("calendar.selectClass")}
                        />
                        </SelectTrigger>
                        <SelectContent className="rounded-2xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl p-2">
                        {classesData?.data?.map((c: Class) => (
                            <SelectItem
                            key={c.id}
                            value={String(c.id)}
                            className="rounded-xl py-3 cursor-pointer"
                            >
                            <span className="font-bold">{c.name}</span>
                            </SelectItem>
                        ))}
                        </SelectContent>
                    </Select>
                    </div>
                    <div className="p-6 rounded-2xl bg-primary/5 text-xs text-primary/70 border border-primary/10 flex items-start gap-4">
                    <Info className="h-5 w-5 shrink-0 mt-0.5" />
                    <p className="font-medium leading-relaxed">{t("calendar.syncInfo")}</p>
                    </div>
                </div>
                <DialogFooter className="flex-col sm:flex-row gap-3">
                    <Button
                    variant="ghost"
                    className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-8"
                    onClick={() => setIsGenerateDialogOpen(false)}
                    >
                    {t("buttons.cancel")}
                    </Button>
                    <Button
                    size="lg"
                    className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-10 bg-ai-primary hover:bg-ai-primary/90 text-white shadow-xl shadow-ai-primary/20"
                    onClick={handleGenerateSchedule}
                    disabled={isGenerating || !selectedClassId}
                    >
                    {isGenerating ? (
                        <>
                        <Loader2 className="h-5 w-5 me-3 animate-spin" />
                        {t("buttons.processing")}
                        </>
                    ) : (
                        <>
                        <Sparkles className="h-5 w-5 me-3" />
                        {t("buttons.create")}
                        </>
                    )}
                    </Button>
                </DialogFooter>
              </div>
            </DialogContent>
          </Dialog>
        )}
      </motion.div>

      <div className="grid lg:grid-cols-12 gap-8 md:gap-12 items-start">
        {/* Calendar Card */}
        <motion.div 
            initial={{ opacity: 0, x: -30 }}
            animate={{ opacity: 1, x: 0 }}
            className="lg:col-span-8"
        >
            <Card className="rounded-4xl border border-border/50 shadow-2xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none overflow-hidden p-4 md:p-8 lg:p-12">
            <Calendar
                mode="single"
                selected={selectedDate}
                onSelect={setSelectedDate}
                className="w-full flex justify-center"
                classNames={{
                months: "w-full",
                month: "w-full space-y-8 md:space-y-12",
                month_caption: "flex justify-center pt-2 relative items-center mb-10 md:mb-16",
                caption_label: "text-2xl md:text-3xl font-black tracking-tighter text-foreground",
                nav: "space-x-2 flex items-center",
                button_previous: cn(
                    "h-10 w-10 md:h-12 md:w-12 bg-muted/40 hover:bg-primary/10 rounded-2xl transition-all flex items-center justify-center p-0 absolute start-2",
                ),
                button_next: cn(
                    "h-10 w-10 md:h-12 md:w-12 bg-muted/40 hover:bg-primary/10 rounded-2xl transition-all flex items-center justify-center p-0 absolute end-2",
                ),
                month_grid: "w-full border-collapse space-y-4",
                weekdays: "flex w-full mb-6",
                weekday:
                    "text-muted-foreground/50 w-full font-black uppercase tracking-[0.2em] text-[9px] md:text-[10px]",
                week: "flex w-full mt-2 gap-2 md:gap-4",
                day: "text-center text-sm p-0 relative w-full h-12 xs:h-16 md:h-20 focus-within:relative focus-within:z-20",
                day_button: cn(
                    "h-full w-full p-0 font-bold hover:bg-primary/5 rounded-2xl md:rounded-[1.5rem] transition-all aria-selected:opacity-100",
                ),
                selected:
                    "bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground focus:bg-primary focus:text-primary-foreground shadow-2xl shadow-primary/30",
                today: "bg-primary/10 text-primary border border-primary/20",
                outside: "text-muted-foreground/30 opacity-50",
                disabled: "text-muted-foreground opacity-50",
                range_middle:
                    "aria-selected:bg-accent aria-selected:text-accent-foreground",
                hidden: "invisible",
                }}
                locale={undefined}
                components={{
                Chevron: ({ orientation }) => {
                    const Icon = orientation === "left" ? ChevronLeft : ChevronRight;
                    return <Icon className="h-6 w-6" />;
                },
                DayButton: ({ day, modifiers, ...props }) => {
                    const date = day.date;
                    const dateKey = dayjs(date).format("YYYY-MM-DD");
                    const dayEvents = eventsByDate[dateKey] || [];
                    const isSelected = modifiers.selected;
                    const isToday = modifiers.today;

                    return (
                    <button
                        {...props}
                        className={cn(
                        props.className,
                        "flex flex-col items-center justify-center h-full w-full relative group/day",
                        isSelected && "text-primary-foreground",
                        !isSelected && isToday && "text-primary",
                        )}
                    >
                        <span className="text-sm md:text-lg lg:text-xl font-black">{date.getDate()}</span>
                        {dayEvents.length > 0 && (
                        <div className="flex flex-wrap justify-center gap-1 md:gap-1.5 mt-1 absolute bottom-2 md:bottom-3 max-w-[80%]">
                            {dayEvents.slice(0, 3).map((event, i) => (
                            <div
                                key={i}
                                className="h-1.5 w-1.5 md:h-2 md:w-2 rounded-full shadow-sm"
                                style={{
                                backgroundColor: isSelected
                                    ? "white"
                                    : getEventColor(event.type, event.color),
                                }}
                            />
                            ))}
                            {dayEvents.length > 3 && (
                            <div className="h-1 w-1 md:h-1.5 md:w-1.5 rounded-full bg-muted-foreground/40" />
                            )}
                        </div>
                        )}
                    </button>
                    );
                },
                }}
            />
            </Card>
        </motion.div>

        {/* Events Sidebar */}
        <motion.div 
            initial={{ opacity: 0, x: 30 }}
            animate={{ opacity: 1, x: 0 }}
            className="lg:col-span-4"
        >
          <Card className="rounded-4xl border border-border/50 shadow-2xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none overflow-hidden sticky top-24">
            <CardHeader className="p-8 md:p-10 pb-6 md:pb-8 border-b border-border/40 bg-muted/20">
              <div className="flex flex-col gap-4">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 rounded-xl bg-primary/10 text-primary">
                        <Clock className="h-5 w-5" />
                    </div>
                    <CardTitle className="text-xl md:text-2xl font-black tracking-tight">
                        {selectedDate
                        ? dayjs(selectedDate).format(
                            i18n.language === "ar" ? "DD MMMM YYYY" : "MMMM D, YYYY",
                            )
                        : t("calendar.selectDate")}
                    </CardTitle>
                </div>
                <Badge
                    variant="ai"
                    className="w-fit px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em]"
                >
                    {selectedDayEvents.length}{" "}
                    {t("calendar.eventsSelectedDay")}
                </Badge>
              </div>
            </CardHeader>
            <CardContent className="p-0">
              {isLoading ? (
                <div className="flex flex-col items-center justify-center py-32 gap-6">
                  <div className="relative">
                    <Loader2 className="h-12 w-12 animate-spin text-primary/10" />
                    <CalendarIcon className="h-5 w-5 text-primary/30 absolute inset-0 m-auto" />
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground/40 animate-pulse">
                    {t("classes.curriculum.loading")}
                  </p>
                </div>
              ) : selectedDayEvents.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-32 text-center px-10 opacity-30 grayscale scale-95 transition-all">
                  <div className="p-6 rounded-4xl bg-muted/50 mb-6">
                    <CalendarIcon className="h-16 w-16" />
                  </div>
                  <p className="font-black uppercase tracking-[0.2em] text-[10px]">
                    {t("calendar.noEvents")}
                  </p>
                  <p className="text-sm font-medium mt-3 leading-relaxed">
                    {t("calendar.noEventsDesc")}
                  </p>
                </div>
              ) : (
                <ScrollArea className="h-112.5 md:h-150 p-6 md:p-8">
                  <div className="space-y-5 pe-2">
                    {selectedDayEvents.map((event, index) => {
                      const color = getEventColor(event.type, event.color);
                      return (
                        <motion.div
                          key={event.id || index}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: index * 0.05 }}
                          onClick={() => handleEventClick(event)}
                          className={cn(
                            "group flex flex-col p-6 rounded-4xl border transition-all duration-300 cursor-pointer shadow-sm hover:shadow-xl hover:shadow-primary/5",
                            event.classId
                              ? "hover:-translate-y-1"
                              : "hover:bg-muted/50 cursor-default",
                          )}
                          style={{
                            borderColor: `${color}20`,
                            backgroundColor: `${color}05`,
                          }}
                        >
                          <div className="flex flex-wrap justify-between items-start gap-3 mb-5">
                            <Badge
                              className="border-none text-[9px] font-black uppercase tracking-widest px-3 py-1.5 rounded-full flex items-center gap-2 shadow-sm"
                              style={{
                                backgroundColor: `${color}15`,
                                color: color,
                                border: `1px solid ${color}20`
                              }}
                            >
                              {getEventIcon(event.type)}
                              {t(`calendar.eventTypes.classes`)}
                            </Badge>
                            {event.startTime && (
                              <div className="flex items-center gap-2 text-[10px] font-black text-muted-foreground/60 bg-background/60 px-3 py-1.5 rounded-full backdrop-blur-md border border-border/40">
                                <Clock className="h-3.5 w-3.5" />
                                <span>
                                  {dayjs(event.startTime).format("HH:mm")}
                                  {event.endTime && ` - ${dayjs(event.endTime).format("HH:mm")}`}
                                </span>
                              </div>
                            )}
                          </div>
                          <h4 className="font-black text-lg md:text-xl tracking-tight mb-2 group-hover:text-primary transition-colors text-start leading-tight">
                            {event.title}
                          </h4>
                          {event.className && (
                            <div className="flex items-center gap-2 text-xs font-bold text-muted-foreground/60">
                              <div className="p-1.5 rounded-lg bg-primary/5">
                                <Users className="h-3 w-3 text-primary" />
                              </div>
                              <span className="truncate">{event.className}</span>
                            </div>
                          )}
                          
                          {event.classId && (
                            <div className="mt-5 flex items-center gap-2 text-[9px] font-black uppercase tracking-widest text-primary opacity-0 group-hover:opacity-100 transition-all -translate-x-2 group-hover:translate-x-0">
                                {t("notifications.viewClass")}
                                <ChevronRight className="h-3 w-3" />
                            </div>
                          )}
                        </motion.div>
                      );
                    })}
                  </div>
                </ScrollArea>
              )}
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </div>
  );
};
export default CalendarPage;

import { ListView } from "@/components/refine-ui/views/list-view.tsx";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb.tsx";
import { Search, Shield, Database, Globe, Clock } from "lucide-react";
import { Input } from "@/components/ui/input.tsx";
import { useMemo, useState } from "react";
import { DataTable } from "@/components/refine-ui/data-table/data-table.tsx";
import { useTable } from "@refinedev/react-table";
import { ActivityLog } from "@/types";
import { ColumnDef } from "@tanstack/react-table";
import { Badge } from "@/components/ui/badge.tsx";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";
