const TeacherCard = ({ channel, onShow }: { channel: TeacherChannel & { teacher: User }, onShow: (id: string) => void }) => {
  const [isHovered, setIsHovered] = useState(false);
  const { t } = useTranslation();

  return (
    <motion.div
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ y: -8 }}
      className="group relative aspect-[4/5.5] rounded-[2.5rem] md:rounded-[3.5rem] overflow-hidden border border-border/40 bg-black shadow-2xl transition-all duration-500"
    >
      <AnimatePresence mode="wait">
        {isHovered && channel.trailerVideoUrl ? (
          <motion.video
            key="video"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            src={channel.trailerVideoUrl}
            autoPlay
            muted
            loop
            playsInline
            className="absolute inset-0 w-full h-full object-cover scale-105"
          />
        ) : (
          <motion.img
            key="image"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            src={channel.thumbnailUrl || channel.teacher.image || "https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&q=80&w=1000"}
            className="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110 opacity-60 group-hover:opacity-100"
            alt={channel.teacher.name}
          />
        )}
      </AnimatePresence>

      {/* Modern Overlay */}
      <div className="absolute inset-0 bg-linear-to-t from-black via-black/20 to-transparent opacity-90 transition-opacity duration-500" />

      {/* Content */}
      <div className="absolute inset-x-0 bottom-0 p-8 md:p-10 space-y-6 z-10">
        <div className="space-y-3">
            <div className="flex items-center gap-2">
                <Badge className="bg-primary/20 backdrop-blur-md text-white border-primary/20 rounded-full px-4 py-1 font-black uppercase tracking-widest text-[8px]">
                    Top Rated
                </Badge>
                {channel.totalViews > 1000 && (
                    <Badge variant="secondary" className="bg-white/10 text-white border-none backdrop-blur-md rounded-full px-4 py-1 font-black uppercase tracking-widest text-[8px]">
