        </div>

        <div className="flex items-center gap-4">
            <Avatar className="h-10 w-10 border-2 border-white/20">
                <AvatarImage src={channel.teacher.image || undefined} />
                <AvatarFallback className="bg-primary/20 text-white font-black text-xs">{channel.teacher.name.substring(0,2).toUpperCase()}</AvatarFallback>
            </Avatar>
            <div className="text-start">
                <p className="text-sm font-black text-white">{channel.teacher.name}</p>
                <p className="text-[9px] font-black uppercase tracking-widest text-white/40">{channel.totalViews.toLocaleString()} Views</p>
            </div>
