                      {/* Info Area */}
                      <div className={cn("flex-1 min-w-0 w-full text-center md:text-start", "md:ms-8")}>
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 mb-2">
                          <h3 className="text-xl md:text-2xl font-black tracking-tight truncate group-hover:text-primary transition-colors leading-tight">
                            {discussion.content}
                          </h3>
                          <div className="flex items-center justify-center md:justify-start gap-2">
                            <Badge 
                                variant="ai" 
                                className="h-6"
                            >
                                {(discussion as any).class?.name || "General"}
                            </Badge>
                            {discussion.replies && discussion.replies.length > 5 && (
                                <Badge className="bg-orange-500/10 text-orange-600 border border-orange-500/20 font-black px-2.5 py-0.5 rounded-full text-[9px] tracking-widest uppercase shadow-sm">
                                    {t("discussions.labels.trending")}
                                </Badge>
                            )}
                          </div>
                        </div>
                        
                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 md:gap-6 mt-4">
                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <User className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">{discussion.user.role}</span>
                                <span className="text-[11px] font-black text-foreground">{discussion.user.name}</span>
                            </div>
                          </div>

                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <MessageCircle className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">{t("discussions.labels.replies")}</span>
                                <span className="text-[11px] font-black text-foreground">{discussion.replies?.length || 0}</span>
                            </div>
                          </div>

                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <Clock className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Activity</span>
                                <span className="text-[11px] font-black uppercase tracking-tight">
                                    {lastActivity.fromNow()}
                                </span>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Action Area */}
                      <div className="flex items-center gap-3 mt-6 md:mt-0 shrink-0">
                        <Button
                          variant="outline"
                          size="lg"
                          className="w-full md:w-auto rounded-2xl px-8 h-12 font-black uppercase tracking-widest text-[10px] transition-all border-primary/20 text-primary hover:bg-primary/5"
                        >
                          {t("buttons.view")}
                          <ArrowRight className={cn("h-4 w-4 ms-2 rtl:-scale-x-100")} />
                        </Button>

                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon" className="h-12 w-12 rounded-2xl md:hidden lg:flex bg-muted/30" onClick={(e) => e.stopPropagation()}>
                                    <MoreHorizontal className="h-5 w-5" />
                                </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end" className="w-64 p-2 rounded-3xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                                <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-[0.15em] text-muted-foreground/40 px-3 py-3">{t("discussions.labels.options")}</DropdownMenuLabel>
                                <DropdownMenuItem onClick={() => show("discussions", discussion.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                    <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                        <Eye className="h-4 w-4" />
                                    </div>
                                    <span className="font-bold">{t("discussions.labels.open")}</span>
                                </DropdownMenuItem>
                                <DropdownMenuItem className="rounded-xl gap-3 py-3 cursor-pointer">
                                    <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                        <Activity className="h-4 w-4" />
                                    </div>
                                    <span className="font-bold">{t("discussions.labels.follow")}</span>
                                </DropdownMenuItem>
                            </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
          )}
        </div>
      </div>
    </ListView>
  );
};

export default DiscussionsListPage;

import { ListView } from "@/components/refine-ui/views/list-view.tsx";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb.tsx";
import { 
  Search, 
  UserPlus, 
  CheckCircle2, 
  XCircle, 
  Trash2, 
  Filter, 
  MoreHorizontal, 
  Eye, 
  CheckSquare, 
  Square, 
  Phone, 
  Mail, 
  LayoutGrid, 
  Activity,
  Users,
  UserCheck,
  UserMinus,
  Clock
} from "lucide-react";
import { Input } from "@/components/ui/input.tsx";
import { useMemo, useState, useRef } from "react";
import { useList, useNavigation, useDelete, useCustomMutation, useInvalidate } from "@refinedev/core";
import { Enrollment } from "@/types";
import { useUserRole } from "@/hooks/use-user-role";
import { Badge } from "@/components/ui/badge.tsx";
import { Button } from "@/components/ui/button.tsx";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Card } from "@/components/ui/card";
import { motion } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import usePageTitle from "@/hooks/use-page-title";
import { useVirtualizer } from "@tanstack/react-virtual";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/empty-state";
import { useTerm } from "@/contexts/term-context";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslation } from "react-i18next";

dayjs.extend(relativeTime);

const EnrollmentsList = () => {
  const { t } = useTranslation();
  usePageTitle(t("enrollments.title"));
  const { identity, isStaff } = useUserRole();

  const { selectedTerm } = useTerm();
  
  const { create, show } = useNavigation();
  const { mutate: unenroll } = useDelete();
  const { mutate: updateStatus, mutation } = useCustomMutation();
  const isUpdating = mutation.isPending;
  const invalidate = useInvalidate();

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [deleteTarget, setDeleteTarget] = useState<number | null>(null);

  const filters = useMemo(() => {
    const f = [];
    if (statusFilter !== "all") {
        f.push({ field: "status", operator: "eq" as const, value: statusFilter });
    }
    if (searchQuery) {
        f.push({ field: "student.name", operator: "contains" as const, value: searchQuery });
    }
    if (selectedTerm) {
        f.push({ field: "termId", operator: "eq" as const, value: selectedTerm.id });
    }
    return f;
  }, [statusFilter, searchQuery, selectedTerm]);

  const { query: { data: enrollmentsData, isLoading } } = useList<Enrollment>({
    resource: "enrollments",
    pagination: { pageSize: 1000, mode: "server" },
    filters,
    sorters: [{ field: "id", order: "desc" }],
    meta: {
      populate: ["student", "class"]
    }
  });

  const enrollments = enrollmentsData?.data || [];
  const hasData = enrollments.length > 0;

  const handleStatusUpdate = (id: number, status: "approved" | "rejected") => {
    updateStatus({
        url: `/enrollments/${id}/status`,
        method: "patch",
        values: { status },
    }, {
        onSuccess: () => {
            toast.success(t("enrollments.toasts.statusUpdate", { status }));
            invalidate({ resource: "enrollments", invalidates: ["list"] });
        }
    });
  };

  const handleBulkAction = (status: "approved" | "rejected") => {
    if (selectedIds.length === 0) return;
    
    const promises = selectedIds.map(id => 
        new Promise((resolve) => {
            updateStatus({
                url: `/enrollments/${id}/status`,
                method: "patch",
                values: { status },
            }, { onSuccess: resolve, onError: resolve });
        })
    );

    toast.promise(Promise.all(promises), {
        loading: t("enrollments.toasts.processing", { count: selectedIds.length }),
        success: () => {
            setSelectedIds([]);
            invalidate({ resource: "enrollments", invalidates: ["list"] });
            return t("enrollments.toasts.bulkSuccess", { count: selectedIds.length });
        },
        error: t("enrollments.toasts.bulkError"),
    });
  };

  const toggleSelect = (id: number) => {
    setSelectedIds(prev => 
        prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: enrollments.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 100,
    overscan: 5,
  });

  // Stats calculation
  const stats = useMemo(() => {
    if (!enrollments.length) return { total: 0, pending: 0, approved: 0 };
    return {
      total: enrollments.length,
      pending: enrollments.filter((e: Enrollment) => e.status === 'pending').length,
      approved: enrollments.filter((e: Enrollment) => e.status === 'approved').length
    };
  }, [enrollments]);

  return (
    <div className="space-y-10 pb-20">
      <ListView>
        <div className="space-y-10">
          <motion.div 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-4"
          >
            <Breadcrumb />
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div>
                <h1 className="text-4xl font-black tracking-tight">{t("enrollments.title")}</h1>
                <p className="text-muted-foreground font-medium mt-1">{t("enrollments.description")}</p>
              </div>
              <div className="flex items-center gap-3 w-full md:w-auto">
                {isStaff && (
                  <Button 
                    onClick={() => create("classes")}
                    className="flex-1 md:flex-none rounded-2xl h-14 px-10 font-black uppercase tracking-widest text-[10px] gap-2 shadow-xl shadow-primary/20 transition-all hover:scale-105 active:scale-95"
                  >
                    <UserPlus className="h-5 w-5" />
                    {t("enrollments.enrollStudent")}
                  </Button>
                )}
              </div>
            </div>
          </motion.div>

          {/* Stats Row */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <Card className="p-6 border-primary/10 bg-card/50 backdrop-blur-sm flex items-center gap-4 rounded-4xl shadow-lg shadow-primary/5">
              <div className="p-3 rounded-2xl bg-primary/10 text-primary">
                <Users className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("enrollments.stats.total")}</p>
                <p className="text-2xl font-black">{isLoading ? "..." : stats.total}</p>
              </div>
            </Card>
            <Card className="p-6 border-amber-500/10 bg-card/50 backdrop-blur-sm flex items-center gap-4 rounded-4xl shadow-lg shadow-amber-500/5">
              <div className="p-3 rounded-2xl bg-amber-500/10 text-amber-600">
                <Activity className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("enrollments.stats.pending")}</p>
                <p className="text-2xl font-black text-amber-600">{isLoading ? "..." : stats.pending}</p>
              </div>
            </Card>
            <Card className="p-6 border-green-500/10 bg-card/50 backdrop-blur-sm flex items-center gap-4 rounded-4xl shadow-lg shadow-green-500/5">
              <div className="p-3 rounded-2xl bg-green-500/10 text-green-600">
                <UserCheck className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("enrollments.stats.active")}</p>
                <p className="text-2xl font-black text-green-600">{isLoading ? "..." : stats.approved}</p>
              </div>
            </Card>
          </div>
          
          {/* Filters & Search */}
          <Card className="p-4 border-primary/5 bg-muted/30 rounded-4xl backdrop-blur-sm">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="relative flex-1 group">
                <Search className="absolute start-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground group-focus-within:text-primary transition-colors" />
                <Input
                  type="text"
                  placeholder={t("enrollments.searchPlaceholder")}
                  className="ps-11 h-14 rounded-2xl border-none bg-background shadow-sm font-medium"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex flex-wrap gap-3">
                {selectedIds.length > 0 && (
                    <div className="flex items-center gap-2 bg-primary/5 px-4 rounded-2xl border border-primary/10 animate-in fade-in slide-in-from-end-4">
                        <span className="text-[10px] font-black uppercase tracking-widest text-primary">{selectedIds.length} {t("common.cases")}</span>
                        <Button size="sm" variant="ghost" className="h-8 text-green-600 hover:bg-green-50 font-black text-[10px] uppercase tracking-widest" onClick={() => handleBulkAction("approved")}>
                            {t("buttons.approve")}
                        </Button>
                        <Button size="sm" variant="ghost" className="h-8 text-destructive hover:bg-destructive/5 font-black text-[10px] uppercase tracking-widest" onClick={() => handleBulkAction("rejected")}>
                            {t("buttons.reject")}
                        </Button>
                    </div>
                )}
                <div className="flex items-center gap-2 bg-background px-4 rounded-2xl shadow-sm border border-primary/5">
                  <Filter className="h-4 w-4 text-muted-foreground" />
                  <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-40 border-none h-10 focus:ring-0 shadow-none font-black text-[10px] uppercase tracking-widest">
                      <SelectValue placeholder={t("enrollments.allStatus")} />
                    </SelectTrigger>
                    <SelectContent className="rounded-2xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                      <SelectItem value="all" className="rounded-xl font-bold">{t("enrollments.allStatus")}</SelectItem>
                      <SelectItem value="pending" className="rounded-xl font-bold">{t("status.upcoming")}</SelectItem>
                      <SelectItem value="approved" className="rounded-xl font-bold">{t("status.active")}</SelectItem>
                      <SelectItem value="rejected" className="rounded-xl font-bold">{t("buttons.reject")}</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </div>
          </Card>

          {/* Virtualized List Container */}
          <div 
            ref={parentRef} 
            className="h-150 overflow-auto pe-2 custom-scrollbar rounded-[2.5rem] border border-primary/5 bg-card/30 backdrop-blur-sm relative"
          >
            {isLoading ? (
              <div className="p-8 space-y-6">
                {Array.from({ length: 6 }).map((_, i) => (
                  <div key={i} className="flex flex-col md:flex-row items-center gap-6">
                    <Skeleton className="h-14 w-14 rounded-2xl shrink-0" />
                    <div className="flex-1 space-y-3 w-full">
                      <Skeleton className="h-6 w-62.5" />
                      <Skeleton className="h-4 w-45" />
                    </div>
                    <Skeleton className="h-10 w-24 rounded-xl" />
                  </div>
                ))}
              </div>
            ) : !hasData ? (
              <div className="h-full w-full flex items-center justify-center p-12">
                <EmptyState
                  icon={Users}
                  title={t("enrollments.empty.title")}
                  description={t("enrollments.empty.desc")}
                  className="border-none bg-transparent min-h-0"
                />
              </div>
            ) : (
              <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, width: '100%', position: 'relative' }}>
                {rowVirtualizer.getVirtualItems().map((virtualItem) => {
                  const enrollment = enrollments[virtualItem.index];
                  const isSelected = selectedIds.includes(enrollment.id);
                  const enrollmentDate = dayjs(enrollment.createdAt);
                  
                  return (
                    <div
                      key={virtualItem.key}
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: `${virtualItem.size}px`,
                        transform: `translateY(${virtualItem.start}px)`,
                      }}
                      className="px-8"
                    >
                      <motion.div
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ duration: 0.2 }}
                        className={cn(
                          "flex flex-col md:flex-row items-center h-full border-b border-primary/5 transition-all group",
                          isSelected ? "bg-primary/4" : "hover:bg-primary/2"
                        )}
                      >
                        {/* Selection & Avatar */}
                        <div className="flex items-center gap-6 shrink-0 mb-4 md:mb-0">
                          <Button 
                              variant="ghost" 
                              size="icon" 
                              className="h-10 w-10 rounded-xl hover:bg-primary/10"
                              onClick={() => toggleSelect(enrollment.id)}
                          >
                              {isSelected ? <CheckSquare className="h-5 w-5 text-primary" /> : <Square className="h-5 w-5 text-muted-foreground/40" />}
                          </Button>
                          <Avatar className="h-16 w-16 rounded-2xl border-4 border-background shadow-lg group-hover:scale-110 transition-transform">
                            <AvatarImage src={enrollment.student.image ?? undefined} className="object-cover" />
                            <AvatarFallback className="bg-primary/5 text-primary font-black text-xl">
                              {enrollment.student.name[0]}
                            </AvatarFallback>
                          </Avatar>
                        </div>

                        {/* Info */}
                        <div className="flex-1 md:ms-8 text-center md:text-start min-w-0 w-full">
                          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4">
                            <h3 className="text-xl font-black tracking-tight truncate group-hover:text-primary transition-colors">
                              {enrollment.student.name}
                            </h3>
                            <div className="flex items-center justify-center md:justify-start gap-2">
                              <Badge 
                                  variant={enrollment.status === 'approved' ? 'default' : enrollment.status === 'pending' ? 'secondary' : 'destructive'}
                                  className="text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border-none"
                              >
                                  {enrollment.status}
                              </Badge>
                              <Badge variant="outline" className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md border-primary/10">
                                  {enrollment.class?.name}
                              </Badge>
                            </div>
                          </div>
                          
                          <div className="flex flex-wrap items-center justify-center md:justify-start gap-x-6 gap-y-2 mt-3">
                            <div className="flex items-center gap-2 text-muted-foreground">
                              <div className="p-1.5 rounded-lg bg-primary/5">
                                  <Mail className="h-3.5 w-3.5 text-primary" />
                              </div>
                              <span className="text-xs font-bold">{enrollment.student.email}</span>
                            </div>

                            {enrollment.student.phoneNumber && (
                              <div className="flex items-center gap-2 text-muted-foreground">
                                  <div className="p-1.5 rounded-lg bg-primary/5">
                                      <Phone className="h-3.5 w-3.5 text-primary" />
                                  </div>
                                  <span className="text-xs font-bold">{enrollment.student.phoneNumber}</span>
                              </div>
                            )}

                            <div className="flex items-center gap-2 text-muted-foreground">
                              <div className="p-1.5 rounded-lg bg-primary/5">
                                  <Clock className="h-3.5 w-3.5 text-primary" />
                              </div>
                              <span className="text-xs font-bold uppercase tracking-tight">
                                  {t("enrollments.requested", { time: enrollmentDate.fromNow() })}
                              </span>
                            </div>
                          </div>
                        </div>

                        {/* Actions */}
                        <div className="flex items-center gap-3 mt-6 md:mt-0 shrink-0">
                          {enrollment.status === 'pending' && (
                              <div className="flex items-center gap-2">
                                  <Button
                                      variant="outline"
                                      size="sm"
                                      className="h-10 rounded-xl font-black uppercase tracking-widest text-[10px] border-green-500/20 text-green-600 bg-green-500/5 hover:bg-green-500/10 px-4"
                                      onClick={() => handleStatusUpdate(enrollment.id, "approved")}
                                      disabled={isUpdating}
                                  >
                                      <CheckCircle2 className="h-4 w-4 me-2" />
                                      {t("buttons.approve")}
                                  </Button>
                                  <Button
                                      variant="outline"
                                      size="sm"
                                      className="h-10 rounded-xl font-black uppercase tracking-widest text-[10px] border-destructive/20 text-destructive bg-destructive/5 hover:bg-destructive/10 px-4"
                                      onClick={() => handleStatusUpdate(enrollment.id, "rejected")}
                                      disabled={isUpdating}
                                  >
                                      <XCircle className="h-4 w-4 me-2" />
                                      {t("buttons.reject")}
                                  </Button>
                              </div>
                          )}

                          <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                  <Button variant="ghost" size="icon" className="h-10 w-10 rounded-xl">
                                      <MoreHorizontal className="h-5 w-5" />
                                  </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-56 rounded-[1.5rem] p-2 bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                                  <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground px-3 py-2">{t("enrollments.options")}</DropdownMenuLabel>
                                  <DropdownMenuItem onClick={() => show("users", enrollment.student.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                      <Eye className="h-4 w-4 text-primary" />
                                      <span className="font-bold">{t("enrollments.viewProfile")}</span>
                                  </DropdownMenuItem>
                                  <DropdownMenuItem onClick={() => show("classes", enrollment.class.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                      <LayoutGrid className="h-4 w-4 text-primary" />
                                      <span className="font-bold">{t("enrollments.viewClass")}</span>
                                  </DropdownMenuItem>
                                  <DropdownMenuSeparator className="my-2" />
                                  <DropdownMenuItem 
                                      onClick={() => setDeleteTarget(enrollment.id)} 
                                      className="rounded-xl gap-3 py-3 cursor-pointer text-destructive focus:text-destructive"
                                  >
                                      <UserMinus className="h-4 w-4" />
                                      <span className="font-bold">{t("enrollments.remove")}</span>
                                  </DropdownMenuItem>
                              </DropdownMenuContent>
                          </DropdownMenu>
                        </div>
                      </motion.div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </ListView>

      <AlertDialog open={deleteTarget !== null} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent className="rounded-[2.5rem] border border-border/50 shadow-2xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none">
          <AlertDialogHeader className="space-y-4">
            <div className="p-4 rounded-2xl bg-destructive/10 text-destructive w-fit">
              <Trash2 className="h-8 w-8" />
            </div>
            <div className="space-y-1">
                <AlertDialogTitle className="text-3xl font-black tracking-tight">{t("enrollments.deleteDialog.title")}</AlertDialogTitle>
                <AlertDialogDescription className="font-medium text-base leading-relaxed">
                    {t("enrollments.deleteDialog.desc")}
                </AlertDialogDescription>
            </div>
          </AlertDialogHeader>
          <AlertDialogFooter className="gap-3 pt-6">
            <AlertDialogCancel className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-8">{t("buttons.cancel")}</AlertDialogCancel>
            <AlertDialogAction 
                onClick={() => {
                    if (deleteTarget) {
                        unenroll({ resource: "enrollments", id: deleteTarget }, { onSuccess: () => { toast.success(t("enrollments.toasts.removed")); setDeleteTarget(null); } });
                    }
                }} 
                className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-12 bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-xl shadow-destructive/20"
            >
                {t("buttons.confirmDelete")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default EnrollmentsList;

import React, { useState } from "react";
import { useList, useCustomMutation, useDelete, useGetIdentity } from "@refinedev/core";
import { FileUpload } from "@/components/file-upload";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { 
  FolderOpen, 
  Trash2, 
  Link as LinkIcon, 
  Video, 
  FileText, 
  Loader2, 
  Plus, 
  Download,
  Search,
  Grid,
  List as ListIcon,
  ChevronRight,
  Sparkles,
  ExternalLink,
  Layers,
  Calendar as CalendarIcon
} from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import dayjs from "dayjs";
import { EmptyState } from "@/components/empty-state";
import { User, UserRole } from "@/types";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";
import { motion, AnimatePresence } from "framer-motion";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb";
import usePageTitle from "@/hooks/use-page-title";

const GlobalLibraryPage = () => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === 'ar';
  usePageTitle(t("library.title"));
  const { data: identity } = useGetIdentity<User>();
  const [isUploadOpen, setUploadOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  
  // Upload State
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [fileUrl, setFileUrl] = useState("");
  const [filePublicId, setFilePublicId] = useState("");

  const { query: { data: resourcesResult, isLoading, refetch } } = useList({
    resource: "resources",
    pagination: { pageSize: 100, mode: "server" }
  });

  const { mutate: createResource, mutation } = useCustomMutation();
  const isCreating = mutation.isPending;
  const { mutate: deleteResource } = useDelete();

  const handleUploadSuccess = (url: string, publicId: string) => {
    setFileUrl(url);
    setFilePublicId(publicId);
    if (!title) {
        setTitle(t("library.resourceTitle")); 
    }
  };

  const handleCreate = () => {
    if (!title || !fileUrl) {
      toast.error(t("library.toasts.fillRequired"));
      return;
    }

    createResource({
      url: "/resources",
      method: "post",
      values: {
        title,
        description,
        url: fileUrl,
        cldPubId: filePublicId,
        type: "file",
        classId: null,
        isInternal: true,
      }
    }, {
      onSuccess: () => {
        toast.success(t("library.toasts.added"));
        setUploadOpen(false);
        setTitle("");
        setDescription("");
        setFileUrl("");
        setFilePublicId("");
        refetch();
      },
      onError: (error: any) => {
        toast.error(error?.response?.data?.message || t("library.toasts.error"));
      }
    });
  };

  const handleDelete = (id: number) => {
    if (confirm(t("library.deleteConfirm"))) {
      deleteResource({
        resource: "resources",
        id,
      }, {
        onSuccess: () => {
            toast.success(t("library.toasts.deleted"));
            refetch();
        }
      });
    }
  };

  const resources = resourcesResult?.data || [];
  const filteredResources = resources.filter((r: any) => 
    r.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const isTeacherOrAdmin = identity?.role === UserRole.TEACHER || identity?.role === UserRole.ADMIN;

  return (
    <div className="space-y-8 md:space-y-12 pb-20">
      {/* Header Section */}
      <motion.div 
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6"
      >
        <div className="space-y-4 flex-1">
          <Breadcrumb />
          <div className="space-y-1 text-start">
            <h1 className="page-title mb-0 flex items-center gap-3">
              <div className="p-3 rounded-2xl bg-primary/10 text-primary border border-primary/5 shadow-sm">
                <FolderOpen className="h-6 w-6 md:h-8 md:w-8" />
              </div>
              {t("library.title")}
            </h1>
            <p className="text-muted-foreground font-medium max-w-2xl text-balance">
              {t("library.description")}
            </p>
          </div>
        </div>
        {isTeacherOrAdmin && (
            <div className="w-full md:w-auto">
                <Dialog open={isUploadOpen} onOpenChange={setUploadOpen}>
                    <DialogTrigger asChild>
                        <Button size="lg" className="w-full md:w-auto rounded-2xl h-12 md:h-14 px-10 font-bold uppercase tracking-widest text-[10px] gap-2 shadow-lg shadow-primary/25 hover:translate-y-[-2px] transition-all">
                            <Plus className="h-5 w-5" /> {t("library.addResource")}
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="rounded-[2.5rem] border-none shadow-2xl bg-card/95 backdrop-blur-xl max-w-lg p-0 overflow-hidden text-start">
                        <div className="p-8 md:p-12 space-y-8">
                            <DialogHeader className="space-y-4 text-start">
                                <div className="p-5 rounded-2xl bg-primary/10 text-primary w-fit mx-auto">
                                    <Plus className="h-10 w-10" />
                                </div>
                                <div className="space-y-2 text-center">
                                    <DialogTitle className="text-3xl font-black tracking-tight">{t("library.addToLibrary")}</DialogTitle>
                                    <DialogDescription className="font-medium text-base text-muted-foreground">{t("library.uploadDesc")}</DialogDescription>
                                </div>
                            </DialogHeader>
                            <div className="space-y-6">
                                <div className="space-y-3">
                                    <Label htmlFor="title" className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground ms-2">{t("library.resourceTitle")}</Label>
                                    <Input 
                                        id="title" 
                                        placeholder={t("library.resourceTitle")} 
                                        value={title}
                                        onChange={(e) => setTitle(e.target.value)}
                                        className="h-16 rounded-3xl bg-muted/30 border-none shadow-inner px-8 text-lg font-black"
                                    />
                                </div>
                                <div className="space-y-3">
                                    <Label htmlFor="description" className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground ms-2">{t("common.description")}</Label>
                                    <Input 
                                        id="description" 
                                        placeholder={t("library.optionalDesc")} 
                                        value={description}
                                        onChange={(e) => setDescription(e.target.value)}
                                        className="h-16 rounded-3xl bg-muted/30 border-none shadow-inner px-8 font-bold"
                                    />
                                </div>
                                <div className="space-y-3">
                                    <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground ms-2">{t("common.upload.label")}</Label>
                                    <div className="p-1 rounded-4xl bg-muted/30 shadow-inner">
                                        <FileUpload 
                                            label={t("common.upload.label")}
                                            folder="library"
                                            onUploadSuccess={handleUploadSuccess}
                                        />
                                    </div>
                                </div>
                            </div>
                            <DialogFooter className="flex-col sm:flex-row gap-3 pt-4">
                                <Button variant="ghost" className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-8 order-2 sm:order-1" onClick={() => setUploadOpen(false)}>{t("buttons.cancel")}</Button>
                                <Button onClick={handleCreate} disabled={isCreating || !fileUrl} size="lg" className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-12 shadow-xl shadow-primary/20 order-1 sm:order-2">
                                    {isCreating ? <Loader2 className="me-3 h-5 w-5 animate-spin" /> : <Plus className="h-5 w-5 me-3" />}
                                    {t("library.addToLibrary")}
                                </Button>
                            </DialogFooter>
                        </div>
                    </DialogContent>
                </Dialog>
            </div>
        )}
      </motion.div>

      {/* Search & View Controls - Sticky */}
      <Card className="p-2 border-border/40 bg-muted/20 rounded-[1.75rem] md:rounded-3xl backdrop-blur-md sticky top-20 z-30 shadow-sm">
        <div className="flex flex-col md:flex-row items-center gap-3">
            <div className="relative flex-1 group w-full">
                <Search className={cn("absolute top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/60 group-focus-within:text-primary transition-colors start-4")} />
                <Input 
                    placeholder={t("library.searchPlaceholder")} 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className={cn("h-12 rounded-2xl border-none bg-background/50 shadow-none font-medium ps-11 pe-4")}
                />
            </div>
            <div className="flex items-center gap-2 w-full md:w-auto">
                <div className="bg-background/50 p-1.5 rounded-2xl flex items-center gap-1 border border-border/40 flex-1 md:flex-none justify-center">
                    <Button 
                        variant={viewMode === "grid" ? "secondary" : "ghost"} 
                        size="sm" 
                        className={cn("rounded-xl h-10 px-4 font-black text-[10px] uppercase tracking-widest gap-2", viewMode === "grid" && "bg-white shadow-sm text-primary")}
                        onClick={() => setViewMode("grid")}
                    >
                        <Grid className="h-4 w-4" />
                        <span className="hidden xs:inline">Grid</span>
                    </Button>
                    <Button 
                        variant={viewMode === "list" ? "secondary" : "ghost"} 
                        size="sm" 
                        className={cn("rounded-xl h-10 px-4 font-black text-[10px] uppercase tracking-widest gap-2", viewMode === "list" && "bg-white shadow-sm text-primary")}
                        onClick={() => setViewMode("list")}
                    >
                        <ListIcon className="h-4 w-4" />
                        <span className="hidden xs:inline">List</span>
                    </Button>
                </div>
            </div>
        </div>
      </Card>

      {/* Library Grid/List */}
      <div className="relative min-h-[400px]">
        {isLoading ? (
            <div className="grid gap-6 grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4">
                {[1,2,3,4,5,6,7,8].map(i => (
                    <Card key={i} className="h-64 bg-background/50 animate-pulse rounded-4xl border-border/20" />
                ))}
            </div>
        ) : filteredResources.length === 0 ? (
            <div className="flex items-center justify-center p-16 bg-card/20 rounded-[2.5rem] border border-dashed border-border/40">
                <EmptyState 
                    icon={Layers}
                    title={t("library.emptyTitle")}
                    description={t("library.emptyDesc")}
                    className="border-none bg-transparent min-h-0"
                />
            </div>
        ) : (
            <div className={cn(
                "grid gap-6 md:gap-8",
                viewMode === "grid" ? "grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4" : "grid-cols-1"
            )}>
                <AnimatePresence mode="popLayout">
                    {filteredResources.map((resource: any, index) => (
                        <motion.div
                            key={resource.id}
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            transition={{ delay: index * 0.03 }}
                        >
                            <Card className={cn(
                                "group relative overflow-hidden transition-all duration-500 border border-border/40 bg-card/50 backdrop-blur-sm hover:shadow-2xl hover:shadow-primary/5 hover:border-primary/20 cursor-pointer",
                                viewMode === "grid" ? "rounded-4xl h-full" : "rounded-3xl"
                            )}>
                                {/* Status Accent */}
                                <div className="absolute start-0 top-0 w-1 h-full bg-primary opacity-0 group-hover:opacity-100 transition-opacity" />

                                <CardContent className={cn("p-6 md:p-8", viewMode === "list" && "flex flex-col md:flex-row items-center gap-6")}>
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="p-4 rounded-2xl bg-primary/10 text-primary shadow-sm border border-primary/5 group-hover:scale-110 transition-transform duration-500">
                                            {resource.type === 'video' ? <Video className="h-7 w-7" /> : 
                                            resource.type === 'link' ? <LinkIcon className="h-7 w-7" /> : 
                                            <FileText className="h-7 w-7" />}
                                        </div>
                                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                            {(isTeacherOrAdmin || resource.ownerId === identity?.id) && (
                                                <Button 
                                                    variant="ghost" 
                                                    size="icon" 
                                                    className="h-10 w-10 rounded-xl text-muted-foreground hover:text-destructive hover:bg-destructive/10"
                                                    onClick={(e) => { e.stopPropagation(); handleDelete(resource.id); }}
                                                >
                                                    <Trash2 className="h-5 w-5" />
                                                </Button>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex-1 min-w-0 text-start">
                                        <h3 className="text-xl font-black tracking-tight group-hover:text-primary transition-colors leading-tight mb-2 truncate" title={resource.title}>
                                            {resource.title}
                                        </h3>
                                        <p className="text-sm font-medium text-muted-foreground/70 line-clamp-2 mb-6 leading-relaxed">
                                            {resource.description || t("library.noDescription")}
                                        </p>
                                        
                                        <div className="pt-6 border-t border-border/40 flex items-center justify-between">
                                            <div className="flex items-center gap-2">
                                                <CalendarIcon className="h-3.5 w-3.5 text-primary/60" />
                                                <span className="text-[10px] font-black uppercase tracking-wider text-muted-foreground/60">
                                                    {dayjs(resource.createdAt).locale(i18n.language).format("MMM D, YYYY")}
                                                </span>
                                            </div>
                                            <Button 
                                                variant="outline" 
                                                size="sm"
                                                className="rounded-xl font-black uppercase tracking-widest text-[9px] h-9 px-4 gap-2 border-primary/10 text-primary hover:bg-primary hover:text-primary-foreground transition-all shadow-sm"
                                                asChild
                                            >
                                                <a href={resource.url} target="_blank" rel="noreferrer">
                                                    {t("buttons.download")}
                                                    <Download className="h-3 w-3" />
                                                </a>
                                            </Button>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
        )}
      </div>
    </div>
  );
};

export default GlobalLibraryPage;

import React, { useState, useEffect, useRef } from "react";
import { useCustom, useCustomMutation, useGetIdentity } from "@refinedev/core";
import { User } from "@/types";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Send, Search, MessageCircle, MoreVertical, Paperclip, ChevronLeft } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { ar as arLocale, enUS as enLocale } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { useTranslation } from "react-i18next";
import { motion } from "framer-motion";
import usePageTitle from "@/hooks/use-page-title";
import { useSearchParams } from "react-router-dom";
import { socket, connectSocket } from "@/lib/socket";

interface Message {
    id: number;
    content: string;
    createdAt: string;
    userId: string;
    recipientId: string;
    isPrivate: boolean;
    user: {
        id: string;
        name: string;
        image: string;
    };
}

interface Conversation {
    user: {
        id: string;
        name: string;
        image: string;
        role: string;
    };
    lastMessage: {
        content: string;
        createdAt: string;
        isMe: boolean;
        isRead: boolean;
    };
}

const MessagesPage = () => {
    const { t, i18n } = useTranslation();
    const isAr = i18n.language === 'ar';
    usePageTitle(t("messages.title"));
    const { data: identity } = useGetIdentity<User>();
    const [searchParams] = useSearchParams();
    const targetUserId = searchParams.get("userId");
    
    const [selectedUser, setSelectedUser] = useState<Conversation["user"] | null>(null);
    const [messageInput, setMessageInput] = useState("");
    const messagesEndRef = useRef<HTMLDivElement>(null); 

    const dateLocale = isAr ? arLocale : enLocale;
    
    // Unified Socket Initialization
    useEffect(() => {
        if (identity) {
            void connectSocket();
        }
    }, [identity]);

    // Fetch Conversations
    const { result: conversationsResult, query: { refetch: refetchConversations, isLoading: isLoadingConversations } } = useCustom<{ data: Conversation[] }>({
        url: "/messages",
        method: "get",
        queryOptions: {
            enabled: !!identity,
            refetchInterval: 10000 
        }
    });

    const conversations = conversationsResult?.data?.data || [];

    // Auto-select user from searchParams (Notification deep-link)
    useEffect(() => {
        if (targetUserId && conversations.length > 0) {
            const existingConv = conversations.find(c => c.user.id === targetUserId);
            if (existingConv) {
                setSelectedUser(existingConv.user);
            }
        }
    }, [targetUserId, conversations]);

    // Fetch Target User if not in conversations (Start new chat)
    const { result: targetUserResult } = useCustom<{ data: Conversation["user"] }>({
        url: `/messages/user/${targetUserId}`,
        method: "get",
        queryOptions: {
            enabled: !!targetUserId && !conversations.find(c => c.user.id === targetUserId),
        }
    });

    useEffect(() => {
        if (targetUserResult?.data?.data) {
            setSelectedUser(targetUserResult.data.data);
        }
    }, [targetUserResult]);

    // Fetch Messages for Selected User
    const { result: messagesResult, query: { refetch: refetchMessages, isLoading: isLoadingMessages } } = useCustom<{ data: Message[] }>({
        url: `/messages/${selectedUser?.id}`,
        method: "get",
        queryOptions: {
            enabled: !!selectedUser,
            refetchInterval: 3000 
        }
    });

    const { mutate: sendMessage } = useCustomMutation();

    // Socket Connection
    useEffect(() => {
        if (!identity?.id) return;

        const handleMsgNotification = (notification: any) => {
             if (notification.type === "message") {
                 void refetchConversations();
                 if (selectedUser) void refetchMessages();
             }
        };

        socket.on("notification", handleMsgNotification);

        return () => {
            socket.off("notification", handleMsgNotification);
        };
    }, [identity?.id, selectedUser, refetchConversations, refetchMessages]);

    // Scroll to bottom on new message
    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
        }
    }, [messagesResult]);

    const handleSend = () => {
        if (!messageInput.trim() || !selectedUser) return;

        sendMessage(
            {
                url: "/messages",
                method: "post",
                values: {
                    recipientId: selectedUser.id,
                    content: messageInput
                }
            },
            {
                onSuccess: () => {
                    setMessageInput("");
                    void refetchMessages();
                    void refetchConversations();
                }
            }
        );
    };

    const messages = messagesResult?.data?.data || [];

    return (
        <div className="container mx-auto py-6 md:py-8 h-[calc(100vh-4rem)] max-w-screen-2xl">
            <div className="grid grid-cols-1 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6 h-full">
                {/* Sidebar: Conversations List */}
                <motion.div
                    initial={{ opacity: 0, x: isAr ? 20 : -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.2 }}
                    className={cn(
                        "md:col-span-1 lg:col-span-2 h-full flex flex-col border-none shadow-xl bg-card/50 backdrop-blur-3xl rounded-[2.5rem]",
                        selectedUser ? "hidden md:flex" : "flex"
                    )}
                >
                    <CardHeader className="p-6 md:p-8 pb-4 border-b border-border/40">
                        <CardTitle className="text-2xl md:text-3xl font-black flex items-center gap-3">
                            <MessageCircle className="h-6 w-6 md:h-8 md:w-8 text-primary" />
                            {t("messages.title")}
                        </CardTitle>
                        <p className="text-muted-foreground font-medium text-sm md:text-base">{t("messages.description")}</p>
                    </CardHeader>
                    <div className="p-4 md:p-6 border-b border-border/40">
                        <div className="relative group">
                            <Search className={cn("absolute top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/60 group-focus-within:text-primary transition-colors", "start-4")} />
                            <Input 
                                placeholder={t("messages.searchPeople")} 
                                className={cn("bg-background/50 border-border/40 h-12 rounded-xl shadow-sm", "ps-11 pe-4")} 
                            />
                        </div>
                    </div>
                    <ScrollArea className="flex-1 p-4 md:p-6">
                        <div className="space-y-3">
                            {isLoadingConversations ? (
                                Array.from({ length: 5 }).map((_, i) => (
                                    <div key={i} className="flex items-center gap-3 p-3 rounded-xl bg-muted/20 animate-pulse">
                                        <div className="h-10 w-10 rounded-full bg-muted/40" />
                                        <div className="flex-1 space-y-2">
                                            <div className="h-4 w-3/4 bg-muted/40 rounded" />
                                            <div className="h-3 w-1/2 bg-muted/40 rounded" />
                                        </div>
                                    </div>
                                ))
                            ) : conversations.length === 0 ? (
                                <div className="text-center p-8 text-muted-foreground text-base">
                                    <MessageCircle className="h-12 w-12 mx-auto mb-4 opacity-30" />
                                    {t("messages.noConversations")}
                                </div>
                            ) : (
                                conversations.map((conv: Conversation) => (
                                    <div
                                        key={conv.user.id}
                                        onClick={() => setSelectedUser(conv.user)}
                                        className={cn(
                                            "flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-colors hover:bg-primary/5 border border-transparent hover:border-primary/10 shadow-sm",
                                            selectedUser?.id === conv.user.id ? "bg-primary/10 border-primary/20" : "bg-background/50"
                                        )}
                                    >
                                        <div className="relative shrink-0">
                                            <Avatar className="h-12 w-12 border-2 border-background shadow-sm">
                                                <AvatarImage src={conv.user.image} />
                                                <AvatarFallback className="bg-primary/10 text-primary font-bold text-sm">{conv.user.name[0]}</AvatarFallback>
                                            </Avatar>
                                            {!conv.lastMessage.isRead && !conv.lastMessage.isMe && (
                                                <div className="absolute -top-1 -end-1 size-3 bg-red-500 rounded-full border-2 border-background animate-pulse" />
                                            )}
                                        </div>
                                        <div className="flex-1 overflow-hidden">
                                            <div className="flex justify-between items-center mb-0.5">
                                                <h3 className="font-bold text-base truncate">{conv.user.name}</h3>
                                                <span className="text-[10px] text-muted-foreground/60">
                                                    {formatDistanceToNow(new Date(conv.lastMessage.createdAt), { addSuffix: false, locale: dateLocale })}
                                                </span>
                                            </div>
                                            <p className="text-sm text-muted-foreground/80 truncate">
                                                {conv.lastMessage.isMe && <span className="font-bold text-primary/80">{t("messages.you")}: </span>}{conv.lastMessage.content}
                                            </p>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </ScrollArea>
                </motion.div>

                {/* Main Chat Area */}
                <motion.div
                    initial={{ opacity: 0, x: isAr ? -20 : 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.2 }}
                    className={cn(
                        "md:col-span-3 lg:col-span-3 h-full flex flex-col border-none shadow-xl bg-card/50 backdrop-blur-3xl rounded-[2.5rem]",
                        selectedUser ? "flex" : "hidden md:flex"
                    )}
                >
                    {selectedUser ? (
                        <>
                            {/* Header */}
                            <div className="p-4 md:p-6 border-b border-border/40 flex justify-between items-center bg-card/30">
                                <div className="flex items-center gap-3">
                                    <Button variant="ghost" size="icon" className="md:hidden" onClick={() => setSelectedUser(null)}>
                                        <ChevronLeft className="h-5 w-5" />
                                    </Button>
                                    <Avatar className="h-12 w-12 border-2 border-background shadow-sm">
                                        <AvatarImage src={selectedUser.image} />
                                        <AvatarFallback className="bg-primary/10 text-primary font-bold text-base">{selectedUser.name[0]}</AvatarFallback>
                                    </Avatar>
                                    <div className="text-start">
                                        <h3 className="font-bold text-lg">{selectedUser.name}</h3>
                                        <Badge variant="outline" className="text-[10px] px-2 py-0.5 h-5 capitalize rounded-full shadow-sm">
                                            {selectedUser.role}
                                        </Badge>
                                    </div>
                                </div>
                                <Button variant="ghost" size="icon" className="h-10 w-10 rounded-xl">
                                    <MoreVertical className="h-5 w-5 text-muted-foreground" />
                                </Button>
                            </div>

                            {/* Messages List */}
                            <ScrollArea className="flex-1 p-4 md:p-6 bg-background/30">
                                <div className="space-y-4">
                                    {isLoadingMessages ? (
                                        Array.from({ length: 5 }).map((_, i) => (
                                            <div key={i} className={cn("flex", i % 2 === 0 ? "justify-end" : "justify-start")}>
                                                <div className="max-w-[60%] rounded-2xl px-4 py-2 bg-muted/30 animate-pulse h-16 w-full" />
                                            </div>
                                        ))
                                    ) : messages.length === 0 ? (
                                        <div className="text-center p-8 text-muted-foreground text-base">
                                            <MessageCircle className="h-12 w-12 mx-auto mb-4 opacity-30" />
                                            {t("messages.noMessages")}
                                        </div>
                                    ) : (
                                        messages.map((msg: Message) => {
                                            const isMe = msg.userId === identity?.id;
                                            return (
                                                <div
                                                    key={msg.id}
                                                    className={cn(
                                                        "flex w-full",
                                                        isMe ? "justify-end" : "justify-start"
                                                    )}
                                                >
                                                    <div
                                                        className={cn(
                                                            "max-w-[70%] rounded-2xl px-4 py-2 text-sm md:text-base shadow-sm",
                                                            isMe
                                                                ? "bg-primary text-primary-foreground ltr:rounded-br-none rtl:rounded-bl-none"
                                                                : "bg-white dark:bg-muted/10 border border-border/40 ltr:rounded-bl-none rtl:rounded-br-none"
                                                        )}
                                                    >
                                                        <p className="text-start leading-relaxed">{msg.content}</p>
                                                        <span className={cn(
                                                            "text-[10px] block mt-1 opacity-70",
                                                            "text-end",
                                                            isMe ? "text-primary-foreground/80" : "text-muted-foreground"
                                                        )}>
                                                            {new Date(msg.createdAt).toLocaleTimeString(isAr ? 'ar-EG' : 'en-US', { hour: '2-digit', minute: '2-digit' })}
                                                        </span>
                                                    </div>
                                                </div>
                                            );
                                        })
                                    )}
                                    <div ref={messagesEndRef} />
                                </div>
                            </ScrollArea>

                            {/* Input Area */}
                            <div className="p-4 md:p-6 bg-card/30 border-t border-border/40">
                                <form
                                    onSubmit={(e) => {
                                        e.preventDefault();
                                        handleSend();
                                    }}
                                    className="flex items-center gap-3"
                                >
                                    <Button type="button" variant="ghost" size="icon" className="text-muted-foreground hover:text-primary h-10 w-10 rounded-xl">
                                        <Paperclip className="h-5 w-5" />
                                    </Button>
                                    <Input
                                        value={messageInput}
                                        onChange={(e) => setMessageInput(e.target.value)}
                                        placeholder={t("messages.typeMessage")}
                                        className="flex-1 bg-background/50 border-border/40 focus-visible:ring-primary h-12 rounded-xl shadow-sm"
                                    />
                                    <Button type="submit" size="icon" disabled={!messageInput.trim()} className="h-12 w-12 rounded-xl shadow-lg shadow-primary/20">
                                        <Send className={cn("h-5 w-5", isAr && "rotate-180")} />
                                    </Button>
                                </form>
                            </div>
                        </>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-muted-foreground p-8 text-center">
                            <div className="h-20 w-20 bg-primary/10 rounded-full flex items-center justify-center mb-4 shadow-lg">
                                <MessageCircle className="h-10 w-10 text-primary" />
                            </div>
                            <h3 className="text-xl md:text-2xl font-bold text-foreground mb-2">{t("messages.selectChat")}</h3>
                            <p className="max-w-sm text-sm md:text-base leading-relaxed">
                                {t("messages.selectChatDesc")}
                            </p>
                        </div>
                    )}
                </motion.div>
            </div>
        </div>
    );
};

export default MessagesPage;

import { ListView } from "@/components/refine-ui/views/list-view.tsx";
