                                    "text-[9px] font-black uppercase tracking-widest px-2.5 py-0.5 rounded-full shadow-sm border-none",
                                    isPublished ? "bg-green-500/10 text-green-600" : "bg-amber-500/10 text-amber-600 border border-amber-500/20"
