                  return (
                    <motion.div
                      key={subject.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      transition={{ delay: index * 0.05 }}
                      className={cn(
                        "group relative flex flex-col md:flex-row items-center p-5 md:p-6 rounded-4xl bg-card/50 backdrop-blur-sm border border-border/40 hover:border-primary/30 hover:bg-card/80 transition-all duration-300 shadow-sm hover:shadow-xl hover:shadow-primary/5 cursor-pointer"
                      )}
                      onClick={() => show("subjects", subject.id)}
                    >
                      {/* Status Line Accent */}
                      <div 
                        className="absolute start-0 top-1/2 -translate-y-1/2 w-1.5 h-12 bg-primary rounded-e-full transition-all group-hover:h-20"
                      />

                      {/* Icon/Code */}
                      <div className="relative shrink-0 mb-4 md:mb-0">
                        <div className="h-20 w-20 rounded-[1.5rem] border-4 border-background flex flex-col items-center justify-center shadow-lg group-hover:scale-105 transition-transform duration-500 bg-primary/10 text-primary">
                          <BookOpen className="h-8 w-8 mb-1" />
                          <span className="text-[10px] font-black uppercase tracking-tighter">
                            {subject.code}
                          </span>
                        </div>
                      </div>

                      {/* Info Area */}
                      <div
                        className={cn(
                          "flex-1 min-w-0 w-full text-start",
                          isAr ? "md:me-8 md:text-end" : "md:ms-8 md:text-start",
                        )}
                      >
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 mb-2">
                          <h3 className="text-xl md:text-2xl font-black tracking-tight truncate group-hover:text-primary transition-colors leading-tight">
                            {subject.name}
                          </h3>
                          <div className="flex items-center justify-center md:justify-start gap-2">
                            <Badge
                              variant="outline"
                              className="text-[9px] font-black uppercase tracking-widest px-2.5 py-0.5 rounded-full border-primary/10 shadow-sm"
                            >
                              {subject.code}
                            </Badge>
                            <Badge className="bg-primary/10 text-primary border-none font-black px-3 py-0.5 rounded-full text-[9px] tracking-widest uppercase shadow-sm">
                              {new Intl.NumberFormat(i18n.language).format(
                                subject.credits || 0,
                              )}{" "}
                              {t("classes.form.studentsUnit")}
                            </Badge>
                          </div>
                        </div>

                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 md:gap-6 mt-4">
                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                              <Building2 className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col">
                              <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Department</span>
                              <span className="text-[11px] font-black text-foreground truncate max-w-[150px]">
                                {subject.department?.name || t("subjects.filters.generalDepartment")}
                              </span>
                            </div>
                          </div>

                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                              <GraduationCap className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col">
                              <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Category</span>
                              <span className="text-[11px] font-black text-foreground uppercase tracking-tight">
                                {t("subjects.academicSubject")}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Action Area */}
                      <div className="flex items-center gap-3 mt-6 md:mt-0 shrink-0">
                        <div className={cn("hidden lg:flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300", isAr ? "-translate-x-4 group-hover:translate-x-0" : "translate-x-4 group-hover:translate-x-0")}>
                          {isAdmin && (
                            <>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-11 w-11 rounded-2xl text-muted-foreground hover:text-primary hover:bg-primary/5 bg-muted/20"
                                onClick={(e) => { e.stopPropagation(); edit("subjects", subject.id); }}
                              >
                                <Pencil className="h-5 w-5" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-11 w-11 rounded-2xl text-destructive hover:bg-destructive/10 bg-muted/20"
                                onClick={(e) => { e.stopPropagation(); setDeleteTarget(subject.id); }}
                              >
                                <Trash2 className="h-5 w-5" />
                              </Button>
                            </>
                          )}
                        </div>

                        <Button
                          variant="outline"
                          size="lg"
                          className="w-full md:w-auto rounded-2xl px-8 h-12 font-black uppercase tracking-widest text-[10px] transition-all border-primary/20 text-primary hover:bg-primary/5"
                        >
                          {t("buttons.viewDetails")}
                          <ArrowRight className={cn("h-4 w-4 ms-2", isAr && "rotate-180 me-2 ms-0")} />
                        </Button>

                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-12 w-12 rounded-2xl md:hidden lg:flex bg-muted/30" onClick={(e) => e.stopPropagation()}>
                              <MoreHorizontal className="h-5 w-5" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-64 p-2 rounded-3xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                            <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-[0.15em] text-muted-foreground/40 px-3 py-3">{t("assignments.list.labels.options")}</DropdownMenuLabel>
                            <DropdownMenuItem onClick={() => show("subjects", subject.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                              <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                <Eye className="h-4 w-4" />
                              </div>
                              <span className="font-bold">{t("buttons.viewDetails")}</span>
                            </DropdownMenuItem>
                            {isAdmin && (
                              <>
                                <DropdownMenuItem onClick={() => edit("subjects", subject.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                  <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                    <Pencil className="h-4 w-4" />
                                  </div>
                                  <span className="font-bold">{t("buttons.editAssignment")}</span>
                                </DropdownMenuItem>
                                <DropdownMenuSeparator className="my-2 opacity-50" />
                                <DropdownMenuItem onClick={() => setDeleteTarget(subject.id)} className="rounded-xl gap-3 py-3 cursor-pointer text-destructive focus:bg-destructive/10">
                                  <div className="p-2 rounded-lg bg-destructive/10 text-destructive">
                                    <Trash2 className="h-4 w-4" />
                                  </div>
                                  <span className="font-bold">{t("buttons.delete")}</span>
                                </DropdownMenuItem>
                              </>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
          )}
        </div>
      </div>

      <AlertDialog open={deleteTarget !== null} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent className="rounded-[2.5rem]">
          <AlertDialogHeader className="space-y-6">
            <div className="p-5 rounded-2xl bg-destructive/10 text-destructive w-fit mx-auto">
              <Trash2 className="h-10 w-10" />
            </div>
            <div className="space-y-2 text-center">
              <AlertDialogTitle className="text-3xl font-black tracking-tight">{t("assignments.list.deleteDialog.title")}</AlertDialogTitle>
              <AlertDialogDescription className="text-base font-medium px-8 leading-relaxed">
                {t("assignments.list.deleteDialog.description")}
              </AlertDialogDescription>
            </div>
          </AlertDialogHeader>
          <AlertDialogFooter className="sm:justify-center gap-4 pt-8">
            <AlertDialogCancel className="rounded-2xl px-10 h-14 font-black uppercase tracking-widest text-[10px]">{t("buttons.cancel")}</AlertDialogCancel>
            <AlertDialogAction 
              onClick={handleConfirmDelete} 
              disabled={isDeleteLoading}
              className="rounded-2xl px-12 h-14 font-black uppercase tracking-widest text-[10px] bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-xl shadow-destructive/20"
            >
              {isDeleteLoading ? t("buttons.processing") : t("buttons.confirmDelete")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </ListView>
  );
};
export default SubjectsList;

import { ListView } from "@/components/refine-ui/views/list-view.tsx";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb.tsx";
import { 
  Search, 
  User, 
  FileText, 
  Calendar, 
  CheckCircle2, 
  Clock, 
  AlertCircle, 
  Eye, 
  BrainCircuit,
  Filter,
  MoreHorizontal,
  ArrowRight,
  Activity,
  CheckSquare,
  LayoutGrid,
  Timer
} from "lucide-react";
import { Input } from "@/components/ui/input.tsx";
import { useMemo, useState, useRef, useCallback } from "react";
import { useList, useNavigation } from "@refinedev/core";
import { Submission } from "@/types";
import { useUserRole } from "@/hooks/use-user-role";
import { Badge } from "@/components/ui/badge.tsx";
import { Button } from "@/components/ui/button.tsx";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { GradingDialog } from "@/features/assignments/pages/grading-dialog";
import { useTerm } from "@/contexts/term-context";
import { Card } from "@/components/ui/card";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import usePageTitle from "@/hooks/use-page-title";
import { useVirtualizer } from "@tanstack/react-virtual";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/empty-state";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useTranslation } from "react-i18next";

dayjs.extend(relativeTime);

const SubmissionsListPage = () => {
  const { t, i18n } = useTranslation();
  const isAr = i18n.language === 'ar';
  
  usePageTitle(t("resources.submissions.label"));
  const { identity, isStaff } = useUserRole();
  const { selectedTerm } = useTerm();

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedSubmission, setSelectedSubmission] = useState<Submission | null>(null);
  const [isGradingOpen, setIsGradingOpen] = useState(false);

  const { show } = useNavigation();

  const handleGradeClick = (submission: Submission) => {
    if (!isStaff) return;
    setSelectedSubmission(submission);
    setIsGradingOpen(true);
  };

  const filters = useMemo(() => {
    const f = [];
    if (searchQuery) {
      f.push({ field: "assignment.title", operator: "contains" as const, value: searchQuery });
    }
    return f;
  }, [searchQuery]);

  const { query } = useList<Submission>({
    resource: "submissions",
    pagination: { pageSize: 1000, mode: "server" },
    filters,
    sorters: [{ field: "updatedAt", order: "desc" }],
    meta: {
      populate: ["student", "assignment", "assignment.class"]
    }
  });

  const submissions = query.data?.data || [];
  const isLoading = query.isLoading;
  const hasData = submissions.length > 0;

  const parentRef = useRef<HTMLDivElement>(null);

  const estimateSize = useCallback(() => 120, []);

  const rowVirtualizer = useVirtualizer({
    count: submissions.length,
    getScrollElement: () => parentRef.current,
    estimateSize,
    overscan: 5,
  });

  // Stats calculation
  const stats = useMemo(() => {
    if (!submissions.length) return { total: 0, graded: 0, pending: 0 };
    return {
      total: submissions.length,
      graded: submissions.filter((s: Submission) => s.grade !== null).length,
      pending: submissions.filter((s: Submission) => s.grade === null).length
    };
  }, [submissions]);

  return (
    <div className="space-y-10 pb-20 text-start">
      <ListView>
        <div className="space-y-10">
          <motion.div 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-4"
          >
            <Breadcrumb />
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div>
                <h1 className="text-4xl font-black tracking-tight">{t("resources.submissions.label")}</h1>
                <p className="text-muted-foreground font-medium mt-1">{t("dashboard.staff.pendingGrading")}</p>
              </div>
            </div>
          </motion.div>

          {/* Stats Row */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <Card className="p-6 border-primary/10 bg-card/50 backdrop-blur-sm flex items-center gap-4 rounded-4xl shadow-lg shadow-primary/5">
              <div className="p-3 rounded-2xl bg-primary/10 text-primary">
                <FileText className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("notifications.stats.total")}</p>
                <p className="text-2xl font-black">{isLoading ? "..." : new Intl.NumberFormat(i18n.language).format(stats.total)}</p>
              </div>
            </Card>
            <Card className="p-6 border-green-500/10 bg-card/50 backdrop-blur-sm flex items-center gap-4 rounded-4xl shadow-lg shadow-green-500/5">
              <div className="p-3 rounded-2xl bg-green-500/10 text-green-600">
                <CheckSquare className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("status.completed")}</p>
                <p className="text-2xl font-black text-green-600">{isLoading ? "..." : new Intl.NumberFormat(i18n.language).format(stats.graded)}</p>
              </div>
            </Card>
            <Card className="p-6 border-amber-500/10 bg-card/50 backdrop-blur-sm flex items-center gap-4 rounded-4xl shadow-lg shadow-amber-500/5">
              <div className="p-3 rounded-2xl bg-amber-500/10 text-amber-600">
                <Activity className="h-6 w-6" />
              </div>
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("assignments.list.table.pending")}</p>
                <p className="text-2xl font-black text-amber-600">{isLoading ? "..." : new Intl.NumberFormat(i18n.language).format(stats.pending)}</p>
              </div>
            </Card>
          </div>
          
          {/* Filters & Search */}
          <Card className="p-4 border-primary/5 bg-muted/30 rounded-4xl backdrop-blur-sm">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="relative flex-1 group">
                <Search className={cn("absolute top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground group-focus-within:text-primary transition-colors", "start-4")} />
                <Input
                  type="text"
                  placeholder={t("assignments.list.filters.searchPlaceholder")}
                  className={cn("h-14 rounded-2xl border-none bg-background shadow-sm font-medium", isAr ? "pe-11" : "ps-11")}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2 bg-background px-4 rounded-2xl shadow-sm border border-primary/5">
                <Filter className="h-4 w-4 text-muted-foreground" />
                <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("notifications.filters.label")}</span>
              </div>
            </div>
          </Card>

          <AnimatePresence>
            {selectedTerm?.status === "archived" && (
              <motion.div 
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="bg-amber-500/10 border border-amber-500/20 text-amber-700 p-6 rounded-4xl shadow-sm flex items-start gap-4 backdrop-blur-sm"
              >
                  <div className="p-3 rounded-2xl bg-amber-500/20">
                    <AlertCircle className="h-6 w-6" />
                  </div>
                  <div className="space-y-1">
                    <p className="font-black uppercase tracking-widest text-xs">{t("dashboard.archiveViewActive")}</p>
                    <p className="text-sm font-medium">{t("dashboard.archiveViewDescription", { termName: selectedTerm.name })}</p>
                  </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Virtualized List Container */}
          <div 
            ref={parentRef} 
            className="h-150 overflow-auto pe-2 custom-scrollbar rounded-[2.5rem] border border-primary/5 bg-card/30 backdrop-blur-sm relative"
          >
            {isLoading ? (
              <div className="p-8 space-y-6">
                {Array.from({ length: 6 }).map((_, i: any) => (
                  <div key={i} className="flex flex-col md:flex-row items-center gap-6">
                    <Skeleton className="h-14 w-14 rounded-2xl shrink-0" />
                    <div className="flex-1 space-y-3 w-full">
                      <Skeleton className="h-6 w-62.5" />
                      <Skeleton className="h-4 w-45" />
                    </div>
                    <Skeleton className="h-10 w-24 rounded-xl" />
                  </div>
                ))}
              </div>
            ) : !hasData ? (
              <div className="h-full w-full flex items-center justify-center p-12">
                <EmptyState
                  icon={FileText}
                  title={t("assignments.list.noAssignments")}
                  description={t("assignments.list.noAssignmentsDescriptionTeacher")}
                  className="border-none bg-transparent min-h-0"
                />
              </div>
            ) : (
              <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, width: '100%', position: 'relative' }}>
                {rowVirtualizer.getVirtualItems().map((virtualItem: any) => {
                  const submission = submissions[virtualItem.index];
                  const submissionDate = dayjs(submission.updatedAt);
                  const isGraded = submission.grade !== null;
                  
                  return (
                    <motion.div
                      key={virtualItem.key}
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ duration: 0.2 }}
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: `${virtualItem.size}px`,
                        transform: `translateY(${virtualItem.start}px)`,
                      }}
                      className="flex flex-col md:flex-row items-center px-8 py-6 border-b border-primary/5 hover:bg-primary/2 transition-all group cursor-pointer"
                      onClick={() => handleGradeClick(submission)}
                    >
                      {/* Student Avatar */}
                      <div className="relative shrink-0 mb-4 md:mb-0">
                        <Avatar className="h-16 w-16 rounded-2xl border-4 border-background shadow-lg group-hover:scale-110 transition-transform">
                          <AvatarImage src={submission.student?.image ?? undefined} className="object-cover" />
                          <AvatarFallback className="bg-primary/5 text-primary font-black text-xl">
                            {submission.student?.name[0]}
                          </AvatarFallback>
                        </Avatar>
                        {submission.isLate && (
                          <div className={cn("absolute -top-2 bg-destructive text-white p-1 rounded-lg border-2 border-background shadow-lg", isAr ? "-start-2" : "-end-2")}>
                            <Timer className="h-3 w-3" />
                          </div>
                        )}
                      </div>

                      {/* Info */}
                      <div className={cn("flex-1 text-center min-w-0 w-full", isAr ? "md:me-8 md:text-end" : "md:ms-8 md:text-start")}>
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4">
                          <h3 className="text-xl font-black tracking-tight truncate group-hover:text-primary transition-colors">
                            {submission.student?.name}
                          </h3>
                          <div className="flex items-center justify-center md:justify-start gap-2">
                            <Badge 
                                variant={isGraded ? 'default' : 'secondary'}
                                className={cn(
                                    "text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border-none",
                                    isGraded ? "bg-green-500/10 text-green-600" : "bg-amber-500/10 text-amber-600"
                                )}
                            >
                                {isGraded ? t("status.completed") : t("assignments.list.table.pending")}
                            </Badge>
                            {submission.isLate && (
                                <Badge variant="destructive" className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md">
                                    {t("assignments.list.table.late")}
                                </Badge>
                            )}
                          </div>
                        </div>
                        
                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-x-6 gap-y-2 mt-3">
                          <div className="flex items-center gap-2 text-muted-foreground">
                            <div className="p-1.5 rounded-lg bg-primary/5">
                                <FileText className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <span className="text-xs font-bold truncate max-w-50">
                                {submission.assignment?.title}
                            </span>
                          </div>

                          <div className="flex items-center gap-2 text-muted-foreground">
                            <div className="p-1.5 rounded-lg bg-primary/5">
                                <LayoutGrid className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <span className="text-xs font-bold">
                                {submission.assignment?.class?.name}
                            </span>
                          </div>

                          <div className="flex items-center gap-2 text-muted-foreground">
                            <div className="p-1.5 rounded-lg bg-primary/5">
                                <Clock className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <span className="text-xs font-bold uppercase tracking-tight">
                                {submissionDate.locale(i18n.language).fromNow()}
                            </span>
                          </div>
                        </div>
                      </div>

                      {/* Actions */}
                      <div className={cn("flex items-center gap-3 mt-6 md:mt-0 shrink-0", "ms-4")}>
                        <div className={cn("flex flex-col", isAr ? "items-start ms-4" : "items-end me-4")}>
                            <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground/40">{t("assignments.grading.finalScore")}</p>
                            <p className={cn(
                                "text-2xl font-black",
                                isGraded ? "text-primary" : "text-muted-foreground/20"
                            )}>
                                {isGraded ? `${new Intl.NumberFormat(i18n.language).format(submission.grade!)}%` : '--'}
                            </p>
                        </div>

                        <Button
                          variant={isGraded ? "outline" : "default"}
                          className={cn(
                            "rounded-2xl px-8 h-12 text-[10px] font-black uppercase tracking-widest transition-all shadow-sm",
                            isGraded ?
                              "border-primary/10 text-primary hover:bg-primary hover:text-primary-foreground" :
                              "bg-primary hover:bg-primary/90 text-white shadow-lg shadow-primary/20",
                          )}
                          onClick={() => handleGradeClick(submission)}
                        >
                          {isGraded ? t("buttons.reviewProof") : t("buttons.grade")}
                          <ArrowRight className={cn("h-4 w-4 ms-2", isAr && "rotate-180")} />
                        </Button>

                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon" className="h-10 w-10 rounded-xl md:hidden lg:flex" onClick={(e) => e.stopPropagation()}>
                                    <MoreHorizontal className="h-5 w-5" />
                                </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end" className="w-56 rounded-[1.5rem] p-2 bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                                <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-widest text-muted-foreground px-3 py-2">{t("assignments.list.labels.options")}</DropdownMenuLabel>
                                <DropdownMenuItem onClick={() => handleGradeClick(submission)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                    <Eye className="h-4 w-4 text-primary" />
                                    <span className="font-bold">{t("buttons.show")}</span>
                                </DropdownMenuItem>
                                {!isGraded && (
                                    <DropdownMenuItem onClick={() => handleGradeClick(submission)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                        <BrainCircuit className="h-4 w-4 text-primary" />
                                        <span className="font-bold">{t("buttons.aiAssist")}</span>
                                    </DropdownMenuItem>
                                )}
                                <DropdownMenuSeparator className="my-2" />
                                {submission.student && (
                                    <DropdownMenuItem onClick={() => show("users", submission.student!.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                        <User className="h-4 w-4 text-primary" />
                                        <span className="font-bold">{t("buttons.viewProfile")}</span>
                                    </DropdownMenuItem>
                                )}
                            </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </motion.div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </ListView>

      {isStaff && (
        <GradingDialog
            isOpen={isGradingOpen}
            onOpenChange={setIsGradingOpen}
            submission={selectedSubmission}
            readOnly={selectedTerm?.status === "archived"}
        />
      )}
    </div>
  );
};

export default SubmissionsListPage;

import { useShow, useUpdate, useGetIdentity, useCustomMutation } from "@refinedev/core";
import { useParams, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import { ShowView } from "@/components/refine-ui/views/show-view";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { 
  Loader2, 
  FileText, 
  Calendar, 
  AlertCircle,
  ArrowLeft,
  Save,
  Wand2,
  Sparkles
} from "lucide-react";
import { Submission, User as UserType, Assignment } from "@/types";
import { toast } from "sonner";
import ReactMarkdown from "react-markdown";
import { useTranslation } from "react-i18next";
import { cn } from "@/lib/utils";
import dayjs from "dayjs";
import { useDashboard } from "@/features/dashboard/hooks/use-dashboard";

const SubmissionShow = () => {
  const { t, i18n } = useTranslation();
  const { coreData } = useDashboard();
  const isAr = i18n.language === 'ar';
  const { id } = useParams();
  const navigate = useNavigate();
  const { data: identity } = useGetIdentity<UserType>();
  
  const [grade, setGrade] = useState<number>(0);
  const [feedback, setFeedback] = useState("");
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const { query: submissionQuery } = useShow<Submission & { assignment?: Assignment }>({
    resource: "submissions",
    id,
  });

  const submission = submissionQuery.data?.data;

  const { mutate: updateSubmission, mutation: updateMutationObj } = useUpdate();
  const { mutate: aiGrade } = useCustomMutation();

  // Sync local state with fetched data
  useEffect(() => {
    if (submission) {
      setGrade(submission.grade ?? submission.suggestedGrade ?? 0);
      setFeedback(submission.feedback ?? submission.suggestedFeedback ?? "");
    }
  }, [submission]);

  const handleSaveGrade = () => {
    updateSubmission({
      resource: "submissions",
      id: id!,
      values: {
        grade,
        feedback,
      },
    }, {
      onSuccess: () => {
        toast.success(t("assignments.grading.gradeSaved"));
        navigate(-1);
      }
    });
  };

  const handleAiAnalyze = () => {
    setIsAnalyzing(true);
    aiGrade({
        url: `/submissions/${id}/ai-grade`,
        method: "post",
        values: {}
    }, {
        onSuccess: (data: any) => {
            const result = data.data;
            setGrade(result.suggestedGrade);
            setFeedback(result.feedback);
            setIsAnalyzing(false);
            toast.success(t("assignments.grading.toasts.aiComplete"));
        },
        onError: () => {
            setIsAnalyzing(false);
            toast.error(t("common.aiServiceError"));
        }
    });
  };

  if (submissionQuery.isPending) {
    return (
      <div className="flex justify-center items-center h-screen">
        <Loader2 className="h-12 w-12 animate-spin text-primary" />
      </div>
    );
  }

  if (!submission) return <div className="p-20 text-center font-bold">{t("assignments.show.notFound")}</div>;

  return (
    <ShowView>
      <div className="max-w-5xl mx-auto space-y-8 text-start">
        {/* Header */}
        <div className="flex items-center justify-between">
            <Button variant="ghost" onClick={() => navigate(-1)} className="gap-2">
                <ArrowLeft className={cn("h-4 w-4", isAr && "rotate-180")} />
                {t("buttons.back")}
            </Button>
            <div className="flex items-center gap-3">
                {submission.aiApprovalStatus === "pending" && (
                    <Badge className="bg-ai-primary/10 text-ai-primary border-ai-primary/20 px-4 py-1 rounded-full font-black uppercase tracking-widest text-[10px] animate-pulse">
                        <Sparkles className="h-3 w-3 me-1.5" />
                        {t("assignments.grading.proposedAI")}
                    </Badge>
                )}
                {submission.grade !== null ? (
                    <Badge className="bg-success text-success-foreground px-4 py-1 rounded-full font-black uppercase tracking-widest text-[10px]">
                        {t("status.completed")}
                    </Badge>
                ) : (
                    <Badge variant="outline" className="px-4 py-1 rounded-full font-black uppercase tracking-widest text-[10px]">
                        {t("assignments.list.table.pending")}
                    </Badge>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left: Student Work */}
            <div className="lg:col-span-2 space-y-6">
                <Card className="border-none shadow-xl overflow-hidden">
                    <CardHeader className="bg-muted/30 border-b">
                        <div className="flex items-center gap-4">
                            <Avatar className="h-12 w-12 border-2 border-background shadow-sm">
                                <AvatarImage src={submission.student?.image || ""} />
                                <AvatarFallback>{submission.student?.name?.[0]}</AvatarFallback>
                            </Avatar>
                            <div>
                                <CardTitle className="text-xl font-black">{submission.student?.name}</CardTitle>
                                <CardDescription className="flex items-center gap-2">
                                    <FileText className="h-3 w-3" />
                                    {submission.assignment?.title}
                                </CardDescription>
                            </div>
                        </div>
                    </CardHeader>
                    <CardContent className="pt-8">
                        <div className="prose prose-sm dark:prose-invert max-w-none bg-muted/10 p-6 rounded-2xl border border-dashed">
                            <ReactMarkdown>{submission.content || t("assignments.grading.noContent")}</ReactMarkdown>
                        </div>
                    </CardContent>
                    <CardFooter className="bg-muted/10 border-t py-4 flex justify-between text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
                        <div className="flex items-center gap-1">
                            <Calendar className="h-3 w-3" />
                            {t("assignments.show.submittedContent")}: {dayjs(submission.createdAt).locale(i18n.language).format("LLL")}
                        </div>
                        {submission.isLate && (
                            <div className="flex items-center gap-1 text-destructive">
                                <AlertCircle className="h-3 w-3" />
                                {t("assignments.list.table.late")}
                            </div>
                        )}
                    </CardFooter>
                </Card>
            </div>

            {/* Right: Grading Panel */}
            <div className="space-y-6">
                <Card className="border-primary/10 shadow-2xl sticky top-24 overflow-hidden">
                    <div className="h-1.5 bg-primary w-full" />
                    <CardHeader>
                        <CardTitle className="text-sm font-black uppercase tracking-widest flex items-center justify-between">
                            {t("assignments.grading.gradeSubmission")}
                            {coreData?.globalConfig?.enableAiFeatures !== false && (
                                <Button 
                                    variant="outline" 
                                    size="sm" 
                                    onClick={handleAiAnalyze}
                                    disabled={isAnalyzing}
                                    className="h-7 text-[10px] gap-1.5 border-ai-primary/20 text-ai-primary hover:bg-ai-primary/5"
                                >
                                    {isAnalyzing ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />}
                                    {t("buttons.aiAssist")}
                                </Button>
                            )}
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-6">
                        <div className="space-y-2">
                            <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("assignments.grading.finalScore")}</Label>
                            <div className="relative">
                                <Input 
                                    type="number" 
                                    value={grade} 
                                    onChange={(e) => setGrade(Number(e.target.value))}
                                    className="h-14 text-3xl font-black text-center rounded-xl bg-muted/20 border-none"
                                    min={0}
                                    max={100}
                                />
                                <div className={cn("absolute top-1/2 -translate-y-1/2 text-xl font-black text-muted-foreground/30", "end-4")}>%</div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <Label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{t("assignments.grading.feedbackToStudent")}</Label>
                            <Textarea 
                                value={feedback}
                                onChange={(e) => setFeedback(e.target.value)}
                                placeholder={t("assignments.grading.feedbackPlaceholder")}
                                className="min-h-[200px] rounded-xl resize-none bg-muted/10 border-none p-4 text-sm leading-relaxed"
                            />
                        </div>

                        {(submission.suggestedGrade !== undefined && submission.suggestedGrade !== null && !submission.grade) && (
                            <div className="p-5 bg-ai-primary/5 rounded-2xl border-2 border-ai-primary/20 space-y-4 animate-in fade-in zoom-in duration-500">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-ai-primary">
                                        <Sparkles className="h-3 w-3" />
                                        {t("assignments.grading.aiSuggestion")}
                                    </div>
                                    <Badge className="bg-ai-primary text-white text-[10px] font-black">{submission.suggestedGrade}%</Badge>
                                </div>
                                <p className="text-xs text-muted-foreground leading-relaxed italic line-clamp-3">
                                    "{submission.suggestedFeedback}"
                                </p>
                                <Button 
                                    size="sm" 
                                    variant="outline"
                                    className="w-full h-9 text-[10px] font-black uppercase tracking-widest gap-2 border-ai-primary/20 text-ai-primary hover:bg-ai-primary hover:text-white transition-all rounded-lg"
                                    onClick={() => {
                                        setGrade(submission.suggestedGrade!);
                                        setFeedback(submission.suggestedFeedback || "");
                                    }}
                                >
                                    <Wand2 className="h-3 w-3" />
                                    {t("assignments.grading.applyAI")}
                                </Button>
                            </div>
                        )}
                    </CardContent>
                    <CardFooter className="border-t bg-muted/5 pt-6">
                        <Button 
                            onClick={handleSaveGrade} 
                            disabled={updateMutationObj.isPending}
                            className="w-full h-12 rounded-xl font-black uppercase tracking-widest shadow-lg shadow-primary/20"
                        >
                            {updateMutationObj.isPending ? <Loader2 className="me-2 h-4 w-4 animate-spin" /> : <Save className="me-2 h-4 w-4" />}
                            {t("buttons.saveGrade")}
                        </Button>
                    </CardFooter>
                </Card>
            </div>
        </div>
      </div>
    </ShowView>
  );
};

export default SubmissionShow;

import { ListView } from "@/components/refine-ui/views/list-view.tsx";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb.tsx";
import { 
  CheckCircle2, 
  XCircle, 
  Filter, 
  MoreHorizontal, 
  Eye, 
  Mail, 
  LayoutGrid, 
  Loader2,
  Clock,
  MessageSquare,
  Briefcase,
  Layers
} from "lucide-react";
import { useMemo, useState, useRef } from "react";
import { useList, useNavigation, useGetIdentity, useCustomMutation, useInvalidate } from "@refinedev/core";
import { TeacherApplication, User, UserRole } from "@/types";
import { Badge } from "@/components/ui/badge.tsx";
import { Button } from "@/components/ui/button.tsx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Card } from "@/components/ui/card";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import usePageTitle from "@/hooks/use-page-title";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/empty-state";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslation } from "react-i18next";

dayjs.extend(relativeTime);

const TeacherApplicationsList = () => {
  const { t, i18n } = useTranslation();
  usePageTitle(t("teacherApps.title"));
  const { data: identity } = useGetIdentity<User>();
  const isAdmin = identity?.role === UserRole.ADMIN;
  
  const { show } = useNavigation();
  const { mutate: updateStatus, mutation: updateMutationObj } = useCustomMutation();
  const invalidate = useInvalidate();

  const isUpdating = updateMutationObj.isPending;

  const [statusFilter, setStatusFilter] = useState<string>("pending");

  const filters = useMemo(() => {
    const f = [];
    if (statusFilter !== "all") {
        f.push({ field: "status", operator: "eq" as const, value: statusFilter });
    }
    return f;
  }, [statusFilter]);

  const { query } = useList<TeacherApplication>({
    resource: "teacher-applications",
    pagination: { pageSize: 50, mode: "server" }, // Reduced page size for global scroll
    filters,
    sorters: [{ field: "id", order: "desc" }],
  });

  const applications = query.data?.data || [];
  const isLoading = query.isLoading;
  const hasData = applications.length > 0;

  const handleStatusUpdate = (id: number, status: "approved" | "rejected") => {
    updateStatus({
        url: `/teacher-applications/${id}/status`,
        method: "patch",
        values: { status },
    }, {
        onSuccess: () => {
            toast.success(t("teacherApps.toasts.statusUpdate", { status }));
            invalidate({ resource: "teacher-applications", invalidates: ["list"] });
            invalidate({ resource: "classes", invalidates: ["list"] });
        }
    });
  };

  return (
    <ListView>
      <div className="space-y-8 md:space-y-12">
        {/* Header Section */}
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6"
        >
          <div className="space-y-4 flex-1">
            <Breadcrumb />
            <div className="space-y-1">
              <h1 className="page-title mb-0 flex items-center gap-3">
                <div className="p-3 rounded-2xl bg-primary/10 text-primary border border-primary/5 shadow-sm">
                  <Briefcase className="h-6 w-6 md:h-8 md:w-8" />
                </div>
                {t("teacherApps.title")}
              </h1>
              <p className="text-muted-foreground font-medium max-w-2xl text-balance">
                {t("teacherApps.description")}
              </p>
            </div>
          </div>
        </motion.div>

        {/* Filters - Sticky */}
        <Card className="p-2 border-border/40 bg-muted/20 rounded-[1.75rem] md:rounded-3xl backdrop-blur-md sticky top-20 z-30 shadow-sm">
          <div className="flex items-center gap-2 bg-background/50 px-3 py-1 rounded-2xl border border-border/40">
            <Filter className="h-3.5 w-3.5 text-muted-foreground/60" />
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-[160px] border-none h-10 focus:ring-0 shadow-none font-bold text-[10px] uppercase tracking-wider bg-transparent">
                <SelectValue placeholder={t("enrollments.allStatus")} />
              </SelectTrigger>
              <SelectContent className="rounded-2xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                <SelectItem value="all" className="font-bold">{t("enrollments.allStatus")}</SelectItem>
                <SelectItem value="pending" className="font-bold">{t("status.upcoming")}</SelectItem>
                <SelectItem value="approved" className="font-bold">{t("status.active")}</SelectItem>
                <SelectItem value="rejected" className="font-bold">{t("buttons.reject")}</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </Card>

        {/* List Container */}
        <div className="relative min-h-[400px]">
          {isLoading ? (
            <div className="space-y-4">
              {Array.from({ length: 5 }).map((_, i: any) => (
                <Card key={i} className="p-6 flex flex-col md:flex-row items-center gap-6 border-border/20 bg-background/50">
                  <Skeleton className="h-20 w-20 rounded-3xl shrink-0" />
                  <div className="flex-1 space-y-4 w-full">
                    <Skeleton className="h-8 w-[350px] max-w-full" />
                    <div className="flex gap-4">
                       <Skeleton className="h-4 w-24" />
                       <Skeleton className="h-4 w-24" />
                    </div>
                  </div>
                  <Skeleton className="h-12 w-36 rounded-2xl" />
                </Card>
              ))}
            </div>
          ) : !hasData ? (
            <div className="flex items-center justify-center p-16 bg-card/20 rounded-[2.5rem] border border-dashed border-border/40">
              <EmptyState
                icon={Layers}
                title={t("teacherApps.empty.title")}
                description={t("teacherApps.empty.desc")}
                className="border-none bg-transparent min-h-0"
              />
            </div>
          ) : (
            <div className="space-y-4">
              <AnimatePresence mode="popLayout">
                {applications.map((app: any, index: any) => {
                  const appDate = dayjs(app.createdAt);
                  
                  return (
                    <motion.div
                      key={app.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      transition={{ delay: index * 0.05 }}
                      className={cn(
                        "group relative flex flex-col md:flex-row items-center p-5 md:p-6 rounded-4xl bg-card/50 backdrop-blur-sm border border-border/40 hover:border-primary/30 hover:bg-card/80 transition-all duration-300 shadow-sm hover:shadow-xl hover:shadow-primary/5"
                      )}
                    >
                      {/* Status Color Accent */}
                      <div 
                        className={cn(
                          "absolute start-0 top-1/2 -translate-y-1/2 w-1.5 h-12 rounded-e-full transition-all group-hover:h-20",
                          app.status === 'approved' ? 'bg-green-500' : app.status === 'pending' ? 'bg-amber-500' : 'bg-destructive'
                        )}
                      />

                      {/* Avatar */}
                      <div className="relative shrink-0 mb-4 md:mb-0">
                        <Avatar className="h-20 w-20 rounded-[1.5rem] border-4 border-background shadow-lg group-hover:scale-105 transition-transform duration-500">
                          <AvatarImage src={app.teacher?.image ?? undefined} className="object-cover" />
                          <AvatarFallback className="bg-primary/10 text-primary font-black text-xl">
                            {app.teacher?.name?.[0]}
                          </AvatarFallback>
                        </Avatar>
                      </div>

                      {/* Info */}
                      <div className={cn("flex-1 min-w-0 w-full", i18n.language === 'ar' ? "md:me-8 md:text-end" : "md:ms-8 md:text-start")}>
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 mb-2">
                          <h3 className="text-xl md:text-2xl font-black tracking-tight truncate group-hover:text-primary transition-colors leading-tight">
                            {app.teacher?.name}
                          </h3>
                          <div className="flex items-center justify-center md:justify-start gap-2">
                            <Badge 
                                variant={app.status === 'approved' ? 'default' : app.status === 'pending' ? 'secondary' : 'destructive'}
                                className={cn(
                                    "text-[9px] font-black uppercase tracking-widest px-2.5 py-0.5 rounded-full shadow-sm",
                                    app.status === 'pending' && "bg-amber-500/10 text-amber-600 border border-amber-500/20"
                                )}
                            >
                                {app.status}
                            </Badge>
                            <Badge variant="ai" className="text-[9px] font-black uppercase tracking-widest px-2.5 py-0.5 rounded-full shadow-sm">
                                {t("teacherApps.labels.applyingFor", { name: app.class?.name })}
                            </Badge>
                          </div>
                        </div>
                        
                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 md:gap-6 mt-4">
                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <Mail className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Email</span>
                                <span className="text-[11px] font-black text-foreground truncate max-w-[150px]">{app.teacher?.email}</span>
                            </div>
                          </div>

                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                <Clock className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Applied</span>
                                <span className="text-[11px] font-black text-foreground uppercase tracking-tight">
                                    {appDate.fromNow()}
                                </span>
                            </div>
                          </div>
                          {app.message && (
                              <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                                  <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                                      <MessageSquare className="h-3.5 w-3.5 text-primary" />
                                  </div>
                                  <div className="flex flex-col">
                                      <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Message</span>
                                      <span className="text-[11px] font-black text-foreground truncate max-w-[150px]">"{app.message}"</span>
                                  </div>
                              </div>
                          )}
                        </div>
                      </div>

                      {/* Action Area */}
                      <div className="flex items-center gap-3 mt-6 md:mt-0 shrink-0">
                        {app.status === 'pending' && isAdmin && (
                              <div className="flex items-center gap-2">
                                  <Button
                                      variant="outline"
                                      size="lg"
                                      className="w-full md:w-auto rounded-2xl px-8 h-12 font-black uppercase tracking-widest text-[10px] border-green-500/20 text-green-600 bg-green-500/5 hover:bg-green-500/10 shadow-sm"
                                      onClick={() => handleStatusUpdate(app.id, "approved")}
                                      disabled={isUpdating}
                                  >
                                      <CheckCircle2 className="h-4 w-4 me-2" />
                                      {t("buttons.approve")}
                                  </Button>
                                  <Button
                                      variant="outline"
                                      size="lg"
                                      className="w-full md:w-auto rounded-2xl px-8 h-12 font-black uppercase tracking-widest text-[10px] border-destructive/20 text-destructive bg-destructive/5 hover:bg-destructive/10 shadow-sm"
                                      onClick={() => handleStatusUpdate(app.id, "rejected")}
                                      disabled={isUpdating}
                                  >
                                      <XCircle className="h-4 w-4 me-2" />
                                      {t("buttons.reject")}
                                  </Button>
                              </div>
                          )}

                          <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                  <Button variant="ghost" size="icon" className="h-12 w-12 rounded-2xl bg-muted/30 hover:bg-muted/50">
                                      <MoreHorizontal className="h-5 w-5" />
                                  </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end" className="w-64 p-2 rounded-3xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                                  <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-[0.15em] text-muted-foreground/40 px-3 py-3">{t("assignments.list.labels.options")}</DropdownMenuLabel>
                                  <DropdownMenuItem onClick={() => show("users", app.teacher.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                      <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                          <Eye className="h-4 w-4" />
                                      </div>
                                      <span className="font-bold">{t("teacherApps.labels.viewTeacher")}</span>
                                  </DropdownMenuItem>
                                  <DropdownMenuItem onClick={() => show("classes", app.class.id)} className="rounded-xl gap-3 py-3 cursor-pointer">
                                      <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                          <LayoutGrid className="h-4 w-4" />
                                      </div>
                                      <span className="font-bold">{t("teacherApps.labels.viewClass")}</span>
                                  </DropdownMenuItem>
                              </DropdownMenuContent>
                          </DropdownMenu>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
          )}
        </div>
      </div>
    </ListView>
  );
};

export default TeacherApplicationsList;

import React, { useEffect, useState } from "react";
import {
  useGetIdentity,
  useCustom,
  useCustomMutation,
  useInvalidate,
} from "@refinedev/core";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Tv,
  Eye,
  BarChart3,
  Loader2,
  AlertCircle,
  LayoutDashboard,
  Sparkles,
  ArrowRight,
  Radio,
  Video,
  Image as ImageIcon,
  Save,
} from "lucide-react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { FileUpload } from "@/components/file-upload";
import { toast } from "sonner";
import { User, TeacherChannel } from "@/types";
import { useTranslation } from "react-i18next";
import { motion, AnimatePresence } from "framer-motion";
import { Badge } from "@/components/ui/badge";
import usePageTitle from "@/hooks/use-page-title";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb";
import { cn } from "@/lib/utils";

const channelSchema = z.object({
  headline: z.string().min(5, "Headline must be at least 5 characters"),
  bio: z.string().min(20, "Bio must be at least 20 characters"),
  trailerVideoUrl: z.string().url().optional().nullable(),
  trailerVideoCldPubId: z.string().optional().nullable(),
  thumbnailUrl: z.string().url().optional().nullable(),
  thumbnailCldPubId: z.string().optional().nullable(),
});

type ChannelFormValues = z.infer<typeof channelSchema>;
const TeacherChannelPage = () => {
  const { t } = useTranslation();
  usePageTitle(t("teacherChannel.title" as any));
  const { data: identity } = useGetIdentity<User>();
  const invalidate = useInvalidate();
  const [isPreviewHovered, setIsPreviewHovered] = useState(false);

  // Refine v5 useCustom returns an object containing 'query'
  const { query } = useCustom<TeacherChannel>({
    url: `/channels/teacher/${identity?.id}`,
    method: "get",
    queryOptions: {
      enabled: !!identity?.id,
      retry: false
    }
  });

  const channelData = query.data;
  const isLoading = query.isPending;

  const { mutate: upsertChannel, mutation: upsertMutation } =
    useCustomMutation();

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    formState: { errors, isDirty },
  } = useForm<ChannelFormValues>({
    resolver: zodResolver(channelSchema),
    defaultValues: {
      headline: "",
      bio: "",
    },
  });

  const watchedValues = watch();

  useEffect(() => {
    if (channelData?.data) {
      reset({
        headline: channelData.data.headline,
        bio: channelData.data.bio,
        trailerVideoUrl: channelData.data.trailerVideoUrl,
        trailerVideoCldPubId: channelData.data.trailerVideoCldPubId,
        thumbnailUrl: channelData.data.thumbnailUrl,
        thumbnailCldPubId: channelData.data.thumbnailCldPubId,
      });
    }
  }, [channelData, reset]);

  const onFinish = (values: ChannelFormValues) => {
    upsertChannel(
      {
        url: "/channels",
        method: "post",
        values,
      },
      {
        onSuccess: () => {
          toast.success(t("teacherChannel.toasts.success"));
          invalidate({
            resource: "teacher-channel",
            invalidates: ["list", "detail"],
          });
        },
        onError: () => {
          toast.error(t("teacherChannel.toasts.error"));
        },
      },
    );
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center h-[85vh] gap-8">
        <motion.div
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          className="relative"
        >
          <div className="absolute inset-[-20px] rounded-full bg-primary/5 animate-ping duration-[3000ms]" />
          <Loader2 className="h-20 w-20 animate-spin text-primary/10 stroke-[1]" />
          <div className="absolute inset-0 flex items-center justify-center">
            <Tv className="h-8 w-8 text-primary/30" />
          </div>
        </motion.div>
        <div className="text-center space-y-2">
          <h2 className="text-sm font-black uppercase tracking-[0.3em] text-primary/60 animate-pulse">
            {t("profile.loading")}
          </h2>
          <p className="text-xs font-medium text-muted-foreground/60 italic">
            Preparing your broadcasting studio...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="container-center section-wrapper !pt-10">
      <div className="noise-overlay" />

      {/* Cinematic Header */}
      <motion.header
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col lg:flex-row lg:items-center justify-between gap-12 mb-16 relative z-10"
      >
        <div className="space-y-6 flex-1 text-start">
          <Breadcrumb />
          <div className="flex items-center gap-6">
            <div className="relative">
              <div className="absolute -inset-4 bg-primary/20 blur-2xl rounded-full animate-pulse" />
              <div className="relative p-5 rounded-3xl bg-primary text-white shadow-2xl">
                <Radio className="h-8 w-8 animate-pulse" />
              </div>
            </div>
            <div>
              <h1 className="text-4xl md:text-6xl font-black tracking-tighter uppercase text-gradient mb-2">
                Studio <span className="text-primary/40">Center</span>
              </h1>
              <p className="text-muted-foreground font-medium max-w-xl text-lg">
                Design your personal "Promotion Channel" to attract students and
                showcase your teaching style.
              </p>
            </div>
          </div>
        </div>

        {channelData?.data && (
          <div className="flex items-center gap-8 glass-card p-8 rounded-[2.5rem] min-w-[320px]">
            <div className="flex-1 text-center">
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground/60 mb-2">
                Broadcast Views
              </p>
              <p className="text-3xl font-black tracking-tighter">
                {channelData.data.totalViews.toLocaleString()}
              </p>
            </div>
            <div className="h-16 w-px bg-border/40" />
            <div className="flex-1 text-center">
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground/60 mb-2">
                Conversion
              </p>
              <p className="text-3xl font-black text-primary tracking-tighter">
                {(channelData.data.conversionRate * 100).toFixed(1)}%
              </p>
            </div>
          </div>
        )}
      </motion.header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20 items-start relative z-10">
        {/* Configuration Form */}
        <div className="lg:col-span-7 space-y-12">
          <div className="space-y-12">
            <form onSubmit={handleSubmit(onFinish)} className="space-y-16">
              <div className="space-y-6 text-start">
                <Label className="text-[11px] font-black uppercase tracking-[0.4em] text-primary ms-2">
                  Promotional Headline
                </Label>
                <Input
                  {...register("headline")}
                  placeholder="e.g. Master Modern Physics with AI"
                  className="h-20 rounded-4xl bg-muted/20 border-none shadow-inner px-10 text-xl md:text-3xl font-black placeholder:text-muted-foreground/20 focus-visible:ring-primary/20 transition-all"
                />
                {errors.headline && (
                  <p className="text-xs text-destructive font-bold flex items-center gap-2 ms-4">
                    <AlertCircle className="h-4 w-4" />
                    {errors.headline.message}
                  </p>
                )}
              </div>

              <div className="space-y-6 text-start">
                <Label className="text-[11px] font-black uppercase tracking-[0.4em] text-primary ms-2">
                  Channel Biography
                </Label>
                <Textarea
                  {...register("bio")}
                  placeholder="Tell your story. What makes your teaching unique?"
                  className="min-h-60 md:min-h-80 rounded-[3rem] bg-muted/20 border-none shadow-inner text-lg md:text-xl font-medium p-10 resize-none focus-visible:ring-primary/20 leading-relaxed italic"
                />
                {errors.bio && (
                  <p className="text-xs text-destructive font-bold flex items-center gap-2 ms-4">
                    <AlertCircle className="h-4 w-4" />
                    {errors.bio.message}
                  </p>
                )}
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-10">
                <div className="space-y-6 text-start">
                  <Label className="text-[11px] font-black uppercase tracking-[0.4em] text-primary ms-2">
                    Video Trailer
                  </Label>
                  <div className="p-1 rounded-[2.5rem] bg-muted/20 shadow-inner group hover:bg-muted/30 transition-colors">
                    <FileUpload
                      folder="trailers"
                      accept="video/mp4,video/quicktime"
                      maxSize={100 * 1024 * 1024}
                      label="Upload Trailer"
                      onUploadSuccess={(url, publicId) => {
                        setValue("trailerVideoUrl", url, { shouldDirty: true });
                        setValue("trailerVideoCldPubId", publicId, {
                          shouldDirty: true,
                        });
                      }}
                    />
                  </div>
                </div>

                <div className="space-y-6 text-start">
                  <Label className="text-[11px] font-black uppercase tracking-[0.4em] text-primary ms-2">
                    Cover Thumbnail
                  </Label>
                  <div className="p-1 rounded-[2.5rem] bg-muted/20 shadow-inner group hover:bg-muted/30 transition-colors">
                    <FileUpload
                      folder="thumbnails"
                      accept="image/*"
                      onUploadSuccess={(url, publicId) => {
                        setValue("thumbnailUrl", url, { shouldDirty: true });
                        setValue("thumbnailCldPubId", publicId, {
                          shouldDirty: true,
                        });
                      }}
                    />
                  </div>
                </div>
              </div>

              <div className="pt-12 border-t border-border/40">
                <Button
                  type="submit"
                  size="lg"
                  disabled={
                    upsertMutation.isPending ||
                    (!isDirty && !!channelData?.data)
                  }
                  className="h-20 w-full md:w-auto px-16 rounded-full font-black uppercase tracking-widest text-sm shadow-2xl shadow-primary/30 transition-all hover:scale-105 active:scale-95 group"
                >
                  {upsertMutation.isPending ? (
                    <Loader2 className="h-6 w-6 animate-spin me-4" />
                  ) : (
                    <Save className="h-6 w-6 me-4 group-hover:rotate-12 transition-transform" />
                  )}
                  {channelData?.data ? "Update Broadcast" : "Launch Channel"}
                </Button>
              </div>
            </form>
          </div>
        </div>

        {/* Live Preview Sidebar */}
        <div className="lg:col-span-5 space-y-12">
          <div className="sticky top-32">
            <div className="flex items-center justify-between mb-8 px-6">
              <div className="flex items-center gap-4">
                <div className="p-3 rounded-2xl bg-primary text-white shadow-lg">
                  <Eye className="h-5 w-5" />
                </div>
                <span className="text-[11px] font-black uppercase tracking-[0.4em] text-muted-foreground/60">
                  Netflix Preview
                </span>
              </div>
              <div className="flex items-center gap-2">
                <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse" />
                <span className="text-[10px] font-black uppercase tracking-widest text-red-500">
                  Live
                </span>
              </div>
            </div>

            <motion.div
              initial={false}
              onMouseEnter={() => setIsPreviewHovered(true)}
              onMouseLeave={() => setIsPreviewHovered(false)}
              className="relative aspect-[4/5.5] rounded-[4rem] overflow-hidden border border-white/10 shadow-[0_40px_100px_-20px_rgba(0,0,0,0.5)] group bg-black cursor-pointer"
            >
              <AnimatePresence mode="wait">
                {isPreviewHovered && watchedValues.trailerVideoUrl ? (
                  <motion.video
                    key="trailer"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    src={watchedValues.trailerVideoUrl}
                    autoPlay
                    muted
                    loop
                    playsInline
                    className="absolute inset-0 w-full h-full object-cover"
                  />
                ) : (
                  <motion.img
                    key="thumbnail"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    src={
                      watchedValues.thumbnailUrl ||
                      identity?.image ||
                      "https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?auto=format&fit=crop&q=80&w=1000"
                    }
                    className="absolute inset-0 w-full h-full object-cover transition-transform duration-[2000ms] group-hover:scale-110"
                    alt="Preview"
                  />
                )}
              </AnimatePresence>

              {/* Advanced Overlay */}
              <div className="absolute inset-0 bg-linear-to-t from-black via-black/40 to-transparent opacity-90 group-hover:opacity-100 transition-opacity duration-700" />

              {/* Content Overlay */}
              <div className="absolute inset-x-0 bottom-0 p-10 md:p-14 space-y-8">
                <div className="space-y-4">
                  <motion.div layout>
                    <Badge className="bg-primary/20 backdrop-blur-md text-primary-foreground border-primary/20 rounded-full px-5 py-1.5 font-black uppercase tracking-[0.2em] text-[10px] mb-4">
                      Premier Educator
                    </Badge>
                  </motion.div>
                  <h3 className="text-4xl md:text-5xl font-black text-white tracking-tighter leading-[0.9] text-start uppercase">
                    {watchedValues.headline ||
                      identity?.name ||
                      "Broadcasting..."}
                  </h3>
                </div>

                <p className="text-lg font-medium text-white/60 line-clamp-3 leading-relaxed text-start italic">
                  {watchedValues.bio ||
                    "Your channel biography will appear here. Students use this to decide if they want to join your classes."}
                </p>

                <div className="flex items-center gap-6 pt-4">
                  <Button className="flex-1 h-16 rounded-2xl font-black uppercase tracking-widest bg-white text-black hover:bg-primary hover:text-white transition-all duration-500 text-[11px] gap-3">
                    <Video className="h-4 w-4" />
                    Explore Classes
                  </Button>
                  <div className="h-16 w-16 rounded-2xl bg-white/10 backdrop-blur-xl border border-white/10 flex items-center justify-center text-white">
                    <BarChart3 className="h-6 w-6" />
                  </div>
                </div>
              </div>
            </motion.div>

            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.5 }}
              className="mt-10 p-10 rounded-[3rem] bg-primary/3 border-2 border-dashed border-primary/20 backdrop-blur-sm text-start relative overflow-hidden"
            >
              <div className="absolute top-0 end-0 p-10 opacity-[0.05]">
                <Radio className="h-20 w-20" />
              </div>
              <div className="flex gap-6 items-start relative z-10">
                <div className="p-3 rounded-2xl bg-primary text-white shadow-lg">
                  <Sparkles className="h-6 w-6" />
                </div>
                <div className="space-y-2">
                  <h4 className="font-black uppercase tracking-widest text-xs">
                    Studio Tip
                  </h4>
                  <p className="text-base font-medium text-muted-foreground/80 leading-relaxed">
                    High-quality video trailers increase conversion by{" "}
                    <span className="text-primary font-black">40%</span>. Hover
                    the preview card to see your video in action.
                  </p>
                </div>
              </div>
            </motion.div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TeacherChannelPage;

import { ListView } from "@/components/refine-ui/views/list-view";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb";
import {
  UserPlus,
  Loader2,
  Users as UsersIcon,
  MessageSquare,
  Eye,
  Layers,
} from "lucide-react";
import { useMemo } from "react";
import { useList, useGetIdentity, useNavigation } from "@refinedev/core";
import { User, UserRole } from "@/types";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/empty-state";
import { motion } from "framer-motion";
import usePageTitle from "@/hooks/use-page-title";
import { useTranslation } from "react-i18next";
import { cn } from "@/lib/utils";

interface Subscription {
  id: number;
  student: User;
  classId: number;
  createdAt: string;
}

const TeacherSubscriptionsList = () => {
  const { t, i18n } = useTranslation();
  usePageTitle(t("teacherSubscriptions.title"));
  const { data: identity } = useGetIdentity<User>();
  const { show } = useNavigation();
  const isAr = i18n.language === "ar";

  const { query } = useList<Subscription>({
    resource: "teacher-subscriptions",
    queryOptions: {
      enabled: !!identity?.id && identity?.role === UserRole.TEACHER,
    },
    meta: {
      populate: ["student"],
    },
  });

  const isLoading = query.isLoading;

  // Since we mapped to enrollments, and backend now scopes enrollments for teachers
  // to only show students in their classes, we just need to unique them
  const students = useMemo(() => {
    const enrollments = query.data?.data || [];
    const studentMap = new Map<string, User>();
    
    enrollments.forEach(enrollment => {
        if (enrollment.student) {
            studentMap.set(enrollment.student.id, enrollment.student);
        }
    });
    
    return Array.from(studentMap.values());
  }, [query.data]);

  const hasData = students.length > 0;

  return (
    <ListView>
      <div className="space-y-8 md:space-y-12">
        {/* Header Section */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6"
        >
          <div className="space-y-4 flex-1">
            <Breadcrumb />
            <div className="space-y-1">
              <h1 className="page-title mb-0 flex items-center gap-3">
                <div className="p-3 rounded-2xl bg-primary/10 text-primary border border-primary/5 shadow-sm">
                  <UserPlus className="h-6 w-6 md:h-8 md:w-8" />
                </div>
                {t("teacherSubscriptions.title")}
              </h1>
              <p className="text-muted-foreground font-medium max-w-2xl text-balance">
                {t("teacherSubscriptions.description")}
              </p>
            </div>
          </div>
        </motion.div>

        {/* Subscriptions List */}
        <div className="relative min-h-[400px]">
          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.from({ length: 6 }).map((_: any, i: any) => (
                <Card
                  key={i}
                  className="p-6 flex items-center gap-6 border-border/20 bg-background/50"
                >
                  <Skeleton className="h-20 w-20 rounded-3xl shrink-0" />
                  <div className="flex-1 space-y-4 w-full">
                    <Skeleton className="h-8 w-3/4" />
                    <Skeleton className="h-4 w-1/2" />
                  </div>
                </Card>
              ))}
            </div>
          ) : !hasData ? (
            <div className="flex items-center justify-center p-16 bg-card/20 rounded-[2.5rem] border border-dashed border-border/40">
              <EmptyState
                icon={Layers}
                title={t("teacherSubscriptions.empty.title")}
                description={t(
                  "teacherSubscriptions.empty.description",
                )}
                className="border-none bg-transparent min-h-0"
              />
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
              {students.map(
                (student: User, index: number) => (
                  <motion.div
                    key={student.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                    className="group relative flex flex-col p-6 rounded-4xl bg-card/50 backdrop-blur-sm border border-border/40 hover:border-primary/30 hover:bg-card/80 transition-all duration-300 shadow-sm hover:shadow-xl hover:shadow-primary/5"
                  >
                    <div className="flex items-center gap-4 mb-6">
                      <Avatar className="h-16 w-16 rounded-2xl border-4 border-background shadow-lg group-hover:scale-105 transition-transform duration-500">
                        <AvatarImage
                          src={student.image ?? undefined}
                          alt={student.name}
                        />
                        <AvatarFallback className="bg-primary/10 text-primary font-black text-xl">
                          {student.name
                            .substring(0, 2)
                            .toUpperCase()}
                        </AvatarFallback>
                      </Avatar>
                      <div className="flex-1 min-w-0">
                        <h3 className="text-xl font-black tracking-tight truncate group-hover:text-primary transition-colors leading-tight">
                          {student.name}
                        </h3>
                        <p className="text-sm text-muted-foreground truncate">
                          {student.email}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-3 pt-4 border-t border-border/40 w-full mt-auto">
                      <Button
                        asChild
                        size="lg"
                        variant="outline"
                        className="flex-1 rounded-2xl h-12 font-black uppercase tracking-widest text-[10px] transition-all border-primary/20 hover:bg-primary/5 text-primary"
                      >
                        <a href={`mailto:${student.email}`}>
                          <MessageSquare className="h-4 w-4 me-2" />
                          {t("buttons.sendMessage")}
                        </a>
                      </Button>
                      <Button
                        asChild
                        size="lg"
                        className="flex-1 rounded-2xl h-12 font-black uppercase tracking-widest text-[10px] shadow-xl shadow-primary/20"
                      >
                        <a
                          href="#"
                          onClick={() => show("users", student.id)}
                        >
                          {t("buttons.viewProfile")}
                          <Eye
                            className={cn("h-4 w-4 ms-2", isAr && "me-2 ms-0")}
                          />
                        </a>
                      </Button>
                    </div>
                  </motion.div>
                ),
              )}
            </div>
          )}
        </div>
      </div>
    </ListView>
  );
};

export default TeacherSubscriptionsList;

import {
  useCreate,
  useDelete,
  useGetIdentity,
  useList,
  useUpdate,
} from "@refinedev/core";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import {
  Activity,
  Archive,
  Calendar,
  CheckCircle,
  Clock,
  Eye,
  History,
  Loader2,
  MoreHorizontal,
  Pencil,
  PlusCircle,
  Trash2,
  Layers,
} from "lucide-react";
import { AcademicTerm, User, UserRole } from "@/types";
import { useMemo, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import usePageTitle from "@/hooks/use-page-title";
import { Skeleton } from "@/components/ui/skeleton";
import { Breadcrumb } from "@/components/refine-ui/layout/breadcrumb";
import { ListView } from "@/components/refine-ui/views/list-view";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { EmptyState } from "@/components/empty-state";
import { useTranslation } from "react-i18next";

dayjs.extend(relativeTime);

export default function TermsList() {
  const { t, i18n } = useTranslation();

  const termSchema = useMemo(() => z.object({
    name: z.string().min(1, t("terms.form.nameRequired")),
    startDate: z.string().min(1, t("terms.form.startRequired")),
    endDate: z.string().min(1, t("terms.form.endRequired")),
  }), [t]);

  type TermFormValues = z.infer<typeof termSchema>;

  usePageTitle(t("terms.title"));
  const { data: identity } = useGetIdentity<User>();
  const isAdmin = identity?.role === UserRole.ADMIN;

  const { query } = useList<AcademicTerm>({
    resource: "academic-terms",
    pagination: { pageSize: 50, mode: "server" },
    sorters: [{ field: "startDate", order: "desc" }],
  });

  const terms = query.data?.data || [];
  const isLoading = query.isPending;

  const { mutate: update, mutation: updateMutation } = useUpdate();
  
  const { mutate: create, mutation: createMutation } = useCreate();
  
  const { mutate: deleteMutation } = useDelete();
  const [isCreateOpen, setIsCreateOpen] = useState(false);

  const form = useForm<TermFormValues>({
    resolver: zodResolver(termSchema),
  });

  const handleActivate = (id: number) => {
    update(
      {
        resource: "academic-terms",
        id,
        values: { status: "active" },
      },
      {
        onSuccess: () => toast.success(t("terms.toasts.activated")),
        onError: () => toast.error(t("terms.toasts.error")),
      },
    );
  };

  const handleArchive = (id: number) => {
    update(
      {
        resource: "academic-terms",
        id,
        values: { status: "archived" },
      },
      {
        onSuccess: () => toast.success(t("terms.toasts.archived")),
        onError: () => toast.error(t("terms.toasts.error")),
      },
    );
  };

  const handleDelete = (id: number) => {
    if (
      window.confirm(t("terms.deleteDialog.title") + " " + t("terms.deleteDialog.description"))
    ) {
      deleteMutation(
        {
          resource: "academic-terms",
          id,
        },
        {
          onSuccess: () => toast.success(t("terms.toasts.deleted")),
          onError: () => toast.error(t("terms.toasts.error")),
        },
      );
    }
  };

  const onSubmit = (values: TermFormValues) => {
    create(
      {
        resource: "academic-terms",
        values: {
          ...values,
          status: "upcoming",
        },
      },
      {
        onSuccess: () => {
          toast.success(t("terms.toasts.created"));
          setIsCreateOpen(false);
          form.reset();
        },
        onError: () => toast.error(t("terms.toasts.error")),
      },
    );
  };

  const stats = useMemo(() => {
    if (!terms.length) return { total: 0, active: 0, upcoming: 0 };
    return {
      total: terms.length,
      active: terms.filter((term) => term.status === "active").length,
      upcoming: terms.filter((term) => term.status === "upcoming").length,
    };
  }, [terms]);

  return (
    <ListView>
      <div className="space-y-8 md:space-y-12">
        {/* Header Section */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6"
        >
          <div className="space-y-4 flex-1">
            <Breadcrumb />
            <div className="space-y-1 text-start">
              <h1 className="page-title mb-0 flex items-center gap-3">
                <div className="p-3 rounded-2xl bg-primary/10 text-primary border border-primary/5 shadow-sm">
                  <Calendar className="h-6 w-6 md:h-8 md:w-8" />
                </div>
                {t("terms.title")}
              </h1>
              <p className="text-muted-foreground font-medium max-w-2xl text-balance">
                {t("terms.description")}
              </p>
            </div>
          </div>
          <div className="w-full md:w-auto">
            {isAdmin && (
              <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                <DialogTrigger asChild>
                  <Button size="lg" className="w-full md:w-auto rounded-2xl h-12 md:h-14 px-10 font-bold uppercase tracking-widest text-[10px] gap-2 shadow-lg shadow-primary/25 hover:-translate-y-0.5 transition-all">
                    <PlusCircle className="h-5 w-5" />
                    {t("terms.create")}
                  </Button>
                </DialogTrigger>
                <DialogContent className="rounded-[2.5rem] border-none shadow-2xl bg-card/95 backdrop-blur-xl max-w-lg p-0 overflow-hidden text-start">
                  <div className="p-8 md:p-12 space-y-8">
                    <DialogHeader className="space-y-4 text-start">
                      <div className="p-5 rounded-2xl bg-primary/10 text-primary w-fit mx-auto">
                        <Calendar className="h-10 w-10" />
                      </div>
                      <div className="space-y-2 text-center">
                        <DialogTitle className="text-3xl font-black tracking-tight">
                          {t("terms.newTitle")}
                        </DialogTitle>
                        <DialogDescription className="font-medium text-base text-muted-foreground">
                          {t("terms.newDesc")}
                        </DialogDescription>
                      </div>
                    </DialogHeader>
                    <form
                      onSubmit={form.handleSubmit(onSubmit)}
                      className="space-y-8"
                    >
                      <div className="space-y-3">
                        <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground ms-2">
                          {t("terms.form.name")}
                        </Label>
                        <Input
                          placeholder={t("terms.form.namePlaceholder")}
                          {...form.register("name")}
                          className="h-16 rounded-3xl bg-muted/30 border-none shadow-inner px-8 text-lg font-black"
                        />
                        {form.formState.errors.name && (
                          <p className="text-xs font-bold text-destructive ms-2">
                            {form.formState.errors.name.message}
                          </p>
                        )}
                      </div>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <div className="space-y-3">
                          <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground ms-2">
                            {t("terms.form.start")}
                          </Label>
                          <Input
                            type="date"
                            {...form.register("startDate")}
                            className="h-16 rounded-3xl bg-muted/30 border-none shadow-inner px-8 font-bold"
                          />
                          {form.formState.errors.startDate && (
                            <p className="text-xs font-bold text-destructive ms-2">
                              {form.formState.errors.startDate.message}
                            </p>
                          )}
                        </div>
                        <div className="space-y-3">
                          <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground ms-2">
                            {t("terms.form.end")}
                          </Label>
                          <Input
                            type="date"
                            {...form.register("endDate")}
                            className="h-16 rounded-3xl bg-muted/30 border-none shadow-inner px-8 font-bold"
                          />
                          {form.formState.errors.endDate && (
                            <p className="text-xs font-bold text-destructive ms-2">
                              {form.formState.errors.endDate.message}
                            </p>
                          )}
                        </div>
                      </div>
                      <DialogFooter className="flex-col sm:flex-row gap-3 pt-4">
                        <Button
                          variant="ghost"
                          type="button"
                          className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-8 order-2 sm:order-1"
                          onClick={() => setIsCreateOpen(false)}
                        >
                          {t("buttons.cancel")}
                        </Button>
                        <Button
                          type="submit"
                          size="lg"
                          className="rounded-2xl font-black uppercase tracking-widest text-[10px] h-14 px-12 shadow-xl shadow-primary/20 order-1 sm:order-2"
                          disabled={createMutation.isPending}
                        >
                          {createMutation.isPending ? (
                            <Loader2 className="h-5 w-5 animate-spin me-3" />
                          ) : (
                            <PlusCircle className="h-5 w-5 me-3" />
                          )}
                          {t("buttons.create")}
                        </Button>
                      </DialogFooter>
                    </form>
                  </div>
                </DialogContent>
              </Dialog>
            )}
          </div>
        </motion.div>

        {/* Stats Row - Adaptive */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 md:gap-6">
          <Card className="p-6 md:p-8 bg-card/40 backdrop-blur-3xl border-border/40 rounded-4xl md:rounded-[2.5rem] flex items-center gap-5 shadow-sm">
            <div className="p-3.5 rounded-2xl bg-primary/10 text-primary">
              <Calendar className="h-6 w-6 md:h-7 md:w-7" />
            </div>
            <div className="text-start">
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 mb-1">
                {t("terms.stats.total")}
              </p>
              <p className="text-2xl md:text-3xl font-black">
                {isLoading ? "..." : new Intl.NumberFormat(i18n.language).format(stats.total)}
              </p>
            </div>
          </Card>
          <Card className="p-6 md:p-8 bg-card/40 backdrop-blur-3xl border-border/40 rounded-4xl md:rounded-[2.5rem] flex items-center gap-5 shadow-sm">
            <div className="p-3.5 rounded-2xl bg-green-500/10 text-green-600">
              <Activity className="h-6 w-6 md:h-7 md:w-7" />
            </div>
            <div className="text-start">
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 mb-1">
                {t("terms.stats.active")}
              </p>
              <p className="text-2xl md:text-3xl font-black text-green-600">
                {isLoading ? "..." : new Intl.NumberFormat(i18n.language).format(stats.active)}
              </p>
            </div>
          </Card>
          <Card className="p-6 md:p-8 bg-card/40 backdrop-blur-3xl border-border/40 rounded-4xl md:rounded-[2.5rem] flex items-center gap-5 shadow-sm">
            <div className="p-3.5 rounded-2xl bg-indigo-500/10 text-indigo-600">
              <Clock className="h-6 w-6 md:h-7 md:w-7" />
            </div>
            <div className="text-start">
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 mb-1">
                {t("terms.stats.upcoming")}
              </p>
              <p className="text-2xl md:text-3xl font-black text-indigo-600">
                {isLoading ? "..." : new Intl.NumberFormat(i18n.language).format(stats.upcoming)}
              </p>
            </div>
          </Card>
        </div>

        {/* List Container - Global Scroll */}
        <div className="relative min-h-100">
          {isLoading ? (
            <div className="space-y-4">
              {Array.from({ length: 5 }).map((_, i) => (
                <Card key={i} className="p-6 flex flex-col md:flex-row items-center gap-6 border-border/20 bg-background/50">
                  <Skeleton className="h-20 w-20 rounded-3xl shrink-0" />
                  <div className="flex-1 space-y-4 w-full">
                    <Skeleton className="h-8 w-87.5 max-w-full" />
                    <div className="flex gap-4">
                       <Skeleton className="h-4 w-24" />
                       <Skeleton className="h-4 w-24" />
                    </div>
                  </div>
                  <Skeleton className="h-12 w-36 rounded-2xl" />
                </Card>
              ))}
            </div>
          ) : terms.length === 0 ? (
            <div className="flex items-center justify-center p-16 bg-card/20 rounded-[2.5rem] border border-dashed border-border/40">
              <EmptyState
                icon={Layers}
                title={t("terms.empty.title")}
                description={t("terms.empty.desc")}
                className="border-none bg-transparent min-h-0"
                action={
                  isAdmin
                    ? {
                        label: t("terms.create"),
                        onClick: () => setIsCreateOpen(true),
                      }
                    : undefined
                }
              />
            </div>
          ) : (
            <div className="space-y-4">
              <AnimatePresence mode="popLayout">
                {terms.map((term, index) => {
                  const startDate = dayjs(term.startDate);
                  const endDate = dayjs(term.endDate);

                  return (
                    <motion.div
                      key={term.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95 }}
                      transition={{ delay: index * 0.05 }}
                      className={cn(
                        "group relative flex flex-col md:flex-row items-center p-5 md:p-6 rounded-4xl bg-card/50 backdrop-blur-sm border border-border/40 hover:border-primary/30 hover:bg-card/80 transition-all duration-300 shadow-sm hover:shadow-xl hover:shadow-primary/5 cursor-pointer"
                      )}
                    >
                      {/* Status Color Accent using logical properties */}
                      <div 
                        className={cn(
                          "absolute start-0 top-1/2 -translate-y-1/2 w-1.5 h-12 rounded-e-full transition-all group-hover:h-20",
                          term.status === "active" ? "bg-green-500" : term.status === "upcoming" ? "bg-indigo-500" : "bg-muted-foreground/40"
                        )}
                      />

                      {/* Icon */}
                      <div className="relative shrink-0 mb-4 md:mb-0">
                        <div
                          className={cn(
                            "h-20 w-20 rounded-[1.5rem] border-4 border-background flex items-center justify-center shadow-lg group-hover:scale-105 transition-transform duration-500",
                            term.status === "active"
                              ? "bg-green-500/10 text-green-600"
                              : term.status === "upcoming"
                                ? "bg-indigo-500/10 text-indigo-600"
                                : "bg-muted/40 text-muted-foreground/60",
                          )}
                        >
                          {term.status === "archived" ? (
                            <History className="h-8 w-8" />
                          ) : (
                            <Calendar className="h-8 w-8" />
                          )}
                        </div>
                      </div>

                      {/* Info Area */}
                      <div className={cn("flex-1 min-w-0 w-full text-start", "md:ms-8")}>
                        <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 mb-2">
                          <h3 className="text-xl md:text-2xl font-black tracking-tight truncate group-hover:text-primary transition-colors leading-tight">
                            {term.name}
                          </h3>
                          <div className="flex items-center justify-center md:justify-start gap-2">
                            <Badge
                              variant={
                                term.status === "active"
                                  ? "default"
                                  : term.status === "upcoming"
                                    ? "secondary"
                                    : "outline"
                              }
                              className="text-[9px] font-black uppercase tracking-widest px-2.5 py-0.5 rounded-full border-none shadow-sm"
                            >
                              {t(`status.${term.status.toLowerCase()}` as any)}
                            </Badge>
                          </div>
                        </div>

                        <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 md:gap-6 mt-4">
                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                              <Calendar className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                              <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Duration</span>
                              <span className="text-[11px] font-black text-foreground">
                                {startDate.locale(i18n.language).format("MMM D, YYYY")} — {endDate.locale(i18n.language).format("MMM D, YYYY")}
                              </span>
                            </div>
                          </div>

                          <div className="flex items-center gap-2.5 bg-background/40 px-3 py-1.5 rounded-full border border-border/20 shadow-sm">
                            <div className="p-1.5 rounded-lg bg-primary/5 shrink-0">
                              <Clock className="h-3.5 w-3.5 text-primary" />
                            </div>
                            <div className="flex flex-col text-start">
                              <span className="text-[9px] uppercase font-bold text-muted-foreground/60 tracking-wider">Timeline</span>
                              <span className="text-[11px] font-black uppercase tracking-tight">
                                {term.status === "active"
                                  ? t("terms.relative.ends", { time: endDate.locale(i18n.language).fromNow() })
                                  : term.status === "upcoming"
                                    ? t("terms.relative.starts", { time: startDate.locale(i18n.language).fromNow() })
                                    : t("terms.relative.completed")}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Action Area */}
                      <div className="flex items-center gap-3 mt-6 md:mt-0 shrink-0">
                        {isAdmin && term.status !== "archived" && (
                          <div className={cn("hidden lg:flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300 group-hover:translate-x-0", "ltr:translate-x-4 rtl:-translate-x-4")}>
                            {term.status === "upcoming" && (
                              <Button
                                variant="outline"
                                size="lg"
                                className="rounded-2xl px-6 h-12 font-black uppercase tracking-widest text-[10px] border-green-500/20 text-green-600 bg-green-500/5 hover:bg-green-500/10"
                                onClick={(e) => { e.stopPropagation(); handleActivate(term.id); }}
                                disabled={updateMutation.isPending}
                              >
                                <CheckCircle className={cn("h-4 w-4", "me-2")} />
                                {t("buttons.activate")}
                              </Button>
                            )}
                            <Button
                              variant="outline"
                              size="lg"
                              className="rounded-2xl px-6 h-12 font-black uppercase tracking-widest text-[10px] border-amber-500/20 text-amber-600 bg-amber-500/5 hover:bg-amber-500/10"
                              onClick={(e) => { e.stopPropagation(); handleArchive(term.id); }}
                              disabled={updateMutation.isPending}
                            >
                              <Archive className={cn("h-4 w-4", "me-2")} />
                              {t("buttons.archive")}
                            </Button>
                          </div>
                        )}

                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-12 w-12 rounded-2xl bg-muted/30 hover:bg-muted/50"
                              onClick={(e) => e.stopPropagation()}
                            >
                              <MoreHorizontal className="h-5 w-5" />
                            </Button>
                          </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="w-64 p-2 rounded-3xl bg-white dark:bg-[#09090b] opacity-100 backdrop-blur-none border border-border/50 shadow-2xl">
                            <DropdownMenuLabel className="text-[10px] font-black uppercase tracking-[0.15em] text-muted-foreground/40 px-3 py-3">{t("assignments.list.labels.options")}</DropdownMenuLabel>
                            <DropdownMenuItem className="rounded-xl gap-3 py-3 cursor-pointer">
                              <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                <Eye className="h-4 w-4" />
                              </div>
                              <span className="font-bold text-xs">{t("buttons.viewClasses")}</span>
                            </DropdownMenuItem>
                            {isAdmin && (
                              <>
                                <DropdownMenuItem className="rounded-xl gap-3 py-3 cursor-pointer">
                                  <div className="p-2 rounded-lg bg-primary/10 text-primary">
                                    <Pencil className="h-4 w-4" />
                                  </div>
                                  <span className="font-bold text-xs">{t("buttons.editTimeline")}</span>
                                </DropdownMenuItem>
                                <DropdownMenuSeparator className="my-2 opacity-50" />
                                <DropdownMenuItem
                                  className="rounded-xl gap-3 py-3 cursor-pointer text-destructive focus:bg-destructive/10"
                                  onClick={() => handleDelete(term.id)}
                                >
                                  <div className="p-2 rounded-lg bg-destructive/10 text-destructive">
                                    <Trash2 className="h-4 w-4" />
                                  </div>
                                  <span className="font-bold text-xs">{t("buttons.deleteTerm")}</span>
                                </DropdownMenuItem>
                              </>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>
          )}
        </div>
      </div>
    </ListView>
  );
}

import { AccessControlProvider } from "@refinedev/core";
import { authProvider } from "./auth";
import { User, UserRole } from "@/types";

/**
 * Access Control Provider
 * Handles client-side visibility of resources and actions.
 * Note: Backend still enforces strict ownership and scoping.
 */
export const accessControlProvider: AccessControlProvider = {
  can: async ({ resource, action, params }) => {
    const identity = (await authProvider.getIdentity?.()) as User | null;
    if (!identity) return { can: false, reason: "Unauthorized." };

    const role = identity.role?.toLowerCase();
    const resourceName = resource || "";

    // 1. ADMISSION: Admins have specific access
    if (role === UserRole.ADMIN) {
      const adminAllowedResources = [
        "dashboard", "departments", "users", "activity-log", "settings",
        "profile-requests", "ai-study-lab", "study-planner", "ai-assistant", "ai-activity-logs", "ai-health-reports",
      ];
      const academicResources = [
        "classes", "assignments", "quizzes", "modules", "resources", "academic-terms",
        "subjects", "attendance", "submissions", "enrollments", "announcements",
        "teacher-applications", "discussions", "calendar",
        "notifications", "progress", "report-card", "portfolio", "messages", "my-teachers", "channels"
      ];

      if (adminAllowedResources.includes(resourceName)) {
        // Admins can do anything on their allowed resources
        return { can: true };
      }

      if (academicResources.includes(resourceName)) {
        // 🏛️ REGISTRAR AUTHORITY: Admins can manage the infrastructure 
        // (Create classes, assign teachers, manage enrollment)
        return { can: true };
      }

      // Default for any other resource not explicitly listed
      return { can: false, reason: "Access denied for this resource." };
    }

    // 2. TEACHER PERMISSIONS
    if (role === UserRole.TEACHER) {
      // Teachers can manage their own classes
      if (resourceName === "classes") {
        // Teachers can create classes
        if (action === "create") return { can: true };
        
        // Teachers can list and show all classes
        if (["list", "show"].includes(action)) return { can: true };
        
        // Ownership check for sensitive actions
        if (["edit", "delete"].includes(action)) {
          // If we have the record, check if this teacher is the owner
          const record = (params as any)?.record;
          if (record && record.teacherId) {
            return { can: record.teacherId === identity.id };
          }
          // Fallback: allow it if no record is provided (backend will still block)
          return { can: true };
        }
      }

      // Teachers can view individual profiles but cannot access global users list
      if (resourceName === "users") {
        if (["show"].includes(action)) return { can: true };
        if (action === "edit" && params?.id === identity?.id) return { can: true };
        return { can: false, reason: "Teachers cannot access the global users directory or edit other user profiles." };
      }

      // Teachers can view their subscribers (new resource/action)
      if (resourceName === "teacher-subscriptions" && ["list", "show"].includes(action)) {
        return { can: true };
      }

      // Specific restriction for applications
      if (resourceName === "teacher-applications") {
        return { can: ["list", "create", "show"].includes(action) };
      }

      // Sidebar & Core Resources (removed "users" to enforce isolation)
      const allowedResources = [
        "dashboard", "ai-assistant", "discussions", "calendar", "subjects",
        "attendance", "submissions", "quizzes", "resources", "classes",
        "modules", "notifications", "progress", "enrollments",
        "classes/enrollments", "announcements", "messages",
        "teacher-channel", "teacher-subscriptions", "academic-terms" // Added academic-terms
      ];

      if (allowedResources.includes(resourceName)) {
        // Teachers can't delete subjects
        if (resourceName === "subjects" && action === "delete") return { can: false };

        return { can: true };
      }

      // Forbidden for Teachers
      const forbidden = ["departments", "profile-requests", "ai-study-lab", "study-planner", "activity-log", "settings"]; // Removed academic-terms
      if (forbidden.includes(resourceName)) return { can: false };

      return { can: false, reason: "Access denied for this resource." };
    }

    // 3. STUDENT PERMISSIONS
    if (role === UserRole.STUDENT) {
      const studentAllowed = [
        "dashboard", "subjects", "classes", "assignments", "discussions", "calendar",
        "attendance", "submissions", "quizzes", "resources",
        "modules", "ai-study-lab", "study-planner", "notifications", "progress",
        "report-card", "portfolio", "messages", "users",
        "teacher-subscriptions", "my-teachers", "teacher-channels", "project-groups", "library", "enrollments", "ai-activity-logs"
      ];

      if (!studentAllowed.includes(resourceName)) return { can: false };

      // Read-only for most things
      if (["list", "show"].includes(action)) return { can: true };

      // Specific Write Actions for Students
      if (resourceName === "submissions" && action === "create") return { can: true };
      if (resourceName === "messages" && action === "create") return { can: true };
      if (resourceName === "discussions" && action === "create") return { can: true };

      // Students can enroll in classes
      if (resourceName === "classes" && action === "enroll") return { can: true };

      // Profiles: Can only edit their own
      if (resourceName === "users" && action === "edit" && params?.id === identity?.id) return { can: true };

      return { can: false, reason: "Access denied." };
    }

    return { can: false, reason: "Unauthorized." };
  },
  options: {
    buttons: {
      hideIfUnauthorized: true,
    },
  },
};

import { DataProvider, HttpError, LogicalFilter } from "@refinedev/core";
import { BACKEND_URL } from "@/config";

const BACKEND_BASE_URL = BACKEND_URL;

/**
 * Helper to handle API errors and return Refine-compatible HttpError
 */
const handleError = async (response: Response): Promise<HttpError> => {
  let json: Record<string, unknown> = {};
  try {
    const text = await response.text();
    if (text) {
      json = JSON.parse(text);
    }
  } catch {
    // Not JSON or empty
  }

  // SILENT 401 & 404: We don't want loud toasts for auth checks or missing optional resources
  if (response.status === 401 || response.status === 404) {
    return {
      message: "", // Empty message prevents the toast
      statusCode: response.status,
    };
  }

  if (json.details) {
    return {
      message: (json.error as string) || "Validation failed",
      statusCode: response.status,
      errors: json.details as Record<string, string>,
    };
  }

  return {
    message:
      (json.error as string) || (json.message as string) || `HTTP error! status: ${response.status}`,
    statusCode: response.status,
  };
};

/**
 * Smart Fetcher: Only adds Content-Type for methods with a body.
 */
const fetcher = async (url: string, options?: RequestInit) => {
  const method = options?.method?.toUpperCase() || "GET";
  const headers: Record<string, string> = {
    ...(options?.headers as Record<string, string>),
  };

  if (["POST", "PUT", "PATCH", "DELETE"].includes(method)) {
    headers["Content-Type"] = "application/json";
  }

  // 🛡️ DUAL AUTH: Better Auth (Cookies) + Bearer Token (Authorization Header)
  const token = localStorage.getItem("token");
  if (token && !headers["Authorization"]) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  return fetch(url, {
    ...options,
    credentials: "include",
    headers: headers,
  });
};

/**
 * Resource Filter Mappings
 * Decouples frontend UI field names from backend query parameters.
 */
const resourceFilterMappings: Record<string, Record<string, string>> = {
  departments: { name: "search", code: "search" },
  users: { search: "search", name: "search", email: "search", role: "role" },
  subjects: { name: "search", code: "search", department: "departmentId" },
  classes: { name: "search", subject: "subjectId", teacher: "teacherId", status: "status", termId: "termId" },
  enrollments: { classId: "classId", studentId: "studentId", status: "status" },
  assignments: { classId: "classId", moduleId: "moduleId" },
  submissions: { assignmentId: "assignmentId", studentId: "studentId" },
  discussions: { classId: "classId", parentId: "parentId" },
  attendance: { classId: "classId", date: "date" },
  resources: { classId: "classId", moduleId: "moduleId", search: "search" },
  "profile-requests": { status: "status", userId: "userId" },
  quizzes: { classId: "classId", moduleId: "moduleId" },
  modules: { classId: "classId" },
  progress: { classId: "classId", userId: "userId" },
  "users/children": { parentId: "parentId" },
  "teacher-applications": { status: "status", teacherId: "teacherId", classId: "classId" },
  channels: { headline: "headline", teacherId: "teacherId" },
};

export const dataProvider: DataProvider = {
  getList: async ({ resource, pagination, filters, sorters }) => {
    let urlPath = resource;
    if (resource === "teacher-channels") urlPath = "channels";
    if (resource === "teacher-subscriptions") urlPath = "enrollments";
    
    const url = new URL(`${BACKEND_BASE_URL}/${urlPath}`);

    // Pagination: Map to _start and _end for backend compatibility
    if (pagination?.mode !== "off") {
      const current = (pagination as any)?.current ?? 1;
      const pageSize = (pagination as any)?.pageSize ?? 10;
      const _start = (current - 1) * pageSize;
      const _end = _start + pageSize;
      url.searchParams.append("_start", _start.toString());
      url.searchParams.append("_end", _end.toString());
    }

    // Filtering: Map operators to backend-compatible suffixes
    if (filters) {
      filters.forEach((filter) => {
        if ("field" in filter) {
          const { field, operator, value } = filter as LogicalFilter;
          const mappedField = resourceFilterMappings[resource]?.[field] || field;
          
          let queryKey = mappedField;
          if (operator === "contains") {
            queryKey = `${mappedField}_like`;
          } else if (operator === "gte") {
            queryKey = `${mappedField}_gte`;
          } else if (operator === "lte") {
            queryKey = `${mappedField}_lte`;
          } else if (operator === "ne") {
            queryKey = `${mappedField}_ne`;
          } else if (operator !== "eq") {
            queryKey = `${mappedField}_${operator}`;
          }

          if (value !== undefined && value !== null && value !== "") {
            url.searchParams.append(queryKey, String(value));
          }
        } else {
            // ⚠️ GOTCHA: ConditionalFilter (OR/AND) not supported by current flat-mapped backend.
            // Suppressing to prevent crash, but logging for developer awareness.
            console.warn("DataProvider: Conditional filters (OR/AND) are not yet supported by the flat-mapping backend.");
        }
      });
    }

    // Sorting: Map to _sort and _order (single sort supported by current backend)
    if (sorters && sorters.length > 0) {
      url.searchParams.append("_sort", sorters[0].field);
      url.searchParams.append("_order", sorters[0].order);
    }

    const response = await fetcher(url.toString());

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    const data = json.data ?? (Array.isArray(json) ? json : []);
    const total = json.pagination?.total ?? data.length;

    return { data, total };
  },

  getOne: async ({ resource, id }) => {
    let urlPath = resource;
    if (resource === "teacher-channels") urlPath = "channels";
    if (resource === "teacher-subscriptions") urlPath = "enrollments";

    const url = `${BACKEND_BASE_URL}/${urlPath}/${id}`;
    const response = await fetcher(url);

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    return {
      data: json.data ?? json,
    };
  },

  create: async ({ resource, variables }) => {
    let urlPath = resource;
    if (resource === "teacher-channels") urlPath = "channels";
    if (resource === "teacher-subscriptions") urlPath = "enrollments";

    const url = `${BACKEND_BASE_URL}/${urlPath}`;
    const response = await fetcher(url, {
      method: "POST",
      body: JSON.stringify(variables),
    });

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    return {
      data: json.data ?? json,
    };
  },

  update: async ({ resource, id, variables }) => {
    let urlPath = resource;
    if (resource === "teacher-channels") urlPath = "channels";
    if (resource === "teacher-subscriptions") urlPath = "enrollments";

    const url = `${BACKEND_BASE_URL}/${urlPath}/${id}`;
    const response = await fetcher(url, {
      method: "PATCH",
      body: JSON.stringify(variables),
    });

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    return {
      data: json.data ?? json,
    };
  },

  deleteOne: async ({ resource, id }) => {
    let urlPath = resource;
    if (resource === "teacher-channels") urlPath = "channels";
    if (resource === "teacher-subscriptions") urlPath = "enrollments";

    const url = `${BACKEND_BASE_URL}/${urlPath}/${id}`;
    const response = await fetcher(url, {
      method: "DELETE",
    });

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    return {
      data: json.data || { id },
    };
  },

  getApiUrl: () => BACKEND_BASE_URL,

  getMany: async ({ resource, ids }) => {
    let urlPath = resource;
    if (resource === "teacher-channels") urlPath = "channels";
    if (resource === "teacher-subscriptions") urlPath = "enrollments";

    const url = new URL(`${BACKEND_BASE_URL}/${urlPath}`);
    ids.forEach((id) => {
      url.searchParams.append("id", String(id));
    });

    const response = await fetcher(url.toString());

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    const data = json.data ?? (Array.isArray(json) ? json : []);
    return { data };
  },

  createMany: async () => {
    throw new Error("createMany not implemented");
  },
  deleteMany: async () => {
    throw new Error("deleteMany not implemented");
  },
  updateMany: async () => {
    throw new Error("updateMany not implemented");
  },

  custom: async ({ url, method, payload, query, headers }) => {
    let requestUrl = url;

    if (!url.startsWith("http")) {
      if (url.startsWith("/")) {
        requestUrl = `${BACKEND_BASE_URL}${url}`;
      } else {
        requestUrl = `${BACKEND_BASE_URL}/${url}`;
      }
    }

    if (query) {
      const searchParams = new URLSearchParams();
      Object.entries(query).forEach(([key, value]) => {
        searchParams.append(key, String(value));
      });
      const separator = requestUrl.includes("?") ? "&" : "?";
      requestUrl += `${separator}${searchParams.toString()}`;
    }

    const response = await fetcher(requestUrl, {
      method: method ? method.toUpperCase() : "GET",
      body: payload ? JSON.stringify(payload) : undefined,
      headers: headers as Record<string, string>,
    });

    if (!response.ok) {
      throw await handleError(response);
    }

    const json = await response.json();
    if (json && typeof json === "object" && "data" in json) {
      return json;
    }
    return { data: json };
  },
};

