export type Class = z.infer<typeof classFormSchema> & {
  id: number;
  inviteCode: string;
  bannerUrl?: string | null;
  bannerCldPubId?: string | null;
  color?: string;
  gradingStatus: GradingStatus;
  allowParentAccess: boolean;
  archivedAt: string | null;
  teachers: {
    teacher: User;
    isPrimary: boolean;
  }[];
  subject: Subject;
  createdAt: string;
  updatedAt: string;
  enrollments: Enrollment[];
  assignments: Assignment[];
  modules?: Module[];
  gradeCategories?: GradeCategory[];
  isLive?: boolean;
  isBreakoutActive?: boolean;
  termId?: number;
  term?: AcademicTerm;
};

export type ClassListItem = Pick<
  Class,
  | "id"
  | "name"
  | "status"
  | "capacity"
  | "bannerUrl"
  | "teachers"
  | "schedules"
  | "isLive"
  | "isBreakoutActive"
  | "color"
  | "enrollments"
> & {
  isEnrolled?: boolean;
  isTeacherAssigned?: boolean;
  subject?: {
    name: string;
    department?: {
      name: string;
    };
  };
  _count?: {
    enrollments: number;
  };
};

